/** Pexels/Pixabay: one simple English word. scriptOnly = ignore scene/title hint context. */
function simplifyStockSearchWord(input: string, hintText = "", scriptOnly = false): string {
  const cleanedInput = input.replace(/\[visual:[^\]]*\]/gi, " ").trim();
  const combined = (scriptOnly ? cleanedInput : `${cleanedInput} ${hintText}`)
    .toLowerCase()
    .replace(/\[visual:[^\]]*\]/gi, " ");
  for (const [nl, en] of Object.entries(DUTCH_STOCK_WORD_MAP)) {
    if (new RegExp(`\\b${nl}\\b`).test(combined)) return en;
  }
  for (const [re, word] of STOCK_TOPIC_WORD_RULES) {
    if (re.test(combined)) return word;
  }
  const tokens = scriptOnly
    ? tokenizeForRelevance(cleanedInput)
    : [
        ...tokenizeForRelevance(cleanedInput),
        ...tokenizeForRelevance(hintText),
      ];
  const seen = new Set<string>();
  const unique = tokens.filter((t) => {
    if (seen.has(t)) return false;
    seen.add(t);
    return true;
  });
  /**
   * THE SAME RULE RONDE 97 ALREADY WROTE, ON THE SECOND PLACE THAT NEEDED IT.
   *
   * `extractPowerWordFromSentence` ranks with `NON_PICTORIAL_WORD_FORM` under a comment that says
   * "LENGTH IS NOT A MEASURE OF WHAT CAN BE PHOTOGRAPHED". This function was the other half of the
   * same job and still sorted by `b.length - a.length` alone, so render 573 asked stock libraries
   * for `"shaped"` eleven times and `"evidence"` ten times — both past participles and
   * abstractions of the narration, both longer than the words that name a thing:
   *
   *     "This act was shaped by new evidence…"  →  shaped(6) / evidence(8)  beat  act(3)
   *
   * Those searches were ALLOWED by the query gate (the beat does contain the word) and returned
   * modern stock: a 3D diagram of shale-gas geology arrived on a beat about the Führerbunker.
   *
   * Not a new rule and not a new list — the existing regex, applied where the same decision is
   * made. A sentence that genuinely holds nothing concrete still yields its best available word,
   * because the form only demotes and never removes.
   */
  const pictorialRank = (w: string): number =>
    NON_PICTORIAL_WORD_FORM.test(w) ? -1 : w.length;
  unique.sort((a, b) => pictorialRank(b) - pictorialRank(a));
  for (const t of unique) {
    if (DUTCH_STOCK_WORD_MAP[t]) return DUTCH_STOCK_WORD_MAP[t];
    if (t.length >= 4 && !RELEVANCE_STOP_WORDS.has(t)) return t.slice(0, 24);
  }
  for (const t of unique) {
    if (t.length >= 3 && !RELEVANCE_STOP_WORDS.has(t)) return t.slice(0, 24);
  }
  if (/\bmodel\s*3\b/.test(combined)) return "tesla";
  /**
   * NOTHING SURVIVED, AND "documentary" IS A WORD THE GATE REFUSES BY NAME.
   *
   * This used to return the literal string `"documentary"`. `hasContentAnchor` answers false for
   * it — it is production vocabulary, which is precisely what check H exists to refuse — so every
   * one of those searches was rejected before it left the building:
   *
   *     [SearchQueryRejected] query="documentary" reason=NO_CONTENT_ANCHOR   ×30
   *
   * Thirty refusals, and a `route=documentary` label on the rejects that made the beat look as
   * though it had asked a real question. Returning nothing says the true thing — this sentence
   * yielded no searchable subject — and the callers below already drop an empty query rather than
   * send it. No gate is relaxed: the same searches are refused, just not attempted.
   */
  return "";
}

function enrichStockQuery(
  query: unknown,
  scene: Scene,
  videoTitle?: string,
  personName?: string,
  beatText?: string
): string {
  const q = toQueryString(query);
  if (beatText?.trim()) {
    const persons = coercePersonName(personName)
      ? [coercePersonName(personName), ...(scene.personNames ?? []).map(coercePersonName)]
      : (scene.personNames ?? []).map(coercePersonName);
    const fromScript = scriptStockSearchQueries(beatText, persons, scene.text, videoTitle);
    if (fromScript.length > 0) return fromScript[0];
  }
  const hint = beatText?.trim() || scene.text;
  if (isBlockedStockQuery(q)) return simplifyStockSearchWord(hint, hint, true);
  return simplifyStockSearchWord(q, hint, Boolean(beatText?.trim()));
}

function tokenizeForRelevance(text: string): string[] {
  /** RONDE 88A: folded first — "Führerbunker" tokenised to "hrerbunker" and scored against nothing. */
  return foldSearchText(text)
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length >= 3 && !RELEVANCE_STOP_WORDS.has(w));
}

/**
 * RONDE 218 — THE PIPELINE SEARCHED FOR ONE THING AND SCORED FOR ANOTHER.
 *
 * ── The gap ─────────────────────────────────────────────────────────────────────────────────
 *
 * The script says, per sentence, what the viewer should SEE: `visual_description`,
 * `priority_subject`, and the search subjects derived from them. `beatVisualSearchSubjects` puts
 * that into the QUERY, and it has done so for a long time.
 *
 * These keywords are the other half — `scoreVisualRelevance(hay, relevanceKeywords)` is what then
 * decides whether a candidate the query returned is actually about this beat. And they were built
 * from the beat text, the scene's cue, the scene's stock query, the person names and the video
 * title. The script's own statement of what to show was not among them, and a grep for it finds no
 * other route by which it arrives.
 *
 * So the render asked for "an abandoned factory floor" and then scored the results against a word
 * list that never mentioned a factory. A perfect match scored no higher than the noise beside it.
 *
 * Two lines above one of the three call sites, `resolveBeatVisualIntent(text)` had already been
 * called and its answer thrown away for this purpose. A value computed and not carried — this
 * codebase's signature fault, at a distance of two lines.
 *
 * ── Why the resolver is called here and not passed in ───────────────────────────────────────
 *
 * The same function the SEARCH side uses, so the two cannot come to different conclusions about
 * one beat. Threading a parameter through three call sites would let a future fourth forget it;
 * asking the one resolver cannot. It is memo-free but cheap — rule-based over the sentence — and
 * it is what `beatVisualSearchSubjects` already does internally on every beat.
 *
 * ── What is deliberately NOT taken from the intent ──────────────────────────────────────────
 *
 * `camera_shot` and `emotion`. The dead `buildRelevanceKeywordsFromIntent` included both; copying
 * that would be a mistake. "wide", "close", "aerial" are production vocabulary — they describe the
 * filming, not the subject — so scoring on them rewards any clip whose description happens to say
 * "wide shot", which is most of them. That is noise dressed as evidence.
 *
 * The cap stays at 20. The list does not get longer, it gets more specific: the intent terms are
 * placed after the beat's own words and before the video title, so what falls off the end is the
 * least beat-specific material rather than anything the script actually asked for.
 */
function buildRelevanceKeywords(scene: Scene, beatText: string, videoTitle?: string): string[] {
  const intent = resolveBeatVisualIntent(beatText);
  const parts = [
    ...tokenizeForRelevance(beatText),
    ...intentSearchQueries(intent).flatMap((q) => tokenizeForRelevance(q)),
    ...tokenizeForRelevance(intent.visual_description ?? intent.visual_intent ?? ""),
    ...tokenizeForRelevance(intent.priority_subject ?? ""),
    ...tokenizeForRelevance(scene.visualCue),
    ...tokenizeForRelevance(scene.pexelsQuery),
    ...(scene.pexelsQueries ?? []).flatMap((q) => tokenizeForRelevance(q)),
    ...(scene.personNames ?? []).flatMap((n) => tokenizeForRelevance(n)),
    ...tokenizeForRelevance(asVideoTitleString(videoTitle)),
  ];
  return Array.from(new Set(parts)).slice(0, 20);
}

function scoreVisualRelevance(text: string, keywords: string[]): number {
  const t = text.toLowerCase();
  let score = 0;
  for (const kw of keywords) {
    if (kw.length < 3) continue;
    if (t.includes(kw)) score++;
  }
  return score;
}

/**
 * Problem 1/2 (production render finding — "Why Hitler Killed Himself and His Wife"):
 * scriptImageFallback candidates (generic image search, e.g. SerpAPI) previously skipped every
 * topical-relevance check in adoptClip. When the provider itself supplies real title text
 * (independent, non-circular evidence — not derived from our own search query), this checks it
 * actually shares *something* with the beat/query/video topic. Returns true (pass) whenever
 * there's no provider title to check, or no usable keywords to check it against — it only
 * rejects when there IS a title and it shares literally nothing with what we know about the
 * beat, exactly the pattern behind the off-topic image that shipped in production ("An open
 * letter to remove Richard M. Stallman...") on a Hitler beat.
 */
export function scriptImageFallbackPassesRelevanceFloor(
  providerTitle: string | undefined,
  sourceQuery: string,
  beatText: string,
  videoTitle?: string
): boolean {
  if (!providerTitle || !providerTitle.trim()) return true;
  const relKeywords = tokenizeForRelevance(`${sourceQuery} ${beatText} ${asVideoTitleString(videoTitle)}`);
  if (relKeywords.length === 0) return true;
  return scoreVisualRelevance(providerTitle, relKeywords) > 0;
}

/**
 * Point 8 (visual-selection quality upgrade — historical consistency): extracts a plausible
 * 4-digit year from free text. Returns null (never invents a year) when nothing matches.
 */
function extractYearFromText(text: string | undefined): number | null {
  if (!text) return null;
  const m = text.match(/\b(1[5-9][0-9]{2}|20[0-2][0-9])\b/);
  return m ? Number(m[0]) : null;
}

/**
 * Soft ranking bonus/penalty for historical-period alignment (Point 8). Compares a year found
 * in the beat/video context against a year found in the candidate's own real provider evidence
 * (dateHint first, then provider title/description — never the filename or our own search
 * query). Returns 0 whenever either side has no extractable year: missing historical metadata
 * is never itself a penalty, only a genuine, evidenced mismatch is. Deliberately bounded small
 * (-3..+2) so it can only nudge, never override, the existing relevance/entity/narration-match
 * terms it's added alongside in adoptClip's candidate sort.
 */
export function historicalDateAlignmentScore(
  providerText: { title?: string; description?: string; dateHint?: string } | undefined,
  beatText: string,
  /** RONDE 71: accepted and deliberately unused — see the target-year note below. */
  _videoTitle?: string
): number {
  // RONDE 71: the target period comes from the BEAT, never from the video title.
  //
  // Point 3 of this round promotes historical accuracy above media type in the ranking. Doing
  // that while the target year could be inherited from the title would make the promotion
  // actively harmful: a Blitz beat under a "April 1945" title would reserve +2 for a 1945
  // photograph and score the correct 1940 one at 0. Returning 0 for a beat that states no year
  // is a weaker signal; ranking on a year the beat never claimed is a wrong one.
  //
  // The parameter stays in the signature: callers pass it positionally, and removing it would
  // be a wider change than this round allows. It is prefixed to say the omission is deliberate.
  const targetYear = extractYearFromText(beatText);
  if (targetYear == null) return 0;
  const candidateYear =
    extractYearFromText(providerText?.dateHint) ??
    extractYearFromText(providerText?.title) ??
    extractYearFromText(providerText?.description);
  if (candidateYear == null) return 0;
  const diff = Math.abs(candidateYear - targetYear);
  // RONDE 79: the same ladder, at a weight that can actually decide something.
  //
  // At -3..+2 the period was noise beside a +12 person match: "Adolf Hitler speaking, 1939" beat
  // "Führerbunker Berlin April 1945" on a beat that says April 1945, because six years of error
  // cost nothing and the name paid twelve. The rungs and their meanings are unchanged — exact,
  // close, uncertain, clearly wrong — only the distance between them.
  //
  // The month rung is new and is the one §8 asked for: a beat that says "April 1945" and a
  // candidate that says "April 1945" agree on more than the year, and can say so.
  if (diff === 0) {
    const beatPeriod = extractPeriodPhrase(beatText);
    const candidateText = [providerText?.dateHint, providerText?.title, providerText?.description]
      .filter(Boolean)
      .join(" ");
    const sameMonth =
      beatPeriod.includes(" ") && candidateText.toLowerCase().includes(beatPeriod.toLowerCase());
    return sameMonth ? 8 : 6;
  }
  if (diff <= 2) return 3;
  if (diff <= 10) return 0;
  return -6;
}

/**
 * RONDE 71 — relevance decides; motion breaks a tie.
 *
 * The candidate sort used to open with
 *
 *     if (stillA !== stillB) return stillA - stillB;
 *
 * before a single score was compared. Media type therefore beat content outright: a mediocre
 * modern stock video won against a perfect Bundesarchiv photograph every time, on every beat.
 * For 1945 the best available material very often IS a photograph, so the rule was inverted
 * against exactly the documentaries this pipeline exists to make.
 *
 * Motion is still a real editorial preference — a montage of stills is worse television — so it
 * is not removed, only demoted. When two candidates are genuinely comparable on content, the
 * moving one still wins. When one is meaningfully more relevant, content wins.
 *
 * "Meaningfully" is MOTION_TIE_BREAK_MARGIN, measured in the same points the sort already uses:
 * an exact entity match is +12, a wrong period -3, a right one +2. A margin of 3 means a period
 * mismatch (5 points between a right and a wrong year) decides, while noise does not.
 *
 * Returns a comparator result for Array.sort — negative keeps `a` first.
 */
export const MOTION_TIE_BREAK_MARGIN = 3;

export function compareBeatCandidates(
  scoreA: number,
  isStillA: boolean,
  scoreB: number,
  isStillB: boolean
): number {
  const gap = scoreB - scoreA;
  // Content first: a clear difference in relevance is never overruled by media type.
  if (Math.abs(gap) > MOTION_TIE_BREAK_MARGIN) return gap;
  // Comparable on content — the existing motion preference decides, exactly as before.
  if (isStillA !== isStillB) return (isStillA ? 1 : 0) - (isStillB ? 1 : 0);
  return gap;
}

/**
 * How strongly a candidate's own provider evidence supports the beat's primary person.
 *
 * RONDE 79 adds "wrong". The four tiers before it could not tell these two apart:
 *
 *   beat: Hitler   candidate title: "Winston Churchill in London, 1945"   -> names someone else
 *   beat: Hitler   candidate title: "Führerbunker Berlin April 1945"      -> names nobody
 *
 * Both were "general" and both scored -6, which is the missing-metadata rule inverted: the
 * second candidate is the correct one for a Führerbunker beat and was being punished for not
 * repeating a name. "general" now means "this text names no person" and is neutral; a candidate
 * that names a DIFFERENT person is "wrong" and is the one that pays.
 */
export type EntityMatchTier = "exact" | "strong" | "general" | "wrong" | "unknown";

/**
 * Point 3 (next-level visual selection — hard entity matching): classifies a candidate against
 * the beat's primary person using only real, provider-authored text (never the search query or
 * filename). "unknown" whenever there's nothing to check — no primary person expected for this
 * beat, or the provider gave no text at all — per the explicit rule that missing metadata must
 * never itself be treated as a wrong candidate.
 *
 * RONDE 79: the "names a different person" case is separated out, using extractPersonNamesFromText
 * — the same classifier the beat side uses, not a second one — so "wrong" needs real evidence of
 * another person and never fires on a candidate that simply says nothing.
 */
export function classifyEntityMatchTier(
  primaryPerson: string | undefined,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): EntityMatchTier {
  const person = coercePersonName(primaryPerson ?? "");
  if (!person) return "unknown";
  const raw = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ")
    : "";
  const hay = raw.toLowerCase();
  if (!hay.trim()) return "unknown";
  const parts = person.toLowerCase().split(/\s+/).filter((p) => p.length >= 2);
  if (!parts.length) return "unknown";
  if (parts.length >= 2 ? parts.every((p) => hay.includes(p)) : hay.includes(parts[0])) return "exact";
  if (parts.length >= 2 && hay.includes(parts[parts.length - 1])) return "strong";
  // The candidate names a person, and it is not this one. That is evidence, not a gap.
  //
  // extractPersonNamesFromText is tuned for narration sentences; a provider caption is a
  // fragment, and on fragments it over-reaches — "Fuhrerbunker Berlin April 1945" comes back as
  // the person "Fuhrerbunker Berlin April". Reading that as a competing person would put a -12
  // on the single most relevant candidate a Führerbunker beat can have, so a caption name has to
  // clear a second bar before it counts: at least two tokens, none of them a month, a known
  // place, or a word the entity vocabulary already knows is a thing.
  const competing = extractPersonNamesFromText(raw).filter((n) => {
    const tokens = n.split(/\s+/).filter(Boolean);
    if (tokens.length < 2) return false;
    if (tokens.some((t) => MONTH_NAMES.has(t.toLowerCase()))) return false;
    if (tokens.some((t) => isNonPersonToken(t.toLowerCase()) || isKnownGeoPhrase(t))) return false;
    return !parts.some((p) => n.toLowerCase().includes(p));
  });
  if (competing.length > 0) return "wrong";
  return "general";
}

/**
 * Score per entity-match tier.
 *
 * RONDE 79 rebalances two of the five. "general" — the candidate's text names no person at all —
 * moves from -6 to 0, because a beat whose best available footage is an unattributed archive
 * still is not served by punishing it for saying nothing. "wrong" takes over the penalty and
 * takes it further: a candidate that demonstrably shows a different person is the one that should
 * lose, and it loses exactly as much as an exact match wins.
 *
 * exact stays at +12 so a real person match keeps its weight — but it no longer decides alone:
 * place, time, event and action now carry comparable weight beside it. See beatContextMatchScore.
 */
export function entityMatchTierScore(tier: EntityMatchTier): number {
  switch (tier) {
    case "exact":
      return 12;
    case "strong":
      return 6;
    case "wrong":
      return -12;
    case "general":
      return 0;
    case "unknown":
      return 0;
  }
}

/**
 * Point 4 (next-level visual selection — event/action matching): a small bonus when the beat
 * centers on a recognizable action (see extractEventCue) and the candidate's own provider text
 * mentions it. 0 (neutral) whenever the beat has no such action, or the candidate has no
 * provider text to check — never a penalty for simply lacking metadata. A provider title that
 * exists but doesn't mention the cue gets a small, bounded penalty (not a hard reject) since a
 * real photo of the right event doesn't always spell the verb out in its title.
 */
export function eventMatchScore(
  beatText: string,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const cue = extractEventCue(beatText);
  if (!cue) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  // RONDE 79: a text that does not spell the cue out is UNKNOWN, not WRONG. The -2 here was the
  // same missing-metadata-as-evidence mistake entityMatchTierScore's "general" tier made: a
  // Bundesarchiv still titled "Brandenburger Tor 1945" does not say "battle", and was being
  // marked down for it on a Battle of Berlin beat.
  return hay.includes(cue) ? 8 : 0;
}

/**
 * Point 5 (next-level visual selection — location consistency, ranking signal not a hard gate):
 * a small bonus when the render's current active location (already derived per-scene from
 * narration text — see dedup.assetDirectorActiveLocation) is actually mentioned in the
 * candidate's own provider text. Only ever a bonus, never a penalty for a candidate that simply
 * doesn't spell the place name out — many genuinely correct historical photos won't.
 */
export function locationMatchScore(
  activeLocation: string | null | undefined,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const loc = (activeLocation ?? "").trim().toLowerCase();
  if (!loc) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  return hay.includes(loc) ? 6 : 0;
}

/**
 * Point 18 (final visual intelligence hardening — object/topic beats): a small bonus when the
 * beat centers on a concrete physical object (see extractObjectCue) and the candidate's own
 * provider text mentions it — same shape as eventMatchScore/locationMatchScore. 0 (neutral)
 * whenever the beat names no object, or the candidate has no provider text to check.
 */
export function objectMatchScore(
  beatText: string,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const cue = extractObjectCue(beatText);
  if (!cue) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  // RONDE 79: a text that does not spell the cue out is UNKNOWN, not WRONG. The -2 here was the
  // same missing-metadata-as-evidence mistake entityMatchTierScore's "general" tier made: a
  // Bundesarchiv still titled "Brandenburger Tor 1945" does not say "battle", and was being
  // marked down for it on a Battle of Berlin beat.
  return hay.includes(cue) ? 8 : 0;
}

/* ═══════════════ RONDE 79 — the beat's own context, as a ranking signal ═══════════════ */

/**
 * RONDE 79 — the beat's place, scored against the candidate.
 *
 * There was no beat-place signal in the ranking at all. locationMatchScore (above) reads
 * dedup.assetDirectorActiveLocation, which is resolved per SCENE and is null on most renders, so
 * "Führerbunker" — a field RONDE 78 already extracts and already sends to the providers — never
 * reached the sort. That is the whole of why
 *
 *     beat: "…in the Führerbunker in April 1945."
 *     candidate: "Führerbunker Berlin April 1945"
 *
 * scored -10 and lost to a generic 1945 portrait.
 *
 * Four tiers, and the missing one is neutral:
 *
 *   exact    the candidate's text contains the place phrase                    +9
 *   partial  it contains a content word of the place or of the named event —   +4
 *            "Berlin" for a "Battle of Berlin" beat is genuinely relevant
 *   wrong    it names a known geographic place, the beat names a known         -6
 *            geographic place, and they are different ones
 *   unknown  it names no place this pipeline can recognise                      0
 *
 * "wrong" needs BOTH sides to be recognisable geography, via the worldGeoSlugs vocabulary the
 * place extractor already uses. A beat whose place is a building ("Führerbunker", "Reichstag")
 * cannot prove that a candidate mentioning London is wrong — London may well be where the
 * building is filed — so that case stays unknown rather than guessing.
 */
export function placeMatchScore(
  beatPlace: string,
  beatEvent: string,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const place = (beatPlace ?? "").trim();
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ")
    : "";
  if (!hay.trim()) return 0;
  const low = hay.toLowerCase();
  if (place && low.includes(place.toLowerCase())) return 9;

  const contentTokens = (phrase: string): string[] =>
    phrase
      .toLowerCase()
      .split(/\s+/)
      .map((t) => t.replace(/[^\p{L}'-]/gu, ""))
      .filter((t) => t.length >= 4 && !STOP_WORDS.has(t) && !NON_VISUAL_QUERY_WORDS.has(t));

  const tokens = [...contentTokens(place), ...contentTokens(beatEvent ?? "")];
  if (tokens.some((t) => low.includes(t))) return 4;

  if (place && isKnownGeoPhrase(place)) {
    const candidateGeo = [...hay.matchAll(new RegExp(CAPITALISED_RUN_SOURCE, "gu"))]
      .map((m) => stripLeadingArticle(m[0]))
      .filter((p) => p && isKnownGeoPhrase(p));
    if (candidateGeo.length > 0) return -6;
  }
  return 0;
}

/**
 * RONDE 79 — the beat's action, scored against the candidate.
 *
 * Deliberately the smallest of the five. A verb is corroboration, not identification: a still
 * captioned "Hitler dictating his testament" is better than one captioned "Hitler", but not by
 * as much as being in the right place in the right year. Matched on the stem so "dictated"
 * finds "dictating" and "dictates" without a conjugation table.
 *
 * Returns 0 — never a penalty — when the beat states no action or the candidate's text does not
 * describe one. Provider captions almost never name the verb, and §11's rule applies here more
 * than anywhere: a caption that says nothing about the action is not evidence of a wrong action.
 */
export function actionMatchScore(
  beatAction: string,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const action = (beatAction ?? "").trim().toLowerCase();
  if (action.length < 4) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  const stem = action.replace(/(?:ed|es|s|ing)$/u, "");
  if (stem.length < 3) return 0;
  return new RegExp(`\\b${stem}(?:e?[ds]|ing|es)?\\b`, "u").test(hay) ? 4 : 0;
}

/**
 * RONDE 79 — the beat's named event, scored against the candidate.
 *
 * eventMatchScore (above) tests EVENT_CUE_RE's bare verb and stays exactly as it is, because
 * classifyBeatFocus and beatFocusPenalty are built on that vocabulary. This scores the RONDE 78
 * phrase instead: "Battle of Berlin", "political testament", "fall of France". A candidate that
 * names the event outright is the single best piece of evidence a caption can carry.
 *
 * exact phrase +8; every content word present but not adjacent +5; nothing +0, never a penalty.
 */
export function eventPhraseMatchScore(
  beatEvent: string,
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  const event = (beatEvent ?? "").trim().toLowerCase();
  if (!event) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  if (hay.includes(event)) return 8;
  const words = event.split(/\s+/).filter((w) => w.length >= 4 && !STOP_WORDS.has(w));
  if (words.length >= 2 && words.every((w) => hay.includes(w))) return 5;
  return 0;
}

/**
 * RONDE 79 — a modern candidate on a historical beat.
 *
 * This is evidence, not a gap, which is why it is allowed to be a penalty: the candidate states
 * a year and that year is recent, while the beat states a period or names a historical event.
 * "Modern Berlin skyline 2019" is a real answer to "which Berlin?" and a wrong one for a beat
 * about the Battle of Berlin. Small — smaller than a wrong location — so it orders candidates
 * without ever outweighing a real place or person match.
 *
 * Silent when the candidate gives no year (unknown is not wrong) or when the beat is not
 * historical, so a modern beat is never penalised for modern footage.
 */
export function modernContextPenalty(
  beatYear: string,
  beatEvent: string,
  providerText: { title?: string; description?: string; dateHint?: string } | undefined
): number {
  const historical =
    /^(?:18|19)\d{2}$/.test((beatYear ?? "").trim()) ||
    /\p{Lu}/u.test((beatEvent ?? "").trim());
  if (!historical) return 0;
  const candidateYear =
    extractYearFromText(providerText?.dateHint) ??
    extractYearFromText(providerText?.title) ??
    extractYearFromText(providerText?.description);
  if (candidateYear == null) return 0;
  return candidateYear >= 1990 ? -3 : 0;
}

/** Every RONDE 79 context term for one candidate, and their sum. */
export interface BeatContextMatch {
  place: number;
  action: number;
  eventPhrase: number;
  modern: number;
  total: number;
}

/**
 * RONDE 79 — the four new terms, computed together from the RONDE 78 retrieval context.
 *
 * The context is the SAME object the providers were queried with — buildTypedRetrievalContext's
 * answer, assembled once per beat in adoptClip and handed to every candidate. There is no second
 * extraction layer for ranking: what the pipeline asked the archive for is what it scores the
 * archive's answer against.
 */
export function beatContextMatchScore(
  ctx: TypedRetrievalContext | undefined,
  providerText: { title?: string; description?: string; tags?: string; dateHint?: string } | undefined
): BeatContextMatch {
  if (!ctx) return { place: 0, action: 0, eventPhrase: 0, modern: 0, total: 0 };
  const place = placeMatchScore(ctx.place, ctx.event, providerText);
  const action = actionMatchScore(ctx.action, providerText);
  const eventPhrase = eventPhraseMatchScore(ctx.event, providerText);
  const modern = modernContextPenalty(ctx.year, ctx.event, providerText);
  return { place, action, eventPhrase, modern, total: place + action + eventPhrase + modern };
}

/**
 * RONDE 79 — the retrieval context for one beat, for the ranking side.
 *
 * Same call, same extractors, same answer as typedQueryPrefix's. Computed once per candidate
 * pool, never per candidate: no network call, no LLM, no new metadata.
 */
export function rankingContextForBeat(beatText: string): TypedRetrievalContext {
  const text = (beatText ?? "").trim();
  return buildTypedRetrievalContext(text, {
    persons: extractPersonNamesFromText(text),
    place: extractVisualPlacePhrase(text),
    action: extractActionCue(text),
  });
}

/**
 * Point 4 (final visual intelligence hardening — secondary entities): full person names the beat
 * mentions besides its primary person — e.g. "Eva Braun" in a beat about Hitler. Reuses
 * extractPersonNamesFromText, the same full-name extractor resolveScenePersons already uses
 * elsewhere in this file, instead of a new NER system. Capped to 2 names to keep the downstream
 * scoring bounded; the primary person (however it's cased/spelled in the beat) is excluded so a
 * beat that only names its already-known primary person yields no secondary entities.
 */
export function extractSecondaryEntities(beatText: string, primaryPerson: string | undefined): string[] {
  const primary = coercePersonName(primaryPerson ?? "").toLowerCase();
  return extractPersonNamesFromText(beatText)
    .filter((n) => n.toLowerCase() !== primary)
    .slice(0, 2);
}

/**
 * Point 4 (final visual intelligence hardening — secondary entities): a small, independent bonus
 * when the candidate's own provider text supports a secondary person the beat names alongside its
 * primary person (e.g. a beat about "Hitler and Eva Braun" — a candidate whose provider text says
 * "Eva Braun" is genuinely relevant even without naming Hitler). Deliberately smaller than
 * entityMatchTierScore's exact-primary-match bonus (12) so "primary + secondary" ranks above
 * "primary only", and "secondary only" still ranks above an unrelated/general candidate — without
 * ever letting a secondary-only match outscore a real primary match. 0 whenever the beat names no
 * secondary person or the candidate has no provider text (missing metadata is never a penalty).
 */
export function secondaryEntityMatchScore(
  secondaryEntities: string[],
  providerText: { title?: string; description?: string; tags?: string } | undefined
): number {
  if (!secondaryEntities.length) return 0;
  const hay = providerText
    ? [providerText.title, providerText.description, providerText.tags].filter(Boolean).join(" ").toLowerCase()
    : "";
  if (!hay.trim()) return 0;
  const matched = secondaryEntities.some((name) => {
    const parts = name.toLowerCase().split(/\s+/).filter((p) => p.length >= 2);
    return parts.length > 0 && parts.every((p) => hay.includes(p));
  });
  return matched ? 5 : 0;
}

/** What kind of concrete thing a beat is primarily asking the viewer to see. */
export type BeatFocus = "event" | "location" | "object" | "person" | "topic" | "general";

/**
 * Point 3 (final visual intelligence hardening — complete beat-focus analysis): classifies the
 * beat's dominant visual target using only signals already extracted elsewhere (extractEventCue,
 * extractLocationPhrase, extractObjectCue, opts.primaryPerson, isHistoricalDocumentary) — no new
 * NER/extraction. Precedence, most to least specific: an event cue is the most specific signal a
 * beat can carry, then a named place, then a named physical object, then a named person, then
 * "topic" (the beat matches a recognized documentary/historical topic per the existing
 * isHistoricalDocumentary check but names no more specific target), else "general" (truly nothing
 * to key off). videoTitle is optional purely for the topic check — every existing call site keeps
 * working unchanged without it (falls through to "general" instead of "topic" in that case).
 */
export function classifyBeatFocus(
  beatText: string,
  primaryPerson: string | undefined,
  videoTitle?: string
): BeatFocus {
  if (extractEventCue(beatText)) return "event";
  if (extractLocationPhrase(beatText)) return "location";
  if (extractObjectCue(beatText)) return "object";
  if (coercePersonName(primaryPerson ?? "")) return "person";
  if (isHistoricalDocumentary(beatText, asVideoTitleString(videoTitle))) return "topic";
  return "general";
}

/**
 * Point 4 (final multi-candidate visual selection patch — generic images fall harder): when a
 * beat has a specific, identifiable focus (event/location/person — i.e. classifyBeatFocus found
 * something concrete to look for) but a candidate's own provider evidence supports NONE of the
 * three next-level signals (no exact/strong entity match, no event match, no location match),
 * that candidate is genuinely generic for this beat — a clearer penalty than the flat "general"
 * entity-tier score alone, so a beat that names something specific pushes unrelated stock imagery
 * down harder than a vague beat would. Neutral (0) whenever the beat itself has no specific focus
 * to fail to match, the candidate matches at least one of the three signals, OR the candidate
 * simply has no provider text at all to judge — consistent with the established rule (Round 4,
 * point 12, explicitly preserved by this round's point 10) that missing metadata must never
 * itself be treated as evidence of a wrong candidate. This only fires when there IS real provider
 * text and it fails to substantiate any of the three signals — genuinely generic-for-this-beat,
 * not merely undocumented.
 */
export function beatFocusPenalty(
  focus: BeatFocus,
  entityTier: EntityMatchTier,
  eventScore: number,
  locationScore: number,
  hasProviderText: boolean,
  objectScore = 0
): number {
  if (focus === "general" || focus === "topic" || !hasProviderText) return 0;
  const hasPositiveSignal =
    entityTier === "exact" || entityTier === "strong" || eventScore > 0 || locationScore > 0 || objectScore > 0;
  return hasPositiveSignal ? 0 : -6;
}

/**
 * Point 17 (final visual intelligence hardening — generic person photo penalty): stronger than
 * beatFocusPenalty above. That function only fires when a candidate matches NONE of the specific
 * signals; this one fires when a candidate matches ONLY the primary person (a generic portrait)
 * while the beat's focus calls for something more specific (an event, a place, or an object) that
 * this candidate's provider text does not support — e.g. a plain Hitler portrait on a beat about
 * the Führerbunker or the wedding to Eva Braun. Acceptance criteria A/C from the final visual-
 * selection hardening task: a candidate with real event/location/object evidence must be able to
 * outrank one that only has the person right. Neutral (0) whenever the beat's focus is person/
 * topic/general (nothing more specific being asked for), the candidate already matches the more
 * specific signal too, or the candidate has no provider text (missing metadata is never a
 * penalty — only a real, evidenced "this is just a portrait" is penalized here).
 */
export function genericPersonPenalty(
  focus: BeatFocus,
  entityTier: EntityMatchTier,
  eventScore: number,
  locationScore: number,
  objectScore: number,
  hasProviderText: boolean
): number {
  if (!hasProviderText) return 0;
  if (focus !== "event" && focus !== "location" && focus !== "object") return 0;
  const matchesSpecificSignal = eventScore > 0 || locationScore > 0 || objectScore > 0;
  const isPersonOnlyMatch = (entityTier === "exact" || entityTier === "strong") && !matchesSpecificSignal;
  return isPersonOnlyMatch ? -8 : 0;
}

/**
 * Limited cross-provider candidate pooling patch (point 10 — smart early exit): true when a
 * single already-fetched candidate is strong enough that a bounded multi-provider still-image
 * pool (see fetchBeatAuthenticStills) can stop collecting from further sources and adopt from
 * what it already has — an exact entity match, plus an actual event/location/object match when
 * the beat's own focus calls for one. Reuses exactly the same signals the pool's own ranking
 * already scores candidates on; not a new/parallel scoring system, just a stop condition built
 * from them.
 */
export function candidatePoolEarlyExitReady(
  focus: BeatFocus,
  entityTier: EntityMatchTier,
  eventScore: number,
  locationScore: number,
  objectScore = 0
): boolean {
  if (entityTier !== "exact") return false;
  if (focus === "event") return eventScore > 0;
  if (focus === "location") return locationScore > 0;
  if (focus === "object") return objectScore > 0;
  return true;
}

/** Provider-authored text about a candidate, in the one shape every scorer below reads. */
export type CandidateProviderText = {
  title?: string;
  description?: string;
  tags?: string;
  dateHint?: string;
};

/** Every RONDE 79 signal for one candidate, plus the sum the ranking sorts on. */
export type BeatRankingSignals = {
  tier: EntityMatchTier;
  entity: number;
  secondary: number;
  event: number;
  location: number;
  object: number;
  date: number;
  place: number;
  eventPhrase: number;
  action: number;
  modern: number;
  negativeEvidence: number;
  genericPenalty: number;
  total: number;
};

/** The per-beat inputs that are identical for every candidate in a pool — resolved once. */
export type BeatRankingContext = {
  beatText: string;
  primaryPerson?: string;
  videoTitle?: string;
  activeLocation?: string | null;
  rankCtx: TypedRetrievalContext;
  focus: BeatFocus;
  secondaryEntities: string[];
};

export function buildBeatRankingContext(
  beatText: string,
  opts: { primaryPerson?: string; videoTitle?: string; activeLocation?: string | null } = {}
): BeatRankingContext {
  return {
    beatText,
    primaryPerson: opts.primaryPerson,
    videoTitle: opts.videoTitle,
    activeLocation: opts.activeLocation ?? null,
    rankCtx: rankingContextForBeat(beatText),
    focus: classifyBeatFocus(beatText, opts.primaryPerson, opts.videoTitle),
    secondaryEntities: extractSecondaryEntities(beatText, opts.primaryPerson),
  };
}

/**
 * RONDE 86 — the RONDE 79 ranking, extracted so more than one path can use it.
 *
 * This is `adoptClip`'s `nextLevelScore`, moved out of its closure without a single term added,
 * removed or reweighted. It was written for the web-provider path and lived where only that path
 * could reach it, which is why the audit found the curated-archive route ranking its candidates
 * on a keyword-tag score alone: the archive scan, the similar-match route and the topic-anchored
 * route each ordered candidates by `pick.score` and then adopted whichever one first cleared the
 * gates. Render 536 printed not one [VisualSelection] line, because the only code that produces
 * one was on the other path.
 *
 * Taking it out of the closure means there is exactly one implementation of "how well does this
 * candidate match this beat", and both paths now answer the question the same way.
 */
export function scoreCandidateAgainstBeat(
  providerText: CandidateProviderText | undefined,
  ctx: BeatRankingContext
): BeatRankingSignals {
  const pt = providerText;
  const tier = classifyEntityMatchTier(ctx.primaryPerson, pt);
  const entity = entityMatchTierScore(tier);
  const secondary = secondaryEntityMatchScore(ctx.secondaryEntities, pt);
  const event = eventMatchScore(ctx.beatText, pt);
  const location = locationMatchScore(ctx.activeLocation, pt);
  const object = objectMatchScore(ctx.beatText, pt);
  const date = historicalDateAlignmentScore(pt, ctx.beatText, ctx.videoTitle);
  const context = beatContextMatchScore(ctx.rankCtx, pt);
  const hasProviderText = Boolean(pt && (pt.title || pt.description || pt.tags));
  // RONDE 79: place/event evidence counts as a positive signal for the focus penalties too.
  const specific = Math.max(event, location, context.place, context.eventPhrase);
  const negativeEvidence = beatFocusPenalty(ctx.focus, tier, event, specific, hasProviderText, object);
  const genericPenalty = genericPersonPenalty(ctx.focus, tier, event, specific, object, hasProviderText);
  return {
    tier,
    entity,
    secondary,
    event,
    location,
    object,
    date,
    place: context.place,
    eventPhrase: context.eventPhrase,
    action: context.action,
    modern: context.modern,
    negativeEvidence,
    genericPenalty,
    total:
      date +
      entity +
      // RONDE 79: eventMatchScore's verb and eventPhraseMatchScore's phrase are the SAME evidence
      // read at two resolutions — "battle" and "Battle of Berlin". Summing them paid twice for one
      // caption, so the stronger reading is taken and the other discarded.
      Math.max(event, context.eventPhrase) +
      location +
      object +
      secondary +
      context.place +
      context.action +
      context.modern +
      negativeEvidence +
      genericPenalty,
  };
}

function buildSceneBeats(
  scene: Scene,
  duration: number,
  maxBeatsCap = 16,
  videoTitle?: string,
  scenePersons: string[] = []
): SceneBeat[] {
  const minVoiceClips = 2;
  const cadenceCap = maxBeatsCap;
  const targetBeats = Math.max(minVoiceClips, Math.ceil(duration / effectiveBeatSec()));
  const beatCap = Math.max(minVoiceClips, Math.min(cadenceCap, targetBeats));

  const rawSentences =
    scene.text.match(/[^.!?]+[.!?]+/g)?.map((s) => s.trim()).filter((s) => s.length > 5) ??
    [scene.text.trim()];

  // Eén beat per zin; alleen samenvoegen als we boven het beat-cap zitten.
  let groups: { text: string; sentenceCount: number }[] = rawSentences.map((text) => ({
    text,
    sentenceCount: 1,
  }));

  while (groups.length < targetBeats && groups.length > 0) {
    let splitIdx = 0;
    let maxWords = 0;
    for (let i = 0; i < groups.length; i++) {
      const w = groups[i].text.split(/\s+/).filter(Boolean).length;
      if (w > maxWords) {
        maxWords = w;
        splitIdx = i;
      }
    }
    const words = groups[splitIdx].text.split(/\s+/).filter(Boolean);
    const minSplitWords = 16;
    if (words.length < minSplitWords) break;
    const mid = Math.ceil(words.length / 2);
    const a = words.slice(0, mid).join(" ");
    const b = words.slice(mid).join(" ");
    groups.splice(splitIdx, 1, { text: a, sentenceCount: 1 }, { text: b, sentenceCount: 1 });
  }

  while (groups.length > beatCap) {
    let mergeIdx = 0;
    let minWords = Infinity;
    for (let i = 0; i < groups.length - 1; i++) {
      const w = groups[i].text.split(/\s+/).filter(Boolean).length;
      if (w < minWords) {
        minWords = w;
        mergeIdx = i;
      }
    }
    const merged = `${groups[mergeIdx].text} ${groups[mergeIdx + 1].text}`;
    groups.splice(mergeIdx, 2, {
      text: merged,
      sentenceCount: groups[mergeIdx].sentenceCount + groups[mergeIdx + 1].sentenceCount,
    });
  }

  const beats: SceneBeat[] = [];
  for (let i = 0; i < groups.length; i++) {
    const text = groups[i].text;
    const subjects = beatVisualSearchSubjects(text);
    const visualAnchor = extractPrimaryVisualAnchor(text);
    const geoTag = extractPrimaryGeoSearchTag(text);
    let powerWord = subjects[0] ?? extractPowerWordFromSentence(text, scenePersons);
    if (visualAnchor) {
      powerWord = visualAnchor;
    } else if (geoTag) {
      powerWord = geoTag;
    }
    let searchQuery =
      subjects[0] ?? visualAnchor ?? geoTag ?? simplifyStockSearchWord(powerWord, text, true);
    if (!searchQuery || isBlockedStockQuery(searchQuery)) {
      searchQuery = stockQueryFromBeatScript(text, scenePersons, scene.text, videoTitle);
    }
    let holdSec = estimateBeatHoldSec(text, groups[i].sentenceCount);
    const visualCues = extractInlineVisualCues(text);
    const visualDescription =
      visualCues[0] ??
      beatVisualDescriptionFromIntent(text) ??
      (visualAnchor || geoTag || subjects[1] || undefined);
    beats.push({
      index: i,
      text,
      searchQuery,
      powerWord,
      keywords: buildRelevanceKeywords(scene, text),
      holdSec,
      visualDescription,
    });
  }

  

  return beats;
}

/** RONDE 647 — the adoption loop itself, for a test that hands it a real file. */
export function adoptClipForTest(...args: Parameters<typeof adoptClip>): ReturnType<typeof adoptClip> {
  return adoptClip(...args);
}

async function adoptClip(
  paths: string[],
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  beatText: string,
  workDir: string,
  sourceQuery = "",
  opts: VisualAdoptOptions = {}
): Promise<string | null> {
  const keywords = opts.keywords ?? [];
  const muskTopic = opts.muskTopic ?? false;
  const strictBeat = strictVoiceVisualMatchEnabled() && !opts.scriptImageFallback;
  const requireBeat = opts.requireBeatMatch || strictBeat;
  const scriptAnchored = opts.scriptAnchored || strictBeat;
  const gateVisualDesc =
    [opts.visualDescription, opts.semanticSummary].filter(Boolean).join(". ").slice(0, 320) ||
    undefined;
  const entityRules = extractBeatRealEntities(beatText, opts.sceneText ?? "", opts.videoTitle ?? "");

  /**
   * RONDE 95 — the retrieval side of the per-beat funnel, counted where retrieval actually ends.
   *
   * `adoptClip` is the multi-candidate entry point: 29 call sites hand it the paths a route
   * produced for one beat. Counting here rather than inside each provider is deliberate — it is
   * the boundary at which "what retrieval produced for this beat" is a single, complete number,
   * and it is one site instead of a rule 29 routes would have to remember.
   *
   * `deduped` is measured against the content key, which is the identity the rest of the pipeline
   * uses; two paths for the same asset are one candidate, and saying otherwise would inflate the
   * retrieved column exactly where render 568's 3995 came from.
   */
  {
    const uniqueKeys = new Set(paths.map((p) => clipContentKey(p)));
    noteRetrieved(dedup.beatShortlist, sceneIndex, beatIndex, paths.length, {
      normalized: paths.length,
      deduped: Math.max(0, paths.length - uniqueKeys.size),
    });
  }

  // Fase 4 (beeldkwaliteit vervolgpatch): generic providerText fallback for every provider that
  // tags its output path (tagPathWithProviderAsset) and records real title/description/tags via
  // putCachedProviderAsset — not just the CelebrityClipCandidate-returning providers the earlier
  // P0/P1 patch wired directly. clipContentKey() on a provider-tagged path is exactly the same
  // string as the providerAssetKey() the asset was cached under, so this is a plain, read-only
  // Map lookup — no new cache, no network call, and it never overwrites metadata a more specific
  // call site (e.g. adoptBestCelebrityClip) already set.
  // Moved ahead of the candidate sort below (point 8, visual-selection quality upgrade) so the
  // sort's historicalDateAlignmentScore term can actually see providerText for candidates that
  // only ever get it through this generic fallback — order doesn't matter for this loop itself,
  // it just populates a Map keyed by path.
  for (const p of paths) {
    const existing = dedup.clipAnnotationMeta.get(p);
    if (existing?.providerText) continue;
    const cachedText = dedup.sourcingCache.assets.get(clipContentKey(p))?.providerText;
    if (cachedText) {
      dedup.clipAnnotationMeta.set(p, { ...existing, providerText: cachedText });
    }
  }

  // Points 3/4/5 (next-level visual selection): entity-match tier, event/action match, and
  // location match all read the same real providerText Map lookup adoptClip's generic fallback
  // above already populates — computed once per candidate path here rather than inline per
  // comparison, to avoid recomputing the same providerText lookup/tier classification twice
  // per sort comparator call.
  // Point 3/4 (final multi-candidate visual selection patch — contextual beat type + sharper
  // generic-image penalty): the beat's dominant focus is the same for every candidate in this
  // pool, so it's classified once outside the per-path closure below.
  // RONDE 79: the beat's own retrieval context, assembled once for the whole pool. This is the
  // same object RONDE 78 builds the provider queries from, so the sort scores candidates against
  // exactly the question that was asked.
  // RONDE 86: assembled through the shared builder, and scored through the shared scorer, so this
  // path and the curated-archive path answer "how well does this match" with the same code.
  const rankingCtx = buildBeatRankingContext(beatText, {
    primaryPerson: opts.primaryPerson,
    videoTitle: opts.videoTitle,
    activeLocation: dedup.assetDirectorActiveLocation,
  });
  const beatFocus = rankingCtx.focus;
  const nextLevelScore = (p: string): number =>
    scoreCandidateAgainstBeat(dedup.clipAnnotationMeta.get(p)?.providerText ?? undefined, rankingCtx).total;
  // RONDE 71: the same score terms as before, in the same order, computed once per candidate
  // instead of twice per comparison. Nothing was added to or removed from the sum.
  const candidateScore = (p: string): number =>
    scoreVisualRelevance(`${sourceQuery} ${path.basename(p)} ${beatText}`, keywords) +
    scoreVisualRelevance(beatText, tokenizeForRelevance(sourceQuery)) +
    scoreBeatNarrationMatch(beatText, sourceQuery, p) * 4 +
    realEntityScore(entityRules, sourceQuery, p) +
    nextLevelScore(p) +
    (muskTopic ? muskBrandScore(sourceQuery, p) : 0);
  /**
   * RONDE 96 — resolved BEFORE the sort, because the sort now reads it.
   *
   * The contract was previously fetched below, purely for `scoreRetrievalContract`. Moving it up
   * changes nothing about what it contains — `getRetrievalContract` is a map lookup on a plan the
   * render already holds — and it lets the beat's intent exist before the first ordering decision
   * is taken, rather than being joined after the order was already fixed.
   */
  const _contract = dedup.documentaryPlan
    ? (await import("./documentaryPlanningEngine")).getRetrievalContract(
        dedup.documentaryPlan,
        sceneIndex,
        beatIndex
      )
    : null;

  /**
   * RONDE 96 — THE BEAT'S INTENT, JOINED HERE BECAUSE THIS IS WHERE ALL THREE PARTS EXIST.
   *
   * `_contract` two lines up is the planner's half; `buildVerifiedQueryContextForBeat` is the
   * extractors' half. `adoptClip` is the only place in the file that holds both at once, and it
   * holds them for the beat that is about to be ranked — so the join costs one call and the
   * ranking below can read what the beat is actually looking for instead of inferring it from a
   * filename.
   *
   * Cached per beat: the second route to reach this beat gets the record the first one built, so
   * two routes can never rank against two different readings of the same sentence.
   */
  const _intent = ensureBeatVisualIntent(dedup.beatIntent, {
    sceneIndex,
    beatIndex,
    ctx: buildVerifiedQueryContextForBeat(beatText, {
      sceneText: opts.sceneText,
    }),
    contract: _contract,
    narrativePurpose: _contract?.visualGoal,
  });
  if (!dedup.beatIntentLogged.has(`s${sceneIndex}b${beatIndex}`)) {
    dedup.beatIntentLogged.add(`s${sceneIndex}b${beatIndex}`);
    console.log(formatVisualIntent(_intent));
  }

  /**
   * RONDE 96 — the beat's intent is a TERM in the existing score, not a second ranker.
   *
   * `intentMatchScore` reads the provider's own text — the title, description and tags the asset
   * arrived with — against the ten fields the beat stated it was looking for, and adds the result
   * to the score `candidateScore` already produces. It does not admit, refuse or override
   * anything: eligibility, the shortlist bound and the vision verdict keep their own jobs, and a
   * scorer that could also reject would be the second selection engine the brief forbids.
   *
   * Why it belongs here rather than deeper: this is the only sort that sees the whole candidate
   * pool for one beat. A candidate the beat actually asked for should reach the bounded shortlist
   * before one it did not, and after RONDE 95 the shortlist is small — so the ORDER candidates
   * arrive in now decides which ones ever get looked at.
   */
  const intentScore = (p: string): number =>
    intentMatchScore(
      _intent,
      [dedup.clipAnnotationMeta.get(p)?.providerText, path.basename(p)].filter(Boolean).join(" ")
    );
  /**
   * RONDE 265 — THE BEAT'S HARD REQUIREMENTS COME BEFORE THE SUM.
   *
   * Render evidence: a candidate with `event +0 place +0 date +0 action +0` ranked first on
   * `narration +96 visual +44 finalScore 139`. The two terms that carried it are the two that say
   * least about whether this is the right footage for this sentence.
   *
   * Raising the event term or lowering the narration term would move a threshold, not change a
   * shape: any soft signal large enough still buys its way past any hard one. What was missing is
   * a KIND rather than a WEIGHT — a beat that names an event, a place and a period has said three
   * things that are TRUE OR FALSE about a candidate, not more or less true.
   *
   * So they are compared first, and the existing score decides everything within a tier. Nothing
   * is admitted or refused here: a candidate satisfying none still ranks, still reaches the
   * shortlist, still gets a vision verdict — it ranks below one that satisfies more. A beat that
   * states no requirement is ordered exactly as it was.
   *
   * Memoised per path because `scoreCandidateAgainstBeat` is not free and a sort calls its
   * comparator O(n log n) times for n candidates.
   */
  const hardMatchCache = new Map<string, ReturnType<typeof documentaryHardMatch>>();
  const hardMatchOf = (p: string) => {
    let m = hardMatchCache.get(p);
    if (!m) {
      const sig = scoreCandidateAgainstBeat(
        dedup.clipAnnotationMeta.get(p)?.providerText ?? undefined,
        rankingCtx
      );
      hardMatchCache.set(p, (m = documentaryHardMatch(_intent, sig)));
    }
    return m;
  };
  const sortedPaths = [...paths].sort((a, b) => {
    const hard = compareHardMatch(hardMatchOf(a), hardMatchOf(b));
    if (hard !== 0) return hard;
    // Content decides; motion only breaks a tie. See compareBeatCandidates.
    return compareBeatCandidates(
      candidateScore(a) + intentScore(a),
      isStillPhotoClip(a),
      candidateScore(b) + intentScore(b),
      isStillPhotoClip(b)
    );
  });
  if (sortedPaths.length > 1) {
    const winnerHard = hardMatchOf(sortedPaths[0]!);
    if (winnerHard.stated > 0) {
      console.log(
        formatHardMatch(sceneIndex, beatIndex, winnerHard, hardMatchOf(sortedPaths[1]!))
      );
    }
  }

  // Point 9 (final multi-candidate visual selection patch — score explainability): log the
  // winning pre-AssetDirector candidate's full signal breakdown — entity/event/location/date
  // from the next-level signals (points 3/4/5, historicalDateAlignmentScore), visual/narration
  // from this same sort's pre-existing terms, and negativeEvidence from the new focus-aware
  // penalty (point 4) — in one line, reusing the file's established
  // `[Pipeline] Scene X beat Y: ...` log convention instead of a new logging system.
  // Curated-archive candidates that proceed to AssetDirector below get a second, richer
  // breakdown (including the diversity modifier) from the existing logAssetDirectorChoice.
  if (sortedPaths.length > 1) {
    const fmt = (n: number) => (n >= 0 ? `+${n}` : `${n}`);
    // Point 20 (final visual intelligence hardening — score explainability): a small, local
    // per-candidate signal breakdown, reused for both the winner and the runner-up so the log can
    // explain WHY the winner won, not just what it scored — no new scoring system, just the same
    // signals nextLevelScore already sums, computed once per candidate for logging.
    const breakdown = (p: string) => {
      // RONDE 86: the same shared scorer the sort above uses, so the explanation can no longer
      // drift away from the decision it is explaining.
      const s = scoreCandidateAgainstBeat(dedup.clipAnnotationMeta.get(p)?.providerText ?? undefined, rankingCtx);
      const visual =
        scoreVisualRelevance(`${sourceQuery} ${path.basename(p)} ${beatText}`, keywords) +
        scoreVisualRelevance(beatText, tokenizeForRelevance(sourceQuery));
      const narration = scoreBeatNarrationMatch(beatText, sourceQuery, p) * 4;
      return {
        tier: s.tier,
        entity: s.entity,
        secondary: s.secondary,
        event: s.event,
        location: s.location,
        object: s.object,
        date: s.date,
        context: { place: s.place, eventPhrase: s.eventPhrase, action: s.action, modern: s.modern },
        visual,
        narration,
        negativeEvidence: s.negativeEvidence,
        genericPenalty: s.genericPenalty,
        finalScore: s.total + visual + narration,
      };
    };
    const topPath = sortedPaths[0]!;
    const top = breakdown(topPath);
    console.log(
      `[VisualSelection] scene=${sceneIndex} beat=${beatIndex} pool=${sortedPaths.length} ` +
        `winner=${path.basename(topPath)} focus=${beatFocus} primaryEntity=${fmt(top.entity)}(${top.tier}) ` +
        `secondaryEntity=${fmt(top.secondary)} event=${fmt(top.event)} location=${fmt(top.location)} ` +
        `object=${fmt(top.object)} date=${fmt(top.date)} place=${fmt(top.context.place)} ` +
        `eventPhrase=${fmt(top.context.eventPhrase)} action=${fmt(top.context.action)} ` +
        `modern=${fmt(top.context.modern)} narration=${fmt(top.narration)} visual=${fmt(top.visual)} ` +
        `negativeEvidence=${fmt(top.negativeEvidence)} genericPenalty=${fmt(top.genericPenalty)} finalScore=${fmt(top.finalScore)}`
    );
    if (sortedPaths.length > 2) {
      const runnerUpPath = sortedPaths[1]!;
      const runnerUp = breakdown(runnerUpPath);
      const margin = top.finalScore - runnerUp.finalScore;
      console.log(
        `[VisualSelection] scene=${sceneIndex} beat=${beatIndex} runner-up=${path.basename(runnerUpPath)} ` +
          `score=${fmt(runnerUp.finalScore)} vs winner score=${fmt(top.finalScore)} margin=${fmt(margin)} ` +
          `reason=${
            [
              top.entity !== runnerUp.entity ? "entity" : null,
              top.secondary !== runnerUp.secondary ? "secondaryEntity" : null,
              top.event !== runnerUp.event ? "event" : null,
              top.location !== runnerUp.location ? "location" : null,
              top.object !== runnerUp.object ? "object" : null,
              top.date !== runnerUp.date ? "date" : null,
              top.genericPenalty !== runnerUp.genericPenalty ? "genericPenalty" : null,
            ]
              .filter(Boolean)
              .join(",") || "visual/narration only"
          }`
      );
    }
  }

  // Pull per-beat data from planning layers (storyboard + rhythm)
  const _shot = getShotForBeat(sceneIndex, beatIndex);
  /**
   * R195 — THE PLANNED MOVEMENT BAND, READ WHERE IT IS ACTUALLY NEEDED.
   *
   * The rhythm engine's own writer runs in the COMPOSE stage, and its comment says the targets are
   * stored "so AssetDirector can use them during retrieval" — which had already finished for that
   * scene, so this lookup always missed. `buildRhythmProfile` is documented as "Pure analysis —
   * does not modify any state" and needs nothing but the beat texts, which this render has had
   * since `sceneBeatsBySceneIndex` was written. So the band is derived here on first use and
   * memoised in the same map, rather than waiting for a write that comes too late.
   */
  const _rhythmBand = ((): readonly [number, number] | null => {
    const key = `s${sceneIndex}b${beatIndex}`;
    const known = dedup.beatRhythmTargets?.get(key);
    if (known) return known;
    if (!visualRhythmEngineEnabled()) return null;
    const beats = dedup.sceneBeatsBySceneIndex.get(sceneIndex);
    if (!beats?.length) return null;
    const profile = buildRhythmProfile(beats.map((b) => b.text));
    profile.motionTargets.forEach((band, bi) => {
      dedup.beatRhythmTargets.set(`s${sceneIndex}b${bi}`, band);
    });
    return dedup.beatRhythmTargets.get(key) ?? null;
  })();
  /**
   * The retrieval contract and the beat's intent are resolved ABOVE, before the sort, because
   * RONDE 96's ranking reads them. See the note there; `_contract` still answers the two
   * questions it answered before — `scoreRetrievalContract` and `preferredShot`.
   */
  /**
   * The framing this beat was planned for: the storyboard's, or the contract's.
   *
   * ── Why the storyboard wins ─────────────────────────────────────────────────────────────────
   *
   * It is the more specific answer. The storyboard planner reads the beat's own sentence and the
   * scene around it; the contract derives its shot from the beat's visual GOAL and narrative act,
   * which is a sound default and a coarser one. Where the storyboard has an opinion it is better
   * informed, so it is used.
   *
   * ── Why the contract is not simply ignored ──────────────────────────────────────────────────
   *
   * The storyboard is an LLM call that can be switched off, time out or return nothing for a beat,
   * and `getShotForBeat` then answers null. Before this the whole shot signal went with it: a beat
   * with no storyboard entry was ranked as though nobody had planned its framing, even though the
   * plan on disk said what it should be. Two sources, one channel, stated precedence — rather than
   * a second scoring path, which is how a system ends up with two rankers that disagree.
   */
  const _plannedShot = _shot?.shotType ?? _contract?.preferredShot ?? null;

  // Asset Director: re-rank using global video context (blueprint, diversity, continuity,
  // storyboard shot type, rhythm motion target, and per-clip annotation metadata)
  const adCtx: AssetDirectorContext = {
    usedPaths: dedup.usedPaths,
    usedCategories: dedup.usedCategories,
    blueprint: dedup.videoBlueprint,
    budgetTracker: dedup.visualBudgetTracker,
    sceneAdoptedClips: dedup.assetDirectorSceneClips,
    prevSceneClips: dedup.assetDirectorPrevSceneClips,
    editorialMemory: dedup.editorialMemory,
    activeEntity: dedup.assetDirectorActiveEntity,
    activeLocation: dedup.assetDirectorActiveLocation,
    activeEra: dedup.assetDirectorActiveEra,
    /**
     * RONDE 220 — the script's own statement of the intended visual, for the layer that decides
     * WHICH candidates the picture editor is shown.
     *
     * RONDE 218 and 219 gave this to the two relevance lists, which judge a candidate once it is
     * in hand. The ranking runs before them and is the reason a candidate is in hand at all: the
     * per-beat look budget is small, so a candidate ranked twelfth is usually never judged.
     *
     * Same resolver as those two rounds and as `beatVisualSearchSubjects`, so the query, the
     * ranking and both scorers cannot come to different conclusions about one beat.
     */
    intentText: (() => {
      const it = resolveBeatVisualIntent(beatText);
      return [
        ...intentSearchQueries(it),
        it.visual_description ?? it.visual_intent ?? "",
        it.priority_subject ?? "",
      ]
        .filter(Boolean)
        .join(" ")
        .trim() || null;
    })(),
    /**
     * R195 — THE PLANNED MOVEMENT BAND, FROM WHICHEVER PLANNER ACTUALLY PLANNED IT.
     *
     * Two producers, stated in precedence rather than merged. `RetrievalContract.motionRange` is
     * the more specific: the Documentary Planning Engine derived it from this beat's narrative act
     * and visual goal, and it is resolved before retrieval. `RhythmProfile.motionTargets` is the
     * general one, read from the beat's own energy words, and it stands when there is no contract.
     *
     * Both are already `[min, max]` on a 0–100 scale, and so is the `motionLevel` the scorer reads
     * off the candidate. Nothing is converted, weighted or invented on the way here.
     */
    targetMotionRange: _contract?.motionRange ?? _rhythmBand ?? null,
    plannedShotType: _plannedShot,
    /**
     * R195 — THE FRAMING THIS BEAT WAS PLANNED FOR, IN THE WORDS THE ANNOTATIONS USE.
     *
     * `expectedCinematicTags` is documented as "Set from blueprint visual type or editorial
     * directive" and had no producer, so `scoreCinematicTags`' direct-match branch never fired.
     * `shotSearchTerms` is the existing vocabulary for exactly this: the canonical phrasing of a
     * framing ("establishing shot", "wide shot", "aerial", "archival footage"), already asserted
     * to be gate-safe by `subjectSearchTerms.test.ts`, and already the words the scorer's own
     * CINEMATIC_KEYWORD_MAP matches against. So this is the planned shot in the annotation's
     * vocabulary, not a mapping invented here — and a framing with no phrasing returns an empty
     * list, which the scorer reads as nothing to say.
     */
    expectedCinematicTags: [...shotSearchTerms(_plannedShot)],
    expectedAudioTypes: beatExpectedAudioTypes(dedup, sceneIndex, beatIndex, opts.sceneText),
    /**
     * The framings of the shots already in this scene, as a model saw them.
     *
     * Reads the same per-clip meta the judge writes its observation into, so the run penalty
     * compares like with like. A clip nobody judged returns undefined and the filename reading
     * stands, exactly as before.
     */
    shotTypeOf: (clipPath: string) =>
      dedup.clipAnnotationMeta.get(clipPath)?.observedShotType ??
      dedup.clipAnnotationMeta.get(clipPath)?.annotation?.cinematography?.shotType ??
      null,
    callbacksPlaced: dedup.assetDirectorCallbacksPlaced,
    retrievalContract: _contract,
    /**
     * R195 — HOW LONG THIS BEAT IS ON SCREEN, WHICH TWO RANKING READERS ASKED FOR AND NEVER GOT.
     *
     * `beatDurationSec` is documented on AssetDirectorContext as "used for temporal best-window
     * selection", and two things read it:
     *
     *   · `computeArchiveMetadataScores` → `selectBestWindowForBeat`, the temporal bonus;
     *   · `computeTrimHint` → the trim hint `adoptClip` applies through
     *     `applySegmentTrimIfNeeded`, which is how a long archive clip is cut down to the window
     *     that actually matches this beat.
     *
     * Both are gated `beatDurationSec && beatDurationSec > 0`, both flags default ON
     * (TEMPORAL_SCENE_INTELLIGENCE_ENABLED, ARCHIVE_V4_METADATA_SCORING_ENABLED) — and the one
     * production call site never set the field. So the whole temporal-window path was switched on
     * in configuration and dead in fact, and the scorer's `else if (… no beat duration …)` branch,
     * written as the exceptional case, was the only branch that ever ran.
     *
     * Read from `sceneBeatsBySceneIndex`, which is documented as "the one function every
     * beat-resolving route calls" and stores the array BY REFERENCE — so when the TTS alignment
     * later writes a measured hold onto the beat, this reads the measured one rather than a copy
     * of the estimate. No new store, no threading through twenty-nine call sites.
     */
    beatDurationSec: dedup.sceneBeatsBySceneIndex.get(sceneIndex)?.[beatIndex]?.holdSec,
  };
  const adResult = rankCandidatesWithContext(sortedPaths, beatText, sceneIndex, beatIndex, adCtx, dedup.clipAnnotationMeta);
  /**
   * R195 — whether the movement plan reached a candidate, recorded where the answer is known.
   *
   * `motionLevel` on the breakdown is what `inferMotionLevel` read, or null when neither an
   * annotation nor a filename cue could say. Two sets rather than a single counter: a beat nobody
   * planned a band for and a beat whose candidates could not be measured need opposite fixes, and
   * the feature matrix reports them as different gaps.
   */
  if (adCtx.targetMotionRange) dedup.motionBandBeats.add(`s${sceneIndex}b${beatIndex}`);
  if (adResult.topScore?.breakdown.motionLevel != null) {
    dedup.motionScoredBeats.add(`s${sceneIndex}b${beatIndex}`);
  }
  if (adResult.reordered && adResult.topScore) {
    logAssetDirectorChoice(adResult.rankedPaths[0]!, sceneIndex, beatIndex, beatText, adResult.topScore);
  }

  // Documentary Taste Model: final human-editor-style re-rank
  // Build per-path AssetDirector score map for blending
  const adScores = new Map<string, number>();
  if (adResult.topScore) {
    for (let _i = 0; _i < adResult.rankedPaths.length; _i++) {
      // Top candidate gets the actual score; others get a decayed estimate
      adScores.set(adResult.rankedPaths[_i]!, Math.max(0, adResult.topScore.finalScore - _i * 5));
    }
  }
  dedup.tasteModelCtx.activeEntity = dedup.assetDirectorActiveEntity;
  dedup.tasteModelCtx.activeEra    = dedup.assetDirectorActiveEra;
  dedup.tasteModelCtx.beatText     = beatText;
  const tasteResult = applyDocumentaryTasteModel(
    adResult.rankedPaths,
    beatText,
    sceneIndex,
    beatIndex,
    dedup.tasteModelCtx,
    dedup.clipAnnotationMeta,
    adScores
  );
  // RONDE 67: a working copy, because the loop below appends to it — see the reprieve.
  const finalPaths = [...tasteResult.rankedPaths];
  /**
   * RONDE 119 — THE COUNTER THAT SAID ZERO BECAUSE NOBODY CALLED IT.
   *
   * ── What it cost ────────────────────────────────────────────────────────────────────────
   *
   * Every beat of render 572 reported `ranked=0` beside `eligible=40` and `shortlisted=8/8`, and
   * that zero was read — by me, in RONDE 117 — as "the shortlist admits whatever arrives first,
   * so the eight questions are spent on the first eight candidates". It is the wrong reading.
   * `noteRanked` was written for this, exported, documented, and never called once: the number
   * was not measuring an unranked funnel, it was measuring nothing at all.
   *
   * `finalPaths` here IS the ranked order — `applyDocumentaryTasteModel` over the asset
   * director's `rankedPaths` — and the loop below walks it from the top. So on this route the
   * eight candidates put to the editor are the top eight, not the first eight to arrive.
   *
   * ── Why the number still matters ────────────────────────────────────────────────────────
   *
   * Because this is one route of several, and the shortlist is shared across all of them. A
   * rescue ladder that spends slots before this loop runs would leave `shortlisted=8` with
   * `ranked` far below it — and that gap, which nothing could previously show, is the whole
   * question of whether the editor is being asked about the best pictures or merely the earliest.
   */
  /**
   * RONDE 227 — and `paths.length`, which is what this route was HANDED.
   *
   * `finalPaths` is the output of two stages that can both drop candidates: the asset director's
   * `rankedPaths`, then `applyDocumentaryTasteModel` over it. So `ranked=0` from here has never
   * been one fact. With the input size recorded beside it, `rankIn=11 ranked=0` says the ordering
   * discarded eleven real candidates, and `rankIn=0 ranked=0` says nothing was ever handed over —
   * and the second is a fault in whatever was meant to fill `paths`, not in the ranking.
   */
  noteRanked(dedup.beatShortlist, sceneIndex, beatIndex, finalPaths.length, paths.length);
  /**
   * R194 §18/§21 — THE BOUNDED REVIEW POOL, DECLARED BEFORE ANYTHING IS ASKED.
   *
   * `finalPaths` IS the cheap ranking — the asset director's order, re-ranked by the taste model —
   * and the loop below walks it from the top. So the candidates this beat will spend the editor's
   * attention on are already the best-ranked ones; what did not exist was any statement of WHICH
   * they were meant to be, which is the difference between a pool and a coincidence.
   *
   * Declared with the beat's existing shortlist cap. Nothing here raises a budget, and a pool
   * larger than the budget would promise looks the render cannot pay for.
   */
  const cheapRankOf = new Map<string, number>();
  finalPaths.forEach((p, i) => { if (!cheapRankOf.has(p)) cheapRankOf.set(p, i); });
  declareVisionReviewPool(
    dedup.visionReviewPool,
    sceneIndex,
    beatIndex,
    finalPaths.map((p, i) => ({ contentKey: clipContentKey(p), cheapRank: i })),
    maxShortlistPerBeat()
  );
  /**
   * R194 §24/§27 — the candidates this beat has seen and is holding, and what the editor said.
   *
   * The loop below no longer stops at the first candidate the editor merely FAILED TO REFUSE. A
   * candidate whose evidence is weaker than FIT goes to the back of the queue and the search
   * continues, so a picture the editor calls a fit at cheap rank 5 can still beat one it could not
   * read at cheap rank 2. `pendingEvidence` is what makes the ordering between the weak tiers
   * decidable at the moment it matters: a held candidate is passed over once more while something
   * strictly better is still waiting.
   */
  const pendingEvidence = new Map<string, VisionEvidence>();
  const heldForWeakEvidence = new Set<string>();
  const postponedForBetterEvidence = new Set<string>();
  /** One candidate's answer, filed on the pool and held pending until the beat resolves it. */
  const noteReviewedCandidate = (clipPath: string, evidence: VisionEvidence): void => {
    noteVisionReviewed(dedup.visionReviewPool, sceneIndex, beatIndex, {
      contentKey: clipContentKey(clipPath),
      cheapRank: cheapRankOf.get(clipPath) ?? finalPaths.length,
      evidence,
      clipPath,
    });
    pendingEvidence.set(clipPath, evidence);
  };
  /** True while a candidate with strictly better evidence than `own` is still unresolved. */
  const betterEvidencePending = (self: string, own: VisionEvidence): boolean => {
    for (const [otherPath, otherEvidence] of pendingEvidence) {
      if (otherPath === self) continue;
      if (evidenceTier(otherEvidence) < evidenceTier(own)) return true;
    }
    return false;
  };
  /**
   * Candidates the picture gate refused, which get one more turn at the very end.
   *
   * Render 533 rejected 34 clips on this gate and put PLACEHOLDERS on eight beats:
   *
   *     [VisualCoverage] s1b4: rejected=7 topRejects=beat_image_gate:6,vision_gate:1
   *                      fallback=PLACEHOLDER (all real sourcing strategies exhausted)
   *
   * The gate was applying one standard to the first candidate and to the last. Refusing the
   * first is free — another follows. Refusing the last means a grey card, which matches the
   * narration less well than the imperfect picture it replaced. A real image always beats a
   * placeholder.
   */
  /**
   * Clips this loop has already sent to the back of the queue after a refusal.
   *
   * RONDE 104 looked at whether this duplicated the relevance ledger and concluded it does not.
   * The ledger records a VERDICT — "the gate refused this picture on this beat" — and is the one
   * place that fact lives. This set records something else: "I have already re-offered this one",
   * which is this loop's own bookkeeping. Deriving it from the ledger would take a clip that a
   * different route refused earlier on the same beat and adopt it IMMEDIATELY instead of putting
   * it last, which is exactly the ordering the reprieve exists to get right: a refused picture is
   * the last resort, not the first.
   */
  const requeuedAfterRefusal = new Set<string>();

  return withVisualDedupLock(dedup, async () => {
    // F3-04: record every candidate considered for this beat (adopted or not) so a post-scene
    // sweep can clean up the losers once this scene's beats are all done — see
    // sweepUnadoptedSceneCandidates. Recording (not a filename glob) means the sweep can only
    // ever touch a path adoptClip itself put forward as a real candidate.
    let sceneCandidates = dedup.sceneCandidatePaths.get(sceneIndex);
    if (!sceneCandidates) {
      sceneCandidates = new Set();
      dedup.sceneCandidatePaths.set(sceneIndex, sceneCandidates);
    }
    for (const p of finalPaths) sceneCandidates.add(p);
    // RONDE 70: what this beat was actually offered. Counting only — nothing is fetched,
    // ranked or judged here, and finalPaths is the list the loop below is about to read.
    noteBeatCandidatesOffered(dedup.beatOutcomeAudit, sceneIndex, beatIndex, finalPaths.length);

    for (const p of finalPaths) {
      /**
       * RONDE 97 (production timeout) — a beat that has asked enough STOPS, it does not keep
       * paying and refusing.
       *
       * RONDE 95 put the shortlist bound inside the vision gate, which runs after the ffprobe,
       * the black-frame pass and the CLIP scoring below. So once a beat's shortlist was full this
       * loop kept paying for every remaining candidate and refusing each one — and, never getting
       * a success, went on to the rescue ladder and the guaranteed ladder as well. A real render
       * timed out at 33 minutes.
       *
       * The bound always meant "this beat has asked enough". Asked here, before the first
       * expensive call, it means that.
       */
      if (beatShortlistExhausted(dedup.beatShortlist, sceneIndex, beatIndex)) {
        console.log(
          `[BeatShortlist] s${sceneIndex}b${beatIndex} stopped looking — shortlist spent ` +
            `(${maxShortlistPerBeat()} candidates asked)`
        );
        break;
      }
      if (!p || dedup.usedPaths.has(p)) continue;
      /**
       * RONDE 647 — A CANDIDATE THAT IS PASSED OVER SAYS WHY.
       *
       * Every `continue` below used to be silent, so a refused file simply stopped existing as far
       * as the lineage could tell. Render 610's YouTube trace ended `delivered=0 refused=3
       * openEnded=5`: five downloaded clips with no terminal event, one of them (`btHJYt5YE9s`,
       * 168 512 bytes) refused on every one of its nine downloads by the size floor below. Each
       * check is exactly what it was; it now names itself on the way out.
       */
      const refuse = (reason: string): true => {
        recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, reason, sourceQuery);
        /** VIDEO 616 — a YouTube fragment refused for what its pixels show is not fetched again. */
        if (reason === "mostly_black" || reason === "baked_edit_text_before_vision") {
          rememberRefusedYoutubeFragment(dedup, p, reason);
        }
        return true;
      };
      if (!fs.existsSync(p) && refuse("file_missing")) continue;
      // Invariant 2 (no duplicate work): this is the authoritative same-render asset-identity
      // gate, and it now runs FIRST — before isValidVideoFile's ffprobe, before
      // isMostlyBlackClip's ffmpeg pass, and before clipPassesVisionGate's frame extraction +
      // CLIP scoring. The identical check used to sit at the very end of this loop body, so a
      // candidate that a different cascade had already adopted still paid for a full ffprobe,
      // black-frame probe and CLIP evaluation before being discarded on a key comparison that
      // was already decidable from its filename. clipContentKey itself is cheap here — a
      // basename regex for provider-tagged and curated clips, a statSync otherwise.
      //
      // Moving it also fixes a real accounting bug: the still-photo branch below increments
      // dedup.stillPhotosThisScene / the global still budget *before* the old check position,
      // so a duplicate still image consumed a scarce still-photo slot and then got rejected
      // anyway, permanently costing the render a still it never used.
      const contentKey = clipContentKey(p);
      if (dedup.usedContentKeys.has(contentKey)) {
        dedup.sourcingCache.totals.duplicateCandidatesSkipped++;
        refuse("already_used_in_render");
        continue;
      }
      if (!(await isValidVideoFile(p)) && refuse("not_a_valid_video")) continue;
      if (isStillPhotoClip(p)) {
        const scriptStill = Boolean(opts.scriptImageFallback);
        if (!scriptStill && !canUseGlobalStillPhoto(dedup) && refuse("still_photo_budget")) continue;
        const sceneStillCap = dedup.stillPhotosMaxThisScene;
        if (!scriptStill && sceneStillCap > 0 && dedup.stillPhotosThisScene >= sceneStillCap && refuse("scene_still_cap")) continue;
        if (scriptStill || canUseGlobalStillPhoto(dedup)) {
          dedup.stillPhotosThisScene++;
          if (canUseGlobalStillPhoto(dedup)) markGlobalStillPhotoUsed(dedup);
        }
      }
      if (isAIGeneratedClip(p) && refuse("ai_generated")) continue;
      if (isRejectedStockClip(p, sourceQuery) && refuse("rejected_stock")) continue;
      if (isPipelineFallbackClip(p) && refuse("pipeline_fallback")) continue;
      if ((await isMostlyBlackClip(p)) && refuse("mostly_black")) continue;
      /**
       * Video 614 — the on-screen-text question, asked BEFORE the picture editor.
       *
       * Someone else's subtitle, title bar or logo never enters the film (the operator's rule), and
       * the archive refuses it at the push gate. Render 614 asked it last: two YouTube shots were
       * downloaded, APPROVED, transformed — and then refused for an E! logo, with the beat's time
       * spent. Asked here, on the downloaded file, a clip with text is passed over and the time goes
       * to the next candidate. The verdict is memoised under the key the archive uses, so the push
       * gate reads it back instead of paying for it twice.
       */
      if (clipRequiresFairUseTransform(p)) {
        const text = await cachedClipBakedEditTextVerdict(
          p, "video/mp4", onScreenTextVerdictKey(dedup, p, contentKey), beatClipTextFilterMaxChecks()
        ).catch(() => null);
        if (text?.verdict === "has_text" && refuse("baked_edit_text_before_vision")) continue;
      }
      if (!opts.scriptImageFallback) {
        if (muskTopic && isOffTopicVisualForMusk(sourceQuery, p)) continue;
        if (
          opts.personTopic &&
          opts.primaryPerson &&
          isOffTopicVisualForPersonTopic(sourceQuery, p, opts.primaryPerson, dedup.clipAnnotationMeta.get(p)?.providerText?.title)
        ) {
          continue;
        }
        if (opts.personTopic && opts.primaryPerson && isStockVideoClip(p)) {
          const hay = `${sourceQuery} ${path.basename(p)}`.toLowerCase();
          const personHit = textMentionsPersonName(hay, opts.primaryPerson);
          const celebCue = /\b(interview|red carpet|talk show|celebrity|paparazzi|jenner|kardashian)\b/.test(hay);
          if (!personHit && !celebCue && refuse("stock_without_person")) continue;
        }
      }
      const category = stockVisualCategory(sourceQuery, p);
      /** RONDE 621 — the same question the gate below asks, so the two cannot answer differently. */
      if (categoryIsBlockedContent(category, muskTopic) && refuse(`blocked_category:${category}`)) continue;
      if (categoryAtLimit(dedup, category, muskTopic) && refuse(`category_at_limit:${category}`)) continue;
      // Documentary beat gate (blocklist-only: known non-documentary / off-topic geo-urban
      // filename patterns) now applies unconditionally, including scriptImageFallback
      // candidates — it was previously exempted here, one of the gaps that let a completely
      // unrelated SerpAPI image reach adoption with zero topical scrutiny.
      const docGate = judgeDocumentaryBeatGate(p, sourceQuery, beatText, opts.videoTitle);
      const failsDocumentaryBeatGate = !docGate.passes;
      // RONDE 174: `armed` separates "this gate had nothing to say about a 1940s subject" from
      // "this gate is broken" — the two the silent-gate detector used to report identically.
      recordGateVerdict("documentary_beat_gate", failsDocumentaryBeatGate, { armed: docGate.armed });
      if (failsDocumentaryBeatGate) {
        recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, "documentary_beat_gate", sourceQuery);
        continue;
      }
      // Musk/Tesla topics: reject generic clips when query targets a specific category
      const queryCategory = stockVisualCategory(sourceQuery);
      if (queryCategory !== "generic" && category === "generic" && refuse("generic_for_specific_query")) continue;
      if (opts.requireMuskBrand && !hasMuskBrandSignal(sourceQuery, p)) continue;
      const beatMatch = scoreBeatNarrationMatch(beatText, sourceQuery, p);
      const queryWords = sourceQuery.split(/\s+/).filter((w) => w.length >= 3);
      const queryInBeat = scoreVisualRelevance(beatText, queryWords) >= 1;
      // Entity evidence (Fix 1, P0/P1 patch) now applies unconditionally, including
      // scriptImageFallback candidates — a named, REAL_ENTITY_RULES-covered entity in the beat
      // still needs independently-authored evidence (curated-archive annotation, or provider
      // title/description/tags) that the candidate actually shows that entity.
      if (entityRules.length > 0) {
        // Only counted when the beat actually HAS entity rules — a beat with none was never
        // asked, and counting it as a silent ask would bury a genuinely broken gate in noise.
        const failsEntityEvidence = !clipSatisfiesRealEntities(entityRules, dedup.clipAnnotationMeta.get(p));
        recordGateVerdict("entity_evidence", failsEntityEvidence);
        if (failsEntityEvidence) {
          recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, "entity_evidence", sourceQuery);
          continue;
        }
      }
      // Final hardening round — point 3: the relevance floor (originally scoped to only
      // scriptImageFallback candidates — Problem 1/2, "Why Hitler Killed Himself and His Wife")
      // now applies to every candidate that has real providerText, not just the generic
      // image-search fallback path. It's still a no-op whenever providerText is absent (the
      // overwhelming majority of candidates today), so this is additive, not a tightening of
      // any candidate that couldn't already be checked. Reject only when the provider's own
      // title shares literally nothing with the query/beat/video topic — the exact pattern
      // behind the off-topic image that shipped in production ("An open letter to remove
      // Richard M. Stallman...") on a Hitler beat.
      {
        const providerTitle = dedup.clipAnnotationMeta.get(p)?.providerText?.title;
        const belowRelevanceFloor = !scriptImageFallbackPassesRelevanceFloor(
          providerTitle, sourceQuery, beatText, opts.videoTitle
        );
        // Only an ask when there IS a provider title to judge — this check is a documented
        // no-op without one, and counting those would make a broken gate look busy.
        if (providerTitle) recordGateVerdict("off_topic_visual", belowRelevanceFloor);
        /**
         * RONDE 114 — this reads a provider TITLE, so it flags and no longer refuses.
         *
         * RONDE 103 took the veto off `vision_gate` and RONDE 104 off `off_topic_protest`, both
         * for the same stated reason: a check that reads metadata instead of the frame can only
         * take material away once a model that looks at the picture is standing behind it. This
         * one was missed, and it sat three lines above that very model.
         *
         * What it actually rejects is a title sharing ZERO tokens with the beat. Real archive
         * titles do that constantly — "Bundesarchiv Bild 183-S33882" is the literal catalogue
         * form of the German federal archive's Hitler photographs, and a foreign-language or
         * accession-number title is the norm rather than the exception. Every one of those was
         * discarded before the decider ever saw the frame.
         *
         * The signal is unchanged and still recorded, so how often it WOULD have fired stays
         * measurable — the same treatment its two demoted siblings got.
         */
        if (belowRelevanceFloor) {
          // Production finding: this reason had no accompanying log line anywhere, so an
          // off_topic_visual verdict in a coverage-gate summary could never be reconstructed from
          // logs (unlike vision_gate, which logs via evaluateClipVisionGate). Minimal targeted
          // logging — same shape as the other reason warnings in this loop — using data
          // already in scope (no new lookups).
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beatIndex}: provider title shares nothing with ` +
              `the beat for "${path.basename(p)}" — flagged, not rejected; the relevance gate decides ` +
              `(provider=${contentKey.split(":")[0] || "unknown"} query="${sourceQuery.slice(0, 60)}" ` +
              `title="${(providerTitle ?? "").slice(0, 60)}")`
          );
        }
      }
      if (opts.scriptImageFallback) {
        /* scriptImageFallback candidates already got the relevance-floor check above; the
           requireBeat/scriptAnchored/personTopic checks below are intentionally skipped for
           this path (unchanged from before this hardening round). */
      } else {
        if (requireBeat && beatMatch < 1 && !queryInBeat && refuse("no_beat_match")) continue;
        if (scriptAnchored && beatMatch < 1 && !queryInBeat && entityRules.length === 0 && refuse("not_script_anchored")) continue;
        if (opts.personTopic && opts.primaryPerson) {
          const parts = opts.primaryPerson.toLowerCase().split(/\s+/).filter((x) => x.length >= 3);
          const hay = `${sourceQuery} ${path.basename(p)}`.toLowerCase();
          const personHit = parts.some((pt) => hay.includes(pt));
          const eventHit = /\b(interview|celebrity|red carpet|keynote|conference|launch)\b/.test(hay);
          if (!personHit && !eventHit && beatMatch < 1 && refuse("person_not_named")) continue;
        }
      }
      if (muskTopic) {
        if (category === "solar" && !/solar|photovoltaic|sun panel/.test(beatText.toLowerCase())) continue;
        if ((category === "rocket" || category === "space") && !isMuskApprovedRocketQuery(sourceQuery)) {
          continue;
        }
        if (BLOCKED_MUSK_COMPETITOR_RE.test(`${sourceQuery} ${path.basename(p)}`)) continue;
        const rel = scoreVisualRelevance(`${sourceQuery} ${path.basename(p)}`, keywords);
        const topicRel = scoreVisualRelevance(`${sourceQuery} ${path.basename(p)}`, MUSK_TOPIC_TOKENS);
        const brand = muskBrandScore(sourceQuery, p);
        // Pexels filenames rarely include "Tesla" — reject only when clearly unrelated.
        if (rel < 1 && topicRel < 1 && brand === 0 && category === "generic") continue;
        if (category === "generic" && queryCategory !== "generic" && rel < 1 && brand === 0) continue;
      }
      let fileSize = 0;
      try { fileSize = fs.statSync(p).size; } catch { refuse("file_missing"); continue; }
      if (fileSize < 180_000 && refuse(`below_size_floor_${fileSize}_bytes`)) continue;
      // Calls evaluateClipVisionGate directly (rather than the boolean-only clipPassesVisionGate
      // wrapper) so a cache hit can be told apart from a fresh evaluation below — a cache hit is
      // the SAME earlier CLIP judgment being returned again, not a new verdict on this candidate.
      const visionResult = await evaluateClipVisionGate(
        p,
        beatText,
        opts.videoTitle,
        workDir,
        sceneIndex,
        beatIndex,
        dedup.perf.fastStockMode,
        undefined,
        gateVisualDesc,
        undefined,
        null,
        undefined,
        // Phase 16: give the vision gate this clip's real asset identity (already computed at
        // the top of this loop) so its score cache can neither collide across two different
        // files that happen to share a basename, nor miss when the same physical asset
        // arrives under a different cascade's filename.
        contentKey
      );
      /**
       * RONDE 103 — CLIP ranks, it does not decide. Same reasoning as in
       * beatClipPassesVisionGate: this gate's content verdicts are measurably inverted on archive
       * material, so `!pass` is logged as a ranking signal and the relevance gate below decides.
       * The score itself is unchanged and still lands on the lineage record.
       */
      if (!visionResult.pass && !visionResult.skipped) {
        console.log(
          `[VisionGate] s${sceneIndex}b${beatIndex} CLIP would have rejected ` +
            `${path.basename(p)} (score=${visionResult.worstScore10 ?? "?"}) — ranking signal only`
        );
      }
      // RONDE 62: look at the picture here too.
      //
      // The gate built in RONDE 58 hangs off the funnel's winner block, and render 532 ran the
      // funnel for exactly one of its three scenes — so scenes 0 and 1 reached the timeline
      // with nothing having looked at what was in the frame. This is the acceptance point every
      // other route passes through: curated archive, rescue, Wikimedia, Openverse, stock, the
      // lot. Verdicts are cached by content identity, so a clip the funnel already judged is
      // free here, and the render-wide budget still bounds the total.
      /**
       * R194 §19/§32 — THE BEAT'S OWN VISION BUDGET, APPLIED ON THE ROUTE THAT ADOPTS.
       *
       * The top of this loop already asks `beatShortlistExhausted` — RONDE 97 put it there so a
       * beat that has asked enough stops paying. It reads a counter this route never wrote: every
       * `admitToShortlist` call in the file sits in `beatClipPassesVisionGate`, which is the RESCUE
       * side. So the main adoption route consulted a bound it never fed, and its questions to the
       * editor were invisible to the funnel that reports how many were asked.
       *
       * Admitting here fixes both halves at once and raises nothing: the cap is
       * `maxShortlistPerBeat()`, unchanged, and it is now what actually bounds this route's asks —
       * which is also what bounds the extra looking the vision-aware search below does.
       */
      const firstLookAtCandidate =
        !requeuedAfterRefusal.has(p) && !heldForWeakEvidence.has(p);
      if (firstLookAtCandidate) {
        noteBeatShortlistEligible(dedup.beatShortlist, sceneIndex, beatIndex);
        /**
         * The SOURCE asks, not just the beat — see `maxShortlistPerBeatPerSource`. Read from the
         * ledger, never from the filename, and null when the ledger cannot name one (which
         * simply leaves that candidate outside the fairness rule rather than guessing at it).
         */
        const admission = admitToShortlist(
          dedup.beatShortlist, sceneIndex, beatIndex, contentKey, undefined,
          dedup.sourcingCache?.lineage?.providerFor(p, contentKey)
        );
        if (!admission.admitted) {
          noteNotAsked(dedup.beatShortlist, sceneIndex, beatIndex, admission.reason);
          console.log(
            `[BeatShortlist] s${sceneIndex}b${beatIndex} not asked — ${admission.reason} ` +
              `(${admission.slotsUsed}/${admission.cap}) route=adopt file=${path.basename(p)}` +
              (admission.eligible != null
                ? ` eligible=${admission.eligible} ranked=${admission.ranked ?? 0}` +
                  ` rankRuns=${admission.rankRuns ?? 0}` +
                  ` unreviewed=${admission.unreviewed ?? 0}`
                : "")
          );
          recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, "shortlist_full", sourceQuery);
          continue;
        }
      }
      if (
        !requeuedAfterRefusal.has(p) &&
        !(await beatClipPassesImageGate(p, contentKey, beatText, opts, workDir, sceneIndex, beatIndex, dedup))
      ) {
        recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, "beat_image_gate", sourceQuery);
        noteVisionAsked(dedup.beatShortlist, sceneIndex, beatIndex, contentKey);
        noteVisionOutcome(dedup.beatShortlist, sceneIndex, beatIndex, "REJECTED");
        noteReviewedCandidate(p, "MISMATCH");
        // Not discarded — moved to the back of the queue. for...of reads the array by index, so
        // an append is visited after every candidate that has not been refused. If one of those
        // is adopted this is never reached again; if none is, this clip gets its turn rather
        // than the beat getting a placeholder.
        requeuedAfterRefusal.add(p);
        finalPaths.push(p);
        continue;
      }
      /**
       * R194 §24/§27 — THE EDITOR'S ANSWER, READ BACK AND ACTED ON.
       *
       * `beatClipPassesImageGate` returns `decision.allowed`, and `allowed` is built as
       * `verdict !== "does_not_fit"` — it folds "this fits" together with "I cannot tell". Until
       * now that boolean was the whole decision, so this loop stopped at the first candidate the
       * editor merely failed to refuse, and a picture it would have called a fit further down the
       * ranked list was never reached.
       *
       * The verdict itself is on the relevance ledger, where `judgeBeatClipRelevance` just wrote
       * it, and `evaluated` separates "looked and could not tell" from "never looked". Read from
       * there rather than re-judged: no second question, no second cost, no second answer that
       * could disagree with the one on the record.
       */
      const beatEvidence: VisionEvidence = requeuedAfterRefusal.has(p)
        ? "MISMATCH"
        : beatVisionEvidenceFor(dedup, p, contentKey, sceneIndex, beatIndex);
      if (firstLookAtCandidate) {
        /** A decline costs no judgement, so it is not counted as one. */
        if (beatEvidence !== "UNREVIEWED") {
          noteVisionAsked(dedup.beatShortlist, sceneIndex, beatIndex, contentKey);
        } else {
          /**
           * RONDE 230 — and it costs no PLACE either.
           *
           * The line above has said "a decline costs no judgement" since R194 and it is right. The
           * place, though, was taken at admission a few lines up, and until now nothing gave it
           * back — so a beat whose first eight candidates all declined could never look at a ninth.
           * Render 576 died exactly that way. See `releaseShortlistSlot`, which refuses to hand
           * back a place the editor actually used and is bounded so R97's cost bound survives.
           */
          const back = releaseShortlistSlot(dedup.beatShortlist, sceneIndex, beatIndex, contentKey);
          if (back.released) {
            console.log(
              `[BeatShortlist] s${sceneIndex}b${beatIndex} slot returned — nobody looked at ` +
                `${path.basename(p)} (route=adopt, now ${back.slotsUsed} held, ` +
                `${back.released_total} returned this beat)`
            );
          }
        }
        noteVisionOutcome(
          dedup.beatShortlist,
          sceneIndex,
          beatIndex,
          beatEvidence === "FIT" ? "APPROVED" : beatEvidence === "UNCLEAR" ? "UNCLEAR" : "NOT_ASKED",
          /**
           * P0-7 — the decline's own cause, read off the same ledger entry the evidence came from.
           *
           * Only meaningful on the NOT_ASKED branch, and `noteVisionOutcome` ignores it elsewhere;
           * passed unconditionally because a reader should not have to check which branch is live
           * to know the argument is the right one.
           */
          beatDeclineReasonFor(dedup, p, contentKey, sceneIndex, beatIndex)
        );
        noteReviewedCandidate(p, beatEvidence);
      }
      /**
       * Weaker than FIT: hold it and keep looking. Same mechanism as the refusal above — the back
       * of this beat's own queue — so there is one deferral idiom in this loop rather than two.
       */
      if (beatEvidence !== "FIT" && firstLookAtCandidate) {
        heldForWeakEvidence.add(p);
        console.log(
          `[VisionSelection] s${sceneIndex}b${beatIndex} holding ${beatEvidence} ` +
            `rank=${cheapRankOf.get(p) ?? "?"} ${path.basename(p)} — looking for a FIT first`
        );
        finalPaths.push(p);
        continue;
      }
      /**
       * A held candidate has come round again. It waits once more while something strictly better
       * is still unresolved, which is what puts UNREVIEWED ahead of UNCLEAR and both ahead of a
       * refused picture. Once per candidate: a second postponement could not change the answer and
       * would only walk the queue again.
       */
      if (
        !postponedForBetterEvidence.has(p) &&
        betterEvidencePending(p, beatEvidence)
      ) {
        postponedForBetterEvidence.add(p);
        finalPaths.push(p);
        continue;
      }
      pendingEvidence.delete(p);
      if (requeuedAfterRefusal.has(p)) {
        // RONDE 103 phase 15: recorded as an override, not relabelled as a pass. The verdict on
        // the ledger stays `does_not_fit` so the render can be asked how many of its shots were
        // used over the picture editor's objection, and answer.
        //
        // RONDE 166: the override is no longer automatic. A refusal that puts a different topic,
        // a title card or a blank frame on screen is declined, and this candidate goes back to
        // being refused — the loop moves to the next path rather than adopting it. The beat keeps
        // every route below it, so this is "look further", not "give the beat a colour card".
        const reprieved = reprieveBeatClip(
          dedup.beatRelevance,
          p,
          "refused, but every alternative failed too; a real picture beats a placeholder"
        );
        if (!reprieved) {
          recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, p, "hard_mismatch", sourceQuery);
          continue;
        }
      }
      // contentKey was computed and checked at the top of this iteration (see the comment
      // there). Nothing between that check and here can add to usedContentKeys — the whole
      // loop runs inside withVisualDedupLock, which serialises every adopt across the render —
      // so this stays the single acceptance point that marks the asset as used.
      dedup.usedPaths.add(p);
      dedup.usedContentKeys.add(contentKey);
      /**
       * RONDE 88A — ONE DECISION, BOTH REGISTRIES.
       *
       * The comment three lines down already knows this key's family can be "curated": the funnel's
       * own download branch (`downloadFunnelCandidate`, `candidate.archivePick`) calls
       * `prepareCuratedArchiveClip` and produces `…_curated_a<id>.mp4`. So a curated archive row can
       * be adopted right here.
       *
       * `usedContentKeys` is what stops the same footage twice; `usedCuratedAssetIds` /
       * `usedCuratedStorageUrls` are what the curated SEARCH reads — the pool filter in
       * `searchCuratedCandidatesForBeat`, `listCuratedArchiveCandidates`' excludeIds, the
       * eligibility loop in `fetchCuratedArchiveBeatClip`, and `archiveAssetPreflight`. Writing one
       * and not the other leaves the search blind to a decision the render has already made: the
       * asset keeps winning the ranking, keeps being downloaded and transcoded, and is refused again
       * at the push every time. Render 568 paid for asset ww2:57364 thirty-eight times and used it
       * once.
       *
       * Every other acceptance point in this file writes both (the four `pushSceneClip` variants,
       * `rejectClip`, the compose backfills, the fast-short rescue). This was the one that did not —
       * the same seam as RONDE 53's `recordClipAdopt`, RONDE 70's beat audit and RONDE 86's failed
       * assets: a rule several routes must remember, remembered by all but one.
       *
       * It cannot change WHICH footage this render may use. `usedContentKeys` above already refuses
       * this asset everywhere, one step later; this only lets the search see that refusal before
       * paying for it.
       */
      markCuratedAssetUsed(p, dedup.usedCuratedAssetIds, dedup.usedCuratedStorageUrls, curatedStorageUrlForClip(p, dedup));
      // Phase 20: attribute the acceptance to whatever produced the content key — a provider
      // name for provider-tagged assets, otherwise the key's own family ("stock", "still",
      // "curated", "file"). Pure counter increment, no I/O.
      const providerOfKey = contentKey.split(":")[0] || "unknown";
      providerMetrics(dedup.sourcingCache, providerOfKey).acceptedCount++;
      // RONDE 70: every gate is behind this candidate now. Whether it becomes the beat's clip is
      // still decided below, so this is where "eligible" is counted and NOT where "adopted" is.
      providerMetrics(dedup.sourcingCache, providerOfKey).eligibleCount++;
      noteBeatEligible(dedup.beatOutcomeAudit, sceneIndex, beatIndex);
      /**
       * RONDE 87: every gate is behind this candidate, so ELIGIBLE/RANKED/SELECTED are facts here.
       *
       * Deliberately attached to the candidate's OWN lineage record — the one
       * putCachedProviderAsset opened with the provider's real name — rather than opening a new
       * one. A candidate the ledger has never seen gets no record and no provider: this path
       * cannot prove where such a file came from, and inventing a provider from `providerOfKey`
       * (which is a content-key family like "stock" or "file", not a provider) is exactly the
       * class of guess this round removes.
       */
      const eligibleRecord = dedup.sourcingCache.lineage.resolve(p, contentKey);
      if (eligibleRecord) {
        /** RONDE 94: through the one writer, so eligibility has a single spelling. */
        dedup.sourcingCache.lineage.markEligible(p, contentKey, "adopt_clip_gates_cleared");
        dedup.sourcingCache.lineage.recordEvent(eligibleRecord.lineageId, "RANKED", { status: "OK" });
        dedup.sourcingCache.lineage.recordEvent(eligibleRecord.lineageId, "SELECTED", { status: "OK" });
        eligibleRecord.sceneIndex = sceneIndex;
        eligibleRecord.beatIndex = beatIndex;
        eligibleRecord.beatText ??= beatText?.slice(0, 240);
        eligibleRecord.query ??= sourceQuery || undefined;
        eligibleRecord.visionScore ??= visionResult.worstScore10 ?? undefined;
      }
      /** The single point at which a candidate really becomes this beat's clip. */
      const markAdopted = (finalPath: string): string => {
        providerMetrics(dedup.sourcingCache, providerOfKey).adoptedCount++;
        /**
         * R194 §29 — the beat's choice, filed beside the evidence it was made on.
         *
         * This is what makes the selection checkable rather than merely instrumented:
         * `visionSelectionViolations` compares this against the pool and reports a beat that
         * passed over a FIT, or used a refused picture while something unrefused was available.
         */
        noteVisionAdopted(dedup.visionReviewPool, sceneIndex, beatIndex, contentKey);
        noteBeatAdopted(dedup.beatOutcomeAudit, sceneIndex, beatIndex, providerOfKey, path.basename(finalPath));
        // RONDE 86/87: `finalPath` is `p` after the segment trim and/or the fair-use transform
        // have renamed it. The derived file gets its OWN record carrying parentLineageId, so the
        // rename can never look like an independent source, and the adoption is recorded against
        // whichever record actually reached the montage.
        const derived =
          finalPath === p
            ? eligibleRecord
            : dedup.sourcingCache.lineage.linkDerivedPath(finalPath, p, "TRANSFORMED");
        if (derived) {
          dedup.sourcingCache.lineage.recordEvent(derived.lineageId, "ADOPTED", {
            status: "OK",
            currentPath: finalPath,
          });
        }
        return finalPath;
      };
      dedup.usedCategories.set(category, (dedup.usedCategories.get(category) ?? 0) + 1);
      // RONDE 29: count the moving/still split as it happens. Classified with the file's own
      // existing classifiers rather than the extension — by this point every adopted path is an
      // mp4, including the ones that are a photograph panned with Ken Burns.
      if (isStillPhotoClip(p) || isCuratedPreparedStillClip(p)) dedup.stillClipCount++;
      else if (isRealVideoFootageClip(p)) dedup.movingClipCount++;
      // RONDE 28: this is the moment we know a source WORKED — the provider, the query that
      // found it, and the score the gate gave it. Recording here rather than at archive
      // ingestion is the difference between remembering a couple of clips per render and
      // remembering all of them: render 528 adopted 18 and archived 2.
      const memoryTopic = get_activeVideoTopic();
      if (memoryTopic) {
        recordAdoptedClipSource({
          subject: memoryTopic.primaryPerson || memoryTopic.videoTitle,
          subjectType: memoryTopic.primaryPerson ? "person" : "topic",
          query: sourceQuery || "",
          contentKey,
          score10: visionResult.worstScore10,
        });
      }
      const mustFairUse = clipRequiresFairUseTransform(p);
      if (dedup.perf.skipFairUseTransform && !mustFairUse) {
        if (await isValidVideoFile(p)) {
          if (!isPipelineFallbackClip(p) && !(await isMostlyBlackClip(p))) { dedup.lastMuskStockClip = p; dedup.lastRealClip = p; }
          recordAdoptedClip(p, adCtx);
          dedup.assetDirectorSceneClips.push(p);
          /**
           * RONDE 201: removed — `recordClipAdopt` now records this for EVERY route, so keeping it
           * here would count this route's pictures twice in the fatigue and shot history that the
           * next beat is scored against. See `bindTasteModelContext`.
           */
          // Apply segment trim hint if this clip has a better temporal segment
          const trimHint = adResult.trimHints?.get(p);
          if (trimHint) {
            const trimmed = await applySegmentTrimIfNeeded(p, trimHint, workDir).catch(() => null);
            if (trimmed) return markAdopted(trimmed);
          }
          return markAdopted(p);
        }
        dedup.usedCategories.set(category, Math.max(0, (dedup.usedCategories.get(category) ?? 1) - 1));
        // RONDE 165: SELECTED was filed above; this exit is where that stopped being true.
        recordAssetOutcome(dedup.sourcingCache.lineage, p, "invalid_file", `s${sceneIndex}b${beatIndex}`, contentKey);
        /** R204: reviewed, and then the file would not open. Not a verdict the beat overrode. */
        noteVisionUnusable(dedup.visionReviewPool, sceneIndex, beatIndex, contentKey, "invalid_file");
        continue;
      }
      const transformMs = mustFairUse
        ? Math.max(dedup.perf.transformTimeoutMs, 25_000)
        : dedup.perf.transformTimeoutMs;
      const transformed = await transformClipForFairUse(
        p, beatText, sceneIndex, beatIndex, workDir, transformMs
      );
      if (
        mustFairUse &&
        (!transformed || !transformed.includes("_transformed") || !fs.existsSync(transformed))
      ) {
        dedup.usedCategories.set(category, Math.max(0, (dedup.usedCategories.get(category) ?? 1) - 1));
        // RONDE 165: a clip that MUST be transformed and could not be is refused, not lost.
        recordAssetOutcome(dedup.sourcingCache.lineage, p, "transform_failed", `s${sceneIndex}b${beatIndex}`, contentKey);
        noteVisionUnusable(dedup.visionReviewPool, sceneIndex, beatIndex, contentKey, "transform_failed");
        continue;
      }
      if (await isValidVideoFile(transformed)) {
        if (!isPipelineFallbackClip(transformed) && !(await isMostlyBlackClip(transformed))) {
          dedup.lastMuskStockClip = transformed; dedup.lastRealClip = transformed;
        }
        recordAdoptedClip(transformed, adCtx);
        dedup.assetDirectorSceneClips.push(transformed);
        /** RONDE 201: recorded centrally now — see the note on the sibling branch. */
        return markAdopted(transformed);
      }
      dedup.usedCategories.set(category, Math.max(0, (dedup.usedCategories.get(category) ?? 1) - 1));
      /**
       * RONDE 165 — the last exit out of an iteration that selected but did not adopt.
       *
       * The transform produced nothing usable. Every adopting branch above `return`s, so reaching
       * this line means `p` was marked SELECTED and the loop is about to move on from it — with or
       * without the `continue` below, which only decides whether `p` may still serve as
       * lastRealClip. Filed once, before either path leaves.
       */
      recordAssetOutcome(dedup.sourcingCache.lineage, p, "transform_failed", `s${sceneIndex}b${beatIndex}`, contentKey);
      /** R204: filed at the same point and for the same reason as the outcome above. */
      noteVisionUnusable(dedup.visionReviewPool, sceneIndex, beatIndex, contentKey, "transform_failed");
      if (mustFairUse) continue;
      if (await isValidVideoFile(p) && !isPipelineFallbackClip(p) && !(await isMostlyBlackClip(p))) {
        dedup.lastMuskStockClip = p; dedup.lastRealClip = p;
      }
    }
    return null;
  });
}

async function tryStockSources(
  fetchers: Array<{ query: string; fetch: () => Promise<string[]> }>,
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  beatText: string,
  workDir: string,
  logLabel: string,
  adoptOpts: VisualAdoptOptions = {}
): Promise<string | null> {
  const maxFetchers = Math.max(2, dedup.perf.maxStockQueriesPerBeat + 1);
  /**
   * RONDE 604 — A SOURCE THAT IS NOT ASKED SAYS SO.
   *
   * These three refusals were bare `continue`s, and with ONE fetcher in the array — which is what
   * `tryBeatRealYouTubeFootage` passes — any of them ends the loop and returns null. The caller then
   * reads `candidates === 0` and reports "the provider had nothing", for a provider that was never
   * asked. That is the same mislabel RONDE 600 removed one layer up, surviving one layer down.
   *
   * `categoryAtLimit` is the one that bites hardest and the hardest to see: `usedCategories` is
   * RENDER-wide and `STOCK_CATEGORY_LIMITS.generic` is 4, so on a documentary — where practically
   * every query classifies as `generic` — this source closes after the fourth adopted clip of the
   * WHOLE video and never says a word. Render 596's later beats ran against a door that had
   * already shut.
   *
   * NOTHING IS RELAXED. Every limit is the number it was; a refusal that happened silently now
   * happens out loud, which is the difference between a budget and a disappearance.
   */
  const declineSource = (reason: string, query: string, detail = ""): void => {
    console.log(
      `[SourceSkipped] scene=${sceneIndex} beat=${beatIndex} provider=${logLabel} ` +
        `reason=${reason} query=${JSON.stringify(query.slice(0, 60))}${detail}`
    );
  };
  for (const { query, fetch } of fetchers.slice(0, maxFetchers)) {
    if (isBlockedStockQuery(query)) {
      declineSource("BLOCKED_QUERY", query);
      continue;
    }
    const category = stockVisualCategory(query);
    if (adoptOpts.muskTopic && (category === "rocket" || category === "space") && !isMuskApprovedRocketQuery(query)) {
      declineSource("MUSK_CATEGORY_NOT_APPROVED", query, ` category=${category}`);
      continue;
    }
    if (categoryAtLimit(dedup, category, adoptOpts.muskTopic)) {
      declineSource(
        "CATEGORY_AT_LIMIT",
        query,
        ` category=${category} used=${dedup.usedCategories.get(category) ?? 0}` +
          `/${categoryLimitFor(dedup, category, adoptOpts.muskTopic)} scope=render`
      );
      continue;
    }
    const fetchMs = dedup.perf.fastStockMode ? 12_000 : 35_000;
    let paths: string[] = [];
    try {
      paths = await withTimeout(fetch(), fetchMs, `${logLabel} fetch s${sceneIndex} b${beatIndex}`);
    } catch {
      continue;
    }
    if (!paths.length) continue;
    const adoptMs = dedup.perf.fastStockMode ? 8_000 : 60_000;
    let clip: string | null = null;
    try {
      clip = await withSceneFetchTimeout(
        () => adoptClip(paths, dedup, sceneIndex, beatIndex, beatText, workDir, query, adoptOpts),
        adoptMs,
        `${logLabel} adopt s${sceneIndex} b${beatIndex}`
      );
    } catch {
      continue;
    }
    if (clip) {
      console.log(`[Pipeline] Scene ${sceneIndex} beat ${beatIndex}: ${logLabel} "${query}"`);
      return clip;
    }
  }
  return null;
}

/** Guaranteed-unique stock for one beat — Pexels/Pixabay/YouTube with global dedup (no grey, no repeats). */
async function fetchUniqueStockForBeat(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle?: string,
  adoptOpts: VisualAdoptOptions = {}
): Promise<string | null> {
  /** RONDE 600: the same budget predicate the beat wall uses — see `youtubeAvailableForBudgeting`. */
  const wallMs = youtubeAvailableForBudgeting()
    ? youtubeBeatFetchTimeoutMs(dedup.perf.fastStockMode) + 8_000
    : dedup.perf.fastStockMode
      ? 24_000
      : 32_000;
  try {
    // RONDE 90 (§2): the beat's proof, in scope for every stock provider this path asks.
    return await withSearchProvenance(beatSearchProvenance(beat, scene, personName), () =>
      withTimeout(
        fetchUniqueStockForBeatInner(
          beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts
        ),
        wallMs,
        `unique stock s${sceneIndex} b${beat.index}`
      )
    );
  } catch {
    return null;
  }
}

async function fetchUniqueStockForBeatInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle?: string,
  adoptOpts: VisualAdoptOptions = {}
): Promise<string | null> {
  if (!youtubeCcReady() && !PEXELS_API_KEY && !PIXABAY_API_KEY) return null;
  const perf = dedup.perf;
  const muskTopic = isMuskTeslaTopic(videoTitle, beat.text);
  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const offset = dedup.globalBeatIndex * 11 + sceneIndex * 5 + beat.index * 3;
  const tag = `b${beat.index}_uniq`;
  const looseOpts: VisualAdoptOptions = {
    ...adoptOpts,
    muskTopic,
    requireBeatMatch: false,
    scriptAnchored: false,
    personTopic: dedup.personTopicLock,
    primaryPerson: dedup.primaryPerson || personName,
    keywords: beat.keywords,
    sceneText: scene.text,
    videoTitle,
  };
  const ytMs = youtubeBeatFetchTimeoutMs(perf.fastStockMode);

  const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle);
  let clip = (await runCentralYoutubeTurn({
               beat,
               scene,
               workDir,
               sceneIndex,
               clipFetchDur,
               dedup,
               visualNeed: "event",
               queries: entityYt,
               queryBuilder: "entityYt",
               termSource: "unique event YouTube",
               adoptOpts: looseOpts,
               timeoutMs: ytMs,
             })).clip;
  if (clip) return clip;

  const primary = scenePersons[0] ?? personName ?? dedup.primaryPerson;
  if (primary) {
    clip = (await runCentralYoutubeTurn({
             beat,
             scene,
             workDir,
             sceneIndex,
             clipFetchDur,
             dedup,
             visualNeed: "person",
             queries: buildPersonCelebrityVideoQueries(primary, beat.text, beat.index),
             queryBuilder: "buildPersonCelebrityVideoQueries",
             termSource: `unique person YouTube (${primary})`,
             adoptOpts: looseOpts,
             timeoutMs: ytMs,
           })).clip;
    if (clip) return clip;
  }

  clip = await tryBeatTopicRealFootage(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    looseOpts,
    videoTitle,
    primary ?? personName,
    { includeTopicYoutube: true, fileTag: tag }
  );
  if (clip) return clip;

  if (!PEXELS_API_KEY && !PIXABAY_API_KEY) return null;
  if (perf.minimizeStockFootage && !canUseLicensedStockBeat(dedup)) return null;

  if (
    !perf.minimizeStockFootage &&
    beat.index % 2 === 1 &&
    beat.index > 0 &&
    (scene.brollQueries?.length ?? 0) > 0 &&
    PEXELS_API_KEY &&
    canUseLicensedStockBeat(dedup)
  ) {
    const brollQ = enrichStockQuery(
      scene.brollQueries![beat.index % scene.brollQueries!.length],
      scene,
      videoTitle,
      personName,
      beat.text
    );
    const brollPaths = await fetchBrollClips(
      [brollQ],
      clipFetchDur,
      workDir,
      sceneIndex,
      dedup.usedPexelsIds,
      dedup.sourcingCache
    );
    clip = await adoptClip(
      brollPaths,
      dedup,
      sceneIndex,
      beat.index,
      beat.text,
      workDir,
      brollQ,
      looseOpts
    );
    if (clip) {
      markLicensedStockBeatUsed(dedup);
      return clip;
    }
  }

  const queryCap = perf.minimizeStockFootage ? 1 : perf.fastStockMode ? 4 : 6;
  const queries = [
    ...buildBeatVisualQueryList(beat.text, scene, videoTitle, scenePersons, queryCap),
    ...(muskTopic ? GOLDEN_MUSK_QUERIES.slice(0, perf.fastStockMode ? 2 : 4) : []),
    enrichStockQuery(scene.pexelsQuery, scene, videoTitle, personName, beat.text),
    stockQueryFromBeatScript(beat.text, scenePersons, scene.text, videoTitle),
    ...(scene.brollQueries ?? []).map((q) =>
      enrichStockQuery(q, scene, videoTitle, personName, beat.text)
    ),
  ].filter(
    (q) => toQueryString(q).length > 2 && !isBlockedStockQuery(toQueryString(q))
  );
  const stockQueries = [...new Set(queries)].slice(
    0,
    perf.minimizeStockFootage ? 1 : perf.fastStockMode ? 3 : 5
  );

  const pexFetch = (query: string, t: string, off: number) => () =>
    fetchPexelsClips(
      query, clipFetchDur, workDir, sceneIndex, perf.fastStockMode ? 2 : 3, [query], true, t,
      dedup.usedPexelsIds, off, dedup.perf.pexelsDownloadRetries,
      { beatText: beat.text }
    );
  const pixFetch = (query: string, t: string, off: number) => () =>
    fetchPixabayClips(query, clipFetchDur, workDir, sceneIndex, 2, t, true, dedup.usedPixabayIds, off, {
      beatText: beat.text,
    });

  for (let qi = 0; qi < stockQueries.length; qi++) {
    const q = stockQueries[qi];
    const off = offset + qi * 2;
    if (PEXELS_API_KEY) {
      clip = await tryStockSources(
        [{ query: q, fetch: pexFetch(q, `${tag}_pex`, off) }],
        dedup, sceneIndex, beat.index, beat.text, workDir, "unique Pexels fallback", looseOpts
      );
      if (clip) {
        markLicensedStockBeatUsed(dedup);
        return clip;
      }
    }
    if (PIXABAY_API_KEY) {
      clip = await tryStockSources(
        [{ query: q, fetch: pixFetch(q, `${tag}_pix`, off + 40) }],
        dedup, sceneIndex, beat.index, beat.text, workDir, "unique Pixabay fallback", looseOpts
      );
      if (clip) {
        markLicensedStockBeatUsed(dedup);
        return clip;
      }
    }
  }
  return null;
}

/**
 * A SLOT WITH NO SENTENCE BEHIND IT MAY NOT SPEND RETRIEVAL.
 *
 * ── What render 594 spent ───────────────────────────────────────────────────────────────────
 *
 *     [BeatRelevance]  s1b6: backfill approval requirement suspended: reason=slot_without_beat  (7×)
 *     [BeatLookups]    beat=s1b6 lookups=13 … declined: no_narration=8
 *     [YOUTUBE_TURN]   scene=1 beat=6 turn=START … result=YOUTUBE_CANDIDATES_DELIVERED usedMs=35533
 *     [VisualLineageEvent] … providerAssetId=LW9xaNF5iLs stage=DOWNLOAD_SUCCEEDED
 *
 * `minClipsForScene` can need more pictures than a scene has sentences, and the extra places are
 * montage slots. There is no beat at that index, so `contextFor` returns nothing, so no approval
 * can ever be earned for anything put there — that rule is RONDE 215's and this round does not
 * touch it. What render 594 showed is the COST of asking anyway: thirteen editor lookups and a
 * thirty-six second YouTube download for a slot whose answer was decided before the search began.
 * That was the only YouTube candidate of the whole render.
 *
 * ── Why the check is here and not at the end ────────────────────────────────────────────────
 *
 * Refusing the candidate after it has been fetched is what already happened. The point is to stop
 * BEFORE provider acquisition, so the beat's turn, its download slot and its reserve stay with
 * the beats that can use them.
 *
 * ── What it does NOT do ─────────────────────────────────────────────────────────────────────
 *
 * It refuses no picture and lowers no bar. The slot is left to the same guaranteed-fill and
 * coverage logic that already handles a beat nothing was found for; it simply gets there without
 * paying for a search first. A scope that cannot count this scene's beats returns false, so the
 * behaviour is unchanged wherever the record is absent — never claim more than you know.
 */
function slotHasNoBeatBehindIt(sceneIndex: number, beatIndex: number | undefined): boolean {
  if (beatIndex == null) return false;
  const scope = getComposeJudgeScope();
  const beatCount = scope?.beatCountFor?.(sceneIndex);
  return beatCount != null && beatIndex >= beatCount;
}

/** Last-resort real stock video — broad queries, non-strict mode. No still photos. */
async function fetchLastResortRealClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle?: string,
  adoptOpts: VisualAdoptOptions = {}
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchLastResortRealClipInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts), { personName });
}

async function fetchLastResortRealClipInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle?: string,
  adoptOpts: VisualAdoptOptions = {}
): Promise<string | null> {
  // Bound each beat's archive attempt so one slow lookup can't eat the whole sequential
  // compose-stage budget — falls through to the stock chain below on timeout.
  let ownArchiveClip: string | null = null;
  try {
    ownArchiveClip = await withSceneFetchTimeout(
      () =>
        fetchCuratedArchiveBeatClipWithLineage(dedup, sceneIndex, beat.index, (pickedOut) =>
          fetchCuratedArchiveBeatClip(
            beat,
            scene,
            workDir,
            sceneIndex,
            beat.holdSec,
            dedup.usedCuratedAssetIds,
            dedup.usedCuratedStorageUrls,
            videoTitle,
            curatedInterviewBudget(dedup),
            curatedImageBudget(dedup),
            undefined,
            {
              varietySeed: dedup.varietySeed,
              crossVideoExcludeIds: dedup.crossVideoExcludeIds,
              assetsCache: dedup.archiveAssetsCache,
              pickedOut,
            }
          )
        ),
      archiveBeatBudgetMs(dedup.videoLength, get_activeBudgetTracker()?.remainingMs?.()),
      `archive s${sceneIndex} b${beat.index} (last resort)`
    );
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: archive beat budget exceeded (last resort) —`,
      (err as Error).message?.slice(0, 80)
    );
  }
  if (ownArchiveClip !== null) return ownArchiveClip;
  
  const tag = `b${beat.index}_lr`;
  const candidateOffset = beat.index * 5 + sceneIndex + 11;
  const queries = [
    ...scriptStockSearchQueries(beat.text),
    enrichStockQuery(beat.searchQuery, scene, videoTitle, personName, beat.text),
    enrichStockQuery(scene.visualCue, scene, videoTitle, personName, beat.text),
    enrichStockQuery(scene.pexelsQuery, scene, videoTitle, personName, beat.text),
    ...(scene.pexelsQueries ?? []).map((q) => enrichStockQuery(q, scene, videoTitle, personName, beat.text)),
    ...(scene.brollQueries ?? []).map((q) => enrichStockQuery(q, scene, videoTitle, personName, beat.text)),
  ].filter((q) => toQueryString(q).length > 2 && !isBlockedStockQuery(toQueryString(q)));

  const uniqueQueries = [...new Set(queries)];

  const ytQueries = [
    // RONDE 249: the script's person before the hardcoded table.
    ...(coercePersonName(personName)
      ? buildPersonCelebrityVideoQueries(personName, beat.text, beat.index)
      : []),
    ...realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle),
  ];
  const ytClip = (await runCentralYoutubeTurn({
                   beat,
                   scene,
                   workDir,
                   sceneIndex,
                   clipFetchDur,
                   dedup,
                   visualNeed: "last_resort",
                   queries: ytQueries,
                   queryBuilder: "ytQueries",
                   termSource: "last-resort YouTube",
                   adoptOpts: adoptOpts,
                   timeoutMs: youtubeBeatFetchTimeoutMs(dedup.perf.fastStockMode),
                 })).clip;
  if (ytClip) return ytClip;

  const topicReal = await tryBeatTopicRealFootage(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    adoptOpts,
    videoTitle,
    personName,
    { includeTopicYoutube: false, fileTag: tag }
  );
  if (topicReal) return topicReal;

  if ((dedup.perf.minimizeStockFootage || realFootageFirstEnabled()) && !canUseLicensedStockBeat(dedup)) {
    return null;
  }

  const stockTryCap = dedup.perf.minimizeStockFootage
    ? 1
    : dedup.perf.fastStockMode
      ? 4
      : 6;
  for (const q of uniqueQueries.slice(0, stockTryCap)) {
    const pex = await fetchPexelsClips(
      q, clipFetchDur, workDir, sceneIndex, 2, undefined, true, `${tag}_pex`,
      dedup.usedPexelsIds, candidateOffset, dedup.perf.pexelsDownloadRetries
    );
    let clip = await adoptClip(pex, dedup, sceneIndex, beat.index, beat.text, workDir, q, adoptOpts);
    if (clip) {
      markLicensedStockBeatUsed(dedup);
      console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: last-resort Pexels "${q}"`);
      return clip;
    }

    const pix = await fetchPixabayClips(
      q, clipFetchDur, workDir, sceneIndex, 2, `${tag}_pix`, true,
      dedup.usedPixabayIds, candidateOffset
    );
    clip = await adoptClip(pix, dedup, sceneIndex, beat.index, beat.text, workDir, q, adoptOpts);
    if (clip) {
      markLicensedStockBeatUsed(dedup);
      console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: last-resort Pixabay "${q}"`);
      return clip;
    }
  }

  return null;
}

/** Real footage of a named person (Pexels video → YouTube → max 1 still). */
async function fetchPersonBeatClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  pexFetch: (query: string, t: string, off: number, count?: number) => () => Promise<string[]>,
  candidateOffset: number,
  tag: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchPersonBeatClipInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts, pexFetch, candidateOffset, tag), { personName });
}

async function fetchPersonBeatClipInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  pexFetch: (query: string, t: string, off: number, count?: number) => () => Promise<string[]>,
  candidateOffset: number,
  tag: string
): Promise<string | null> {
  const personLocked = dedup.personTopicLock && Boolean(dedup.primaryPerson);
  if (!coercePersonName(personName)) return null;
  if (!personLocked && !beatMentionsPerson(beat.text, personName)) return null;

  const personQueries = buildPersonCelebrityVideoQueries(personName, beat.text, beat.index);
  const loosePerson: VisualAdoptOptions = {
    ...adoptOpts,
    requireBeatMatch: false,
    personTopic: true,
    primaryPerson: personName,
    keywords: buildPersonBeatRelevanceKeywords(personName, beat.text),
  };

  const fast = dedup.perf.fastStockMode;
  let clip = (await runCentralYoutubeTurn({
               beat,
               scene,
               workDir,
               sceneIndex,
               clipFetchDur,
               dedup,
               visualNeed: "person",
               queries: personQueries,
               queryBuilder: "personQueries",
               termSource: `person YouTube (${personName})`,
               adoptOpts: loosePerson,
               timeoutMs: youtubeBeatFetchTimeoutMs(fast),
             })).clip;
  if (clip) return clip;

  const celebVids = await withSceneFetchTimeout(
    () => fetchPersonCelebrityVideoClips(
      personName,
      clipFetchDur,
      workDir,
      sceneIndex,
      celebrityFetchFastMode(dedup.perf, scene.duration) ? 2 : 3,
      `${tag}_person`,
      beat.index,
      beat.text,
      celebrityFetchFastMode(dedup.perf, scene.duration),
      dedup.usedContentKeys,
      dedup.sourcingCache
    ),
    personCelebrityVideoWallMs(dedup.perf, scene.duration),
    `person celebrity video s${sceneIndex} b${beat.index}`
  ).catch(() => [] as CelebrityClipCandidate[]);
  clip = await adoptBestCelebrityClip(
    celebVids,
    dedup,
    sceneIndex,
    beat.index,
    beat.text,
    workDir,
    personName,
    loosePerson
  );
  if (clip && !isStillPhotoClip(clip)) {
    console.log(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: person video Wiki/Sepia/Archive (${personName})`
    );
    return clip;
  }

  if (canUseLicensedStockBeat(dedup)) {
    clip = await tryStockSources(
      [{
        // RONDE 93 (§6): the person, not an interview the beat never mentioned.
        query: personName,
        fetch: pexFetch(personName, `${tag}_person_vid`, candidateOffset, 2),
      }],
      dedup,
      sceneIndex,
      beat.index,
      beat.text,
      workDir,
      `person Pexels video (${personName})`,
      loosePerson
    );
    if (clip && !isStillPhotoClip(clip)) {
      markLicensedStockBeatUsed(dedup);
      return clip;
    }
  }

  if (SERPAPI_KEY && canUseGlobalStillPhoto(dedup)) {
    const serpQ = buildPersonSerpQuery(personName, sceneIndex, beat.index, beat.text);
    const serpPaths = await fetchSerpAPIImages(
      serpQ,
      clipFetchDur,
      workDir,
      sceneIndex,
      MULTI_CANDIDATE_FETCH_COUNT,
      `${tag}_person`,
      {
        dedup,
        personPortrait: true,
        resultOffset: sceneIndex * 2 + beat.index,
      }
    );
    clip = await adoptClip(
      serpPaths, dedup, sceneIndex, beat.index, beat.text, workDir, serpQ, loosePerson
    );
    if (clip) {
      console.log(`[Pipeline] Scene ${sceneIndex} beat ${beat.index}: SerpAPI portrait (${serpQ})`);
      return clip;
    }
  }

  if (canUseGlobalStillPhoto(dedup)) {
    const ovPaths = await fetchOpenverseImages(
      `${personName} portrait face`,
      clipFetchDur,
      workDir,
      sceneIndex,
      MULTI_CANDIDATE_FETCH_COUNT,
      `${tag}_person`,
      { dedup, personPortrait: true }
    );
    clip = await adoptClip(
      ovPaths, dedup, sceneIndex, beat.index, beat.text, workDir, personName, loosePerson
    );
    if (clip) return clip;
  }

  if (!dedup.perf.minimizeStockFootage && canUseLicensedStockBeat(dedup)) {
    const personPexels = personQueries.slice(0, fast ? 1 : 2);
    clip = await tryStockSources(
      personPexels.map((pq, pi) => ({
        query: pq,
        fetch: pexFetch(pq, `${tag}_person`, candidateOffset + pi, fast ? 1 : 2),
      })),
      dedup, sceneIndex, beat.index, beat.text, workDir, `person Pexels fallback (${personName})`, loosePerson
    );
    if (clip && !isStillPhotoClip(clip)) {
      markLicensedStockBeatUsed(dedup);
      return clip;
    }
  }

  return null;
}

// F3-28: source cascade priority for historical/archival beat sourcing. Own curated archive is
// handled by the caller (fetchCuratedArchiveBeatClip) before this list is ever consulted; Pexels
// and Pixabay are deliberately NOT in this list — they stay the separate, absolute-last-resort
// tier in fetchBeatArchivalThenPexels/fetchBeatStockFallback, tried only after every tier below
// has failed for a beat. Exported as plain data so the exact required order can be verified with
// a direct assertion instead of mocking every underlying fetch function.
/**
 * THE HISTORICAL CASCADE — A MEMBER LIST, NOT AN ORDERING AUTHORITY.
 *
 * ── What this literal is, and what it deliberately is NOT any more ──────────────────────────
 *
 * It reads tier 3 before tier 1: `internet_archive` ahead of `youtube_cc`. That is not an
 * oversight — F3-28 states it as a requirement and `videoPipeline.f328SourceCascade.test.ts`
 * asserts the exact sequence. It is an editorial judgement about which ARCHIVAL sources answer a
 * historical beat best, made before the sourcing ladder existed.
 *
 * The integrity audit asked whether it is a second routing authority, and the honest answer is
 * that it no longer is one. Every search in this cascade passes `searchGateDecision`, so the
 * ladder decides which tier may run: on a beat whose tier 1 is neither attempted nor declined,
 * the Internet Archive entry is refused with TIER_OUT_OF_ORDER and the loop moves to `youtube_cc`.
 * The runtime order is the ladder's; this list supplies the MEMBERS and the preference among
 * sources that share a tier.
 *
 * I did reorder it by tier in this round, and reverted that. It changed no runtime behaviour the
 * ladder was not already deciding, and it overrode an explicit earlier requirement to buy nothing.
 * If the two orderings should be reconciled in the literal as well, that is a product decision
 * about F3-28 rather than a routing fix, and it belongs to whoever owns that requirement.
 */
export const HISTORICAL_SOURCE_TIER_ORDER = [
  "internet_archive",
  "youtube_cc",
  "wikimedia",
  "nara",
  "flickr",
  "sepiasearch",
  "vimeo",
  "media_ccc",
  "nasa",
] as const;
export type HistoricalSourceTier = (typeof HISTORICAL_SOURCE_TIER_ORDER)[number];

/** Archival real video for historical beats, tried in HISTORICAL_SOURCE_TIER_ORDER (no
 *  stills/stock — Pexels/Pixabay are the caller's separate last-resort tier). */
export async function fetchHistoricalBeatVideo(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  intent: ReturnType<typeof buildMediaSearchIntent>,
  adoptOpts: VisualAdoptOptions,
  tag: string,
  opts: HistoricalBeatVideoOpts = {}
): Promise<string | null> {
  // RONDE 90 (§2): the beat's proof, in scope for every provider search beneath this call.
  return withSearchProvenance(beatSearchProvenance(beat, scene), () =>
    fetchHistoricalBeatVideoInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, intent, adoptOpts, tag, opts)
  );
}

/**
 * RONDE 132 — the two knobs the corrected-query research pass needs, and nothing else.
 *
 * Deliberately additive: every existing caller passes neither and gets exactly the behaviour it
 * had. The research pass is the only caller that sets them, and it sets both together.
 */
export type HistoricalBeatVideoOpts = {
  skipYoutube?: boolean;
  /**
   * Queries to try FIRST, ahead of the ones this cascade builds for itself.
   *
   * They are still deduped and still cut to the same per-beat cap, so this does not widen the
   * provider budget — it changes which questions get asked inside it. Every string here must have
   * come from `buildPrioritisedQueries`; the SearchGate that wraps this call is what enforces
   * that, and a term that does not trace to the beat is refused there exactly as any other would
   * be.
   */
  leadQueries?: readonly string[];
  /**
   * Allow this beat's cascade to run a SECOND time.
   *
   * `historicalCascadeAttemptedBeats` normally makes the cascade a once-per-beat affair, which is
   * right for the ordinary path. A research pass is by definition a second look, so it says so
   * rather than quietly deleting the guard for everyone. The caller enforces the one-pass limit;
   * this flag only removes the door.
   */
  researchPass?: boolean;
};

async function fetchHistoricalBeatVideoInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  intent: ReturnType<typeof buildMediaSearchIntent>,
  adoptOpts: VisualAdoptOptions,
  tag: string,
  opts: HistoricalBeatVideoOpts = {}
): Promise<string | null> {
  // F3-49: skip the whole cascade outright if it already ran (and missed) for this exact beat
  // earlier this render — see historicalCascadeAttemptedBeats' doc comment on VisualDedupState.
  //
  // RONDE 132: a research pass is allowed through, once. The one-pass limit lives in the caller's
  // `mismatchResearchedBeats` set, so this guard keeps its original meaning for every other route.
  const cascadeKey = `s${sceneIndex}b${beat.index}`;
  if (!opts.researchPass && dedup.historicalCascadeAttemptedBeats.has(cascadeKey)) {
    return null;
  }
  const beatKeywords = adoptOpts.keywords ?? beat.keywords;
  const loose: VisualAdoptOptions = { ...adoptOpts, requireBeatMatch: false, scriptAnchored: false };
  const queries = buildHistoricalArchivalQueries(intent, beat.text, { place: extractVisualPlacePhrase(beat.text), action: extractActionCue(beat.text) });
  const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, adoptOpts.videoTitle);
  // Credit optimization: cap applies per tier (each of the 9 tiers below tries the same
  // deduped query list, in order, stopping at first success) — was 6 in normal mode, which at
  // 9 tiers meant up to 54 tier-fetch attempts per beat in the worst case (all tiers/queries
  // miss). 3 strong, deduped queries (2 in fastStockMode, unchanged) keeps the same
  // strongest-query-first ordering while roughly halving that worst-case ceiling, without
  // dropping any tier or changing ranking/content.
  const queryCap = dedup.perf.fastStockMode ? 2 : 3;
  /**
   * RONDE 132 — the corrected question leads, inside the same cap.
   *
   * `uniqueQueryStrings` dedupes, and the slice is unchanged, so a research pass asks the SAME
   * NUMBER of questions the ordinary pass would have asked — just better ones. That is what makes
   * this affordable: it does not add provider calls, it redirects them.
   */
  const allQueries = uniqueQueryStrings([...(opts.leadQueries ?? []), ...entityYt, ...queries]).slice(
    0,
    queryCap
  );
  const archiveHitsPerQuery = dedup.perf.fastStockMode ? 1 : 2;
  const youtubeReady = !opts.skipYoutube;

  /**
   * RONDE 260B — the cascade's YouTube tier is an adapter over the beat's one central turn.
   *
   * The tier used to be called once per query and searched every time. Its queries are all known
   * before the loop starts, so the turn takes them together: one visit to the provider, with the
   * same query set the per-query loop would have used, and the candidates delivered to the pool the
   * cascade ranks across ten sources.
   *
   * Delivered once, on the first query that reaches the tier. Later queries get an empty list
   * because the provider has already answered for all of them — not because the tier was refused.
   */
  let ytDelivered = false;
  const cascadeYoutubeCandidates = async (): Promise<string[]> => {
    if (ytDelivered) return [];
    ytDelivered = true;
    const turn = await runCentralYoutubeTurn({
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      visualNeed: "archival",
      queries: allQueries,
      queryBuilder: "historicalCascadeQueries",
      termSource: `historical cascade ${tag}`,
      adoptOpts,
      timeoutMs: youtubeBeatFetchTimeoutMs(dedup.perf.fastStockMode),
      deliver: "candidates",
      // The cascade never spent from the entity ceiling; making it do so would tighten a gate.
      countsAgainstEntityCeiling: false,
    });
    return turn.candidatePaths;
  };

  // Visual dedup: dedup.usedContentKeys is the SAME set adoptClip checks/populates on actual
  // acceptance (see clipContentKey's PROVIDER_ASSET_TAG_RE branch) — passing it into every tier
  // here lets a provider skip a search hit whose provider:hash(id) key was already accepted
  // earlier this render (by this cascade or by researchBeatClipUnified's own direct fetch
  // calls) before spending the metadata/license/download cost on it. adoptClip's own
  // provider-tag check remains the authoritative, race-safe gate regardless of this optimization.
  const fetchTierPaths = async (tier: HistoricalSourceTier, q: string): Promise<string[]> => {
    switch (tier) {
      case "internet_archive":
        if (!dedup.perf.enableArchival) return [];
        return (await fetchInternetArchiveClips(
          q, clipFetchDur, workDir, sceneIndex, archiveHitsPerQuery, `${tag}_hist`, "", beatKeywords,
          dedup.usedContentKeys,
          dedup.sourcingCache
        )).map((h) => h.path);
      case "youtube_cc":
        if (!youtubeReady) return [];
        return cascadeYoutubeCandidates();
      case "wikimedia":
        return (await fetchWikimediaVideos(
          q, clipFetchDur, workDir, sceneIndex, 2, `${tag}_hist`, "", beatKeywords, dedup.usedContentKeys, dedup.sourcingCache
        )).map((h) => h.path);
      case "nara":
        return fetchNaraClips(q, clipFetchDur, workDir, sceneIndex, 1, dedup.usedContentKeys, dedup.sourcingCache);
      case "flickr":
        return fetchFlickrCCVideos(
          q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_hist`, "", beatKeywords, dedup.usedContentKeys, dedup.sourcingCache
        );
      case "sepiasearch":
        return (await fetchSepiaSearchVideos(
          q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_hist`, "", beatKeywords, dedup.usedContentKeys, dedup.sourcingCache
        )).map((h) => h.path);
      case "vimeo":
        return (await fetchVimeoCCVideos(
          q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_hist`, "", beatKeywords, dedup.usedContentKeys, dedup.sourcingCache
        )).map((h) => h.path);
      case "media_ccc":
        // P0 fix 3: same tech/celebrity topic gate already used elsewhere (e.g.
        // fetchPersonCelebrityVideoClips) — applied here so a beat unrelated to that topic
        // skips this relatively slow, ungated-elsewhere provider instead of always querying it.
        if (!personMatchesTechCccTopic(intent.primaryPerson ?? "", beat.text)) return [];
        return fetchMediaCccVideos(q, clipFetchDur, workDir, sceneIndex, 1, `${tag}_hist`, dedup.usedContentKeys, dedup.sourcingCache);
      case "nasa":
        // P0 fix 3: same space-topic gate already used to build `intent.spaceTopic` elsewhere
        // (e.g. line ~1812) — computed fresh here rather than trusting intent.spaceTopic, since
        // at least one caller (fetchHistoricalBeatRescue) hardcodes that field to false
        // regardless of actual topic, which would have wrongly disabled NASA for every rescue.
        if (!isSpaceRelatedTopic(scene.visualCue, scene.pexelsQuery, beat.text, scene.text, adoptOpts.videoTitle ?? "")) {
          return [];
        }
        return fetchNasaVideoClips(q, clipFetchDur, workDir, sceneIndex, 1, dedup.usedContentKeys, dedup.sourcingCache);
    }
  };

  // F3-49: mark attempted only here, right before the first external call — a cancellation or
  // exception in the (synchronous, cheap) setup above never reaches this line, so it can't
  // poison a future genuine first attempt for this beat. Once the cascade actually starts,
  // it counts as attempted regardless of how it ends (success, miss, thrown error, or
  // cancellation mid-loop) — matching strictRefillAttemptedScenes' existing semantics.
  dedup.historicalCascadeAttemptedBeats.add(cascadeKey);

  // Limited cross-provider video pooling patch: instead of adopting whichever tier of
  // HISTORICAL_SOURCE_TIER_ORDER happens to be tried first, collect candidates across a bounded
  // number of tiers (same providers, same per-tier query/count budgets as before) into one pool,
  // then run adoptClip's existing ranking/gates ONCE across the combined pool. A candidate that
  // already looks strong enough — reusing the exact same entity/event/location signals the still-
  // image pooling patch (fetchBeatAuthenticStills) uses, no new scoring system — still short-
  // circuits collection, so the common "first tier already nails it" case costs no extra fetches
  // versus the old sequential first-success behavior. POOL_RAW_CANDIDATE_TARGET additionally caps
  // how many tiers get tried on a run of weak/empty misses, so a beat with no strong signal
  // doesn't unconditionally exhaust all 9 tiers before ranking (worst case — nothing found at all
  // — is unchanged: it already tried every tier/query before returning null).
  const pool: string[] = [];
  const beatFocus = classifyBeatFocus(beat.text, intent.primaryPerson || undefined, adoptOpts.videoTitle);
  const providerTextFor = (p: string) =>
    dedup.clipAnnotationMeta.get(p)?.providerText ?? dedup.sourcingCache.assets.get(clipContentKey(p))?.providerText;
  const strongEnoughToStopPooling = (p: string): boolean => {
    const pt = providerTextFor(p);
    if (!pt) return false;
    return candidatePoolEarlyExitReady(
      beatFocus,
      classifyEntityMatchTier(intent.primaryPerson || undefined, pt),
      eventMatchScore(beat.text, pt),
      locationMatchScore(dedup.assetDirectorActiveLocation, pt),
      objectMatchScore(beat.text, pt)
    );
  };
  const POOL_RAW_CANDIDATE_TARGET = 3;
  const POOL_MAX = 5;

  /**
   * WHAT THIS CASCADE CANNOT SERVE, SAID BEFORE IT WALKS.
   *
   * ── Render 592-B: two beats that asked no provider at all ───────────────────────────────────
   *
   * `HISTORICAL_SOURCE_TIER_ORDER` holds nine providers: one of tier 1 and eight of tier 3. Not a
   * single tier-2 member. So this cascade could never attempt the operator's own archive, and the
   * ladder — which refuses a tier while a higher one is neither attempted nor declined — refused
   * every one of its own tier-3 members for skipping a tier 2 that this route has no way to ask.
   *
   * Beats s2b4 and s2b5 of render 592-B are the receipt: twenty-four TIER_OUT_OF_ORDER refusals
   * each and `providers=0`. Two sentences whose route asked nothing of anybody.
   *
   * The declaration is a fact about the ROUTE, computed from its own member list rather than
   * written down a second time: add an archive provider to the cascade and the decline disappears
   * by itself. It cannot let stock through early — a route whose members stop at tier 3 unlocks
   * tier 3, and tier 4 still waits on whatever tier 3 does.
   */
  declineTiersNotServedBy(HISTORICAL_SOURCE_TIER_ORDER, "historical_cascade");

  let stopPooling = false;
  for (const tier of HISTORICAL_SOURCE_TIER_ORDER) {
    if (stopPooling) break;
    for (const q of allQueries) {
      const paths = await fetchTierPaths(tier, q);
      if (paths.length === 0) continue;
      pool.push(...paths);
      // Point 11 (final visual intelligence hardening — per-candidate source query): record the
      // actual query that found each candidate, informational/explainability only (see
      // CandidateMeta.sourceQuery's doc comment in assetDirector.ts) — adoptClip's own gate
      // evaluation below still uses beat.text as the shared sourceQuery for the whole pool, so
      // this can never reopen the BLOCKED_STOCK_VISUAL_RE sourceQuery-scoping bug fixed earlier.
      for (const p of paths) {
        const existing = dedup.clipAnnotationMeta.get(p) ?? {};
        if (!existing.sourceQuery) dedup.clipAnnotationMeta.set(p, { ...existing, sourceQuery: q });
      }
      if (paths.some(strongEnoughToStopPooling) || pool.length >= POOL_RAW_CANDIDATE_TARGET) {
        stopPooling = true;
        break;
      }
    }
  }

  if (!pool.length) return null;
  const boundedPool = [...new Set(pool)].slice(0, POOL_MAX);
  // Point: the pool spans candidates fetched under several different generated query strings
  // (buildHistoricalArchivalQueries's own variants, e.g. "${anchor} archival footage") — passing
  // any one of those specific strings as adoptClip's single sourceQuery for the WHOLE merged pool
  // would score every other candidate against a query it was never actually found under. beat.text
  // is the one description that's true for the whole pool regardless of which query/tier found
  // which candidate, so it's the only safe choice here — unlike the single-query case elsewhere
  // in this file, where sourceQuery and beatText intentionally differ.
  const clip = await adoptClip(boundedPool, dedup, sceneIndex, beat.index, beat.text, workDir, beat.text, loose);
  if (isRealVideoClip(clip)) {
    console.log(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: historical video from pool of ${boundedPool.length} (${HISTORICAL_SOURCE_TIER_ORDER.join("/")})`
    );
    return clip;
  }

  return null;
}

/**
 * Universal media research (Laag 2+3): parallel multi-source fetch, rank, adopt best clip.
 * Falls through to the legacy waterfall when nothing passes adoption gates.
 */
async function researchBeatClipUnified(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  beatQueries: string[],
  scenePersons: string[],
  primary: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  tag: string,
  muskTopic: boolean,
  pexFetch: (query: string, t: string, off: number, count?: number) => () => Promise<string[]>,
  candidateOffset: number
): Promise<string | null> {
  // RONDE 90 (§2): the beat's proof, in scope for every provider search beneath this call.
  return withSearchProvenance(beatSearchProvenance(beat, scene, primary, scenePersons), () =>
    researchBeatClipUnifiedInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, beatQueries, scenePersons, primary, videoTitle, adoptOpts, tag, muskTopic, pexFetch, candidateOffset)
  );
}

async function researchBeatClipUnifiedInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  beatQueries: string[],
  scenePersons: string[],
  primary: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  tag: string,
  muskTopic: boolean,
  pexFetch: (query: string, t: string, off: number, count?: number) => () => Promise<string[]>,
  candidateOffset: number
): Promise<string | null> {
  if (process.env.ENABLE_MEDIA_RESEARCH === "false") return null;

  const perf = dedup.perf;
  const spaceTopic = isSpaceRelatedTopic(
    scene.visualCue,
    scene.pexelsQuery,
    beat.text,
    scene.text,
    videoTitle ?? "",
    beat.powerWord
  );

  const historicalCtx =
    isHistoricalDocumentary(videoTitle, beat.text, scene.text) && !dedup.personTopicLock;
  const effectivePrimary = historicalCtx ? "" : (primary?.trim() ?? "");

  const intent = buildMediaSearchIntent({
    beatText: beat.text,
    searchQueries: beatQueries,
    keywords: adoptOpts.keywords ?? beat.keywords,
    primaryPerson: effectivePrimary,
    persons: scenePersons,
    videoTitle,
    powerWord: beat.powerWord,
    personTopicLock: dedup.personTopicLock && !historicalCtx,
    spaceTopic,
    muskTopic,
  });

  const archivalFirst = prefersRealFootageOnly(intent);
  const realOnly = realFootageFirstEnabled();

  if (archivalFirst || realOnly) {
    if (youtubeSourcingEnabled()) {
      const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle);
      const ytFirstQueries = [
        // RONDE 249: the script's person before the hardcoded table.
        ...(effectivePrimary.trim()
          ? buildPersonCelebrityVideoQueries(effectivePrimary, beat.text, beat.index)
          : []),
        ...entityYt,
        ...buildTopicDocumentaryYoutubeQueries(beat, scene, videoTitle),
      ];
      const ytFirst = (await runCentralYoutubeTurn({
                        beat,
                        scene,
                        workDir,
                        sceneIndex,
                        clipFetchDur,
                        dedup,
                        visualNeed: "research",
                        queries: [...new Set(ytFirstQueries.map(toQueryString).filter((q) => q.length > 3))].slice(0, 6),
                        queryBuilder: "ytFirstQueries",
                        termSource: "research YouTube first",
                        adoptOpts: { ...adoptOpts, requireBeatMatch: false, scriptAnchored: false },
                        timeoutMs: youtubeBeatFetchTimeoutMs(perf.fastStockMode),
                      })).clip;
      if (ytFirst && isAuthenticVideoClip(ytFirst)) return ytFirst;
    } else {
      const histFirst = await fetchHistoricalBeatVideo(
        beat,
        scene,
        workDir,
        sceneIndex,
        clipFetchDur,
        dedup,
        intent,
        adoptOpts,
        tag,
        { skipYoutube: true }
      );
      if (histFirst && isAuthenticVideoClip(histFirst)) return histFirst;
    }
  }

  if (archivalFirst) {
    const histClip = await fetchHistoricalBeatVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      intent,
      adoptOpts,
      tag,
      { skipYoutube: true }
    );
    if (histClip && isAuthenticVideoClip(histClip)) return histClip;
  }

  const queries = archivalFirst
    ? buildHistoricalArchivalQueries(intent, beat.text, { place: extractVisualPlacePhrase(beat.text), action: extractActionCue(beat.text) }).slice(0, perf.fastStockMode ? 4 : 6)
    : intent.searchQueries.slice(0, perf.fastStockMode ? 2 : 4);
  const primaryQ = queries[0] || beat.searchQuery || beat.powerWord;
  const beatKeywords = adoptOpts.keywords ?? beat.keywords;
  const entityRules = extractBeatRealEntities(beat.text, scene.text, videoTitle ?? "");
  const fetchMs = archivalFirst
    ? (perf.fastStockMode ? 40_000 : 45_000)
    : (perf.fastStockMode ? 18_000 : 35_000);
  const maxTasks = archivalFirst
    ? (perf.fastStockMode ? 14 : 18)
    : (perf.fastStockMode ? 10 : 18);

  const toCandidates = (
    paths: string[],
    query: string,
    source: MediaSourceKind,
    isVideo: boolean
  ): MediaCandidate[] =>
    paths.filter(Boolean).map((p) => ({ path: p, query, source, isVideo }));

  /**
   * `provider` is the capability registry's label for whatever this task asks, so the round can
   * order itself by what the beat needs instead of by the order the pushes happen to be written in.
   *
   * Optional on purpose. Three of the fourteen tasks — the celebrity route, Unsplash and SerpAPI —
   * have no registry entry, and inventing one for them to satisfy a type would be exactly the
   * guess `providerCapability` refuses to make. An unlabelled task is ordered as "no information",
   * which leaves it precisely where it was.
   */
  type ResearchTask = { provider?: string; run: () => Promise<MediaCandidate[]> };
  const ytTasks: ResearchTask[] = [];
  const tasks: ResearchTask[] = [];

  const ytAvailable =
    youtubeSourcingEnabled() &&
    (process.env.YOUTUBE_API_KEY || RAPIDAPI_KEY || process.env.YOUTUBE_CC_DL_SERVICE);
  if (ytAvailable) {
    /**
     * RONDE 260 — the research race asked YouTube up to THREE times for one beat: once with the
     * entity queries, then once per celebrity/topic query. Three tasks, three searches, three sets
     * of downloads, all for the same beat and all ranked together afterwards anyway.
     *
     * They are now one task holding the beat's one turn, searching with the union of exactly the
     * queries the three tasks would have used. Nothing is dropped from the query set and nothing is
     * ranked differently — `toCandidates` still labels each candidate with the query it was found
     * under, because the race's ranking reads that.
     */
    const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle);
    const entityUsable =
      entityYt.length > 0 && dedup.entityYoutubeFetchesUsed < perf.maxEntityYoutubePerVideo;
    const ytQueries = primary?.trim()
      ? buildPersonCelebrityVideoQueries(primary, beat.text, beat.index).slice(0, 2)
      : queries.slice(0, 2);
    const unionQueries = [
      ...new Set([...(entityUsable ? entityYt.slice(0, 2) : []), ...ytQueries].filter(Boolean)),
    ];
    if (unionQueries.length > 0) {
      ytTasks.push({
        provider: "youtube_cc",
        run: async () => {
          /**
           * The turn is taken inside `run` and not while the task list is built: a task the race
           * never reaches — the `maxTasks` cap, a cancelled scope — must not hold the beat's turn
           * for a search that never ran.
           */
          const turn = await runCentralYoutubeTurn({
            beat,
            scene,
            workDir,
            sceneIndex,
            clipFetchDur,
            dedup,
            visualNeed: primary?.trim() ? "person" : "research",
            queries: unionQueries,
            queryBuilder: entityUsable
              ? "realEntityYoutubeQueriesForBeat+buildPersonCelebrityVideoQueries"
              : "buildPersonCelebrityVideoQueries",
            termSource: "research race",
            adoptOpts,
            timeoutMs: youtubeBeatFetchTimeoutMs(perf.fastStockMode),
            deliver: "candidates",
            // Exactly what the entity task did before, and what the celebrity tasks did not.
            countsAgainstEntityCeiling: entityUsable,
          });
          return toCandidates(turn.candidatePaths, unionQueries[0], "youtube_cc", true);
        },
      });
    }
  }

  if (effectivePrimary) {
    tasks.push({
      run: async () => {
        const fast = celebrityFetchFastMode(perf, scene.duration);
        const hits = await fetchPersonCelebrityVideoClips(
          effectivePrimary,
          clipFetchDur,
          workDir,
          sceneIndex,
          fast ? 2 : 3,
          `${tag}_research`,
          beat.index,
          beat.text,
          fast,
          dedup.usedContentKeys,
          dedup.sourcingCache
        );
        return hits.map((h) => ({
          path: h.path,
          query: h.query,
          source: "person_celebrity" as const,
          isVideo: true,
        }));
      },
    });
  }

  const querySlice = archivalFirst ? queries.slice(0, 4) : queries.slice(0, 2);
  for (const q of querySlice) {
    tasks.push({
      provider: "wikimedia",
      run: async () => {
        const hits = await fetchWikimediaVideos(
          q,
          clipFetchDur,
          workDir,
          sceneIndex,
          archivalFirst ? 3 : 2,
          `${tag}_research`,
          primary ?? "",
          beatKeywords,
          dedup.usedContentKeys,
          dedup.sourcingCache
        );
        return hits.map((h) => ({
          path: h.path,
          query: h.query,
          source: "wikimedia_video" as const,
          isVideo: true,
        }));
      },
    });

    if (perf.enableArchival) {
      tasks.push({
        provider: "internet_archive",
        run: async () => {
          const hits = await fetchInternetArchiveClips(
            q,
            clipFetchDur,
            workDir,
            sceneIndex,
            2,
            `${tag}_research`,
            primary ?? "",
            beatKeywords,
            dedup.usedContentKeys,
            dedup.sourcingCache
          );
          return hits.map((h) => ({
            path: h.path,
            query: h.query,
            source: "internet_archive" as const,
            isVideo: true,
          }));
        },
      });
    }
  }

  if (
    europeanaSourcingEnabled() &&
    EUROPEANA_API_KEY?.trim() &&
    (intent.topicKind === "historical" || intent.topicKind === "news")
  ) {
    tasks.push({
      provider: "europeana",
      run: async () => {
        const hits = await fetchEuropeanaVideos(
          queries.slice(0, 2),
          clipFetchDur,
          workDir,
          sceneIndex,
          2,
          `${tag}_research`,
          primary ?? "",
          beatKeywords,
          dedup.usedContentKeys,
          dedup.sourcingCache
        );
        return hits.map((h) => ({
          path: h.path,
          query: h.query,
          source: "europeana" as const,
          isVideo: true,
        }));
      },
    });
  }

  if (perf.enableNasa && spaceTopic && primaryQ) {
    tasks.push({
      provider: "nasa",
      run: async () => {
        const paths = await fetchNasaVideoClips(
          primaryQ, clipFetchDur, workDir, sceneIndex, 1, dedup.usedContentKeys, dedup.sourcingCache
        );
        return toCandidates(paths, primaryQ, "nasa", true);
      },
    });
  }

  if (!archivalFirst && !dedup.personTopicLock) {
    tasks.push({
      provider: "wikimedia",
      run: async () => {
        const imgs = await fetchWikimediaImages(
          primaryQ,
          clipFetchDur,
          workDir,
          sceneIndex,
          1,
          `${tag}_research`,
          { dedup, beatIndex: beat.index }
        );
        return toCandidates(imgs, primaryQ, "wikimedia_image", false);
      },
    });
    tasks.push({
      provider: "openverse",
      run: async () => {
        const ovQuery = primary?.trim() ? `${primary} ${primaryQ}` : primaryQ;
        const paths = await fetchOpenverseImages(
          ovQuery,
          clipFetchDur,
          workDir,
          sceneIndex,
          1,
          `${tag}_research`,
          { dedup, personPortrait: Boolean(primary?.trim()) }
        );
        return toCandidates(paths, ovQuery, "openverse", false);
      },
    });
    if (UNSPLASH_ACCESS_KEY?.trim()) {
      tasks.push({
        run: async () => {
          const unsplashQ = primary?.trim() ? `${primary} ${primaryQ}` : primaryQ;
          const paths = await fetchUnsplashImages(
            unsplashQ,
            clipFetchDur,
            workDir,
            sceneIndex,
            1,
            `${tag}_research`,
            { dedup, personPortrait: Boolean(primary?.trim()) }
          );
          return toCandidates(paths, unsplashQ, "unsplash", false);
        },
      });
    }
  }

  const allowStill =
    !archivalFirst &&
    (dedup.stillPhotosMaxThisScene === 0
      ? canUseGlobalStillPhoto(dedup)
      : dedup.stillPhotosThisScene < dedup.stillPhotosMaxThisScene);

  if (!archivalFirst && SERPAPI_KEY && allowStill && canUseGlobalStillPhoto(dedup)) {
    const serpQ = primary?.trim()
      ? buildPersonSerpQuery(primary, sceneIndex, beat.index, beat.text)
      : (primaryQ || beat.powerWord);
    tasks.push({
      run: async () => {
        const paths = await fetchSerpAPIImages(
          serpQ,
          clipFetchDur,
          workDir,
          sceneIndex,
          1,
          `${tag}_research`,
          {
            dedup,
            personPortrait: Boolean(primary?.trim()) || dedup.personTopicLock,
            resultOffset: sceneIndex * 2 + beat.index,
          }
        );
        return toCandidates(paths, serpQ, "serpapi", false);
      },
    });
  }

  // RONDE 97: the YouTube thumbnail task stood here, behind this same still-photo budget. It was
  // the worst of the four call sites, because it returned its stills under the "youtube_cc" source
  // label — so a ken-burns pan across a search-result picture was recorded as real YouTube footage
  // and counted as such in the audit. The whole branch is gone, its query included: a still cannot
  // be cut into a fragment, which is what FastVid uses YouTube for.

  const allowStock =
    !realOnly &&
    ((intent.personTopicLock && effectivePrimary)
      ? true
      : !perf.minimizeStockFootage && canUseLicensedStockBeat(dedup));

  if (!archivalFirst && allowStock) {
    if (intent.personTopicLock && primary?.trim()) {
      tasks.push({
        provider: "pexels",
        run: async () => {
          const personQueries = buildPersonStockVideoQueries(primary, beat, scene, videoTitle).slice(0, 3);
          const out: MediaCandidate[] = [];
          for (const q of personQueries) {
            if (PEXELS_API_KEY) {
              const pex = await fetchPexelsClips(
                q,
                clipFetchDur,
                workDir,
                sceneIndex,
                1,
                undefined,
                true,
                `${tag}_research`,
                dedup.usedPexelsIds,
                candidateOffset,
                perf.pexelsDownloadRetries
              );
              out.push(...toCandidates(pex, q, "pexels", true));
            }
            if (PIXABAY_API_KEY) {
              const pix = await fetchPixabayClips(
                q,
                clipFetchDur,
                workDir,
                sceneIndex,
                1,
                `${tag}_research`,
                true,
                dedup.usedPixabayIds,
                candidateOffset
              );
              out.push(...toCandidates(pix, q, "pixabay", true));
            }
          }
          return out;
        },
      });
    } else {
      for (const q of queries.slice(0, 2)) {
        if (PEXELS_API_KEY) {
          tasks.push({
            provider: "pexels",
            run: async () => {
              const paths = await pexFetch(q, `${tag}_research`, candidateOffset, muskTopic ? 2 : 1)();
              return toCandidates(paths, q, "pexels", true);
            },
          });
        }
        if (PIXABAY_API_KEY) {
          tasks.push({
            provider: "pixabay",
            run: async () => {
              const paths = await fetchPixabayClips(
                q,
                clipFetchDur,
                workDir,
                sceneIndex,
                1,
                `${tag}_research`,
                true,
                dedup.usedPixabayIds,
                candidateOffset
              );
              return toCandidates(paths, q, "pixabay", true);
            },
          });
        }
      }
    }
  }

  /**
   * NINE RESEARCH TASKS WERE BUILT AND NEVER RUN.
   *
   * This line stood two hundred lines higher, directly after the YouTube and archive tasks were
   * queued and BEFORE nine more `tasks.push(...)` calls. `[...ytTasks, ...tasks]` copies the array
   * as it is at that moment, so everything pushed afterwards went into `tasks` — which nothing
   * reads again. Europeana, NASA, Wikimedia images, Openverse, Unsplash, SerpAPI, Pexels (two
   * routes) and Pixabay (two routes) were constructed for every beat and discarded.
   *
   * ── Why this is a defect and not a budget ───────────────────────────────────────────────────
   *
   * `maxTasks` is 10, 14 or 18. The copied list held at most about nine, so the slice below never
   * bound anything — a ceiling of eighteen over a list that cannot reach ten is not a ceiling that
   * was meant to exclude these. It was written for the list WITH them in it.
   *
   * It has been this way since the line was introduced (60dc4f7, 17 Aug, "limited cross-provider
   * pooling"): ten pushes already sat below it in that same commit. Nothing drifted; the snapshot
   * was taken in the wrong place on the first day.
   *
   * ── What this does and does not change ──────────────────────────────────────────────────────
   *
   * The order is kept exactly — YouTube first, then the rest — because the slice favours the front
   * of the list and the YouTube route is the primary one. What changes is that the tail exists.
   *
   * These providers are NOT idle in the pipeline: each has between two and seven other call sites
   * and runs from them. What was missing is their part in the per-beat research round, which is
   * the round that looks for material for the sentence a shot will play under.
   *
   * `maxTasks` now binds for the first time, which is its job, and `fetchMs`/`researchMs` bound
   * the round as they always did. Nothing here raises a budget.
   */
  const allResearchTasks = [...ytTasks, ...tasks];

  /**
   * THE ROUND ASKS THE SOURCES THAT CAN ANSWER THIS BEAT — not the first ten in the file.
   *
   * ── What it replaces ──────────────────────────────────────────────────────────────────────
   *
   * `maxTasks` is 10, 14 or 18 and the list above holds fourteen, so the slice below genuinely
   * cuts. What it cut was decided entirely by the order the pushes are written in: YouTube, the
   * celebrity route, Wikimedia video, Internet Archive, Europeana, NASA, Wikimedia images,
   * Openverse, Unsplash, SerpAPI, then the stock libraries. Identical for a beat about the
   * Japanese economy and a beat about a bunker in 1945.
   *
   * ── What this is, and what it deliberately is not ─────────────────────────────────────────
   *
   * A stable reorder of the existing list, and nothing else. No task is added, none is removed,
   * no provider is skipped, no budget moves: `maxTasks` still binds and still binds at the same
   * number. It is a filter on ORDER, which is what decides who survives the slice.
   *
   * Not a second selection engine: the ordering key is `providerFitForNeed`, the same registry the
   * ranking reads, and it returns `null` for a source nobody has characterised. A null keeps the
   * task exactly where it was — "no information" is never a reason to demote a source.
   *
   * A beat whose intent proved nothing produces an empty `preferred`, every fit is then null, and
   * the order is byte-identical to the order before this round. The default is the old behaviour.
   */
  const routedResearchTasks = orderResearchTasksByNeed(
    allResearchTasks,
    mediaFormsForIntent(beatVisualIntent(dedup.beatIntent, sceneIndex, beat.index))
  );

  const researchMs = archivalFirst
    ? (perf.fastStockMode ? 95_000 : 110_000)
    : (perf.fastStockMode ? 50_000 : 100_000);
  let allCandidates: MediaCandidate[] = [];

  try {
    const settled = await withTimeout(
      Promise.allSettled(
        routedResearchTasks.slice(0, maxTasks).map((task) =>
          withTimeout(task.run(), fetchMs, `media research s${sceneIndex} b${beat.index}`).catch(
            () => [] as MediaCandidate[]
          )
        )
      ),
      researchMs,
      `media research s${sceneIndex} b${beat.index}`
    );
    for (const result of settled) {
      if (result.status === "fulfilled") allCandidates.push(...result.value);
    }
  } catch {
    return null;
  }

  if (!allCandidates.length) return null;

  const enrichScore = (c: MediaCandidate, base: number) =>
    base +
    scoreBeatNarrationMatch(beat.text, c.query, c.path) * 4 +
    realEntityScore(entityRules, c.query, c.path) +
    (primary && textMentionsPersonName(`${c.query} ${path.basename(c.path)}`, primary) ? 5 : 0) +
    (muskTopic ? muskBrandScore(c.query, c.path) : 0);

  let ranked = rankMediaCandidates(allCandidates, intent, enrichScore);
  ranked = await applyAiRelevanceRanking(ranked, intent, {
    fastMode: perf.fastStockMode,
    timeoutMs: perf.fastStockMode ? 8_000 : 14_000,
  });
  const adoptMs = perf.fastStockMode ? 12_000 : 45_000;
  const topN = perf.fastStockMode ? 12 : 20;
  const { videoFirst, stillFallback, stockFallback } = partitionCandidatesForIntent(ranked, intent);
  const adoptPools = archivalFirst
    ? realOnly
      ? [videoFirst]
      : [videoFirst, stillFallback, stockFallback]
    : [ranked];

  /**
   * RONDE 252 — THE POOL IS OFFERED AS A POOL.
   *
   * This walked `pool.slice(0, topN)` — up to twelve or twenty candidates — and called
   * `adoptClip([candidate.path], …)` once for each. A list of twenty became twenty selections of
   * one, and the beat's ranking, review pool and vision ordering each had a single candidate to
   * decide between. Render 585: `ranked / rankRuns` never above 1.00 on any beat, `reviewPool=1`
   * on all fifteen against a cap of 8.
   *
   * The candidates are already on disk, so offering them together starts no transfer that
   * offering them singly did not. What changes is that `adoptClip` now gets to do the job it
   * documents itself as doing.
   *
   * ── WHY THE LOOP SURVIVES, RATHER THAN BECOMING ONE CALL ────────────────────────────────
   *
   * Two checks below are about the candidate that WON, not about the pool: the licensed-stock
   * cap fires only for a pexels/pixabay candidate, and the type checks fire per pool. With one
   * call per candidate those were trivially attributable. With a pool they are not, so the winner
   * is resolved back to its candidate through `clipContentKey`, which exists for exactly this and
   * whose own note states the rule it relies on: "a derived asset keeps its parent's identity".
   *
   * A winner rejected by one of those checks is removed and the REMAINING pool is offered again,
   * which preserves the old behaviour of trying the next candidate — while still asking about a
   * pool rather than a single path. The rounds are bounded by the pool size, so this can never
   * cost more `adoptClip` calls than the per-candidate loop it replaces, and normally costs one.
   *
   * A winner that cannot be resolved to a candidate is treated as licensed stock: the cap is the
   * conservative reading, and a gate that cannot identify what it is admitting must not admit it
   * freely.
   */
  for (const pool of adoptPools) {
    if (!pool.length) continue;
    let selection = pool.slice(0, topN);
    while (selection.length > 0) {
      let clip: string | null = null;
      try {
        clip = await withSceneFetchTimeout(
          () => adoptClip(
            selection.map((c) => c.path),
            dedup,
            sceneIndex,
            beat.index,
            beat.text,
            workDir,
            /**
             * The beat text, not one candidate's query: the pool spans candidates found under
             * different query strings, and the two existing multi-candidate call sites both pass
             * the beat text for that reason — scoring every candidate against a query it was
             * never found under is worse than scoring none of them against their own.
             */
            beat.text,
            adoptOpts
          ),
          adoptMs,
          `media research adopt s${sceneIndex} b${beat.index}`
        );
      } catch {
        break;
      }
      if (!clip) break;
      const winnerKey = clipContentKey(clip);
      const winnerIdx = selection.findIndex((c) => clipContentKey(c.path) === winnerKey);
      const winner = winnerIdx >= 0 ? selection[winnerIdx]! : undefined;
      /** Drop the winner and re-offer the rest; an unidentifiable winner ends the pool. */
      const retryWithout = (): boolean => {
        if (winnerIdx < 0) return false;
        selection = selection.filter((_, i) => i !== winnerIdx);
        return true;
      };
      if (archivalFirst && pool === videoFirst && !isAuthenticVideoClip(clip)) {
        if (retryWithout()) continue;
        break;
      }
      if (archivalFirst && pool === stillFallback && !isStillPhotoClip(clip) && !isAuthenticVideoClip(clip)) {
        if (retryWithout()) continue;
        break;
      }
      if (!winner || winner.source === "pexels" || winner.source === "pixabay") {
        if (!canUseLicensedStockBeat(dedup)) {
          if (retryWithout()) continue;
          break;
        }
        markLicensedStockBeatUsed(dedup);
      }
      console.log(
        `[MediaResearch] Scene ${sceneIndex} beat ${beat.index}: ` +
          `${winner?.source ?? "unresolved"} "${winner?.query ?? beat.text}" ` +
          `(score ${winner?.score ?? "n/a"}) from a pool of ${selection.length}`
      );
      return clip;
    }
  }

  return null;
}

/** Script-anchored clip fetch: real footage first; licensed stock only when minimize is off or cap allows later. */
async function fetchBeatClipFromScript(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  pexFetch: (query: string, t: string, off: number, count?: number) => () => Promise<string[]>,
  candidateOffset: number,
  tag: string,
  muskTopic: boolean
): Promise<string | null> {
  const perf = dedup.perf;
  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const historicalDoc =
    isHistoricalDocumentary(videoTitle, scene.text, beat.text) && !dedup.personTopicLock;
  const primary = historicalDoc
    ? ""
    : (scenePersons[0] ?? personName ?? dedup.primaryPerson ?? "");
  const maxQ = perf.fastStockMode ? Math.min(3, perf.maxStockQueriesPerBeat) : perf.maxStockQueriesPerBeat;
  const beatQueries = buildBeatVisualQueryList(beat.text, scene, videoTitle, scenePersons, maxQ);
  const ytMs = youtubeBeatFetchTimeoutMs(perf.fastStockMode);

  let clip: string | null = null;

  if (realFootageFirstEnabled()) {
    const primaryFetch = await beatPrimaryFetch(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      primary || personName,
      videoTitle,
      adoptOpts,
      scenePersons,
      `${tag}_primary`,
      "script primary"
    );
    if (primaryFetch) return primaryFetch;

    clip = await fetchBeatAuthenticVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      videoTitle,
      adoptOpts,
      scenePersons,
      primary ?? personName,
      `${tag}_auth`
    );
    if (clip) return clip;
  }

  clip = await researchBeatClipUnified(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    beatQueries,
    scenePersons,
    primary ?? "",
    videoTitle,
    adoptOpts,
    tag,
    muskTopic,
    pexFetch,
    candidateOffset
  );
  if (clip && realFootageFirstEnabled()) {
    if (isLicensedStockClip(clip)) clip = null;
    else if (isAuthenticVideoClip(clip) || !isPipelineFallbackClip(clip)) return clip;
  } else if (clip) {
    return clip;
  }

  const legacyEngine = process.env.ENABLE_MEDIA_RESEARCH === "false";

  if (!legacyEngine) {
    if (
      muskTopic &&
      perf.enableMuskHeroFetch &&
      !dedup.muskHeroFetchUsed &&
      beat.index === 0 &&
      sceneIndex === 0
    ) {
      dedup.muskHeroFetchUsed = true;
      clip = (await runCentralYoutubeTurn({
               beat,
               scene,
               workDir,
               sceneIndex,
               clipFetchDur,
               dedup,
               visualNeed: "hero",
               queries: HERO_YOUTUBE_QUERIES,
               queryBuilder: "HERO_YOUTUBE_QUERIES",
               termSource: "hero YouTube",
               adoptOpts: { ...adoptOpts, requireMuskBrand: false },
               timeoutMs: ytMs,
             })).clip;
      if (clip) return clip;
    }

    if (canUseLicensedStockBeat(dedup)) {
      clip = await fetchBeatStockFallback(
        beat,
        scene,
        workDir,
        sceneIndex,
        clipFetchDur,
        dedup,
        personName,
        videoTitle,
        adoptOpts,
        "post-authentic"
      );
      if (clip) return clip;
    }

    if (
      beat.index % 2 === 1 &&
      beat.index > 0 &&
      (scene.brollQueries?.length ?? 0) > 0 &&
      PEXELS_API_KEY &&
      canUseLicensedStockBeat(dedup)
    ) {
      const brollQ = enrichStockQuery(
        scene.brollQueries![beat.index % scene.brollQueries!.length],
        scene,
        videoTitle,
        primary ?? personName,
        beat.text
      );
      const brollPaths = await fetchBrollClips(
        [brollQ],
        clipFetchDur,
        workDir,
        sceneIndex,
        dedup.usedPexelsIds,
        dedup.sourcingCache
      );
      clip = await adoptClip(
        brollPaths,
        dedup,
        sceneIndex,
        beat.index,
        beat.text,
        workDir,
        brollQ,
        adoptOpts
      );
      if (clip) {
        markLicensedStockBeatUsed(dedup);
        return clip;
      }
    }

    return null;
  }

  // Legacy waterfall — only when ENABLE_MEDIA_RESEARCH=false
  const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle);
  clip = (await runCentralYoutubeTurn({
           beat,
           scene,
           workDir,
           sceneIndex,
           clipFetchDur,
           dedup,
           visualNeed: "event",
           queries: entityYt,
           queryBuilder: "entityYt",
           termSource: "event YouTube",
           adoptOpts: adoptOpts,
           timeoutMs: ytMs,
         })).clip;
  if (clip) return clip;

  if (
    muskTopic &&
    perf.enableMuskHeroFetch &&
    !dedup.muskHeroFetchUsed &&
    beat.index === 0 &&
    sceneIndex === 0
  ) {
    dedup.muskHeroFetchUsed = true;
    clip = (await runCentralYoutubeTurn({
             beat,
             scene,
             workDir,
             sceneIndex,
             clipFetchDur,
             dedup,
             visualNeed: "hero",
             queries: HERO_YOUTUBE_QUERIES,
             queryBuilder: "HERO_YOUTUBE_QUERIES",
             termSource: "hero YouTube",
             adoptOpts: { ...adoptOpts, requireMuskBrand: false },
             timeoutMs: ytMs,
           })).clip;
    if (clip) return clip;
  }

  if (primary) {
    clip = await fetchPersonBeatClip(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      primary,
      videoTitle,
      adoptOpts,
      pexFetch,
      candidateOffset,
      tag
    );
    if (clip) return clip;
  }

  clip = await tryBeatTopicRealFootage(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    adoptOpts,
    videoTitle,
    primary ?? personName,
    { includeTopicYoutube: true, fileTag: tag }
  );
  if (clip) return clip;

  if (
    !perf.minimizeStockFootage &&
    beat.index % 2 === 1 &&
    beat.index > 0 &&
    (scene.brollQueries?.length ?? 0) > 0 &&
    PEXELS_API_KEY &&
    canUseLicensedStockBeat(dedup)
  ) {
    const brollQ = enrichStockQuery(
      scene.brollQueries![beat.index % scene.brollQueries!.length],
      scene,
      videoTitle,
      primary ?? personName,
      beat.text
    );
    const brollPaths = await fetchBrollClips(
      [brollQ],
      clipFetchDur,
      workDir,
      sceneIndex,
      dedup.usedPexelsIds,
      dedup.sourcingCache
    );
    clip = await adoptClip(
      brollPaths,
      dedup,
      sceneIndex,
      beat.index,
      beat.text,
      workDir,
      brollQ,
      adoptOpts
    );
    if (clip) {
      markLicensedStockBeatUsed(dedup);
      return clip;
    }
  }

  if (canUseLicensedStockBeat(dedup)) {
    clip = await fetchBeatStockFallback(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      personName,
      videoTitle,
      adoptOpts,
      "legacy stock"
    );
    if (clip) return clip;
  }

  return null;
}

async function fetchBeatClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  spaceTopic: boolean,
  personName: string,
  videoTitle?: string
): Promise<string | null> {
  // RONDE 90 (§2): the beat's proof, in scope for every provider search beneath this call.
  return withSearchProvenance(beatSearchProvenance(beat, scene, personName), () =>
    fetchBeatClipInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, spaceTopic, personName, videoTitle)
  );
}

async function fetchBeatClipInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  spaceTopic: boolean,
  personName: string,
  videoTitle?: string
): Promise<string | null> {
  
  const tag = `b${beat.index}`;
  const candidateOffset = beat.index * 3 + sceneIndex + dedup.globalBeatIndex;
  const muskTopic = isMuskTeslaTopic(videoTitle, scene.text);
  const perf = dedup.perf;
  const adoptOpts: VisualAdoptOptions = {
    muskTopic,
    personTopic: dedup.personTopicLock,
    primaryPerson: dedup.primaryPerson || personName,
    keywords: beat.keywords,
    sceneText: scene.text,
    videoTitle,
    requireBeatMatch: false,
    requireMuskBrand: false,
    scriptAnchored: perf.scriptOnlyVisuals,
  };

  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const maxQ = perf.maxStockQueriesPerBeat;
  let q = stockQueryFromBeatScript(beat.text, scenePersons, scene.text, videoTitle);
  if (isBlockedStockQuery(q)) {
    q = stockQueryFromBeatScript(beat.text, scenePersons, scene.text, videoTitle);
  }

  const pexCount = muskTopic ? 4 : 2;
  const pexFetch = (query: string, t: string, off: number, count = pexCount) =>
    () => fetchPexelsClips(
      query, clipFetchDur, workDir, sceneIndex, count, [query], true, t,
      dedup.usedPexelsIds, off, perf.pexelsDownloadRetries
    );
  const pixFetch = (query: string, t: string, off: number) =>
    () => fetchPixabayClips(query, clipFetchDur, workDir, sceneIndex, 2, t, true, dedup.usedPixabayIds, off);
  const brollFetch = (query: string) =>
    () => fetchBrollClips([query], clipFetchDur, workDir, sceneIndex, dedup.usedPexelsIds);

  let clip: string | null = await fetchBeatClipFromScript(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    personName,
    videoTitle,
    adoptOpts,
    pexFetch,
    candidateOffset,
    tag,
    muskTopic
  );
  if (clip) {
    dedup.globalBeatIndex++;
    return clip;
  }

  if (realFootageFirstEnabled()) {
    const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
    clip = await fetchBeatAuthenticVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      videoTitle,
      {
        muskTopic: isMuskTeslaTopic(videoTitle, scene.text),
        personTopic: dedup.personTopicLock,
        primaryPerson: dedup.primaryPerson || personName,
        keywords: beat.keywords,
        sceneText: scene.text,
        videoTitle,
        requireBeatMatch: false,
      },
      scenePersons,
      personName,
      `${tag}_auth`
    );
    if (clip) {
      dedup.globalBeatIndex++;
      return clip;
    }
  }

  if (perf.scriptOnlyVisuals) {
    
    if (canUseLicensedStockBeat(dedup)) {
      const extra = await fetchUniqueStockForBeat(
        beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts
      );
      if (extra) {
        markLicensedStockBeatUsed(dedup);
        dedup.globalBeatIndex++;
        return extra;
      }
    }
    dedup.globalBeatIndex++;
    return null;
  }

  /**
   * RONDE 260 — the beat cascade's four YouTube tiers, reduced to the beat's one turn.
   *
   * Hero, real-event, archival-early and archival-late each called `fetchYouTubeCCClips` directly,
   * and for one beat up to three of them could fire: the same provider searched three times, with
   * three query sets, three rounds of metadata and download attempts, before anything was ranked.
   *
   * The tiers are NOT merged into one query set. Two of them search at `minRelevanceScore=2` and
   * one at 1, and folding them together would mean either loosening a gate or tightening one —
   * the first is forbidden outright and the second is a silent change to what a beat may adopt.
   * Instead the tier order already written here decides: the highest-priority YouTube tier that
   * applies to this beat takes the turn, with its own gate intact, and the rest are handed its
   * outcome. Every tier's non-YouTube fetchers are untouched.
   */
  const askYoutubeOnceForThisBeat = async (
    who: string,
    need: CentralYoutubeNeed,
    queries: string[],
    keywords: string[],
    minRelevanceScore: number,
    queryBuilder: string,
    /** Only the real-event tier ever spent from the per-video entity ceiling. */
    countsAgainstEntityCeiling: boolean
  ): Promise<string[]> => {
    const turn = await runCentralYoutubeTurn({
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      visualNeed: need,
      queries,
      queryBuilder,
      termSource: who,
      adoptOpts: { ...adoptOpts, keywords },
      timeoutMs: youtubeBeatFetchTimeoutMs(perf.fastStockMode),
      deliver: "candidates",
      minRelevanceScore,
      countsAgainstEntityCeiling,
    });
    return turn.candidatePaths;
  };

  // 0a) Hero beat: YouTube CC + NASA for recognizable SpaceX/Tesla (once per video)
  if (
    muskTopic &&
    perf.enableMuskHeroFetch &&
    !dedup.muskHeroFetchUsed &&
    beat.index === 0 &&
    sceneIndex === 0
  ) {
    const heroKw = [...MUSK_TOPIC_TOKENS, ...beat.keywords];
    const heroOpts = { ...adoptOpts, requireMuskBrand: true };
    clip = await tryStockSources(
      [
        {
          query: "SpaceX Falcon 9 launch",
          fetch: () =>
            askYoutubeOnceForThisBeat(
              "hero", "hero", HERO_YOUTUBE_QUERIES, heroKw, 2, "HERO_YOUTUBE_QUERIES", false
            ),
        },
        {
          query: "SpaceX Starship",
          fetch: () => fetchNasaVideoClips("SpaceX Starship launch", clipFetchDur, workDir, sceneIndex, 1),
        },
        ...HERO_MUSK_QUERIES.map((hq, hi) => ({
          query: hq,
          fetch: pexFetch(hq, `${tag}_hero`, candidateOffset + hi, 6),
        })),
        ...HERO_MUSK_QUERIES.slice(0, 3).map((hq, hi) => ({
          query: hq,
          fetch: pixFetch(hq, `${tag}_hero_px`, candidateOffset + hi + 20),
        })),
      ],
      dedup, sceneIndex, beat.index, beat.text, workDir, "hero", heroOpts
    );
    if (clip) {
      dedup.muskHeroFetchUsed = true;
      dedup.globalBeatIndex++;
      return clip;
    }
    dedup.muskHeroFetchUsed = true;
  }

  // 0) Opening beat when hero waterfall missed (scene 0 only; hero returns early on success)
  if (!clip && beat.index === 0 && sceneIndex === 0 && muskTopic) {
    const heroOpts = { ...adoptOpts, requireMuskBrand: true };
    clip = await tryStockSources(
      OPENING_MUSK_QUERIES.map((oq, oi) => ({
        query: oq,
        fetch: pexFetch(oq, `${tag}_open`, candidateOffset + oi, 4),
      })),
      dedup, sceneIndex, beat.index, beat.text, workDir, "opening", heroOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  // 1a) Real-world YouTube CC — only when this beat names the entity (capped per video; slow)
  const entityYt = realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle);
  if (
    entityYt.length > 0 &&
    dedup.entityYoutubeFetchesUsed < dedup.perf.maxEntityYoutubePerVideo &&
    (process.env.YOUTUBE_API_KEY || RAPIDAPI_KEY || process.env.YOUTUBE_CC_DL_SERVICE)
  ) {
    dedup.entityYoutubeFetchesUsed++;
    clip = await tryStockSources(
      [{
        query: entityYt[0],
        fetch: () =>
          askYoutubeOnceForThisBeat(
            "real-event YouTube", "event", entityYt.slice(0, 2), beat.keywords, 1,
            "realEntityYoutubeQueriesForBeat", true
          ),
      }],
      dedup, sceneIndex, beat.index, beat.text, workDir, "real-event YouTube", adoptOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  if (perf.enableArchival) {
    clip = await tryStockSources(
      [
        {
          query: q,
          fetch: async () =>
            (await fetchInternetArchiveClips(q, clipFetchDur, workDir, sceneIndex, 1, tag)).map((c) => c.path),
        },
        {
          query: q,
          fetch: () =>
            askYoutubeOnceForThisBeat(
              "archival early", "archival", [toQueryString(q)], beat.keywords, 2, "beatStockQuery", false
            ),
        },
      ],
      dedup, sceneIndex, beat.index, beat.text, workDir, "archival early", adoptOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  // 2) Licensed stock — only after authentic sources above
  const topicQueries = buildTopicAnchoredQueries(scene, videoTitle, personName, videoTitle, beat.text);
  if (canUseLicensedStockBeat(dedup)) {
    clip = await tryStockSources(
      topicQueries.slice(0, perf.maxTopicQueries).map((tq, ti) => ({
        query: tq,
        fetch: pexFetch(tq, `${tag}_topic`, candidateOffset + ti, 2),
      })),
      dedup, sceneIndex, beat.index, beat.text, workDir, "topic Pexels", adoptOpts
    );
    if (clip) {
      markLicensedStockBeatUsed(dedup);
      dedup.globalBeatIndex++;
      return clip;
    }
  }

  // 3) Golden pool fallback for Musk when beat-specific search missed
  if (muskTopic) {
    const golden = GOLDEN_MUSK_QUERIES[dedup.globalBeatIndex % GOLDEN_MUSK_QUERIES.length];
    const goldenCat = stockVisualCategory(golden);
    const goldenFetchers: Array<{ query: string; fetch: () => Promise<string[]> }> = [];
    if (perf.enableNasa && spaceTopic && goldenCat === "rocket" && (dedup.usedCategories.get("rocket") ?? 0) === 0) {
      goldenFetchers.push({
        query: golden,
        fetch: () => fetchNasaVideoClips(golden, clipFetchDur, workDir, sceneIndex, 1),
      });
    }
    goldenFetchers.push({ query: golden, fetch: pexFetch(golden, `${tag}_golden`, candidateOffset + 1) });
    goldenFetchers.push({ query: golden, fetch: pixFetch(golden, `${tag}_golden`, candidateOffset + 1) });
    clip = await tryStockSources(goldenFetchers, dedup, sceneIndex, beat.index, beat.text, workDir, "golden", adoptOpts);
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  // 4) Dedicated B-roll cutaways on odd beats
  if (beat.index % 2 === 1 && beat.index > 0 && (scene.brollQueries?.length ?? 0) > 0) {
    const brollQ = enrichStockQuery(
      scene.brollQueries![beat.index % scene.brollQueries!.length],
      scene, videoTitle, personName
    );
    clip = await tryStockSources(
      [{ query: brollQ, fetch: brollFetch(brollQ) }],
      dedup, sceneIndex, beat.index, beat.text, workDir, "B-roll", adoptOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  // 5) Pixabay + archival sources (archival only when Pexels/Pixabay exhausted)
  clip = await tryStockSources(
    [{ query: q, fetch: pixFetch(q, `${tag}_pix`, candidateOffset) }],
    dedup, sceneIndex, beat.index, beat.text, workDir, "Pixabay", adoptOpts
  );
  if (clip) { dedup.globalBeatIndex++; return clip; }

  if (perf.enableNasa && spaceTopic && stockVisualCategory(q) === "rocket") {
    clip = await tryStockSources(
      [{ query: q, fetch: () => fetchNasaVideoClips(q, clipFetchDur, workDir, sceneIndex, 1) }],
      dedup, sceneIndex, beat.index, beat.text, workDir, "NASA", adoptOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  if (perf.enableArchival) {
    clip = await tryStockSources(
      [
        {
          query: q,
          fetch: async () =>
            (await fetchInternetArchiveClips(q, clipFetchDur, workDir, sceneIndex, 1, tag)).map((c) => c.path),
        },
        {
          query: q,
          fetch: () =>
            askYoutubeOnceForThisBeat(
              "archival", "archival", [toQueryString(q)], beat.keywords, 2, "beatStockQuery", false
            ),
        },
      ],
      dedup, sceneIndex, beat.index, beat.text, workDir, "archival", adoptOpts
    );
    if (clip) { dedup.globalBeatIndex++; return clip; }
  }

  // 6) Scene fallback queries
  const fallbackQueries = filterQueryStrings(
    [scene.visualCue, scene.pexelsQuery, ...(scene.pexelsQueries ?? [])],
    3,
    (fq) => fq !== toQueryString(q) && !isBlockedStockQuery(fq)
  );

  const looseAdopt: VisualAdoptOptions = { ...adoptOpts, requireBeatMatch: false };
  clip = await tryStockSources(
    fallbackQueries.map((fq, fi) => ({ query: fq, fetch: pexFetch(fq, `${tag}_fb`, candidateOffset + fi, 1) })),
    dedup, sceneIndex, beat.index, beat.text, workDir, "fallback Pexels", looseAdopt
  );
  if (clip) { dedup.globalBeatIndex++; return clip; }

  const lastResort = await fetchLastResortRealClip(
    beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, looseAdopt
  );
  if (lastResort) {
    dedup.globalBeatIndex++;
    return lastResort;
  }

  
  dedup.globalBeatIndex++;
  return clip;
}

/** Stock queries that always include the named person (VidRush person-docs). */
function buildPersonStockVideoQueries(
  personName: string,
  beat: SceneBeat,
  scene: Scene,
  videoTitle?: string
): string[] {
  /**
   * RONDE 93 (§6) — "Adolf Hitler red carpet" and "Adolf Hitler makeup brand" came from here.
   *
   * Four suffixes were appended to EVERY person, unconditionally: interview, red carpet, talk
   * show, makeup brand. The comment above says "VidRush person-docs", and for an influencer video
   * they are reasonable defaults; there is nothing in the function that ever asked whether the
   * documentary was about an influencer. Applied to a historical figure they are not merely
   * useless, they are grotesque.
   *
   * scriptEventSearchQueries keeps every one of these terms available — it emits "red carpet" for
   * a beat that mentions a premiere or a gala, "interview" for a beat that mentions one. The
   * difference is that the beat has to say so.
   */
  const persons = [personName];
  const out = [
    personName,
    ...buildPersonCelebrityVideoQueries(personName, beat.text, beat.index).slice(0, 5),
    ...scriptEventSearchQueries(beat.text, persons),
  ].filter((q) => {
    const s = toQueryString(q);
    return s.length > 3 && !isBlockedStockQuery(s);
  });
  return [...new Set(out)].slice(0, 6);
}

/** Pexels/Pixabay with person name in every query — no generic b-roll for celebrity topics. */
async function fetchBeatPersonStockVideo(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  reason: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchBeatPersonStockVideoInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts, reason), { personName });
}

async function fetchBeatPersonStockVideoInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  reason: string
): Promise<string | null> {
  if (!coercePersonName(personName)) return null;
  const personAdopt: VisualAdoptOptions = {
    ...adoptOpts,
    requireBeatMatch: false,
    scriptAnchored: false,
    personTopic: true,
    primaryPerson: personName,
  };
  const queries = buildPersonStockVideoQueries(personName, beat, scene, videoTitle);
  const tag = `b${beat.index}_person_stock`;
  const off = beat.index + sceneIndex * 5;

  return withSceneFetchTimeout(
    async () => {
      for (const q of queries) {
        const pex = await fetchPexelsClips(
          q,
          clipFetchDur,
          workDir,
          sceneIndex,
          MULTI_CANDIDATE_FETCH_COUNT,
          undefined,
          true,
          tag,
          dedup.usedPexelsIds,
          off,
          dedup.perf.pexelsDownloadRetries
        );
        let clip = await adoptClip(
          pex, dedup, sceneIndex, beat.index, beat.text, workDir, q, personAdopt
        );
        if (isRealVideoClip(clip)) {
          if (canUseLicensedStockBeat(dedup)) markLicensedStockBeatUsed(dedup);
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: person stock (${reason}) — Pexels "${q}"`
          );
          return clip;
        }

        const pix = await fetchPixabayClips(
          q, clipFetchDur, workDir, sceneIndex, MULTI_CANDIDATE_FETCH_COUNT, tag, true, dedup.usedPixabayIds, off
        );
        clip = await adoptClip(
          pix, dedup, sceneIndex, beat.index, beat.text, workDir, q, personAdopt
        );
        if (isRealVideoClip(clip)) {
          if (canUseLicensedStockBeat(dedup)) markLicensedStockBeatUsed(dedup);
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: person stock (${reason}) — Pixabay "${q}"`
          );
          return clip;
        }
      }
      return null;
    },
    beatStockFallbackWallMs(dedup.perf),
    `person stock s${sceneIndex} b${beat.index}`
  ).catch(() => {
    return null;
  });
}

/** Pexels/Pixabay when online search exceeds 1 minute or finds nothing. */
async function fetchBeatStockFallback(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  reason: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchBeatStockFallbackInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, adoptOpts, reason), { personName });
}

async function fetchBeatStockFallbackInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  reason: string
): Promise<string | null> {
  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const primary =
    coercePersonName(personName) ||
    coercePersonName(adoptOpts.primaryPerson) ||
    coercePersonName(dedup.primaryPerson) ||
    coercePersonName(scenePersons[0]) ||
    "";
  if (primary || dedup.personTopicLock) {
    const personClip = await fetchBeatPersonStockVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      primary || dedup.primaryPerson || scenePersons[0] || "",
      videoTitle,
      adoptOpts,
      reason
    );
    if (personClip) return personClip;
    if (dedup.personTopicLock || primary) return null;
  }

  const loose: VisualAdoptOptions = {
    ...adoptOpts,
    requireBeatMatch: false,
    scriptAnchored: false,
  };

  // In archive-first mode, topic-specific queries must be FIRST so they survive the slice cap.
  // Auto-detect country/topic from video title + beat text → inject as first Pexels anchor.
  //
  // Beat text is checked FIRST for event/situation overrides (WWII, flood, protest, …).
  // If the beat signals a different topic than the video title (topic switch), those anchors
  // replace the geo-anchors automatically — for ALL countries and ALL topics.
  const { anchors: rawTopicAnchors, topicKey: beatTopicKey } = { anchors: [] as string[], topicKey: "none" };

  // ── Topic-switch detector ────────────────────────────────────────────────────
  // Log whenever a beat's topic differs from the previous beat's topic.
  // e.g. "amsterdam" → "wwii" when the narration shifts to WWII occupation.
  

  // ── Visual variety enforcer ──────────────────────────────────────────────────
  // Sort topic anchors so least-used ones come first. This ensures consecutive
  // beats on the same topic (e.g. Netherlands) get different imagery:
  //   beat 0 → "Amsterdam canal"   (used 0×) → first
  //   beat 3 → "Dutch cycling"     (used 0×) → first (Amsterdam used 1×)
  //   beat 6 → "Netherlands bicycle" (used 0×) → first (others used 1×)
  // Per-topic rotation is automatic: each anchor key is tracked independently,
  // so WWII anchors and Netherlands anchors each maintain their own usage counts.
  const topicAnchors = [...rawTopicAnchors].sort(
    (a, b) => (dedup.usedPexelsAnchors.get(a) ?? 0) - (dedup.usedPexelsAnchors.get(b) ?? 0)
  );

  const topicSpecific = buildBeatVisualQueryList(beat.text, scene, videoTitle, scenePersons, 5);
  const queries = [
        beat.searchQuery,
        enrichStockQuery(beat.powerWord, scene, videoTitle, personName, beat.text),
        scene.visualCue,
        scene.pexelsQuery,
        ...topicSpecific,
      ];
  const filteredQueries = filterQueryStrings(queries, 3, (q) => !isBlockedStockQuery(q));
  // More queries allowed in archive-first mode since Pexels IS the only fallback
  const maxQueries = 3;
  const unique = [...new Set(filteredQueries)].slice(0, maxQueries);
  const tag = `b${beat.index}_stock`;
  const off = beat.index + sceneIndex * 3;

  return withSceneFetchTimeout(
    async () => {
      for (const q of unique) {
        const pex = await fetchPexelsClips(
          q,
          clipFetchDur,
          workDir,
          sceneIndex,
          MULTI_CANDIDATE_FETCH_COUNT,
          undefined,
          true,
          tag,
          dedup.usedPexelsIds,
          off,
          dedup.perf.pexelsDownloadRetries
        );
        let clip = await adoptClip(
          pex, dedup, sceneIndex, beat.index, beat.text, workDir, q, loose
        );
        if (clip && !isStillPhotoClip(clip) && !isPipelineFallbackClip(clip)) {
          if (canUseLicensedStockBeat(dedup)) markLicensedStockBeatUsed(dedup);
          // Visual variety enforcer: mark this anchor as used so the next beat picks a different one
          dedup.usedPexelsAnchors.set(q, (dedup.usedPexelsAnchors.get(q) ?? 0) + 1);
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: stock fallback (${reason}) — Pexels "${q}"`
          );
          return clip;
        }

        const pix = await fetchPixabayClips(
          q, clipFetchDur, workDir, sceneIndex, MULTI_CANDIDATE_FETCH_COUNT, tag, true, dedup.usedPixabayIds, off
        );
        clip = await adoptClip(
          pix, dedup, sceneIndex, beat.index, beat.text, workDir, q, loose
        );
        if (clip && !isStillPhotoClip(clip) && !isPipelineFallbackClip(clip)) {
          if (canUseLicensedStockBeat(dedup)) markLicensedStockBeatUsed(dedup);
          // Visual variety enforcer: mark this anchor as used so the next beat picks a different one
          dedup.usedPexelsAnchors.set(q, (dedup.usedPexelsAnchors.get(q) ?? 0) + 1);
          console.log(
            `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: stock fallback (${reason}) — Pixabay "${q}"`
          );
          return clip;
        }
      }
      return null;
    },
    beatStockFallbackWallMs(dedup.perf),
    `stock fallback s${sceneIndex} b${beat.index}`
  ).catch((err) => {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: stock fallback skipped:`,
      (err as Error).message
    );
    return null;
  });
}

/** True video clip (not Ken-Burns still). */
function isRealVideoClip(filePath: string | null): boolean {
  if (!filePath) return false;
  return !isStillPhotoClip(filePath) && !isPipelineFallbackClip(filePath);
}

/** Exhaust authentic sources (Archive, Wikimedia, YouTube CC) before stills/stock. */
async function fetchBeatAuthenticVideo(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  scenePersons: string[],
  personName: string,
  tag: string
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => fetchBeatAuthenticVideoInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, videoTitle, adoptOpts, scenePersons, personName, tag), { personName, scenePersons });
}

async function fetchBeatAuthenticVideoInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  videoTitle: string | undefined,
  adoptOpts: VisualAdoptOptions,
  scenePersons: string[],
  personName: string,
  tag: string
): Promise<string | null> {
  const topicHay = [videoTitle, scene.text, beat.text].filter(Boolean).join(" ");
  const historicalDoc = isHistoricalDocumentary(topicHay) && !dedup.personTopicLock;
  const intent = buildMediaSearchIntent({
    beatText: beat.text,
    searchQueries: beatMediaSearchQueries(beat, videoTitle),
    keywords: adoptOpts.keywords ?? beat.keywords,
    primaryPerson: historicalDoc ? "" : personName,
    persons: scenePersons,
    videoTitle,
    powerWord: beat.powerWord,
    personTopicLock: dedup.personTopicLock && !historicalDoc,
    spaceTopic: isSpaceRelatedTopic(scene.visualCue, scene.pexelsQuery, beat.text, scene.text, videoTitle ?? ""),
    muskTopic: adoptOpts.muskTopic ?? false,
  });
  const loose: VisualAdoptOptions = { ...adoptOpts, requireBeatMatch: false, scriptAnchored: false };

  if (youtubeSourcingEnabled()) {
    const ytQueries = [
      // RONDE 249: the script's person before the hardcoded table.
      ...(coercePersonName(personName) ? buildPersonCelebrityVideoQueries(personName, beat.text, beat.index) : []),
      ...realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle),
      ...(asVideoTitleString(videoTitle).trim()
        ? [
            `${asVideoTitleString(videoTitle)} documentary footage`,
            `${asVideoTitleString(videoTitle)} archival`,
          ]
        : []),
    ];
    const yt = (await runCentralYoutubeTurn({
                 beat,
                 scene,
                 workDir,
                 sceneIndex,
                 clipFetchDur,
                 dedup,
                 visualNeed: "authentic",
                 queries: ytQueries,
                 queryBuilder: "ytQueries",
                 termSource: "authentic YouTube",
                 adoptOpts: loose,
                 timeoutMs: youtubeBeatFetchTimeoutMs(dedup.perf.fastStockMode),
               })).clip;
    if (isAuthenticVideoClip(yt ?? "")) return yt;
    if (youtubeOnlySourcingEnabled()) return null;
  }

  const hist = await fetchHistoricalBeatVideo(
    beat, scene, workDir, sceneIndex, clipFetchDur, dedup, intent, loose, tag, { skipYoutube: true }
  );
  if (isAuthenticVideoClip(hist ?? "")) return hist;

  if (coercePersonName(personName)) {
    const celebVids = await fetchPersonCelebrityVideoClips(
      personName,
      clipFetchDur,
      workDir,
      sceneIndex,
      3,
      `${tag}_auth`,
      beat.index,
      beat.text,
      false
    );
    const celeb = await adoptBestCelebrityClip(
      celebVids,
      dedup,
      sceneIndex,
      beat.index,
      beat.text,
      workDir,
      personName,
      { ...loose, personTopic: true, primaryPerson: personName }
    );
    if (isAuthenticVideoClip(celeb ?? "")) return celeb;
  }

  return null;
}

/** Fast 1-min path: ≤20s real footage, then AI, then Pexels. */
async function resolveBeatClipFastTurbo(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  beatAdoptOpts: VisualAdoptOptions
): Promise<string | null> {
  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const historicalDoc =
    isHistoricalDocumentary(videoTitle, scene.text, beat.text) && !dedup.personTopicLock;
  const tag = `b${beat.index}`;
  /**
   * RONDE 648 — YOUTUBE FIRST MEANS FIRST.
   *
   * This route opened with `fetchBeatInternetStillsFirst` — Wikimedia and web stills, the open
   * sources — and reached YouTube only inside `beatPrimaryFetch` after it. In YouTube-first mode the
   * stills wait: `beatPrimaryFetch` opens with the YouTube-first slice and then the archive, and the
   * stills come after both, where the operator placed the open sources.
   */
  const youtubeFirst = youtubeFirstPerBeatEnabled();
  let clip: string | null = null;
  if (!youtubeFirst) {
    clip = await fetchBeatInternetStillsFirst(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      scenePersons,
      videoTitle,
      beatAdoptOpts,
      `${tag}_inet`
    );
    if (clip && isRealVideoClip(clip) && !isPipelineFallbackClip(clip)) return clip;
  }

  /**
   * RONDE 622 — THE WALL THAT COULD NEVER PAY, MEASURED IN PRODUCTION.
   *
   * ── Render 598, on the deploy that carried every fix of this session ────────────────────────
   *
   *     [YouTube] TURN_DECLINED scene=0 — 20s left and a turn costs 24s
   *         clock="b0_fastyt-first s0 b0" granted=20s
   *
   * Eleven beats, one number: `granted=20s`, every time. Render 597 printed the identical figure
   * months of rounds earlier. That repetition is the tell — a clock clamped by traffic varies, and
   * this one never did, because it is not traffic. It is this literal.
   *
   * `beatPrimaryFetch` is the function that opens a YouTube turn on this route, and the window it
   * is given here is 20s — or 15s for a historical documentary, which is the case this pipeline
   * exists for. A turn costs `YOUTUBE_MIN_TURN_MS`: one 12s search plus the 12s download floor.
   * Twenty is less than twenty-four and fifteen is less. The door therefore refuses EVERY turn on
   * this route, correctly, for a window nobody meant to withhold — and no render on this path has
   * ever searched YouTube.
   *
   * ── Why this is not a budget increase ───────────────────────────────────────────────────────
   *
   * `beatWallWithYoutubeTurn` is the shared answer eleven other walls already use, and RONDE 600
   * wrote it for exactly this: the turn's window is ADDED to the wall rather than carved out of
   * it, so the cascade loses nothing. Its supplement is zero when there is no YouTube to budget
   * for, which means a build without a key keeps 15s and 20s to the millisecond.
   *
   * The base numbers do not move. `historicalDoc ? 15_000 : 20_000` is still what this route
   * spends on its own work; what changes is that a beat which may ALSO open a YouTube turn is now
   * wide enough to hold one, exactly as `runBeatClipFetch` and the scene wall already are.
   *
   * ── What was measured, and what it cost to find ─────────────────────────────────────────────
   *
   * RONDE 615 declared this wall closed after building the nest in a test and reading 55s at the
   * innermost point. The nest was constructed from the layers I believed production used; the
   * route production actually takes is this one. That test proves what it describes and did not
   * describe this — which is why the anchor below is a literal-free assertion against the helper,
   * not another reconstruction.
   */
  const primaryMs = youtubeFirstWall(beatWallWithYoutubeTurn(historicalDoc ? 15_000 : 20_000));
  try {
    clip = await withSceneFetchTimeout(
      () => beatPrimaryFetch(
        beat,
        scene,
        workDir,
        sceneIndex,
        clipFetchDur,
        dedup,
        personName,
        videoTitle,
        beatAdoptOpts,
        scenePersons,
        `${tag}_fast`,
        "fast primary"
      ),
      primaryMs,
      `fast primary s${sceneIndex} b${beat.index}`
    );
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: fast primary cap:`,
      (err as Error).message
    );
  }
  if (clip && isRealVideoClip(clip) && !isPipelineFallbackClip(clip)) return clip;

  /** RONDE 648 — the open sources' stills, after YouTube and the archive, in YouTube-first mode. */
  if (youtubeFirst) {
    const stills = await fetchBeatInternetStillsFirst(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      scenePersons,
      videoTitle,
      beatAdoptOpts,
      `${tag}_inet`
    );
    if (stills && isRealVideoClip(stills) && !isPipelineFallbackClip(stills)) return stills;
    if (!clip && stills && !isPipelineFallbackClip(stills)) clip = stills;
  }

  

  if (canUseLicensedStockBeat(dedup)) {
    clip = await fetchBeatStockFallback(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      personName,
      videoTitle,
      beatAdoptOpts,
      "fast turbo"
    );
    if (clip && isRealVideoClip(clip)) {
      markLicensedStockBeatUsed(dedup);
      return clip;
    }
  }

  clip = await fetchBeatScriptImageForced(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    scenePersons,
    videoTitle,
    `${tag}_must`
  );
  return clip && !isPipelineFallbackClip(clip) ? clip : null;
}

/**
 * Turbo path for 1–2 min videos: real video first (YouTube → stock, ≤1min), still only as last resort.
 */
async function resolveBeatClipTurbo(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  beatAdoptOpts: VisualAdoptOptions
): Promise<string | null> {
  // RONDE 100B: proof in scope before any provider is asked — see withBeatProvenance.
  return withBeatProvenance(beat, scene, () => resolveBeatClipTurboInner(beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, beatAdoptOpts), { personName });
}

async function resolveBeatClipTurboInner(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  personName: string,
  videoTitle: string | undefined,
  beatAdoptOpts: VisualAdoptOptions
): Promise<string | null> {
  if (dedup.perf.fastStockMode) {
    return resolveBeatClipFastTurbo(
      beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, beatAdoptOpts
    );
  }

  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const historicalDoc =
    isHistoricalDocumentary(videoTitle, scene.text, beat.text) && !dedup.personTopicLock;
  const turboAdopt: VisualAdoptOptions = {
    ...beatAdoptOpts,
    requireBeatMatch: false,
    scriptAnchored: false,
    personTopic: !historicalDoc && (dedup.personTopicLock || scenePersons.length > 0),
    primaryPerson: historicalDoc
      ? ""
      : (beatAdoptOpts.primaryPerson || scenePersons[0] || personName),
  };

  const person = historicalDoc
    ? ""
    : (scenePersons[0] ?? personName ?? dedup.primaryPerson ?? "").trim();
  const muskTopic = isMuskTeslaTopic(videoTitle, scene.text);
  const maxQ = Math.min(3, dedup.perf.maxStockQueriesPerBeat);
  const beatQueries = buildBeatVisualQueryList(beat.text, scene, videoTitle, scenePersons, maxQ);
  const tag = `b${beat.index}`;
  const candidateOffset = beat.index * 3 + sceneIndex + dedup.globalBeatIndex;
  const pexFetch = (query: string, t: string, off: number, count = 1) =>
    () =>
      fetchPexelsClips(
        query,
        clipFetchDur,
        workDir,
        sceneIndex,
        count,
        [query],
        true,
        t,
        dedup.usedPexelsIds,
        off,
        dedup.perf.pexelsDownloadRetries
      );

  if (realFootageFirstEnabled()) {
    const primary = await beatPrimaryFetch(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      personName,
      videoTitle,
      beatAdoptOpts,
      scenePersons,
      `${tag}_primary`,
      "turbo primary"
    );
    if (primary) return primary;

    const authFirst = await fetchBeatAuthenticVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      videoTitle,
      turboAdopt,
      scenePersons,
      person,
      `${tag}_auth0`
    );
    if (authFirst) return authFirst;
  }

  const unified = await researchBeatClipUnified(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    beatQueries,
    scenePersons,
    person,
    videoTitle,
    turboAdopt,
    tag,
    muskTopic,
    pexFetch,
    candidateOffset
  );
  const topicHay = [beat.text, videoTitle, scene.text].filter(Boolean).join(" ");
  const archivalBeat =
    historicalDoc ||
    inferTopicKind(
      topicHay,
      person,
      isSpaceRelatedTopic(scene.visualCue, scene.pexelsQuery, beat.text, scene.text, videoTitle ?? "", beat.powerWord),
      dedup.personTopicLock
    ) === "historical" ||
    inferTopicKind(topicHay, person, false, dedup.personTopicLock) === "news";

  if (unified && !isPipelineFallbackClip(unified) && !(await isMostlyBlackClip(unified))) {
    if (realFootageFirstEnabled()) {
      if (isAuthenticVideoClip(unified)) return unified;
      if (!isStillPhotoClip(unified) && !isLicensedStockClip(unified)) return unified;
    } else if (!archivalBeat || isRealVideoClip(unified)) {
      return unified;
    }
  }

  if (archivalBeat || realFootageFirstEnabled()) {
    const histIntent = buildMediaSearchIntent({
      beatText: beat.text,
      searchQueries: beatQueries,
      keywords: beatAdoptOpts.keywords ?? beat.keywords,
      primaryPerson: person,
      persons: scenePersons,
      videoTitle,
      powerWord: beat.powerWord,
      personTopicLock: dedup.personTopicLock && !historicalDoc,
      spaceTopic: false,
      muskTopic,
    });
    const turboYtQueries = [
      // RONDE 249: the script's person before the hardcoded table.
      ...(person.trim() ? buildPersonCelebrityVideoQueries(person, beat.text, beat.index) : []),
      ...realEntityYoutubeQueriesForBeat(beat.text, scene.text, videoTitle),
      ...beatQueries.slice(0, 2),
    ];
    const turboYt = (await runCentralYoutubeTurn({
                      beat,
                      scene,
                      workDir,
                      sceneIndex,
                      clipFetchDur,
                      dedup,
                      visualNeed: "archival",
                      queries: [...new Set(turboYtQueries.map(toQueryString).filter((q) => q.length > 3))].slice(0, 5),
                      queryBuilder: "turboYtQueries",
                      termSource: "turbo archival YouTube",
                      adoptOpts: turboAdopt,
                      timeoutMs: youtubeBeatFetchTimeoutMs(dedup.perf.fastStockMode),
                    })).clip;
    if (turboYt && isAuthenticVideoClip(turboYt)) return turboYt;

    const hist = await fetchHistoricalBeatVideo(
      beat, scene, workDir, sceneIndex, clipFetchDur, dedup, histIntent, turboAdopt, tag, {
        skipYoutube: true,
      }
    );
    if (hist && isAuthenticVideoClip(hist)) return hist;
  }

  let c: string | null = null;
  let searchTimedOut = false;
  try {
    c = await withSceneFetchTimeout(
      async () => {
        if (person) {
          const ytQueries = buildPersonCelebrityVideoQueries(person, beat.text, beat.index).slice(0, 3);
          const yt = (await runCentralYoutubeTurn({
                       beat,
                       scene,
                       workDir,
                       sceneIndex,
                       clipFetchDur,
                       dedup,
                       visualNeed: "person",
                       queries: ytQueries,
                       queryBuilder: "ytQueries",
                       termSource: "turbo person YouTube",
                       adoptOpts: { ...turboAdopt, personTopic: true, primaryPerson: person },
                       timeoutMs: 42_000,
                     })).clip;
          if (isRealVideoClip(yt) && !(await isMostlyBlackClip(yt!))) return yt;
        } else {
          const ytQueries = uniqueQueryStrings([beat.searchQuery, scene.visualCue], 1);
          const yt = (await runCentralYoutubeTurn({
                       beat,
                       scene,
                       workDir,
                       sceneIndex,
                       clipFetchDur,
                       dedup,
                       visualNeed: "topic",
                       queries: ytQueries,
                       queryBuilder: "ytQueries",
                       termSource: "turbo YouTube",
                       adoptOpts: turboAdopt,
                       timeoutMs: 35_000,
                     })).clip;
          if (isRealVideoClip(yt) && !(await isMostlyBlackClip(yt!))) return yt;
        }

        if (person) {
          const celebVids = await withSceneFetchTimeout(
            () => fetchPersonCelebrityVideoClips(
              person,
              clipFetchDur,
              workDir,
              sceneIndex,
              2,
              `b${beat.index}_turbo_celeb`,
              beat.index,
              beat.text,
              true
            ),
            22_000,
            `turbo celebrity s${sceneIndex} b${beat.index}`
          ).catch(() => [] as CelebrityClipCandidate[]);
          const celeb = await adoptBestCelebrityClip(
            celebVids,
            dedup,
            sceneIndex,
            beat.index,
            beat.text,
            workDir,
            person,
            { ...turboAdopt, personTopic: true, primaryPerson: person }
          );
          if (isRealVideoClip(celeb)) return celeb;
        }

        return null;
      },
      beatVisualSearchMaxMs(dedup.perf),
      `turbo video search s${sceneIndex} b${beat.index}`
    );
  } catch (err) {
    searchTimedOut = true;
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: video search >1min:`,
      (err as Error).message
    );
  }

  if (isAuthenticVideoClip(c ?? "")) return c;
  if (realFootageFirstEnabled() && c && isLicensedStockClip(c)) c = null;

  const stock = await fetchBeatStockFallback(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    personName,
    videoTitle,
    beatAdoptOpts,
    searchTimedOut ? ">1min cap" : "no video"
  );
  if (isLicensedStockClip(stock ?? "")) {
    if (canUseLicensedStockBeat(dedup) && isRealVideoClip(stock!)) return stock;
  } else if (isRealVideoClip(stock)) {
    return stock;
  }

  if (!canUseGlobalStillPhoto(dedup)) return null;

  const imgAdopt: VisualAdoptOptions = { ...turboAdopt, scriptImageFallback: true };
  let img = await fetchBeatScriptImageClip(
    beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, imgAdopt, `b${beat.index}`
  );
  if (img && !isPipelineFallbackClip(img)) return img;

  img = await fetchBeatScriptImageForced(
    beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, `b${beat.index}`
  );
  return img && !isPipelineFallbackClip(img) ? img : null;
}

/** Real footage first (capped); script-matched still image; AI/stock last resort. */
async function resolveBeatClipForBeat(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  spaceTopic: boolean,
  personName: string,
  videoTitle: string | undefined,
  beatAdoptOpts: VisualAdoptOptions
): Promise<string | null> {
  

  if (dedup.perf.fastStockMode) {
    return resolveBeatClipTurbo(
      beat, scene, workDir, sceneIndex, clipFetchDur, dedup, personName, videoTitle, beatAdoptOpts
    );
  }

  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const minimize = dedup.perf.minimizeStockFootage;
  let c: string | null = null;
  try {
    c = await withSceneFetchTimeout(
      async () => {
        let v = await runBeatClipFetch(
          beat, scene, workDir, sceneIndex, clipFetchDur, dedup, spaceTopic, personName, videoTitle
        );
        if (!v || isPipelineFallbackClip(v)) {
          v = await resolveBeatClipFast(
            beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, beatAdoptOpts
          );
        }
        return v;
      },
      /**
       * RONDE 623 — THE FOURTH, FOUND BY THE SWEEP RATHER THAN BY A RENDER.
       *
       * This scope holds `runBeatClipFetch` AND `resolveBeatClipFast`, and both reach a YouTube
       * turn. Its size is `beatVisualSearchMaxMs`, which returns `perBeatSearchMs * 0.4` under an
       * active render budget and 12_000 without one — against a turn priced at 24s. It escaped
       * RONDE 622 twice over: the number is behind a function rather than typed in, and the scope's
       * first argument is an `async () => {}` closure, which that round's walker did not read.
       *
       * Today's fast profile returns to `resolveBeatClipTurbo` before reaching this line, so no
       * production render is known to have been bitten by it. That is a fact about one profile and
       * not about the wall: a non-fast render on a tight budget lands here with whatever
       * `perBeatSearchMs * 0.4` happens to be. A wall a turn can open under is sized for one, or it
       * is a wall waiting for its render.
       */
      beatWallWithYoutubeTurn(beatVideoSearchWallMs(dedup.perf)),
      `video search s${sceneIndex} b${beat.index}`
    );
  } catch (err) {
    console.warn(
      `[Pipeline] Scene ${sceneIndex} beat ${beat.index}: video search capped:`,
      (err as Error).message
    );
  }
  if (c && !isPipelineFallbackClip(c) && !(await isMostlyBlackClip(c))) {
    if (!realFootageFirstEnabled() || isAuthenticVideoClip(c) || isStillPhotoClip(c)) return c;
  }

  if (realFootageFirstEnabled()) {
    const auth = await fetchBeatAuthenticVideo(
      beat,
      scene,
      workDir,
      sceneIndex,
      clipFetchDur,
      dedup,
      videoTitle,
      beatAdoptOpts,
      scenePersons,
      personName,
      `b${beat.index}_auth`
    );
    if (auth) return auth;
  }

  c = await fetchBeatStockFallback(
    beat,
    scene,
    workDir,
    sceneIndex,
    clipFetchDur,
    dedup,
    personName,
    videoTitle,
    beatAdoptOpts,
    "after search"
  );
  if (c && !isPipelineFallbackClip(c)) return c;

  if (canUseGlobalStillPhoto(dedup)) {
    const imgAdopt: VisualAdoptOptions = { ...beatAdoptOpts, scriptImageFallback: true };
    let img = await fetchBeatScriptImageClip(
      beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, imgAdopt, `b${beat.index}`
    );
    if (img && !isPipelineFallbackClip(img)) return img;
    img = await fetchBeatScriptImageForced(
      beat, scene, workDir, sceneIndex, clipFetchDur, dedup, scenePersons, videoTitle, `b${beat.index}`
    );
    if (img && !isPipelineFallbackClip(img)) return img;
  }

  return null;
}

// ─── Unified beat-clip retrieval entry point ─────────────────────────────────
//
// Replaces the six separate dispatch functions (beatPrimaryFetch,
// resolveBeatClipFast, resolveBeatClipFastTurbo, resolveBeatClipTurbo,
// resolveBeatClipForBeat, fetchBeatArchivalThenPexels) with a single interface.
// Internal routing is based on dedup.perf flags — callers no longer need to
// pick the right function.
//
type ResolveBeatClipOptions = {
  spaceTopic?: boolean;
  scenePersons?: string[];
  personName?: string;
  videoTitle?: string;
  adoptOpts?: VisualAdoptOptions;
  /** When true: only try archive/youtube/primary sources — skip full search tree. */
  primaryOnly?: boolean;
  tag?: string;
  stockReason?: string;
};

// ── F3-27: live archive→web fallback→ingest→learning wiring ─────────────────
// Minimum distinct candidates a scene needs before its archive coverage is
// considered sufficient — only drives the coverage-warning signal (F3-26 #8/#9),
// never the actual retrieval or quality gates (those are untouched).
const FUNNEL_RECOMMENDED_COVERAGE_COUNT = 3;

/** F3-27 self-learning: prioritise queries that previously worked for this entity/topic
 *  (recordVisualSearchMemory / getVisualSearchMemoryForEntity, F3-26), without ever
 *  replacing the normal query set — proven queries are prepended, never a hard filter.
 *  If none exist, or the lookup fails, the original queries are returned unchanged so
 *  normal web sourcing proceeds exactly as before. */
export async function primeQueriesWithSearchMemory(
  entity: string | undefined,
  baseExtraQueries: string[] | undefined
): Promise<string[] | undefined> {
  const trimmedEntity = entity?.trim();
  if (!trimmedEntity) return baseExtraQueries;
  try {
    const [memory, deadQueries] = await Promise.all([
      getVisualSearchMemoryForEntity(trimmedEntity, 3),
      // RONDE 28c: the dead-end half of the memory was being written and never read. Reading it
      // here is the whole point of having recorded it.
      getDeadEndQueries(trimmedEntity),
    ]);
    const proven = memory
      .filter((m) => m.success && m.query)
      .sort((a, b) => (b.usageCount ?? 0) - (a.usageCount ?? 0))
      .map((m) => m.query);

    const base = baseExtraQueries ?? [];
    // Demote, never drop. A query that failed on several sources goes to the BACK of the list, so
    // the earlier ones get first claim on the beat's budget — but if they come up short it is
    // still tried. Removing it would let two unlucky renders blind this subject permanently.
    const demoted = base.filter((q) => deadQueries.has(q));
    const kept = base.filter((q) => !deadQueries.has(q));
    if (proven.length === 0 && demoted.length === 0) return baseExtraQueries;
    if (demoted.length > 0) {
      console.log(
        `[SearchMemory] "${trimmedEntity}": demoted ${demoted.length} quer(y/ies) that came up ` +
          `empty on multiple sources — ${demoted.slice(0, 2).map((q) => `"${q.slice(0, 40)}"`).join(", ")}`
      );
    }
    return [...new Set([...proven, ...kept, ...demoted])];
  } catch {
    return baseExtraQueries;
  }
}

/** F3-27: derive the F3-26 coverage-warning input from a resolved retrieval funnel
 *  result and fire the (best-effort, non-blocking) user/admin warning when the archive
 *  plus web sourcing combined are still short. applyCoverageWarningIfNeeded never
 *  throws (F3-26), and this is fired without awaiting so it never delays the current
 *  video's beat retrieval. */
export function reportFunnelCoverageIfInsufficient(
  videoId: number | null | undefined,
  entity: string | undefined,
  funnel: RetrievalFunnelResult
): void {
  const trimmedEntity = entity?.trim();
  if (!videoId || !trimmedEntity) return;
  const archiveCount = funnel.candidates.filter((c) => c.source === "archive").length;
  const webFoundCount = funnel.candidates.filter((c) => c.source !== "archive").length;
  void applyCoverageWarningIfNeeded(videoId, {
    entity: trimmedEntity,
    archiveCount,
    recommendedCount: FUNNEL_RECOMMENDED_COVERAGE_COUNT,
    webSearchAttempted: true,
    webFoundCount,
  });
}

async function resolveBeatClip(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  sceneIndex: number,
  clipFetchDur: number,
  dedup: VisualDedupState,
  opts: ResolveBeatClipOptions = {}
): Promise<string | null> {
  const {
    spaceTopic = false,
    videoTitle,
    adoptOpts = {},
    primaryOnly = false,
    tag = `b${beat.index}`,
    stockReason = "beat",
  } = opts;
  const scenePersons = opts.scenePersons
    ?? resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const personName = opts.personName ?? scenePersons[0] ?? dedup.primaryPerson ?? "";

  /**
   * THE ONE PRODUCTION ENTRY FOR A BEAT'S VISUAL SOURCING.
   *
   * Every route a beat can take to a provider runs inside this scope — both branches below, the
   * thirty strategy functions beneath them, and every rescue and fallback they reach. That is what
   * makes the tier ladder enforceable: `searchGateDecision`, which every external provider already
   * passes, asks `admitProviderForTier` whether the tier may run yet, and a tier that would skip
   * one above it is refused with `TIER_OUT_OF_ORDER`.
   *
   * The strategies are untouched. They still decide WHAT to search for — the query, the person,
   * the visual need — and no longer decide the ORDER of the sources, which is the split this round
   * is about: a strategy is not a sourcing route.
   */
  return runCentralVisualSourcing(
    {
      renderId: String(getActiveVideoId() ?? "-"),
      sceneIndex,
      beatIndex: beat.index,
      declined: beatSourcingDeclines(dedup),
    },
    async () => {
      if (primaryOnly) {
        return beatPrimaryFetch(
          beat, scene, workDir, sceneIndex, clipFetchDur, dedup,
          personName, videoTitle, adoptOpts, scenePersons, tag, stockReason
        );
      }
      return resolveBeatClipForBeat(
        beat, scene, workDir, sceneIndex, clipFetchDur, dedup,
        spaceTopic, personName, videoTitle, adoptOpts
      );
    }
  );
}

/**
 * The tiers this render can already prove are unavailable, before the beat starts.
 *
 * §6's distinction made structural. A tier that is absent from this list has NOT been declined,
 * and a provider below it stays refused until something actually attempts it — "not called" and
 * "declined" must not collapse into each other, because that is precisely how stock ends up first.
 *
 * Every entry is something the code KNOWS: a capability switch, a missing key, a ceiling already
 * spent. Nothing here is a guess about whether a tier would have found anything.
 */
function beatSourcingDeclines(dedup: VisualDedupState): TierDecline[] {
  const declines: TierDecline[] = [];

  if (!youtubeSourcingEnabled()) {
    declines.push({ tier: "YOUTUBE", reason: "ENABLE_YOUTUBE_SOURCING_OFF" });
  } else if (!youtubeCcReady()) {
    declines.push({ tier: "YOUTUBE", reason: "NO_YOUTUBE_CAPABILITY" });
  } else if (dedup.entityYoutubeFetchesUsed >= dedup.perf.maxEntityYoutubePerVideo) {
    declines.push({ tier: "YOUTUBE", reason: "ENTITY_CEILING_SPENT" });
  }

  /**
   * Tier 3 is a set of collections, most of which need no key at all — Internet Archive, Wikimedia
   * and Openverse among them. It is declined only when the render has switched archival sourcing
   * off, which is a decision rather than an absence.
   */
  if (!dedup.perf.enableArchival && !dedup.perf.enableNasa) {
    declines.push({ tier: "OPEN_SOURCES", reason: "ARCHIVAL_AND_NASA_DISABLED" });
  }

  if (!PEXELS_API_KEY && !PIXABAY_API_KEY) {
    declines.push({ tier: "STOCK", reason: "NO_STOCK_PROVIDER_CONFIGURED" });
  }
  return declines;
}

// ─── 3e. Fetch All Visuals for a Scene (beat-aligned) ───────────────────────
// One stock clip per ~3.5s narration beat, in narrative order. No clip recycling.
type SceneVisualsResult = {
  clips: string[];
  beatDurations: number[];
  /** Beats used when fetching clips — same segmentation as voiceover sentences. */
  beats?: SceneBeat[];
  /** Beat index per clip (parallel to clips). */
  clipBeatIndices?: number[];
};
type BeatProgressPhase = "beat" | "backfill";

/**
 * RONDE 103 phase 4 — the beat context, built in one place from the objects that already have it.
 *
 * Every route that reaches the relevance gate has a `beat` and a `scene`; what they did not have
 * was an agreed shape to hand on. Building it here rather than at each call site means the judge
 * is asked the same question about the same beat no matter which route arrived at it — which is
 * also what makes the cache key stable across routes.
 */
function beatVisualContext(
  beat: { text?: string; index?: number },
  scene: { text?: string; index?: number },
  videoTitle: string | undefined
): BeatVisualContext {
  /**
   * RONDE 175 §3 — what the pipeline already established, handed to the judge.
   *
   * The judge's question carried the title, the paragraph and the line, and left it to infer the
   * subject and the period from prose. `buildVideoVisualContext` has established the period and
   * the places for this documentary, and neither ever reached the question.
   *
   * The period is passed as the DOCUMENTARY's, never as this shot's: a WWII film can legitimately
   * cut to a 1919 photograph, and telling the judge the narration places this shot in the 1940s
   * would make it refuse a correct picture. The prompt labels the scope.
   */
  const visual = get_activeVideoVisualContext();
  const anchors = visual
    ? {
        documentaryPeriod: visual.period?.trim() || undefined,
        documentaryPlaces: visual.locations?.filter(Boolean).slice(0, 3),
      }
    : undefined;
  return {
    sceneIndex: scene.index ?? 0,
    beatIndex: beat.index ?? 0,
    beatText: beat.text ?? "",
    sceneText: scene.text,
    videoTitle: asVideoTitleString(videoTitle) || undefined,
    anchors,
  };
}

/**
 * RONDE 103, second audit — the acceptance point refuses what the gate refused.
 *
 * Every named adopt/rescue route reaches the relevance gate, and the sweep confirms it. But a
 * list of routes is not a proof that no route was missed, and the four `pushSceneClip` closures
 * are where a clip actually becomes a beat's clip — the narrowest place that is true. Asking here
 * means a route added later cannot push a clip this render has already refused, whatever it did
 * or did not call on the way.
 *
 * It refuses only a `does_not_fit` nobody reprieved. A clip the gate has never seen passes: this
 * cannot judge, and pretending otherwise would empty montages on the routes that build their own
 * files. That gap is counted rather than assumed away — see barrierCoverage.
 */
/**
 * Exported for the regression suite. RENDER 592-B's defect lives in this function's own branching
 * — whether it reads the last look's outcome — and a test that cannot call it can only assert
 * things about the source text, which is how the previous round's mutations survived.
 */
/**
 * THE ARCHIVE-FIRST INVARIANT, AT THE ONE BOUNDARY EVERY PICTURE CROSSES.
 *
 * ── Why here, and not in the twenty-five routes ─────────────────────────────────────────────
 *
 * The previous round gave the funnel, the scene pool and the two web-wide rescue routes an
 * archive handle before adoption. That left the historical tier cascade — some twenty-five
 * `adoptClip` call sites — still able to put a Wikimedia, NASA, Openverse or SerpAPI clip into the
 * film with no handle of ours, and the honest report said so.
 *
 * Twenty-five patches would be twenty-four chances to forget. This codebase has already answered
 * where the single point is, twice, in its own words:
 *
 *   RONDE 93: "The `clips.push` inside the four scene-push variants is where a picture actually
 *   enters the film. The adopt recorder cannot be the guard: it runs after the push has already
 *   returned true, so refusing there refuses a RECORD, not a PICTURE."
 *
 *   RONDE 232: "There are four `pushSceneClip` definitions and every one of them opens with this
 *   call. Putting the recording in the callers means remembering it four times and a fifth time
 *   for the next one; putting it here means the refusal cannot be made without recording it."
 *
 * So this is the boundary, and it is now five call sites, one of them inside
 * `fetchSceneVisualsInner` — which is where the funnel, the pool, the cascade and the rescue
 * ladders all end. A route cannot place a picture without passing here.
 *
 * ── What it decides ─────────────────────────────────────────────────────────────────────────
 *
 * Only about clips whose EXTERNAL PROVIDER THIS RENDER CAN PROVE, read from the lineage record's
 * root — the identity a transformed or trimmed file inherits from the asset it was made from.
 * Nothing is inferred from a filename or a content-key family; a clip the ledger cannot place is
 * not turned into a claim.
 *
 * Four outcomes allow the push without storing anything, and each is a real category rather than
 * a way round the rule:
 *
 *   not_external      no record, or no provable provider — a generated card, a guaranteed filler,
 *                     a local file. There is no external asset here to archive.
 *   already_archived  the root already carries an archiveAssetId: the curated archive's own
 *                     material, and everything the four eager routes stored moments ago.
 *   exempt_source     RONDE 9's standing exception. Pexels and Pixabay may not enter the curated
 *                     archive — a stock clip ingested tagged "adolf hitler" outranked real archive
 *                     footage on every later render — and `archive` is already in it.
 *   ingestion_stopped the operator switched external ingestion off. Refusing every external clip
 *                     because of a setting would turn a configuration choice into an outage.
 *
 * Everything else is stored, awaited, before the picture enters the film. A store that fails
 * REFUSES THE PUSH: a clip that cannot be read back from our own storage is not a clip this
 * architecture is willing to put in a timeline, and the beat falls through to the next candidate
 * exactly as it would for any other refusal. That is a deliberate change of posture from the
 * previous round, where a storage failure cost the handle and not the clip — and it is the point
 * of the invariant: "archive later" is the thing being removed.
 */
type ArchivePushVerdict =
  | { ok: true; reason: "not_external" | "already_archived" | "exempt_source" | "ingestion_stopped" | "stored" }
  | { ok: false; reason: string };

/**
 * Video 614 — the key under which the archive's on-screen-text verdict for this clip is memoised.
 * The same expression `ensureArchiveBackedBeforePush` hands the archive as `remoteUrl`, so an answer
 * given before the picture editor is the answer the push gate reads back.
 */
function onScreenTextVerdictKey(dedup: VisualDedupState, clipPath: string, contentKey: string): string {
  const ledger = dedup.sourcingCache?.lineage;
  const record = ledger?.resolve(clipPath, contentKey) ?? null;
  const root = record && ledger ? ledger.rootOf(record.lineageId) ?? record : record;
  const provider = root?.provider?.trim().toLowerCase() || "unknown";
  const providerAssetId = root?.providerAssetId?.trim() || null;
  const cached = providerAssetId ? getCachedProviderAsset(dedup.sourcingCache, provider, providerAssetId) : null;
  const remoteUrl = root?.sourceUrl ?? root?.originalUrl ?? cached?.canonicalUrl ?? null;
  return remoteUrl || `${provider}:${providerAssetId ?? "unknown"}:${path.basename(clipPath)}`;
}

async function ensureArchiveBackedBeforePush(
  dedup: VisualDedupState,
  clipPath: string,
  contentKey: string,
  sceneIndex: number,
  beatIndex: number | undefined
): Promise<ArchivePushVerdict> {
  const ledger = dedup.sourcingCache?.lineage;
  const record = ledger?.resolve(clipPath, contentKey) ?? null;
  /** The asset this file was MADE FROM, because a trim or a fair-use transform has its own record. */
  const root = record && ledger ? ledger.rootOf(record.lineageId) ?? record : record;
  const provider = root?.provider?.trim().toLowerCase() || null;
  if (!root || !provider) return { ok: true, reason: "not_external" };
  if (root.archiveAssetId != null) {
    /**
     * RENDER 595 §1 — THE EXEMPTION READ ONE ROW AND THE TIMELINE READ ANOTHER.
     *
     * ── The two rows ────────────────────────────────────────────────────────────────────
     *
     * This gate resolves the clip's record and then walks to its ROOT — the asset a trim, an
     * extension or a fair-use transform was made from — because that is where the provider
     * identity lives. The cinematic planner does not walk: it reads
     * `lineage.resolve(clipPath, clipContentKey(clipPath))` and builds the timeline identity out
     * of THAT record's `archiveAssetId` (videoPipeline.ts, `adoption:`).
     *
     * `linkDerivedPath` copies the parent's handle when the derived record is CREATED. A root
     * archived after that — archived on an earlier beat's push, or reused by checksum — never
     * reaches its children. So the gate saw a handle, took the exemption, stored nothing, and the
     * planner read a row that still said null:
     *
     *     no ARCHIVE_STORE_START for vc_999c384232, and archiveAssetId=null on the timeline
     *
     * ── The fix, and why it is not a new archive layer ──────────────────────────────────
     *
     * The handle is not invented here and nothing is stored: the root's own `archiveAssetId` is
     * written onto the record the timeline will read. `attachArchiveAsset` fills and never
     * overwrites, so a record that already had one keeps it. The rehydrator fetches that asset —
     * the untrimmed original — and the timeline's `sourceIn`/`sourceOut` make this clip's cut out
     * of it, which is exactly what those fields are for.
     *
     * Re-ingesting the derived file instead would store the same footage twice, which §14's
     * checksum and provider-asset deduplication exists to prevent.
     */
    if (record && record.archiveAssetId == null && ledger) {
      const attached = ledger.attachArchiveAsset(record, root.archiveAssetId);
      console.log(
        `[ProductionArchive] s${sceneIndex}b${beatIndex ?? "?"} ARCHIVE_HANDLE_INHERITED ` +
          `archiveAssetId=${root.archiveAssetId} provider=${provider} ` +
          `file=${path.basename(clipPath)} attached=${attached.archiveAssetId != null} — ` +
          `this file was made from an asset the archive already holds`
      );
    }
    return { ok: true, reason: "already_archived" };
  }
  /**
   * RONDE 647 — EVERY SHOT IS KEPT IN OUR OWN STORAGE, STOCK INCLUDED.
   *
   * Video 604 rendered cleanly and was not delivered: one Pexels shot carried no archive asset, and
   * the delivery gate requires one for every clip (CLIP_WITHOUT_ARCHIVE_ASSET) while this line
   * exempted stock from being stored. Two rules that could never both be met. Stock is now stored
   * too — in the separate, inactive Stockbeelden archive, so RONDE 9's rule still holds: stock is
   * never offered as archive footage. Only the curated archive's own rows stay exempt.
   */
  const stock = isStockProvider(provider);
  if (!stock && !sourceMayEnterCuratedArchive(provider)) return { ok: true, reason: "exempt_source" };
  if (!externalAssetIngestionEnabled()) return { ok: true, reason: "ingestion_stopped" };

  const providerAssetId = root.providerAssetId?.trim() || null;
  /** Provider-authored detail the fetcher cached, when it cached any. Never invented. */
  const cached = providerAssetId
    ? getCachedProviderAsset(dedup.sourcingCache, provider, providerAssetId)
    : null;
  const facts: ExternalClipArchiveFacts = {
    source: provider,
    providerAssetId,
    title: root.assetTitle?.trim() || path.basename(clipPath),
    mediaType: root.mediaType === "image" ? "image" : "video",
    license: cached?.license?.reported ?? null,
    licenseUrl: null,
    durationSec: cached?.durationSec ?? null,
    sourceCreator: null,
    remoteUrl: root.sourceUrl ?? root.originalUrl ?? cached?.canonicalUrl ?? null,
  };
  const stored = await storeExternalClipForTimeline({
    clipPath,
    facts,
    metadata: {
      ...archiveMetadataForExternalClip(facts, {
        beatQuery: root.query?.trim() || root.beatText?.slice(0, 80) || "",
        personContext: Boolean(dedup.personTopicLock && dedup.primaryPerson),
        topics: [],
      }),
      ...(stock ? { stockArchive: true } : {}),
    },
    lineage: ledger,
    workDir: path.dirname(clipPath),
    sceneIndex,
    beatIndex: beatIndex ?? 0,
    route: "push_gate",
  });
  if (stored.status === "stored") return { ok: true, reason: "stored" };
  return { ok: false, reason: `${stored.code}:${stored.mediaStatus}` };
}

export async function beatClipRefusedByRelevanceGate(
  dedup: VisualDedupState,
  clipPath: string,
  sceneIndex: number,
  beatIndex: number | undefined,
  /**
   * RENDER 579 — only the two backfill push closures pass "approval"; every other caller keeps the
   * default and therefore keeps exactly the behaviour it had. See `composeBarrierAllows`.
   */
  demand: "no_refusal" | "approval" = "no_refusal"
): Promise<boolean> {
  /**
   * The editorial question first, unchanged, then the archive one.
   *
   * Order matters and is asserted: a picture the barrier refuses must never be stored, or every
   * refused candidate would be ingested on its way out — which is the archive poisoning RONDE 9
   * exists to prevent, arriving through the back door.
   */
  if (await relevanceGateRefusesClip(dedup, clipPath, sceneIndex, beatIndex, demand)) return true;
  const archived = await ensureArchiveBackedBeforePush(
    dedup, clipPath, clipContentKey(clipPath), sceneIndex, beatIndex
  );
  if (archived.ok) return false;
  recordArchivePushRefusal(dedup, clipPath, sceneIndex, beatIndex, archived.reason);
  return true;
}

/**
 * One spelling of the refusal, because there are two gates that can make it.
 *
 * `beatClipRefusedByRelevanceGate` is the boundary for every route that has a beat. The fast-short
 * compose rescue has its own gate — `montageClipPassesComposeGate` — and does not pass through it,
 * so it asks the archive question itself. Both must refuse the same way, or the two routes would
 * disagree about what a refused clip looks like in the ledger and in the log.
 */
function recordArchivePushRefusal(
  dedup: VisualDedupState,
  clipPath: string,
  sceneIndex: number,
  beatIndex: number | undefined,
  cause: string
): void {
  const reason = `archive not ready (${cause})`;
  console.warn(
    `[BeatRelevance] s${sceneIndex}b${beatIndex ?? "?"}: refusing to push ` +
      `${path.basename(clipPath)} — ${reason}; an external clip that cannot be read back from ` +
      `our own storage may not enter the timeline`
  );
  dedup.sourcingCache?.lineage?.recordRejection(clipPath, reason, clipContentKey(clipPath));
  if (beatIndex != null) {
    recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, clipPath, reason);
  }
  tracePushOutcome(dedup, clipPath, sceneIndex, beatIndex, false, reason);
}

/** The editorial gate exactly as it was — see `beatClipRefusedByRelevanceGate` above. */
async function relevanceGateRefusesClip(
  dedup: VisualDedupState,
  clipPath: string,
  sceneIndex: number,
  beatIndex: number | undefined,
  demand: "no_refusal" | "approval" = "no_refusal"
): Promise<boolean> {
  /**
   * RENDER 564 — get an answer before this clip becomes part of a scene.
   *
   * The barrier below turns away a refused clip, and a clip nobody judged is not refused. Render
   * 564 put `scene_1_b0_curated_a57670.mp4` into scene 1 at 17:56:18 with eight verdicts existing
   * in the entire render and none of them about it; the refusal landed at 17:58:29.
   *
   * This route knows its beat, so it asks directly rather than going through the adopt audit.
   * Already-judged clips cost nothing, and every failure path leaves the barrier's answer exactly
   * as it was — see ensureVerdictBeforeCompose.
   */
  /**
   * RENDER 592-B — AND THE ANSWER IS KEPT THIS TIME.
   *
   * This call's return value was discarded. `ensureVerdictBeforeCompose` has seven outcomes and
   * three of them say the look could not happen because there is no sentence behind the slot; the
   * barrier below then refused the clip for the absence of the very look it had just been told
   * about. Scene 2 of render 592-B did that forty-six times over four files, filled its beats with
   * text overlays, and died on the export gate that rejects them. See `nothingToJudgeAgainst`.
   */
  let lastLook: ComposeJudgeOutcome | undefined;
  if (beatIndex != null) {
    const ensured = await ensureVerdictBeforeCompose({
      clipPath,
      contentKey: clipContentKey(clipPath),
      sceneIndex,
      beatIndex,
      route: "push",
      /**
       * RONDE 199 — this is the picture, not a candidate.
       *
       * Every push closure calls this immediately before `adoptionGuardRefusesPush`, and the guard
       * no longer accepts "nobody looked" as an answer. So the look has to be obtainable here even
       * when the beat has spent its comparison budget: otherwise the tightening would not make the
       * render judge more pictures, it would make it ship fewer — which is the render-569 failure
       * this codebase has already paid for once.
       */
      finalSay: true,
    });
    lastLook = ensured.outcome;
  }
  const contentKey = clipContentKey(clipPath);
  /**
   * THE BEAT IS PASSED, BECAUSE THIS ROUTE HAS ONE.
   *
   * The barrier read one verdict per clip and never asked which sentence it was about, so a
   * `does_not_fit` earned at one beat turned the clip away at every beat — including beats where
   * the editor had approved it. See `composeBarrierAllows` for why that is the pre-pool screening's
   * failure in a second place, and for what does NOT change: a beat with no verdict of its own
   * still inherits the refusal.
   *
   * `beatIndex` is optional on this function and null on the routes that genuinely have no beat;
   * those keep exactly the behaviour they had.
   */
  const barrier = composeBarrierAllows(
    dedup.beatRelevance,
    clipPath,
    contentKey,
    beatIndex != null ? { sceneIndex, beatIndex } : undefined,
    /**
     * RENDER 579 — the backfill routes ask for an approval, not merely the absence of a refusal.
     * See `composeBarrierAllows` for the two asset ids that shipped on `verdict=unknown` and why
     * the other routes deliberately keep the fail-open answer they have always had.
     */
    demand
  );
  if (barrier.allow) return false;
  /**
   * RENDER 592-B — A DEMAND NOTHING CAN MEET IS NOT A STANDARD, AND THIS IS THE SECOND PLACE IT
   * HAD TO BE SAID.
   *
   * ── What scene 2 did ────────────────────────────────────────────────────────────────────────
   *
   *     [BeatRelevance] s2b0: refusing to push scene_2_slot0_guaranteed.mp4 —
   *         backfill needs an approval; nobody looked at this clip for s2b0
   *     …forty-six times, over four files, for one sentence.
   *
   * Then `Scene 2 slot 0/100/200/300: text-overlay fallback OK`, and the export gate — which
   * rejects exactly those, by `isPipelineFallbackClip` — ended the render on
   * `4 zinnen maar 0 voice/script-matchende clips`.
   *
   * ── Why it could not recover ────────────────────────────────────────────────────────────────
   *
   * `adoptionGuardRefusesPush` has held the answer since RONDE 215: when the last look reports
   * `no_scope`, `beat_unknown` or `no_narration` there is no sentence behind the slot, so no amount
   * of asking can produce a verdict, and demanding one empties the film instead of raising the bar.
   * This route made the same decision from the same information and did not apply that policy —
   * because it threw the information away. One `await` without an assignment, and the whole of it.
   *
   * ── What is suspended, and what is not ──────────────────────────────────────────────────────
   *
   * ONLY the approval requirement, and only on those three outcomes. The barrier is asked again
   * under the demand every other route uses, so a `does_not_fit` nobody reprieved still refuses
   * here exactly as it did before — `no verdict` becomes `no approval required`, never `approved`.
   * The picture then faces every later gate unchanged, the beat may not claim an approved picture,
   * and the export gate still counts a pipeline fallback as unusable.
   */
  const approvalRefusal =
    demand === "approval" && barrier.reason.startsWith("backfill needs an approval");
  if (approvalRefusal && beatIndex != null && lastLook && nothingToJudgeAgainst(lastLook)) {
    const relaxed = composeBarrierAllows(
      dedup.beatRelevance,
      clipPath,
      contentKey,
      { sceneIndex, beatIndex },
      "no_refusal"
    );
    if (relaxed.allow) {
      const seen = dedup.backfillApprovalSuspended.get(lastLook) ?? 0;
      dedup.backfillApprovalSuspended.set(lastLook, seen + 1);
      /**
       * Counted every time, said once. Render 592-B printed its refusal forty-six times for one
       * beat; an exemption that repeats itself that often is a transcript, not a report. Keyed the
       * same way `adoptionGuardRefusesPush` keys its own repeats.
       */
      const repeats = noteRepeatedRefusal(
        dedup.clipRejectAudit,
        sceneIndex,
        beatIndex,
        contentKey || path.basename(clipPath),
        `BACKFILL_APPROVAL_SUSPENDED:${lastLook}`
      );
      if (repeats === 0) {
        console.warn(
          `[BeatRelevance] s${sceneIndex}b${beatIndex}: backfill approval requirement suspended: ` +
            `reason=${lastLook} file=${path.basename(clipPath)} — there is no narration to judge ` +
            `this picture against, so no approval can be earned for it; the picture is NOT approved ` +
            `and this beat may not claim one`
        );
      }
      return false;
    }
    /** The relaxed demand refuses too, so this was a real editorial no. It falls through. */
  }
  /**
   * AND WHEN THE LOOK FAILED FOR A REASON THAT IS NOT "THERE WAS NOTHING TO LOOK AT".
   *
   * `budget_spent`, or an `already_judged` that resolves to a recorded non-verdict, both mean the
   * render could not obtain a verdict it was able to ask for. That is a fault in the render, not a
   * judgement on the picture, and the refusal below is still correct — but it must not read as an
   * editorial one. Said once per beat and clip, beside the refusal rather than instead of it.
   */
  if (
    approvalRefusal &&
    beatIndex != null &&
    lastLook &&
    !nothingToJudgeAgainst(lastLook) &&
    lastLook !== "judged" &&
    lastLook !== "placeholder" &&
    barrier.reason.includes("nobody looked at this clip")
  ) {
    const repeats = noteRepeatedRefusal(
      dedup.clipRejectAudit,
      sceneIndex,
      beatIndex,
      contentKey || path.basename(clipPath),
      `BACKFILL_VERDICT_UNAVAILABLE:${lastLook}`
    );
    if (repeats === 0) {
      console.error(
        `[BeatRelevance] s${sceneIndex}b${beatIndex}: backfill verdict unavailable: ` +
          `reason=${lastLook} file=${path.basename(clipPath)} — the last look was asked for and did ` +
          `not produce a verdict; this refusal is the render failing to judge, not the editor refusing`
      );
    }
  }
  /** Only the refusals this rule actually caused — a `does_not_fit` would have been refused anyway. */
  if (demand === "approval" && barrier.reason.startsWith("backfill needs an approval")) {
    dedup.backfillRefusedWithoutApproval += 1;
    /**
     * RONDE 232 — the half of that number that is about the render rather than the picture. See
     * `backfillRefusedNeverLookedAt`; `composeBarrierAllows` decides which sentence it wrote.
     */
    if (barrier.reason.includes("nobody looked at this clip")) {
      dedup.backfillRefusedNeverLookedAt += 1;
    }
  }
  console.warn(
    `[BeatRelevance] s${sceneIndex}b${beatIndex ?? "?"}: refusing to push ` +
      `${path.basename(clipPath)} — ${barrier.reason}`
  );
  /**
   * A REFUSAL IS AN OUTCOME, AND IT BELONGS ON THE LEDGER.
   *
   * ── The hole this closes ────────────────────────────────────────────────────────────────────
   *
   * This warned to the console and returned. The clip therefore never entered the scene's clip
   * list — and `noteSceneClipsResourced`, the one place that writes REPLACED when a scene is
   * re-sourced, iterates `previous.clips`. An asset refused HERE is not in that list and never can
   * be, so no later pass could explain it either. Its ledger record stopped at ADOPTED with
   * nothing after it, which is exactly what `[AssetNotRendered] … reachedAssigned=true
   * outcome=DROPPED_WITHOUT_EVENT` reports.
   *
   * Render 567's approved YouTube clip is in that state: adopted for s0b0, absent from the film,
   * and the beat filled by `scene_0_slot100_guaranteed.mp4` instead. Whether this gate is what
   * turned that particular clip away is NOT established — the supplied log begins after sourcing —
   * but a refusal that records nothing can never be read back, whichever clip it happens to.
   *
   * ── Why here and not in the callers ─────────────────────────────────────────────────────────
   *
   * There are four `pushSceneClip` definitions and every one of them opens with this call. Putting
   * the recording in the callers means remembering it four times and a fifth time for the next
   * one; putting it here means the refusal cannot be made without recording it. That is the seam
   * this codebase keeps splitting on, closed at the single point all routes already pass through.
   *
   * `recordRejection` resolves by path, derivation chain and content key, and returns false when
   * the ledger never knew the clip — an honest miss, not an invented record.
   */
  dedup.sourcingCache?.lineage?.recordRejection(clipPath, barrier.reason, contentKey);
  /**
   * AND THE BEAT'S OWN TALLY, WHICH IS WHAT THE PLACEHOLDER DECISION READS.
   *
   * ── The false statement this removes ────────────────────────────────────────────────────────
   *
   * When a beat ends up empty, `rescueBeatVisualWhenEmptyInner` prints
   *
   *     [VisualCoverage] s0b0: rejected=0 topRejects=none contextualSearch=true
   *                      fallback=PLACEHOLDER (all real/contextual/AI sourcing strategies exhausted)
   *
   * and then makes `scene_0_slot100_guaranteed.mp4`. For render 567's beat 0 that parenthetical was
   * untrue: a real YouTube clip had been found, downloaded, judged `fits`, selected, transformed
   * and adopted. Nothing was exhausted — the asset was turned away at this gate, and because the
   * refusal was recorded nowhere the tally said `rejected=0`, which is indistinguishable from a
   * beat that was never offered anything.
   *
   * `beatRejectCount` and `beatRejectReasons` already feed that line. Writing here is what makes it
   * tell the truth: the same beat now reads `rejected=1 topRejects=<the barrier's own reason>`.
   *
   * ── What is deliberately NOT done ───────────────────────────────────────────────────────────
   *
   * The clip is still refused. A barrier that judged this footage wrong for this narration is an
   * editorial decision, and forcing it into the film to avoid a placeholder would be exactly the
   * "turn a blocking problem into a non-blocking one" this project forbids. The placeholder stays;
   * what changes is that it can be explained.
   */
  if (beatIndex != null) {
    recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex, clipPath, barrier.reason);
  }
  tracePushOutcome(dedup, clipPath, sceneIndex, beatIndex, false, barrier.reason);
  return true;
}

/**
 * THE PUSH SAYS WHAT IT DECIDED, AT THE MOMENT IT DECIDES IT.
 *
 * ── Why a line here and not only a ledger event ─────────────────────────────────────────────
 *
 * `pushSceneClip` is the narrowest point at which a clip becomes a beat's clip: it is the sole
 * writer of `clipBeatIndices`, and `clipBeatIndices` is the only test the placeholder rescue makes.
 * Every caller nevertheless awaits the push and throws the answer away, so the moment
 * a beat lost its real asset appeared nowhere in the log — it could only be inferred, afterwards,
 * from a guaranteed filler showing up.
 *
 * The ledger already gets a terminal outcome for a refusal, and the beat tally already gets a
 * reason. Both are read at the END of the render. This is the same fact in the running log, in the
 * beat's own order, so a reader can follow one asset down the file instead of reconstructing it
 * from three summaries.
 *
 * ── Identity, not position ──────────────────────────────────────────────────────────────────
 *
 * The asset is named by what the ledger proved about it — provider and provider asset id, folded
 * to the root of any derivation chain — and never by an index. `resolve` walks the path, the
 * derivation chain and the content key, so a transformed file still reports the identity of the
 * asset it was made from. When the ledger does not know the clip, the line says `asset=unknown`
 * and carries the basename: an honest gap, not a guess.
 */
function tracePushOutcome(
  dedup: VisualDedupState,
  clipPath: string,
  sceneIndex: number,
  beatIndex: number | undefined,
  accepted: boolean,
  reason: string
): void {
  /** RONDE 660 — the beat's own memory of it: see `refusedAtPush` on the relevance ledger. */
  if (dedup.beatRelevance && beatIndex != null) {
    notePushOutcomeForBeat(
      dedup.beatRelevance, sceneIndex, beatIndex, { clipPath, contentKey: clipContentKey(clipPath) || null }, accepted
    );
  }
  const ledger = dedup.sourcingCache?.lineage;
  const record = ledger?.resolve(clipPath, clipContentKey(clipPath)) ?? null;
  const root = record && ledger ? ledger.rootOf(record.lineageId) ?? record : record;
  const asset = root
    ? `${root.provider ?? "UNVERIFIED"}:${root.providerAssetId ?? root.archiveAssetId ?? root.lineageId}`
    : "unknown";
  console.log(
    `[PushTrace] scene=${sceneIndex} beat=${beatIndex ?? "?"} asset=${asset} ` +
      `lineage=${root?.lineageId ?? "none"} accepted=${accepted} reason=${reason} ` +
      `file=${path.basename(clipPath)}`
  );
}

/**
 * The other refusal every `pushSceneClip` makes: this render already used this footage.
 *
 * Same reasoning as above — it printed a warning and returned false, so a clip turned away for
 * being a repeat left the ledger holding ADOPTED and no ending. A duplicate is a perfectly good
 * editorial decision and it has a reason worth keeping; what it must not be is silent.
 *
 * The four call sites differ in whether they warn, which is why the warning stays theirs and only
 * the recording lives here.
 */
/**
 * RONDE 93 — THE MONTAGE BOUNDARY.
 *
 * The `clips.push` inside the four scene-push variants is where a picture actually enters the
 * film. RONDE 92 established that the adopt recorder cannot be the guard: it runs after the push
 * has already returned true, so refusing there refuses a RECORD, not a PICTURE.
 *
 * (Written without the literal call spelling on purpose: ronde103CentralGate's structural sweep
 * slices the file between top-level declarations and scans the text for routes that can place a
 * clip. A doc comment quoting that spelling is picked up as the previous function's body and
 * reported as an ungated route — a false finding produced by prose, which is worth avoiding
 * rather than teaching the sweep to ignore.)
 *
 * The route states what it is adopting through `withAdoptionIntent`, ambiently, the way this file
 * already scopes a beat's provenance and its query scope. A route that states nothing yields null
 * and passes exactly as before — this is incremental by construction, not a flag day.
 *
 * A refusal here is a real terminal outcome: the clip never reaches `clips[]`, and the lineage
 * records DROPPED_AT_PUSH with the guard's own reason rather than the clip vanishing.
 */
/**
 * Exported for the regression suite. RENDER 592-B: the claim that this guard suspends its vision
 * requirement on exactly three outcomes was asserted by reading its source text for three string
 * literals, which a mutation can leave intact while making them irrelevant. Asked of the function.
 */
export async function adoptionGuardRefusesPush(
  dedup: VisualDedupState,
  clipPath: string,
  sceneIndex: number,
  beatIndex: number | undefined
): Promise<boolean> {
  const source = currentAdoptionIntent();
  if (!source) return false;

  /**
   * RONDE 215 — THE GUARD ASKS FOR ITSELF, BECAUSE 12 OF ITS 17 CALLERS NEVER DID.
   *
   * ── What render 575 measured ────────────────────────────────────────────────────────────────
   *
   *     [AdoptionGuard] scene=0 beat=1 route=rescue_wikimedia eligible=true vision=NOT_ASKED
   *         blocked=FUNNEL_WITHOUT_EVIDENCE reason=route "rescue_wikimedia" claims RESCUE_REAL
   *         without vision (NOT_ASKED)
   *     [AdoptionGuard] scene=0 beat=1 route=fallback           ... (28×)
   *     [AdoptionGuard] scene=0 beat=1 route=rescue_placeholder ... (24×)
   *
   * Scene 0 finished with no picture at all and the export gate refused the film. Real Wikimedia
   * footage, already ELIGIBLE, was thrown away — not because the editor disliked it, but because
   * nobody had asked.
   *
   * RONDE 199 made this function REQUIRE a verdict. The asking lives in
   * `beatClipRefusedByRelevanceGate`, which is called at 5 of this guard's 17 call sites. At the
   * other 12 the answer was NOT_ASKED by construction, and after RONDE 199 that is a refusal. A
   * reader tightened without its writer — this codebase's signature defect, and this time I wrote
   * it.
   *
   * The rule moves into the one place all 17 pass through, so a route can no longer demand evidence
   * it never gathered. The five that already ask are unaffected: `ensureVerdictBeforeCompose`
   * returns `already_judged` for a clip on the ledger and costs nothing.
   *
   * ── The half that is NOT a missing call ─────────────────────────────────────────────────────
   *
   * Some callers pass a SYNTHETIC beat index. `fillSceneToMinimumClips` passes `2000 + slot` and
   * its own comment says so: "`slot` is this array's own position counter — NOT a real narrative
   * beat index". There is no sentence behind such an index, so there is nothing to judge the
   * picture AGAINST, and no amount of asking can produce a verdict.
   *
   * Demanding one there is demanding the impossible, which is the RONDE 199b `askImpossible`
   * lesson in a second form: a requirement that cannot be met does not raise the standard, it
   * empties the film. So the two outcomes that mean "there was nothing to ask against" suspend the
   * vision requirement for THIS adoption — named and logged, never silent — while "nobody tried"
   * keeps refusing exactly as RONDE 199 intended.
   */
  let askWasPossible = true;
  if (beatIndex == null) {
    askWasPossible = false;
  } else if (dedup.beatRelevance) {
    const ensured = await ensureVerdictBeforeCompose({
      clipPath,
      contentKey: clipContentKey(clipPath),
      sceneIndex,
      beatIndex,
      route: "adoption_guard",
      /** The picture is about to be used, so it is judged — see `BeatRelevanceParams.finalSay`. */
      finalSay: true,
    });
    /**
     * RENDER 592-B: this triple used to be spelled out here and nowhere else, which is how the
     * push/backfill route came to make the same decision without it. `nothingToJudgeAgainst` is
     * the same three outcomes with the same meaning, read by both.
     */
    if (nothingToJudgeAgainst(ensured.outcome)) {
      askWasPossible = false;
      console.warn(
        `[AdoptionGuard] s${sceneIndex}b${beatIndex}: nothing to judge against ` +
          `(${ensured.outcome}) file=${path.basename(clipPath)} route=${source} — ` +
          `the vision requirement is suspended for this adoption, not waived for the render`
      );
    }
  }

  const ledger = dedup.sourcingCache?.lineage;
  /** RONDE 94: the single central read — same helper the adopt audit and every route now use. */
  const eligible = Boolean(ledger?.isEligible(clipPath, clipContentKey(clipPath)));
  /**
   * RONDE 94: what the editor SAID, not merely whether it spoke. `does_not_fit` and `unknown` are
   * no longer silently as good as `fits` — see `visionVerdictFromGate`.
   */
  const judgement =
    dedup.beatRelevance && beatIndex != null
      ? relevanceVerdictForRenderedAsset(dedup.beatRelevance, {
          localPath: clipPath,
          currentFilename: path.basename(clipPath),
          contentKey: clipContentKey(clipPath),
          sceneIndex,
          beatIndex,
        })
      : null;
  /** RONDE 199b: `evaluated` travels with the verdict — see `visionVerdictFromGate`. */
  const vision = visionVerdictFromGate(judgement?.verdict, judgement?.evaluated);
  /**
   * RONDE 94: not "was this picture judged" but "could anything be judged at all". See
   * `adoptionGuardVerdict` — this suspends the vision requirement only when the model never
   * loaded, and RONDE 89's export gate still refuses the film such a render produces.
   */
  /**
   * RONDE 199b — and the same fact from the OTHER editor.
   *
   * `visionPipelineIsUnavailable()` is the CLIP model's latch. The beat image gate is a different
   * model behind a different provider, and it has its own way of being unreachable: no key, every
   * provider in cooldown, the spend budget gone, a 429 with no capacity. Until now nothing joined
   * the two, so a render whose beat judge could not be reached still had its vision requirement
   * enforced — and once "nobody looked" stopped counting as an answer, that would have refused
   * every adoption and emptied the film.
   *
   * Both are the same statement: this render has no picture editor. See `askImpossible`.
   */
  const visionAvailable =
    !visionPipelineIsUnavailable() &&
    !dedup.beatImageGate?.askImpossible &&
    /** RONDE 215: and there was a sentence to judge this picture against. See above. */
    askWasPossible;

  const verdict = adoptionGuardVerdict({ source, eligible, vision, visionAvailable });
  /**
   * Two facts for the replay bundle, recorded on EVERY adoption — allowed or refused, since a
   * bundle that only kept the refusals could never show a fix turning one into an adoption.
   *
   * The vision verdict is a fact about the world (what the editor said) and is replayed as input.
   * The guard's own outcome is a decision, kept only so a replay can be diffed against the render
   * it came from — it is never fed back in.
   */
  if (replayRecordingActive()) {
    const beat = beatIndex ?? 0;
    const file = path.basename(clipPath);
    const contentKey = clipContentKey(clipPath) || null;
    recordReplayFact({ kind: "vision", scene: sceneIndex, beat, file, contentKey, verdict: vision, visionAvailable });
    recordReplayFact({
      kind: "adoption",
      scene: sceneIndex,
      beat,
      route: source,
      eligible,
      vision,
      visionAvailable,
      allowed: verdict.allowed,
      code: verdict.allowed ? null : verdict.code,
    });
  }
  /**
   * AN EXEMPTION THAT LETS A PICTURE IN MUST NOT ALSO LET IN THE CLAIM THAT IT WAS CHECKED.
   *
   * This is the door video 580's WW2 clips came through. `askWasPossible` is false, the vision
   * requirement is suspended, `adoptionGuardVerdict` allows the adoption — and the picture is
   * then recorded under the beat it was fetched for, where `own_footage` used to mean "this beat
   * is finished". Real footage plus a suspended check read exactly like real footage that passed.
   *
   * The adoption still goes through. Refusing it is what RONDE 215 already measured and rejected:
   * a requirement nothing can satisfy empties the film instead of raising the bar, and the owner
   * has been clear that an empty video is the worst outcome of all.
   *
   * What changes is that the exemption is now COUNTED, per route, and said out loud at the end of
   * the render. The claim is withdrawn separately and structurally: no verdict was filed, so
   * `verificationForBeat` answers `never_asked`, and `buildBeatVisualStatuses` downgrades the
   * beat's coverage from `own_footage` to `unjudged_footage`. The picture is in the film and the
   * report no longer says anybody approved it.
   */
  if (verdict.allowed && !visionAvailable && !askWasPossible && adoptionPolicyFor(source).countsAsRealFootage) {
    const seen = dedup.adoptedWithSuspendedVision.get(source) ?? 0;
    dedup.adoptedWithSuspendedVision.set(source, seen + 1);
    console.warn(
      `[AdoptionGuard] s${sceneIndex}b${beatIndex ?? "?"} route=${source} ` +
        `UNJUDGED_REAL_FOOTAGE_ADOPTED file=${path.basename(clipPath)} — real footage entered the ` +
        `film with the vision requirement suspended; this beat may not claim an own approved picture`
    );
  }
  if (verdict.allowed) return false;

  /**
   * The decision is a pure function of (source, eligible, vision, visionAvailable). Re-offering the
   * same asset cannot change it, so the second and later refusals say the same words — nine of them
   * for one file on render 573. Counted every time, printed on the first, and named as a repeat
   * after that so the loop is visible instead of the transcript of it.
   */
  const refusalRepeats = noteRepeatedRefusal(
    dedup.clipRejectAudit,
    sceneIndex,
    beatIndex ?? 0,
    clipContentKey(clipPath) || path.basename(clipPath),
    verdict.code
  );
  console.warn(
    `[AdoptionGuard] scene=${sceneIndex} beat=${beatIndex ?? "?"} route=${source} ` +
      `eligible=${eligible} vision=${vision}${visionAvailable ? "" : " visionUnavailable"} blocked=${verdict.code} reason=${verdict.reason} ` +
      `file=${path.basename(clipPath)}` +
      (refusalRepeats > 0 ? ` REPEAT=${refusalRepeats + 1} — re-offered after an unchanged refusal` : "")
  );
  recordClipReject(dedup.clipRejectAudit, sceneIndex, beatIndex ?? 0, clipPath, verdict.code);
  ledger?.recordRejection(clipPath, verdict.code, clipContentKey(clipPath));
  tracePushOutcome(dedup, clipPath, sceneIndex, beatIndex, false, verdict.code);
  return true;
}

/**
 * The render's own account of every picture that entered with the vision requirement suspended.
 *
 * Exported for the test suite: this is a pure string function over a counter, and the claim worth
 * asserting — that a clean render says so in words rather than by staying quiet — is a property of
 * the sentence, not of a pipeline run.
 */
/**
 * The backfill's own suspensions, per outcome, as the tail of the `[BackfillApproval]` line.
 *
 * Empty string when nothing was suspended, so a render that never needed the exemption says
 * nothing rather than printing a row of zeroes. Exported for the same reason its sibling above is:
 * the claim worth asserting — that a suspension is never silent — is a property of this sentence.
 */
export function formatBackfillApprovalSuspensions(
  byOutcome: ReadonlyMap<ComposeJudgeOutcome, number>
): string {
  const rows = [...byOutcome.entries()].filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1]);
  if (rows.length === 0) return "";
  const total = rows.reduce((sum, [, n]) => sum + n, 0);
  return (
    ` · approvalSuspended=${total} (${rows.map(([o, n]) => `${o}=${n}`).join(" ")}) — ` +
    /**
     * "no sentence behind those slots", not "no narration".
     *
     * The outcomes counted here are not all the same finding: `slot_without_beat` is a montage
     * slot past the end of a scene's sentences, `no_narration` is a beat whose text is empty, and
     * `beat_unknown` is a clip nothing could place. The per-outcome breakdown above already says
     * which; this sentence used to overwrite all three with the name of one of them.
     */
    `no sentence behind those slots, so no approval could be earned; they are not approved`
  );
}

export function formatSuspendedVisionAdoptions(byRoute: ReadonlyMap<string, number>): string {
  const rows = [...byRoute.entries()].filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1]);
  const total = rows.reduce((sum, [, n]) => sum + n, 0);
  if (total === 0) {
    return "[UnjudgedFootage] adopted=0 — every picture in this film was put to the picture editor";
  }
  return (
    `[UnjudgedFootage] adopted=${total} ` +
    `(${rows.map(([route, n]) => `${route}=${n}`).join(" ")}) — real footage the editor was never ` +
    `shown, because the slot it filled had no narration to judge it against. These beats may not ` +
    `claim an approved own picture; see coverage=unjudged_footage`
  );
}

function noteDuplicateClipRefused(
  dedup: VisualDedupState,
  clipPath: string,
  contentKey: string,
  sceneIndex: number,
  beatIndex: number | undefined
): void {
  dedup.sourcingCache?.lineage?.recordRejection(clipPath, "duplicate_clip_once_per_video", contentKey);
  /** Same reason as the barrier above: the beat's tally is what the placeholder decision reads. */
  if (beatIndex != null) {
    recordClipReject(
      dedup.clipRejectAudit, sceneIndex, beatIndex, clipPath, "duplicate_clip_once_per_video"
    );
  }
  tracePushOutcome(dedup, clipPath, sceneIndex, beatIndex, false, "duplicate_clip_once_per_video");
}

/** RONDE 103: attribute one gate call's spend to the beat that asked for it. */
function noteVisionSpend(
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  spent: { judged: number; failed: number; skipped: number }
): void {
  for (let i = 0; i < spent.judged; i++) noteBeatVision(dedup.beatOutcomeAudit, sceneIndex, beatIndex, "judged");
  for (let i = 0; i < spent.failed; i++) noteBeatVision(dedup.beatOutcomeAudit, sceneIndex, beatIndex, "unavailable");
}

/**
 * THE GATE'S ANSWER AND THE GATE'S BILL, RECORDED TOGETHER.
 *
 * ── What render 562's ledger said ───────────────────────────────────────────────────────────
 *
 *     TOTAAL  vision_calls=61  vision_evaluated=16
 *
 * Read as written, the gate was asked sixty-one times and produced sixteen answers. It is not what
 * happened. There are four `checkBeatRelevance` sites — the guaranteed ladder, the adopt path, the
 * archive gate and the retrieval funnel — and ALL FOUR reported their spend while only the funnel
 * reported its verdict. Forty-five verdicts existed and were counted by nothing.
 *
 * That is the fifth appearance of one seam: R53's `recordClipAdopt`, R62's still/moving counters,
 * R70's beat audit, R86's failed-asset registration, and now this. Every one was a rule each route
 * had to remember, and in every one most routes did not.
 *
 * ── Why a wrapper rather than three more call sites ─────────────────────────────────────────
 *
 * Adding `noteBeatVisionVerdict` to the other three would fix this render and leave the seam open
 * for the next route. The spend and the verdict come from ONE call and belong to ONE beat, so the
 * call is what records them. A new route cannot report half.
 *
 * The two counters stay separate numbers because they measure different things: a cached verdict
 * costs no call and is still a verdict, and a call that times out costs a call and yields none. It
 * is their being counted by different SETS OF ROUTES that made them incomparable.
 */
/**
 * "THIS CANDIDATE IS WORTH PAYING A JUDGEMENT FOR" — written down, once, wherever that is decided.
 *
 * ── The defect ──────────────────────────────────────────────────────────────────────────────
 *
 * Render 597 refused four pictures the editor had APPROVED:
 *
 *     [AdoptionGuard] scene=2 beat=2 route=beat_fetch eligible=false vision=APPROVED
 *       blocked=FUNNEL_WITHOUT_EVIDENCE
 *       reason=route "beat_fetch" claims REAL_FUNNEL without eligibility
 *       file=scene_2_b2_pool_youtube_cc_ytcc_3k-HbACK31g__…mp4
 *
 * That clip was found, ranked by its thumbnail, downloaded, scored 10.0, judged APPROVED and
 * INGESTED INTO THE ARCHIVE as asset 57782. Its provenance was complete — `lineage=rmuccwkmt-1#40`,
 * provider, providerAssetId, archiveAssetId. It failed on the stamp that says provenance exists.
 *
 * FIVE functions judge a beat's picture:
 *
 *     generateGuaranteedBeatClip        11636
 *     beatClipPassesImageGate           15860
 *     beatClipPassesVisionGate          33469   ← the only one that stamped
 *     pushMotionGraphicBeatClipIfAny    34759
 *     fetchSceneVisualsInner            41192   ← where render 597's clip came through
 *
 * RONDE 94 declared `fetchSceneVisualsInner`'s three insertion points REAL_FUNNEL deliberately,
 * reasoning that "a REAL_FUNNEL claim without eligibility and vision is refused, so an
 * over-generous reading here cannot smuggle anything in". That reasoning was right and the
 * assumption under it was not: it took the eligibility writer to cover these routes. It covered one.
 *
 * ── Why HERE ────────────────────────────────────────────────────────────────────────────────
 *
 * `markEligible`'s own doc names the moment: "immediately before the picture is judged, because
 * that is the real decision every route already makes: this candidate survived its route's
 * deterministic filters and is worth paying a judgement for." `judgeBeatClipRelevance` IS that
 * moment, for all five. One hook rather than five pastes, which is what would be forgotten again.
 *
 * ── What is NOT relaxed ─────────────────────────────────────────────────────────────────────
 *
 * `markEligible` still returns false when the ledger has never seen the file, and still refuses to
 * invent provenance. A clip with no record stays ineligible and says so. The four routes that
 * already had provenance simply stop being refused for never having passed the one desk that
 * stamps it.
 */
function noteEligibleForJudgement(
  dedup: VisualDedupState,
  clipPath: string | undefined,
  route: string,
  sceneIndex: number,
  beatIndex: number
): boolean | undefined {
  if (!clipPath) return undefined;
  const contentKey = clipContentKey(clipPath);
  const recorded = dedup.sourcingCache?.lineage?.markEligible(clipPath, contentKey, route);
  /**
   * `=== false` and not `!recorded`: the ledger is optional, so an absent one yields undefined,
   * and "there was no ledger" is not the same finding as "the ledger had no record for this clip".
   */
  if (recorded === false) {
    console.warn(
      `[EligibilityGap] scene=${sceneIndex} beat=${beatIndex} route=${route} ` +
        `file=${path.basename(clipPath)} contentKey=${contentKey} ` +
        `— the lineage ledger has no record for this clip, so it can never satisfy REAL_FUNNEL`
    );
  }
  return recorded;
}

async function judgeBeatClipRelevance(
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  params: Omit<BeatRelevanceParams, "onSpend">
): Promise<BeatRelevanceDecision> {
  /**
   * THE STAMP, FOR ALL FIVE JUDGES — see `noteEligibleForJudgement`.
   *
   * Before `checkBeatRelevance`, because the decision being recorded is "this is worth judging",
   * and it is being made by the act of calling this function.
   *
   * A PLACEHOLDER IS EXEMPT. The guaranteed ladder's card rungs reach this function with
   * `placeholder: true` so the judge can decline to look at a grey rectangle, and a drawn card
   * must never read as eligible for the category that claims a verified own visual — RONDE 606
   * spent a whole round making cards distinguishable and this would blur it again.
   *
   * `beatClipPassesVisionGate` keeps its own call: it stamps BEFORE the shortlist admission, and
   * that admission can return early without ever reaching this function. Moving the stamp instead
   * of adding one would have narrowed a route while widening four. Same helper, one body, and
   * `markLineageEligible` is idempotent so the second stamp costs nothing.
   */
  if (!params.placeholder) {
    noteEligibleForJudgement(dedup, params.clipPath, "judged", sceneIndex, beatIndex);
  }
  const decision = await checkBeatRelevance({
    ...params,
    onSpend: (spent) => noteVisionSpend(dedup, sceneIndex, beatIndex, spent),
  });
  /**
   * `evaluated === false` is a DECLINE — budget spent, gate off, nothing to judge — and must never
   * read as a picture the gate looked at and disliked. See `BeatRelevanceDecision.evaluated`.
   */
  noteBeatVisionVerdict(
    dedup.beatOutcomeAudit,
    sceneIndex,
    beatIndex,
    decision.evaluated === false
      ? "never_asked"
      : decision.verdict === "fits"
        ? "accepted"
        : decision.verdict === "does_not_fit"
          ? "rejected"
          : "unclear",
    /**
     * WHICH PICTURE, so one candidate cannot count as fifteen.
     *
     * The same identity the relevance ledger uses to carry a verdict across a rename, and the one
     * `providerVisionFunnel` is already unique on. `params.contentKey` when the caller has it —
     * that survives the file being copied or renamed — and the clip path otherwise, which is what
     * the ledger itself keys on.
     */
    params.contentKey || params.clipPath,
    decision.declineCause ?? null
  );
  /**
   * THE FRAMING THE JUDGE JUST SAW, filed where the ranking will look for it.
   *
   * This is the seam this codebase keeps finding: a fact one route establishes and the next does
   * not receive. A model has just had this clip's frames in front of it and named how the shot is
   * framed — and `scoreShotVariety` would still have fallen back to a regex over the download
   * filename, because nothing carried the answer across.
   *
   * Merged into the existing per-clip meta rather than stored separately: `clipAnnotationMeta` is
   * already what `rankCandidatesWithContext` is handed, so there is no second store to keep in
   * step and no route that can read one without the other.
   */
  if ((decision.framing || decision.depicts) && params.clipPath) {
    const existing = dedup.clipAnnotationMeta.get(params.clipPath) ?? {};
    dedup.clipAnnotationMeta.set(params.clipPath, {
      ...existing,
      ...(decision.framing ? { observedShotType: decision.framing } : {}),
      /**
       * The judge's own description of these frames, kept rather than logged and dropped.
       *
       * It is the strongest evidence a non-archive candidate has about its own content, and the
       * 40% annotation weight had nothing better than a provider's reel title to work with. See
       * `observedDepicts` on CandidateMeta.
       */
      ...(decision.depicts ? { observedDepicts: decision.depicts } : {}),
    });
  }
  return decision;
}

/**
 * RONDE 87 — one lineage record per curated archive asset, opened from the row itself.
 *
 * Called from two places that must not each open their own: the scan loop, which needs a record to
 * hang ELIGIBLE/RANKED on before anything is downloaded, and preparePooledArchiveClip, which needs
 * one to hang the download outcome on. Keyed on the asset's own content key — the same
 * deterministic string clipContentKey() produces for a prepared curated clip — so the second
 * caller finds the first caller's record instead of creating a duplicate.
 *
 * The provider comes from the archive row's own `archiveName`. That is the name of the collection
 * the asset was ingested into and read back out of, which is a fact about the row, not a guess
 * about a filename. `own_archive` is used only when the row itself carries no archive name, and is
 * a real answer — this asset came from the customer's own uploaded archive.
 */
export function ensureCuratedAssetLineage(
  dedup: VisualDedupState,
  picked: CuratedCandidatePick,
  sceneIndex: number,
  beatIndex: number
): VisualLineageRecord {
  return ensureCuratedAssetLineageOn(dedup.sourcingCache.lineage, picked, sceneIndex, beatIndex);
}

/**
 * RONDE 170 — the same record, for a caller that holds the ledger rather than the whole render.
 *
 * `downloadFunnelCandidate` is handed a SourcingCache, not a VisualDedupState, so it could not
 * reach the function above — which is a large part of why the funnel's curated branch opened no
 * lineage at all and its clips reported UNVERIFIED. Same body, one fewer thing required of the
 * caller; the wrapper keeps every existing call site unchanged.
 */
/**
 * Moved to `visualSourceLineage`, where the ledger it writes into lives — the replay engine has to
 * call the SAME writer, and could not import this module to reach it. Re-exported so that every
 * existing caller, and the structural tests that look for it here, are unaffected.
 */
export { ensureCuratedAssetLineageOn };

/**
 * RONDE 645 — every curated clip `fetchCuratedArchiveBeatClip` prepares is bound to its asset's
 * lineage record in the active render, exactly as `prepareArchiveBeatClip` above does for the
 * primary route: opened (or found) from the pick, the prepared file bound to it, the download
 * recorded. The adoption that follows then resolves the file to a record with a provider, an
 * archive id and — for an archived YouTube segment — its YouTube origin, instead of opening an
 * anonymous UNVERIFIED one.
 */
setCuratedClipPreparedHook((picked, sceneIndex, beatIndex, clipPath) => {
  const lineage = get_activeSourcingCache()?.lineage;
  if (!lineage) return;
  const record = ensureCuratedAssetLineageOn(lineage, picked, sceneIndex, beatIndex);
  lineage.bindPath(record.lineageId, clipPath, clipContentKey(clipPath));
  lineage.recordEvent(record.lineageId, "DOWNLOAD_SUCCEEDED", { status: "OK", currentPath: clipPath });
});

/** RONDE 649 — see `setCuratedAssetRefusedHook`: this beat's own no, from the active render. */
setCuratedAssetRefusedHook((sceneIndex, beatIndex, assetId) => {
  const cache = get_activeSourcingCache();
  const ledger = cache ? ledgerBySourcingCache.get(cache) : undefined;
  if (!ledger) return null;
  return beatAlreadyRefusedPicture(ledger, sceneIndex, beatIndex, {
    contentKey: curatedAssetContentKey(assetId),
  });
});

/**
 * RONDE 87 — a stable, groupable reason string from a thrown error message.
 *
 * The summary groups failures by reason, and raw ffmpeg/probe messages carry durations and paths
 * that make every failure unique ("source video too short (2.14s)"). This maps the messages the
 * prepare path actually throws onto the fixed vocabulary §F asks for. An unrecognised message is
 * NOT forced into a bucket — it comes back as `other` with nothing invented about its cause.
 */
export function normalizeFailureReason(message: string | undefined): string {
  const m = (message ?? "").toLowerCase();
  if (!m.trim()) return "unspecified";
  /**
   * RONDE 115 — a status the fetcher already decided is kept, not re-derived from its spelling.
   *
   * The seven YouTube download statuses are a closed vocabulary produced by
   * `summariseYoutubeDownloadAttempts`. Passing one through the guesswork below would bucket
   * DOWNLOAD_TIMEOUT under the generic `timeout` alongside every provider's socket timeout, and
   * DOWNLOAD_UNAVAILABLE — which means "no route is configured", an operator action — under
   * `other`. This branch is first so a decided answer is never overwritten by a keyword match.
   */
  if (/^download_[a-z_]+$/.test(m.trim())) return m.trim();
  if (m.includes("source video too short")) return "source_video_too_short";
  if (m.includes("trimmed clip too short")) return "trimmed_clip_too_short";
  if (m.includes("ken burns clip too short")) return "ken_burns_clip_too_short";
  if (m.includes("styled still clip too short")) return "styled_still_too_short";
  if (m.includes("license")) return "license_rejected";
  if (m.includes("timed out") || m.includes("timeout")) return "timeout";
  if (m.includes("enoent") || m.includes("no such file")) return "file_missing";
  if (m.includes("decode") || m.includes("invalid data")) return "decode_error";
  if (m.includes("404") || m.includes("403") || m.includes("fetch") || m.includes("network")) {
    return "download_error";
  }
  return "other";
}

async function pushMotionGraphicBeatClipIfAny(
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  videoTitle: string | undefined,
  dedup: VisualDedupState,
  pushClip: (clipPath: string, holdSec?: number) => boolean | Promise<boolean>,
  holdSec = beat.holdSec
): Promise<boolean> {
  // Text burns onto B-roll per beat — skip standalone text-on-color motion-graphic cards.
  if (facelessSubtitlesEnabled()) return false;
  if (yearsOnlyOnScreen() || !motionGraphicsEnabled()) return false;
  if (dedup.motionGraphicsUsed >= maxMotionGraphicsPerVideo()) return false;

  const mgfxClip = await tryRenderMotionGraphicBeatClip(
    beat.text,
    scene.index,
    beat.index,
    workDir,
    holdSec,
    dedup.motionGraphicsUsed,
    videoTitle,
    FFMPEG_BIN,
    (cmd, ms, label) => withSceneFetchTimeout(() => exec(cmd), ms, label)
  );
  if (!mgfxClip) return false;
  dedup.motionGraphicsUsed++;
  /**
   * RONDE 103 phase 7, second audit — a motion graphic is a card, not a claim about the world.
   *
   * tryRenderMotionGraphicBeatClip draws the beat's OWN text and figures onto a background; there
   * is no footage in it and no subject it could be wrong about, so "does this picture belong
   * under this narration" has no answer to give. It is registered as a placeholder rather than
   * left unregistered, so the compose barrier can tell "deliberately exempt" from "nobody looked".
   */
  await judgeBeatClipRelevance(dedup, scene.index, beat.index, {
    clipPath: mgfxClip,
    contentKey: clipContentKey(mgfxClip),
    ctx: beatVisualContext(beat, scene, videoTitle),
    workDir,
    state: dedup.beatImageGate,
    ledger: dedup.beatRelevance,
    route: "motion_graphic",
    placeholder: true,
  });
  return await withAdoptionIntent("motion_graphic", () => pushClip(mgfxClip, holdSec));
}

async function applyVideoBeatTextOverlay(
  clipPath: string,
  beat: SceneBeat,
  scene: Scene,
  workDir: string,
  holdSec: number,
  fastMode = false,
  /**
   * RONDE 103 phase 17 — carry the relevance decision across the rename.
   *
   * This is the one shared step between "the gate judged this clip" and "the compose barrier
   * checks this clip", and it writes a new file. Content identity carries the decision for
   * anything with real provenance; a clip whose only identity is its size and name (the `file:`
   * family) needs the hand-off written down explicitly, and this is where it happens for every
   * route at once rather than at thirteen call sites.
   */
  relevance?: BeatRelevanceLedger,
  /** RONDE 94 — see `carry` below: the overlay is a derivation, and it must be recorded as one. */
  lineageForOverlay?: VisualSourceLedger
): Promise<string> {
  const carry = (out: string): string => {
    if (relevance) inheritBeatRelevance(relevance, clipPath, out);
    /**
     * RONDE 94 — the rename must not break the provenance chain either.
     *
     * RONDE 103 phase 17 carried the RELEVANCE decision across this rename and left the lineage to
     * the content key, which works for anything with real provenance and silently fails for the
     * `file:` family. `linkDerivedPath` is this ledger's declared mechanism for exactly this step —
     * its own doc names "the text overlay" as a call site it expects — so the derived file is a
     * child of the clip it was burnt from rather than a new identity that happens to look similar.
     * Without it `isEligible(withText)` can answer false for an asset that was eligible one line
     * earlier, which would turn RONDE 94's enforcement into a refusal of the pipeline's own work.
     */
    lineageForOverlay?.linkDerivedPath(out, clipPath, "OVERLAYED", { reason: "faceless_text_overlay" });
    return out;
  };
  if (deferFacelessSubtitlesToCompose() && facelessSubtitlesEnabled()) {
    return clipPath;
  }
  if (!facelessSubtitlesEnabled() || !isVisualOverlayFootageClip(clipPath)) {
    return clipPath;
  }
  if (fastMode && isLicensedStockClip(clipPath)) {
    return clipPath;
  }
  if (await isMostlyBlackClip(clipPath)) {
    console.warn(
      `[Pipeline] Scene ${scene.index} beat ${beat.index}: skip text on dark clip ${path.basename(clipPath)}`
    );
    return clipPath;
  }
  return carry(await burnFacelessTextOnVideoClip(
    clipPath,
    beat.text,
    scene.index,
    beat.index,
    workDir,
    holdSec,
    FFMPEG_BIN,
    (cmd, ms, label) => withSceneFetchTimeout(() => exec(cmd), ms, label)
  ));
}

/**
 * THE CONTRACT LAYER FOR A CURATED CLIP FETCHED OUTSIDE THE RANKED QUEUE.
 *
 * ── What render 570 proved ──────────────────────────────────────────────────────────────────
 *
 *     7x  route=archive  eligible=false  vision=APPROVED  blocked=FUNNEL_WITHOUT_EVIDENCE
 *     [ExportReadiness] BLOCKS no_verified_own_visual   0 of 16 (never_asked=16, own_footage=2)
 *     [ExportReadiness] BLOCKS mostly_unverified_clips  9 of 12 fetched clip(s)
 *
 * `adoptArchiveBeatClip` adopts curated clips on three paths. Its ranked queue opens the asset's
 * lineage the moment the candidate is queued. The other two fetch through
 * `fetchCuratedArchiveBeatClip` — which returns a prepared file path and cannot reach the ledger,
 * since that lives on the render's dedup state — and then push under `{ source: "archive" }`,
 * which is REAL_FUNNEL.
 *
 * So `markEligible` at the vision gate had nothing to resolve, `isEligible` answered false, and
 * seven pictures the editor had APPROVED were refused. The beats fell through to
 * `subject_fallback`, and both of render 570's blocking gates follow from that one gap.
 *
 * ── Why here, and not at the tryClip that failed ─────────────────────────────────────────────
 *
 * Putting `ensureCuratedAssetLineage` in front of one `tryClip` would fix one call site and leave
 * the next fetch free to repeat it — this file's recurring seam, for the seventeenth time. The
 * fetch is where the asset's identity is decided, so this wraps THE FETCH: every caller that
 * obtains a curated clip this way gets its lineage opened, or gets null.
 *
 * It records identity and nothing else. Eligibility is still written in exactly one place, at the
 * vision gate, for every route alike — this only gives that writer something to resolve. A clip
 * that is refused later is refused on the same terms as before.
 */
async function fetchCuratedArchiveBeatClipWithLineage(
  dedup: VisualDedupState,
  sceneIndex: number,
  beatIndex: number,
  fetch: (pickedOut: { assetId?: number; storageUrl?: string; pick?: CuratedCandidatePick }) => Promise<string | null>
): Promise<string | null> {
  /**
   * TIER 2, RECORDED HERE BECAUSE IT PASSES NO SEARCH GATE.
   *
   * The own archive is a database query, not a provider search, so it never reaches
   * `searchGateDecision` — which is where every external tier marks itself attempted. Without this
   * line tier 2 would read NOT_REACHED on every beat and tier 3 would be refused for skipping it,
   * which is the failure mode of enforcing an order through one door and forgetting a route that
   * uses another.
   *
   * Recorded on entry rather than on success: attempting a tier is what the ladder asks about, and
   * an archive that held nothing for this beat has still been asked.
   */
  noteTierAttempted("OWN_ARCHIVE", "curated");
  const pickedOut: { assetId?: number; storageUrl?: string; pick?: CuratedCandidatePick } = {};
  const clip = await fetch(pickedOut);
  if (!clip) return clip;
  /**
   * The replay bundle's fetch fact. Recorded HERE because this is the one place that holds both
   * the resulting clip and the pick behind it — the two halves a ledger record needs. A bundle
   * records what the fetch FOUND, never what the render then decided about it.
   */
  if (replayRecordingActive()) {
    recordReplayFact({
      kind: "fetch",
      scene: sceneIndex,
      beat: beatIndex,
      route: "curated_fetch",
      file: path.basename(clip),
      contentKey: clipContentKey(clip) || null,
      pick: pickedOut.pick
        ? {
            assetId: pickedOut.pick.asset.id,
            archiveName: pickedOut.pick.archiveName,
            mediaType: pickedOut.pick.asset.mediaType ?? undefined,
            durationSec: pickedOut.pick.asset.durationSec ?? undefined,
            score: pickedOut.pick.score,
          }
        : null,
    });
  }
  if (pickedOut.pick) {
    /** The same writer the ranked queue uses — one definition of what a curated record is. */
    ensureCuratedAssetLineage(dedup, pickedOut.pick, sceneIndex, beatIndex);
  } else {
    /**
     * A clip with no pick behind it. Nothing is invented — the honest outcome is that this asset
     * has no provenance and REAL_FUNNEL will refuse it — but the render says so by name instead of
     * leaving another anonymous `eligible=false` to be traced across four renders.
     */
    console.warn(
      `[EligibilityGap] scene=${sceneIndex} beat=${beatIndex} route=curated_fetch ` +
        `file=${path.basename(clip)} — the fetch returned a clip with no pick, so no lineage ` +
        `record could be opened and this clip can never satisfy REAL_FUNNEL`
    );
  }
  return clip;
}

/** What the two stock bounds cost this render. Printed unconditionally, zero included. */
export function formatStockLadderBounds(state: {
  stockLadderStandAsides: number;
  stockQueryRepeatsSkipped: number;
  stockLadderRunsByBeat: ReadonlyMap<string, number>;
}): string {
  const beats = state.stockLadderRunsByBeat.size;
  return (
    `[StockLadder] beatsAsked=${beats} repeatRunsRefused=${state.stockLadderStandAsides} ` +
    `repeatQueriesSkipped=${state.stockQueryRepeatsSkipped} — a beat's words do not change between ` +
    `routes, so the same question is asked once`
  );
}

/**
 * WHICH SOURCES MAY ENTER THE CURATED ARCHIVE — one predicate, because there are now two readers.
 *
 * RONDE 9 (render 519 + the admin screenshot) barred Pexels and Pixabay: a generic stock clip that
 * happened to win a Hitler beat was ingested tagged "adolf hitler", and then outranked real
 * archival footage on every later Hitler render. That is the self-poisoning loop, and this round
 * does not touch it. `archive` is excluded for the opposite reason — those assets are already in
 * the archive, so storing them again would be a copy of ourselves.
 *
 * It was an inline expression that only the funnel could read. The scene-pool route needed the
 * same rule and had no way to ask for it, which is how the two routes came to disagree about
 * whether a downloaded clip gets stored at all.
 */
/** RONDE 647 — stock libraries: stored for the film, in the Stockbeelden archive only. */
export function isStockProvider(source: string): boolean {
  const s = source.trim().toLowerCase();
  return s === "pexels" || s === "pixabay";
}

export function sourceMayEnterCuratedArchive(source: string): boolean {
  const s = source.trim().toLowerCase();
  return s !== "pexels" && s !== "pixabay" && s !== "archive";
}

/**
 * The candidate facts the archive needs, in the shape BOTH routes can produce.
 *
 * The funnel holds a `FunnelCandidate` wrapping a `PoolCandidate`; the scene-pool route holds the
 * `PoolCandidate` itself. Rather than teach the archive about two candidate types, each route
 * hands over this — the fields that were already being read, named once.
 */
export type ExternalClipArchiveFacts = {
  source: string;
  providerAssetId: string | null;
  title: string;
  mediaType: "video" | "image";
  license?: string | null;
  licenseUrl?: string | null;
  durationSec?: number | null;
  sourceCreator?: string | null;
  remoteUrl?: string | null;
};

/**
 * The provenance both archive routes send, built from ONE literal.
 *
 * This is RONDE 9's metadata, lifted out of the funnel branch unchanged — every field below is the
 * one that was there, with its reasoning. It moved because a second route now needs it, and two
 * copies of this literal is two chances for the same clip to be archived under different
 * provenance depending on which route happened to win the beat.
 */
export function archiveMetadataForExternalClip(
  c: ExternalClipArchiveFacts,
  opts: { beatQuery: string; personContext: boolean; topics: string[] }
): ProductionArchiveMetadata {
  return {
    title: c.title,
    // RONDE 9: NEVER the narration keywords — those describe what is SAID, not what is SHOWN, and
    // they poisoned the archive. Content-true tags come from Rekognition inside
    // ingestExternalClipToArchive; the provider's own title above stays the searchable text.
    tags: [],
    // RONDE 9b: Rekognition person-tagging runs ONLY for person-locked renders.
    personContext: opts.personContext,
    sourceNote: `${c.source}:${c.providerAssetId ?? "unknown"}`,
    mediaType: c.mediaType,
    mimeType: c.mediaType === "video" ? "video/mp4" : "image/jpeg",
    durationSec: c.durationSec ?? undefined,
    // FASE 1: prefer the provider's own per-asset licence label over the generic per-source
    // literal, which is only a fallback for sources that do not expose one.
    licenseNote:
      c.license ??
      (c.source === "pexels" ? "Pexels license" :
       c.source === "pixabay" ? "Pixabay license" :
       c.source === "wikimedia" ? "CC BY-SA / CC0" :
       c.source === "internet_archive" ? "Internet Archive — see licenseUrl" :
       c.source === "europeana" ? "Europeana — see licenseUrl" :
       c.source === "openverse" ? "Openverse — see licenseUrl" :
       c.source === "nasa" ? "Public Domain (NASA / U.S. Government Work)" :
       c.source === "nara" ? "Public Domain (NARA / U.S. Government Work)" :
       c.source === "loc" ? "Library of Congress — see licenseUrl" : undefined),
    sourceUrl: c.remoteUrl ?? undefined,
    sourcePlatform: c.source,
    sourceCreator: c.sourceCreator ?? undefined,
    licenseUrl: c.licenseUrl ?? undefined,
    originalQuery: opts.beatQuery,
    // RONDE 28: the query that found it, never the asset's title. Search memory stores this as
    // "the query that worked", and a title is not a query.
    matchedQuery: opts.beatQuery,
    topics: opts.topics,
  };
}

/**
 * THE ARCHIVE-FIRST INVARIANT, AT BOTH ENDS OF THE BEAT.
 *
 * ── What the audit proved ───────────────────────────────────────────────────────────────────
 *
 * `storeForProduction` is the only function that turns a downloaded external clip into an
 * `archiveAssetId` attached to THIS render's lineage, and it had exactly one call site, behind
 * `winningExternalCandidate` — which is set only for a funnel winner. The scene-pool route
 * adopts through `recordClipAdopt` → `recordUse` → `formatSelection` and asked for no handle at
 * all, so every clip it won reached the timeline carrying a provider id and nothing of ours.
 *
 * `assetRehydrator` tries `archiveAssetId` first and falls through to the provider without one.
 * For YouTube — which lives in the scene pool since RONDE 175 — that means a later re-render has
 * to reach YouTube again, and YouTube is measurably blocked at intervals.
 *
 * ── Why this is one function and not two ────────────────────────────────────────────────────
 *
 * The brief's requirement is that the funnel winner, the pool winner and any other clip entering
 * the current timeline share ONE persistence semantic. Two call sites of `storeForProduction`
 * with hand-written wrappers would be two semantics again by the next round. This is the wrapper,
 * written once: store the file that is already on disk, and attach the handle to the ledger.
 *
 * ── What it deliberately does NOT do ────────────────────────────────────────────────────────
 *
 * It does not download. `storeForProduction` takes `localPath`, so the bytes the beat already
 * fetched are the bytes that are stored — no second provider call.
 *
 * It does not re-archive. `storeForProduction` already answers that itself: it reports
 * `reused: true` with `reusedBy: "checksum" | "provider_asset_id"`, and both lookups require
 * `mediaStatus = READY`, so a half-written earlier attempt is not mistaken for a hit.
 *
 * It does not fail the render. A storage outage costs the render its archive handle and nothing
 * else — the beat keeps the provider identity it already had, exactly as the funnel has behaved
 * since the handle was first carried. What it must never do is fail SILENTLY, so the failure is
 * named with its own code at the moment it happens.
 */
async function storeExternalClipForTimeline(params: {
  clipPath: string;
  facts: ExternalClipArchiveFacts;
  metadata: ProductionArchiveMetadata;
  lineage: VisualSourceLedger | undefined;
  workDir: string;
  sceneIndex: number;
  beatIndex: number;
  /**
   * Which route won the beat, so the log says where a missing handle came from.
   *
   * `push_gate` is the universal backstop in `beatClipRefusedByRelevanceGate`: the other four are
   * eager stores that run earlier and carry their route's own richer provenance, and the gate is
   * what makes it impossible for a route to skip the step altogether.
   */
  route: "funnel" | "pool" | "rescue" | "push_gate";
}): Promise<ProductionArchiveOutcome> {
  const { clipPath, facts, sceneIndex, beatIndex, route } = params;
  const stored = await storeForProduction({
    localPath: clipPath,
    provider: facts.source,
    providerAssetId: facts.providerAssetId,
    metadata: params.metadata,
    deps: productionArchiveDeps({
      /**
       * The pipeline's own downloader, so its timeout, its process-wide byte budget and its
       * logging apply to the read-back unchanged — §16's "no second downloader".
       */
      download: async (url, dest) => {
        await downloadToFileStreaming(url, dest, 120_000, "productionArchive:readBack");
        return fs.existsSync(dest) && fs.statSync(dest).size > 0;
      },
    }),
    ctx: {
      projectId: getActiveVideoId() ?? null,
      sceneIndex,
      beatIndex,
      provider: facts.source,
      providerAssetId: facts.providerAssetId,
    },
    verifyDir: params.workDir,
    expectVideo: facts.mediaType === "video",
  }).catch((err): ProductionArchiveOutcome => ({
    status: "failed",
    code: "ARCHIVE_RECORD_FAILED",
    message: (err as Error).message.slice(0, 200),
    mediaStatus: "FAILED",
  }));

  /**
   * THE HANDLE, CARRIED. This is the line the whole invariant is about.
   *
   * Without it the id is computed and discarded, and the only difference would be a prettier log.
   * `attachArchiveAsset` fills and never overwrites, so a clip that already had a handle keeps
   * the one it had.
   */
  if (stored.status === "stored") {
    const attached = params.lineage?.attachArchiveAssetToPath(
      clipPath, stored.archiveAssetId, clipContentKey(clipPath)
    );
    if (!attached) {
      console.warn(
        `[ProductionArchive] s${sceneIndex}b${beatIndex} ARCHIVE_ASSET_UNATTACHED route=${route} ` +
          `archiveAssetId=${stored.archiveAssetId} file=${path.basename(clipPath)} — ` +
          `the bytes are stored and READY, but the lineage ledger has no record for this path, ` +
          `so the timeline cannot be told about it`
      );
    }
  } else {
    /**
     * A failed store means two different things depending on where it happened, and saying the
     * wrong one is how a log stops being evidence.
     *
     * On the four EAGER routes the clip may still be adopted — they run before the push, and the
     * push gate will try again and decide. On the PUSH GATE itself there is no second chance: that
     * is the boundary, and a clip that cannot be read back from our own storage does not enter the
     * film. Neither may be silent.
     */
    console.warn(
      route === "push_gate"
        ? `[ProductionArchive] s${sceneIndex}b${beatIndex} ARCHIVE_NOT_READY_AT_PUSH ` +
            `provider=${facts.source} providerAssetId=${facts.providerAssetId ?? "none"} ` +
            `code=${stored.code} status=${stored.mediaStatus} reason="${stored.message}" — this ` +
            `clip is refused; it cannot be read back from our own storage`
        : `[ProductionArchive] s${sceneIndex}b${beatIndex} ARCHIVE_STORE_FAILED_BEFORE_PUSH ` +
            `route=${route} provider=${facts.source} providerAssetId=${facts.providerAssetId ?? "none"} ` +
            `code=${stored.code} status=${stored.mediaStatus} reason="${stored.message}" — the push ` +
            `gate will decide whether this clip may still be used`
    );
  }
  return stored;
}

// Thin wrapper so fetchSceneVisualsInner's own heartbeat entry always gets cleared on the way
// out — success, thrown error, or cancellation — instead of lingering under whichever scene
// happened to set it last (see the heartbeat tracking comment above setWorkerHeartbeat).
async function fetchSceneVisuals(
  scene: Scene,
  workDir: string,
  videoTitle: string | undefined,
  dedup: VisualDedupState,
  onBeatProgress?: (beatIndex: number, beatTotal: number, phase?: BeatProgressPhase) => void,
  sceneAudioPath?: string,
  prefetchPools?: Map<number, Promise<import("./scenePool").SceneCandidatePool>>,
  prefetchFunnels?: Map<number, Promise<RetrievalFunnelResult>>
): Promise<SceneVisualsResult> {
  const heartbeatLabel = `fetchSceneVisuals s${scene.index}`;
  setWorkerHeartbeat(heartbeatLabel);
  try {
    return await fetchSceneVisualsInner(
      scene, workDir, videoTitle, dedup, onBeatProgress, sceneAudioPath, prefetchPools, prefetchFunnels
    );
  } finally {
    clearWorkerHeartbeat(heartbeatLabel);
  }
}

async function fetchSceneVisualsInner(
  scene: Scene,
  workDir: string,
  videoTitle: string | undefined,
  dedup: VisualDedupState,
  onBeatProgress?: (beatIndex: number, beatTotal: number, phase?: BeatProgressPhase) => void,
  sceneAudioPath?: string,
  prefetchPools?: Map<number, Promise<import("./scenePool").SceneCandidatePool>>,
  prefetchFunnels?: Map<number, Promise<RetrievalFunnelResult>>
): Promise<SceneVisualsResult> {
  videoTitle = coerceVisionString(videoTitle);
  

  const clipFetchDur = 4;
  const scenePersons = resolveScenePersons(scene, videoTitle, dedup.primaryPerson || undefined);
  const historicalDoc = isHistoricalDocumentary(videoTitle, scene.text) && !dedup.personTopicLock;
  const personName = historicalDoc
    ? ""
    : (scenePersons[0] ?? dedup.primaryPerson ?? extractPrimaryPersonFromTitle(videoTitle) ?? "");
  const spaceTopic = isSpaceRelatedTopic(scene.visualCue, scene.pexelsQuery, scene.text, videoTitle ?? "");
  const beatCap = dedup.perf.fastStockMode
      ? sceneBeatCapForCadence(scene.duration, dedup.perf.maxBeatsPerScene)
      : Math.min(
          dedup.perf.maxBeatsPerScene,
          Math.max(2, Math.ceil(scene.duration / effectiveBeatSec()))
        );
  dedup.stillPhotosThisScene = 0;
  // Asset Director: rotate scene clip buffers + build editorial memory for next scene
  if (assetDirectorEnabled()) {
    // Build style memory from the clips we just adopted so the next scene can inherit style
    if (dedup.assetDirectorSceneClips.length > 0) {
      dedup.editorialMemory = buildSceneStyleMemory(
        dedup.assetDirectorSceneClips, dedup.clipAnnotationMeta
      );
    }
    dedup.assetDirectorPrevSceneClips = dedup.assetDirectorSceneClips;
    dedup.assetDirectorSceneClips = [];
    // Taste Model: reset per-scene shot/emotion history at scene boundary
    resetTasteModelScene(dedup.tasteModelCtx);
    // Extract era hint from scene text (e.g. "1944", "19th century")
    const eraMatch = scene.text?.match(/\b(1[0-9]{3}|20[0-2][0-9]|[0-9]{2}(st|nd|rd|th) century)\b/i);
    dedup.assetDirectorActiveEra = eraMatch?.[0] ?? null;
    // Extract location hint (capitalize words that might be place names)
    const locMatch = scene.text?.match(/\b(?:in|at|near|over|across|through) ([A-Z][a-z]+(?: [A-Z][a-z]+)?)\b/);
    dedup.assetDirectorActiveLocation = locMatch?.[1] ?? null;
    // Primary entity: reuse activeEntity across scenes unless overridden by primaryPerson
    if (dedup.primaryPerson) dedup.assetDirectorActiveEntity = dedup.primaryPerson;
  }
  const realOnly = realFootageFirstEnabled();
  dedup.stillPhotosMaxThisScene = historicalDoc && dedup.perf.fastStockMode
    ? beatCap
    : realOnly
      ? (historicalDoc ? beatCap : 1)
      : historicalDoc
        ? beatCap
        : dedup.perf.fastStockMode
          ? 2
          : maxStillPhotosForScene(scene.index, scenePersons.length > 0, dedup.personTopicLock);
  const beats = resolveSceneBeats(scene, scene.duration, beatCap, videoTitle, scenePersons, dedup);
  await applyVoiceAlignmentToBeats(beats, sceneAudioPath, scene.duration, dedup, scene.index);
  const clips: string[] = [];
  const beatDurations: number[] = [];
  const archiveBeatFilled = new Set<number>();

  // ── Editorial Sequence Planner: enrich beats with shot-level visual descriptions ──
  if (editorialSequencePlannerEnabled() && beats.length > 0) {
    try {
      const vctx = dedup.videoVisualContext ?? { people: [], period: "", locations: [], visualStyles: [] };
      await getOrGenerateStoryboard(
        scene.index,
        scene.text,
        beats.map((b) => ({ index: b.index, text: b.text })),
        videoTitle ?? "",
        vctx
      );
      for (const beat of beats) {
        const shot = getShotForBeat(scene.index, beat.index);
        if (!shot) continue;
        const enriched = enrichBeatFromShot(beat.text, [beat.searchQuery], shot);
        if (enriched.pexelsQueries[0] && enriched.pexelsQueries[0] !== beat.searchQuery) {
          beat.searchQuery = enriched.pexelsQueries[0];
          beat.powerWord = enriched.pexelsQueries[0];
        }
        if (!beat.visualDescription && enriched.visualDescription) {
          beat.visualDescription = enriched.visualDescription;
        }
      }
    } catch (err) {
      console.warn(`[Editorial] s${scene.index} enrichment skipped:`, (err as Error).message?.slice(0, 80));
    }
  }

  console.log(
    `[Pipeline] Scene ${scene.index}: ${beats.length} zin-beats (~${effectiveBeatSec()}s) — ` +
    `power words: [${beats.map((b) => b.powerWord).join(", ")}]` +
    ("")
  );

  // ── P1 + P4 + Funnel: Scene-level candidate pool ───────────────────────────
  // When ENABLE_RETRIEVAL_FUNNEL=true: use hybrid archive+internet funnel.
  // Otherwise P1/P4: external-only pool (archive searched separately per beat).
  // P4: prefetch promises are already resolved by the time we get here.
  // Falls back to normal per-beat retrieval on any error or when flags are off.
  let scenePool: import("./scenePool").SceneCandidatePool | null = null;
  let funnelResult: RetrievalFunnelResult | null = null;

  if (sceneCandidatePoolEnabled()) {
    try {
      const poolT0 = Date.now();
      if (retrievalFunnelEnabled()) {
        // Funnel path: archive + internet in parallel, coverage-weighted
        const prefetchFunnel = prefetchFunnels?.get(scene.index);
        // Delivery deadline only — see funnelAwaitTimeoutMs(). Defaults to the 60_000 this
        // await has always used; FASTVID_FUNNEL_TIMEOUT_MS raises it for a controlled run.
        const funnelTimeoutMs = funnelAwaitTimeoutMs();
        const funnelAwaitT0 = Date.now();
        console.log(`[FunnelTimeout] scene=${scene.index} timeoutMs=${funnelTimeoutMs}`);
        /**
         * RONDE 241 — THE STAGES THAT SPEND THE RENDER ARE MEASURED, NOT JUST THE CHEAP ONES.
         *
         * `[Budget]` proved retrieval runs 10x over its allowance in every one of 39 measured
         * renders. `[Step]` could not say what inside it: the only instrumented steps were the
         * provider searches, and those all read 0ms because they come from cache. RONDE 237 made
         * the report legible; it reported 1.7 seconds of an hour because 1.7 seconds was all
         * anybody had ever measured.
         *
         * These three are the retrieval phase, in the order it runs: finding candidates, fetching
         * them, judging them. `dedup.stepTiming` is the recorder the render already threads
         * everywhere, so nothing new is plumbed — the meter existed, it was simply not attached to
         * anything that takes time. `funnelAwaitT0` is the stamp this block already took two lines
         * above for its own timeout arithmetic — measured once, read twice, so the number in the
         * report and the number the timeout uses can never drift apart.
         */
        console.log(`[Hang] BEFORE funnel await s${scene.index} prefetch=${!!prefetchFunnel}`);
        // P1-B: anchor era-less stock phrasing to the year/person/location the script states.
        const inlineFunnelQueries = anchorQueriesToHistoricalContext({
          primaryQuery: scene.pexelsQuery || scene.visualCue || scene.text.slice(0, 80),
          extraQueries: await primeQueriesWithSearchMemory(videoTitle, scene.pexelsQueries?.slice(0, 2)),
          sceneText: scene.text,
          videoTitle,
          primaryPerson: dedup.primaryPerson || personName,
        });
        if (inlineFunnelQueries.anchored) {
          console.log(
            `[HistoricalAnchor] scene=${scene.index} primary="${inlineFunnelQueries.primaryQuery}" ` +
            `year=${inlineFunnelQueries.year || "n/a"} extras=${inlineFunnelQueries.extraQueries.length}`
          );
        }
        funnelResult = prefetchFunnel
          ? await withTimeout(prefetchFunnel, funnelTimeoutMs, `prefetchFunnel s${scene.index}`)
          : await withTimeout(runSceneVisualDiscovery(
              { renderId: String(getActiveVideoId() ?? "-"), sceneIndex: scene.index },
              () => buildRetrievalFunnel({
              sceneIndex: scene.index,
              sceneText: scene.text,
              primaryQuery: inlineFunnelQueries.primaryQuery,
              extraQueries: inlineFunnelQueries.extraQueries,
              /**
               * RONDE 603 — the two providers this funnel never asked. Render 597 logged
               * `archive=not_wired … youtube_cc=no_search_function_supplied` once per scene,
               * because this route is `buildSceneCandidatePool`'s third caller and the only one
               * that supplied neither. The same functions the direct pool call site below uses.
               */
              youtubeSearch: scenePoolYoutubeSearch(dedup.sourcingCache),
              archiveSearch: scenePoolArchiveSearch(
                scene.text,
                dedup,
                inlineFunnelQueries.primaryQuery ? [inlineFunnelQueries.primaryQuery] : [],
                [dedup.primaryPerson || personName].filter(Boolean)
              ),
              pexelsApiKey: PEXELS_API_KEY || undefined,
              pixabayApiKey: process.env.PIXABAY_API_KEY || undefined,
              europeanaApiKey: europeanaSourcingEnabled() ? (EUROPEANA_API_KEY || undefined) : undefined,
              naraApiKey: NARA_API_KEY || undefined,
              skipOpenverse: !openverseStillsEnabled(),
              videoTitle: videoTitle || undefined,
              // Hold back archive assets used in recent same-topic videos so a filled
              // archive keeps looking for fresh footage instead of shipping the same clips.
              crossVideoExcludeIds: dedup.crossVideoExcludeIds,
              // RONDE 29: how far this render is running below its moving-footage target.
              // 0 (neutral) for the first few clips and whenever the target is already met.
              movingShareDeficit: movingShareDeficit(
                dedup.movingClipCount,
                dedup.movingClipCount + dedup.stillClipCount
              ),
              // RONDE 131: the persistent cross-video memory, read under the SAME key it is
              // written under at the adopt point below — get_activeVideoTopic()'s person, or the
              // title when the video is not about a person. Write and read must agree or the
              // memory is invisible to itself, which is how RONDE 28 found it last time.
              /**
               * RONDE 175 §2 — what this passage is about, for period/place/subject ranking.
               *
               * SCENE-level, because that is the scope this funnel runs at: it builds one
               * candidate pool per scene, so the years come from the scene's narration rather than
               * from one beat's sentence. That is also the honest scope — a scene about 1926 makes
               * a 1945 reel a worse candidate for any of its beats.
               *
               * Read off text the script actually contains and context the pipeline established,
               * never invented. A candidate saying nothing about its period is unaffected, so the
               * catalogue-numbered archive titles this pipeline lives on score exactly as before.
               */
              beatTemporalContext: {
                years: yearsIn(scene.text).map(String),
                places: get_activeVideoVisualContext()?.locations?.slice(0, 3),
                subjects: [activeMemoryEntity(), ...(scene.personNames ?? [])].filter(
                  (x): x is string => Boolean(x)
                ),
              },
              memoryEntity: activeMemoryEntity(),
              memoryExcludeAssetIds: dedup.usedCuratedAssetIds,
              memoryMetrics: dedup.searchMemoryMetrics,
              memoryRecalledInto: dedup.recalledAssetIds,
              // RONDE 132 §11: the scene index rotates which equally-proven memory asset comes
              // first, so a subject with a deep memory does not put its single most-used clip in
              // every video.
              memoryVarietySeed: scene.index + 1,
              onMemoryAssetExcluded: (m) => {
                noteDuplicateAttempt(dedup.visualDedupStats, "archive_asset_id");
                console.log(
                  formatVisualDedupReject({
                    // Readable from any module in this render — what runWithActiveVideoId exists for.
                    videoId: getActiveVideoId() ?? null,
                    beat: `s${scene.index}`,
                    asset: `curated:asset:${m.assetId}`,
                    matchedOn: "archive_asset_id",
                  })
                );
              },
            })
            ), funnelTimeoutMs, `buildRetrievalFunnel s${scene.index}`);
        console.log(
          `[FunnelTimeout] scene=${scene.index} completed elapsedMs=${Date.now() - funnelAwaitT0} ` +
          `timeoutMs=${funnelTimeoutMs}`
        );
        console.log(`[Hang] AFTER funnel await s${scene.index} candidates=${funnelResult?.candidates?.length ?? 0}`);
        recordPipelineTiming(
          dedup.stepTiming, "image_search", "Funnel candidate pool", Date.now() - funnelAwaitT0, scene.index
        );
        const waited = Date.now() - poolT0;
        console.log(
          `[Funnel] Scene ${scene.index}: ${funnelResult.candidates.length} candidates ` +
          `(coverage=${funnelResult.archiveCoverage.toFixed(2)}, strategy=${funnelResult.strategy}) ` +
          `${prefetchFunnel ? `prefetch waited ${waited}ms` : `inline ${waited}ms`}`
        );
        // F3-27: fire the (best-effort) genuine-shortage warning once the real archive+web
        // tally for this scene is known — never a false positive from a pre-web snapshot.
        reportFunnelCoverageIfInsufficient(getActiveVideoId(), videoTitle, funnelResult);
      } else {
        // P1/P4 path: external-only pool
        const prefetchPromise = prefetchPools?.get(scene.index);
        console.log(`[Hang] BEFORE pool await s${scene.index} prefetch=${!!prefetchPromise}`);
        // P1-B: same historical anchoring as the funnel path above.
        const inlinePoolQueries = anchorQueriesToHistoricalContext({
          primaryQuery: scene.pexelsQuery || scene.visualCue || scene.text.slice(0, 80),
          extraQueries: scene.pexelsQueries?.slice(0, 2),
          sceneText: scene.text,
          videoTitle,
          primaryPerson: dedup.primaryPerson || personName,
        });
        scenePool = prefetchPromise
          ? await withTimeout(prefetchPromise, 60_000, `prefetchPool s${scene.index}`)
          : await withTimeout(runSceneVisualDiscovery(
              { renderId: String(getActiveVideoId() ?? "-"), sceneIndex: scene.index },
              () => buildSceneCandidatePool({
              sceneIndex: scene.index,
              sceneText: scene.text,
              primaryQuery: inlinePoolQueries.primaryQuery,
              extraQueries: inlinePoolQueries.extraQueries,
              pexelsApiKey: PEXELS_API_KEY || undefined,
              pixabayApiKey: process.env.PIXABAY_API_KEY || undefined,
              /** RONDE 177 — YouTube joins the pool here, through the existing search client. */
              youtubeSearch: scenePoolYoutubeSearch(dedup.sourcingCache),
              /**
               * RONDE 245 — and the operator's own archive, through the existing selection.
               *
               * The scene's own anchors are what the archive is asked about, the same text every
               * other provider in this pool is given. See `scenePoolArchiveSearch` for why this
               * calls `listCuratedArchiveCandidates` rather than re-deriving a match.
               */
              archiveSearch: scenePoolArchiveSearch(
                scene.text,
                dedup,
                inlinePoolQueries.primaryQuery ? [inlinePoolQueries.primaryQuery] : [],
                [dedup.primaryPerson || personName].filter(Boolean)
              ),
              /**
               * RONDE 246 — what "enough" means for THIS scene, so the tiered run can stop before
               * the slow tail. Without it every tier is asked, which is the old cost minus the
               * parallelism — so this is not an optimisation detail, it is the thing that pays for
               * tiering at all.
               */
              beatCount: beats.length,
              /**
               * P0-8 — WHAT THIS SCENE NEEDS, so the tier table answers for this scene.
               *
               * The union of the needs of the sentences in it, from the same registry and the same
               * intents the ranking already reads one layer down. Without it every provider keeps
               * the tier a constant gave it, and a scene satisfied by tier 1 never asks the archives
               * on a beat dated to 1945. See `tierTasksByNeed` — it reorders, never removes.
               */
              mediaFormNeed: mediaFormsForScene(
                beats.map((b) => beatVisualIntent(dedup.beatIntent, scene.index, b.index))
              ),
            })
            ), 60_000, `buildSceneCandidatePool s${scene.index}`);
        console.log(`[Hang] AFTER pool await s${scene.index} candidates=${scenePool?.candidates?.length ?? 0}`);
        const waited = Date.now() - poolT0;
        console.log(
          `[Pool] Scene ${scene.index}: pool ready (${prefetchPromise ? `prefetch, waited ${waited}ms` : `inline ${waited}ms`}) — ` +
          `${scenePool.candidates.length} candidates, cache=${scenePool.metrics.cacheHit}`
        );
      }
    } catch (err) {
      console.warn(`[Pool/Funnel] Scene ${scene.index}: unavailable, falling back to per-beat retrieval:`, (err as Error).message?.slice(0, 80));
      scenePool = null;
      funnelResult = null;
    }
  }
  // ───────────────────────────────────────────────────────────────────────────

  const muskTopic = isMuskTeslaTopic(videoTitle, scene.text);
  const beatAdoptOpts: VisualAdoptOptions = {
    muskTopic,
    personTopic: dedup.personTopicLock,
    primaryPerson: dedup.primaryPerson || personName,
    keywords: [],
    sceneText: scene.text,
    videoTitle,
    requireBeatMatch: false,
    scriptAnchored: dedup.perf.fastStockMode ? false : dedup.perf.scriptOnlyVisuals,
  };

  const pushSceneClip = async (clipPath: string, holdSec: number, beatIndex: number): Promise<boolean> => {
    if (await beatClipRefusedByRelevanceGate(dedup, clipPath, scene.index, beatIndex)) return false;
    if (await adoptionGuardRefusesPush(dedup, clipPath, scene.index, beatIndex)) return false;
    const key = clipContentKey(clipPath);
    if (dedup.usedContentKeys.has(key)) {
      console.warn(
        `[Pipeline] Scene ${scene.index} beat ${beatIndex}: skipping duplicate clip ${path.basename(clipPath)} (once per video)`
      );
      noteDuplicateClipRefused(dedup, clipPath, key, scene.index, beatIndex);
      return false;
    }
    let actualHold = holdSec;
    if (fs.existsSync(clipPath)) {
      const probed = await probeVideoDurationSec(clipPath);
      if (probed > 0.15) {
        actualHold = Math.min(holdSec, probed - 0.04);
      }
    }
    dedup.usedContentKeys.add(key);
    clips.push(clipPath);
    beatDurations.push(actualHold);
    markCuratedAssetUsed(clipPath, dedup.usedCuratedAssetIds, dedup.usedCuratedStorageUrls, curatedStorageUrlForClip(clipPath, dedup));
    
    if (
      clipPath && !isPipelineFallbackClip(clipPath) && !isStillPhotoClip(clipPath) &&
      fs.existsSync(clipPath)
    ) {
      dedup.lastMuskStockClip = clipPath; dedup.lastRealClip = clipPath;
      // RONDE 142: a real clip was adopted, so the extension run is over — the picture changed.
      resetExtendHold(dedup.extendHold);
    }
    return true;
  };

  /**
   * ONE LADDER PER BEAT, AROUND THE WHOLE BEAT.
   *
   * ── What the integrity audit found ──────────────────────────────────────────────────────────
   *
   * The ladder used to be opened by `resolveBeatClip`. That reads like the beat's entry point and
   * is not: it is this loop's THIRD route to a picture. The funnel resolves a beat above it, the
   * scene pool resolves a beat above that, and both ran with no ladder at all — which the gate
   * treated as "always admitted". A Pexels clip could become a beat's picture with tiers 1, 2 and
   * 3 reading NOT_REACHED, and the render log would not have said so. The stock fallbacks after
   * the cascade sat outside it too.
   *
   * So the ladder moves up to the beat itself. Everything below is now inside one scope: the
   * funnel's winner, the pool's candidates, the cascade, every rescue, every last-resort fetch.
   * `runCentralVisualSourcing` inside `resolveBeatClip` re-enters this same ladder instead of
   * starting a second one.
   *
   * ── Why a closer rather than a callback ─────────────────────────────────────────────────────
   *
   * This body is seventeen hundred lines of branches, `continue`s and early exits. Wrapping it in
   * a callback would be the large rewrite this round is told not to do, and would change control
   * flow that has nothing to do with sourcing. The closer is called at the TOP of the next
   * iteration and once after the loop, so a `continue` — of which there are several — closes the
   * previous beat's ladder rather than leaking it into the next one.
   */
  {
    startSceneYoutubeLookahead(scene, beats, workDir, clipFetchDur, videoTitle, personName, dedup);
  }
  const renderIdForLadder = String(getActiveVideoId() ?? "-");
  let closeBeatLadder: (() => void) | null = null;
  try {
  for (let bi = 0; bi < beats.length; bi++) {
    const beat = beats[bi];
    closeBeatLadder?.();
    /**
     * The scene's own discovery is carried IN, not re-derived. The funnel and the pool really did
     * query these tiers for this scene, through this same gate; a beat that started from a blank
     * ladder would report NOT_REACHED for a tier the log can show being asked, and would make the
     * cascade re-ask it to earn a permission the render had already paid for.
     */
    const sceneSeed = sceneDiscoverySeed(renderIdForLadder, scene.index);
    closeBeatLadder = beginBeatSourcing({
      renderId: renderIdForLadder,
      sceneIndex: scene.index,
      beatIndex: beat.index,
      declined: [...beatSourcingDeclines(dedup), ...(sceneSeed?.declined ?? [])],
      seedAttempted: sceneSeed?.attempted,
    });
    beatAdoptOpts.keywords = beat.keywords;
    onBeatProgress?.(bi, beats.length, "beat");
    const pushClip = (clipPath: string, holdSec = beat.holdSec): Promise<boolean> =>
      pushSceneClip(clipPath, holdSec, beat.index);
    const beatWallMs = beatVisualWallMs(dedup.perf);
    let clip: string | null = null;
    const beatPulse = setInterval(() => {
      onBeatProgress?.(bi, beats.length, "beat");
    }, 10_000);
    try {
      if (await pushMotionGraphicBeatClipIfAny(beat, scene, workDir, videoTitle, dedup, pushClip, beat.holdSec)) {
        continue;
      }
      if (funnelResult && funnelResult.candidates.length > 0) {
        // Funnel path: archive-first with per-beat gap detection (when enabled),
        // or hybrid coverage-weighted ranking (original behaviour).
        let funnelCandidates: FunnelCandidate[];
        let funnelBeatEmb: number[] | null = null;

        if (archiveFirstBeatsEnabled()) {
          // ── Archive-first per-beat gap detection ──────────────────────────────
          // 1. Compute beat embedding (1 API call; model caches by text)
          const beatDoc = `${beat.text}. ${beat.visualDescription ?? ""}`.slice(0, 400);
          const beatEmb = await createTextEmbedding(beatDoc).catch(() => null);
          funnelBeatEmb = beatEmb;
          // 2. Score archive candidates in-memory (no API calls)
          // RONDE 38: bestArchiveOut captures WHICH candidate produced the score, for the
          // diagnostic line below. Same loop inside findBestArchiveScoreForBeat, same returned
          // score — the out-object is written but never read by any decision.
          const bestArchiveOut: { candidate?: FunnelCandidate } = {};
          const bestArchiveScore = beatEmb
            ? findBestArchiveScoreForBeat(funnelResult.candidates, beatEmb, bestArchiveOut)
            : null;
          // 3. Resolve gap strategy based on confidence + diversity guard
          const gapStrategy = resolvePerBeatGapStrategy(bestArchiveScore, dedup.consecutiveArchiveBeats);
          console.log(
            `[Funnel] s${scene.index}b${beat.index}: archiveScore=${bestArchiveScore?.toFixed(3) ?? "n/a"} ` +
            `consec=${dedup.consecutiveArchiveBeats} strategy=${gapStrategy}`
          );
          // RONDE 38 — calibration measurement only, never a decision.
          //
          // This is the per-beat counterpart to [FunnelCalib]: computeArchiveCoverage runs once
          // per SCENE and has no beat index, but THIS is where the strategy that actually orders
          // the candidates for a beat is chosen. Everything printed is already in hand — the
          // score was just computed, the candidate came back with it, and the beat text is the
          // loop variable — so there is no query, no fetch and no embedding call here.
          {
            const bc = bestArchiveOut.candidate;
            const bcAssetId = bc?.archivePick?.asset?.id;
            const bcArchive = bc?.archivePick?.archiveName?.trim();
            const bcTitle = bc?.title?.trim();
            const bcKeyword = bc?.archiveKeywordScore;
            console.log(
              `[FunnelBeatCalib] s${scene.index}b${beat.index} strategy=${gapStrategy} ` +
              `archiveScore=${bestArchiveScore?.toFixed(4) ?? "n/a"} kw=${bcKeyword ?? "unknown"} ` +
              `asset=${bcAssetId ?? "unknown"} archive="${bcArchive || "unknown"}" ` +
              `title="${bcTitle || "unknown"}" ` +
              `beat="${(beat.text ?? "").replace(/\s+/g, " ").trim().slice(0, 60) || "unknown"}"`
            );
            /**
             * RONDE 125 — the same facts, said in the one sentence the audit asked for.
             *
             * [FunnelBeatCalib] above is a calibration line: it prints the score so the
             * thresholds can be tuned. It does not say whether this beat REUSED what the archive
             * already had or went out and searched again, and that is the question "does FastVid
             * get faster with every video" actually turns on.
             *
             * Nothing here is computed: the score, the strategy, the candidate list and the beat
             * text were all in hand a line ago. No query, no fetch, no embedding call.
             */
            const reused = gapStrategy === "archive_only";
            const scoredCandidates = funnelResult.candidates.filter(
              (c) => c.archivePick?.asset?.id != null
            );
            const knownSuccessful = scoredCandidates.filter(
              (c) => (c.archivePick?.asset?.editorialScore ?? 50) > 50
            ).length;
            console.log(
              formatArchiveRetrieval({
                sceneIndex: scene.index,
                beatIndex: beat.index,
                query: (beat.text ?? "").replace(/\s+/g, " ").trim(),
                candidates: scoredCandidates.length,
                bestScore: bestArchiveScore ?? null,
                stopThreshold: BEAT_ARCHIVE_STOP_THRESHOLD,
                knownSuccessful,
                outcome: reused ? "reuse" : "external",
                strategy: gapStrategy,
              })
            );
            if (!reused) {
              console.log(
                formatNoStrongMatch({
                  sceneIndex: scene.index,
                  beatIndex: beat.index,
                  query: (beat.text ?? "").replace(/\s+/g, " ").trim(),
                  bestScore: bestArchiveScore ?? null,
                  stopThreshold: BEAT_ARCHIVE_STOP_THRESHOLD,
                })
              );
            }
          }
          // 4. Order candidates: archive leads unless aggressive mode
          funnelCandidates = orderCandidatesForBeatGap(funnelResult.candidates, gapStrategy);
          // Update consecutive archive counter
          if (gapStrategy === "archive_only") {
            dedup.consecutiveArchiveBeats++;
          } else {
            dedup.consecutiveArchiveBeats = 0;
          }
          // FASE 4: widened from 4 to FUNNEL_CANDIDATE_POOL_LIMIT — this is a metadata-only
          // visibility cap (no extra API calls), so a strong candidate ranked 5th+ can still
          // reach buildDownloadShortlist() below instead of being cut before it's ever seen.
          funnelCandidates = funnelCandidates.slice(0, poolThumbnailRankingEnabled() ? 8 : FUNNEL_CANDIDATE_POOL_LIMIT);
        } else {
          // Original coverage-weighted ranking (no per-beat gap detection)
          funnelCandidates = funnelResult.candidates.slice(0, poolThumbnailRankingEnabled() ? 8 : FUNNEL_CANDIDATE_POOL_LIMIT);
        }

        if (poolThumbnailRankingEnabled() && funnelCandidates.some(c => c.thumbnailUrl)) {
          // Rerank external candidates (pool ones) by CLIP — archive ones have no thumbnail
          const external = funnelCandidates.filter(c => c.poolCandidate && c.thumbnailUrl);
          if (external.length > 0) {
            const reranked = await rankCandidatesByThumbnailClip(
              external.map(c => c.poolCandidate!),
              beat.text, beat.visualDescription, videoTitle, scene.index, beat.index
            );
            // Update clipSimilarity back onto funnel candidates
            for (const fc of external) {
              const rr = reranked.find(r => r.id === fc.poolCandidate!.id);
              if (rr) { fc.clipSimilarity = rr.clipSimilarity; fc.rankingScore += (rr.clipSimilarity ?? 0) * 0.3; }
            }
          }
          if (!archiveFirstBeatsEnabled()) {
            // Only re-sort when NOT in archive-first mode (gap detection already ordered candidates)
            funnelCandidates = [...funnelCandidates].sort((a, b) => b.rankingScore - a.rankingScore);
          }
          funnelCandidates = funnelCandidates.slice(0, 3);
        }

        // FASE 1 — Visual Discovery Engine: score every downloaded candidate with the
        // existing VisionGate instead of stopping at the first one that downloads
        // successfully, then let pickBestFunnelCandidate() (bronbias-aware) choose the
        // winner. VisionGate itself (pass/fail criteria, threshold, cache) is untouched —
        // it is simply called on more than one candidate per beat now.
        // FASE 4: the flat top-N slice is replaced by buildDownloadShortlist(), which applies
        // source diversity (no single source, especially stock, can monopolize the download
        // budget) while still letting relevance (rankingScore) decide who fills the
        // available slots — see retrievalFunnel.ts for the full rationale. Budget raised from
        // 3 to MAX_FUNNEL_CANDIDATES_TO_SCORE (=6) since candidates now compete for slots
        // across up to 15 visible metadata candidates (FUNNEL_CANDIDATE_POOL_LIMIT) instead
        // of just the first 3-4.
        // FIX 2: exclude assets an earlier beat already won, so the identical per-scene
        // candidate list produces a different shortlist per beat. Falls back to the full
        // list inside buildDownloadShortlist() once everything has been used.
        /**
         * RONDE 164 — the beat's own funnel, counted at every step.
         *
         * `candidatesFound` is what retrieval returned for the SCENE, before the metadata slice
         * above narrowed it: render 553's s1b6 found 25 and offered 3, and only the raw number
         * makes that visible. Everything else is filled in by the code that already computes it.
         */
        const sourcingAudit = createArchiveSourcingAudit();
        const candidatesFoundForBeat = funnelResult.candidates.length;
        /**
         * RONDE 176 — this beat's own sentence orders the pool before the shortlist is cut.
         *
         * The funnel searched once for the SCENE; this runs once per BEAT. Between them nothing
         * re-read the beat, so a beat's order was the scene's order minus what its neighbours had
         * already taken — which gave the last beat of a scene systematically worse options than
         * the first, for no reason but its position in the loop.
         *
         * The years come from the beat's own text here, not the scene's: at this point the
         * sentence IS in scope, which it is not where the funnel is built.
         */
        const beatContext = {
          years: yearsIn(beat.text).map(String),
          places: get_activeVideoVisualContext()?.locations?.slice(0, 3),
          subjects: [activeMemoryEntity(), ...(scene.personNames ?? [])].filter(
            (x): x is string => Boolean(x)
          ),
        };
        const toScore = buildDownloadShortlist(
          reorderShortlistForBeat(funnelCandidates, beatContext),
          MAX_FUNNEL_CANDIDATES_TO_SCORE,
          dedup.usedFunnelCandidateIds,
          sourcingAudit
        );
        const discoveredCount = funnelCandidates.length;
        const shortlistCount = toScore.length;
        let downloadedCount = 0;
        // RONDE 131: `let`, because a refusal reorders what is left. The array's CONTENTS are
        // never changed by that — see reorderAfterMismatch, which returns a permutation.
        let scored: ScoredFunnelCandidate[] = [];
        // FASE 7.2 — embedding-space separation. funnelBeatEmb is an OpenAI
        // text-embedding-3-small vector (1536 dim, see createTextEmbedding above). It is the
        // right vector for the archive/text ranking below (findBestArchiveScoreForBeat,
        // computeSegmentSimilarities) and stays in use there, unchanged. It is the WRONG
        // vector for VisionGate, which compares against CLIP ViT-B/32 *image* embeddings
        // (512 dim): cosineSimilarity() bails out with `a.length !== b.length -> return 0`,
        // so every funnel candidate scored an exact 0.0000 and could never win — proven in
        // render 512 (38 rejects, all rawSimilarity=0.0000 exact, while the non-funnel path
        // in the same render produced real 0.18-0.24 scores). Passing no queryEmb here lets
        // VisionGate resolve its own CLIP text embedding via resolveBeatQueryEmbedding(),
        // which is the already-proven-correct behaviour on every non-funnel path.
        console.log(
          `[FunnelVisionGate] s${scene.index}b${beat.index} queryEmbeddingSource=resolved-by-vision-gate` +
          (funnelBeatEmb ? ` textEmbDim=${funnelBeatEmb.length}(archive-ranking-only)` : ` textEmb=none`)
        );
        // RONDE 5 / FIX 6 — the shortlist downloads run in bounded parallel batches instead
        // of one at a time. Render 517: the sequential form cost 2-4s per download + ~0.5s
        // VisionGate × up to 6 candidates = 12-25s per beat, while the beat-fill budget is
        // 12s (turbo) to 20s — so beats were killed mid-loop with all their (passing!)
        // candidates already downloaded but no winner ever picked (0 funnel winners reached
        // compose; beat s1b3 had six VisionGate-passed candidates die this way). Batching the
        // downloads 3 at a time drops the download phase to ~1 batch-round per 3 candidates;
        // VisionGate stays sequential (CPU-bound CLIP work — parallelizing it buys little and
        // competes with ffmpeg for the same cores). Results are applied in shortlist order,
        // so `scored` keeps exactly the order the sequential loop produced.
        /**
         * RENDER 562 — screen the shortlist on what the provider already told us, before the
         * first byte is fetched.
         *
         * `white-lives-matter-montana-activism-in-butte-2` under narration about Hitler's 1944
         * ceasefire needs no frame to be refused; the identifier says what it is. It was
         * nevertheless downloaded, trimmed, and only then offered to a picture editor who had no
         * provider left to answer with — so it was adopted.
         *
         * Text only, so Groq stays in the chain: this is the one relevance check that still runs
         * when the vision providers are down, which is exactly when it is needed. It may only
         * REFUSE — see candidateSubjectGate.ts. A candidate it lets through has proved nothing
         * and still faces the image gate on its real frames.
         *
         * NOTHING IS DOWNLOADED HERE, not even a thumbnail. The metadata was returned by the
         * search that already happened.
         */
        /**
         * IN PARALLEL, for the reason RONDE 5's FIX 6 exists.
         *
         * Six sequential text calls at ~1s each would spend a third of a 12-20s beat budget
         * before a single byte was fetched — which is the exact shape of the defect FIX 6 fixed
         * for the downloads themselves ("beats were killed mid-loop after downloading passing
         * candidates"). The screens are independent of one another, so they all go at once and
         * the results are applied in shortlist order.
         */
        /**
         * RENDER 563 — through the SAME entry point the download itself uses.
         *
         * This loop used to call `judgeCandidateSubject` directly, with a context it built here.
         * The scene-pool route calls `downloadAndTrimPoolCandidate` without passing this loop, and
         * so had no screen at all — `[SubjectGate] asked=0` on the render after the gate shipped.
         *
         * The check now lives at the download, where no route can miss it. This loop stays because
         * it asks EARLY and in PARALLEL — refused candidates never enter a download batch, and the
         * screens go six at once instead of three — but it is an optimisation now, not the
         * enforcement, and it asks the identical question: same function, same ambient context,
         * and the judge's own cache means the download's re-ask costs nothing.
         */
        const subjectVerdicts = await Promise.all(
          toScore.map(async (candidate) => {
            const pool = candidate.poolCandidate;
            /** Curated archive picks are the operator's own library — not screened by this. */
            if (!pool) return { candidate, pool: null, decision: null };
            const decision = await screenCandidateBeforeDownload({
              facts: {
                id: pool.id,
                assetId: pool.assetId,
                source: pool.source,
                title: pool.title,
                description: pool.description,
                tags: pool.tags,
              },
              sceneIndex: scene.index,
              beatIndex: beat.index,
            });
            return { candidate, pool, decision };
          })
        );
        const subjectScreened: FunnelCandidate[] = [];
        for (const { candidate, pool, decision } of subjectVerdicts) {
          if (!pool || !decision || decision.allowed) {
            subjectScreened.push(candidate);
            continue;
          }
          console.warn(
            `[SubjectGate] s${scene.index}b${beat.index} REFUSED ${pool.source}:${pool.assetId} ` +
              `— ${decision.reason} (no download made)`
          );
        }

        const FUNNEL_DOWNLOAD_CONCURRENCY = 3;
        /**
         * YOUTUBE IS ASKED WHILE THERE IS STILL TIME TO ANSWER.
         *
         * This is the route the production render actually uses — `fetchSceneVisualsInner`'s funnel
         * branch, whose downloads go through `downloadFunnelCandidate` →
         * `downloadAndTrimPoolCandidate` → `downloadYouTubeCCClip`, which is where all seventeen
         * `0s left in the scene budget` refusals came from. Ordering it here rather than in the
         * cascade is the whole point: `fetchBeatArchivalThenPexels` is a different route and this
         * render never entered it.
         *
         * See `hoistBudgetSensitiveDownload` for why this is an ordering change and not a budget
         * one — a nested scope is clamped to its parent's deadline, so a larger slice cannot buy
         * time a spent beat does not have.
         */
        const downloadOrder = youtubeFirstEnabled()
          ? hoistBudgetSensitiveDownload(subjectScreened)
          : subjectScreened;
        if (downloadOrder[0] !== subjectScreened[0]) {
          console.log(
            `[Funnel] s${scene.index}b${beat.index}: YouTube candidate moved to the front of the ` +
              `download order — it is the only source whose transfer the beat budget can refuse outright`
          );
        }
        const downloadedClips: Array<{ candidate: FunnelCandidate; clipPath: string }> = [];
        /**
         * RONDE 240 — THREE AT A TIME, NOT THREE AND THEN A WAIT.
         *
         * This was `for (…dlIdx += 3) { await Promise.all(batch.map(…)) }`: a barrier every three
         * candidates. `Promise.all` settles on its SLOWEST member, so two downloads that finished
         * in two seconds sat idle until the third returned — and being first in the order bought
         * the hoisted YouTube candidate nothing, because it shared a batch with whatever was ranked
         * next. One `loc` transfer held a beat for twenty-five minutes exactly this way while its
         * two neighbours had long since finished.
         *
         * A limit of three keeps the concurrency the batch was there to impose — the same number,
         * the same ceiling on parallel transfers — while removing the barrier: a finished slot
         * starts the next candidate immediately instead of waiting for its neighbours.
         *
         * ── Why results are written by POSITION and not pushed ──────────────────────────────
         *
         * `downloadedClips` feeds the evaluation below, and its order is the ranking order — the
         * order `hoistBudgetSensitiveDownload` was written to set. Pushing as each download settles
         * would order by SPEED instead, so a fast low-ranked candidate would be judged ahead of the
         * YouTube one deliberately put in front. That would undo RONDE 233/234 silently, while
         * every test still passed. So each result lands in its own slot and the list is compacted
         * in order afterwards: concurrency changes, ranking does not.
         */
        /**
         * THE LADDER, ASKED BEFORE THE TRANSFERS START.
         *
         * The funnel searched at SCENE scope, so its provider queries are long past by the time a
         * beat gets here — there is nothing left for `searchGateDecision` to refuse. The download
         * is where this beat actually spends the tier, so that is where the ladder gets its say.
         *
         * Filtered here rather than inside the concurrent download below, deliberately: three
         * transfers running at once would ask the ladder at once, each seeing a different set of
         * attempted tiers, and the answer would depend on which request happened to arrive first.
         * In ranking order, one at a time, the walk is the walk.
         *
         * A refused candidate is SKIPPED, never punished: it keeps its place in the funnel for a
         * later beat whose ladder has got further, and `usedFunnelCandidateIds` is deliberately not
         * touched.
         */
        const tierAdmittedOrder: FunnelCandidate[] = [];
        for (const candidate of downloadOrder) {
          const verdict = admitPoolCandidateTier(candidate.source);
          if (verdict.admitted) {
            tierAdmittedOrder.push(candidate);
            continue;
          }
          console.log(
            `[Funnel] s${scene.index}b${beat.index}: ${candidate.source} candidate not downloaded — ` +
              `${verdict.reason}` +
              (verdict.skipped.length > 0 ? ` (skips ${verdict.skipped.join(",")})` : "")
          );
        }
        const downloadLimit = pLimit(FUNNEL_DOWNLOAD_CONCURRENCY);
        const downloadSlots: Array<{ candidate: FunnelCandidate; clipPath: string } | null> =
          new Array(tierAdmittedOrder.length).fill(null);
        const downloadsT0 = Date.now();
        await Promise.all(
          tierAdmittedOrder.map((candidate, slotIdx) =>
            downloadLimit(async () => {
              const clipPath = await downloadFunnelCandidate(candidate, workDir, scene.index, beat.index, beat.holdSec, dedup.sourcingCache);
              if (clipPath) downloadSlots[slotIdx] = { candidate, clipPath };
              else downloadSlots[slotIdx] = null;
            })
          )
        );
        recordPipelineTiming(
          dedup.stepTiming,
          "image_download",
          `Funnel downloads (${tierAdmittedOrder.length} candidate(s), ${FUNNEL_DOWNLOAD_CONCURRENCY} at a time)`,
          Date.now() - downloadsT0,
          scene.index
        );
        {
          for (let slotIdx = 0; slotIdx < tierAdmittedOrder.length; slotIdx++) {
            const candidate = tierAdmittedOrder[slotIdx]!;
            const clipPath = downloadSlots[slotIdx]?.clipPath ?? "";
            if (!clipPath) {
              // FIX 3 — register failed downloads too. Only the beat WINNER used to be recorded,
              // so a candidate whose download fails stayed in every later beat's shortlist and
              // was re-fetched on each one. Render 515: two Wikimedia assets that answered HTTP
              // 429 were retried 4x each across the scene's beats, burning shortlist slots that
              // downloadable candidates could have used.
              //
              // Registered under the same candidate id FIX 1 + FIX 2 use, so a failure simply
              // means "this beat and later beats look further down the same ranking". No retry,
              // no backoff, no provider change: the candidate is skipped, not punished, and the
              // exhaustion rule in buildDownloadShortlist()/pickBestFunnelCandidate() still
              // restores the full list once everything has been used, so this can never be the
              // sole cause of a fallback while other candidates remain.
              dedup.usedFunnelCandidateIds.add(candidate.id);
              continue;
            }
            downloadedCount++;
            downloadedClips.push({ candidate, clipPath });
          }
        }
        /**
         * THE FUNNEL REPORTS TO THE BEAT AUDIT — the route that does the work, counted at last.
         *
         * ── The measurement defect this closes ──────────────────────────────────────────────
         *
         * `noteBeatCandidatesOffered` had exactly one caller: `adoptClip`. The retrieval funnel
         * adopts through its own block below and never goes through `adoptClip` — the same gap
         * RONDE 53 closed for `recordClipAdopt` and RONDE 62 closed for the still/moving counters,
         * one layer up and still open.
         *
         * So every beat the funnel served reported `offered=0`, and `resolveBeatStatus` labels a
         * beat with `offered === 0` and nothing else recorded as `no_candidates`. A production
         * render that downloaded 56 assets reported `noCandidates=10` and `REAL_ASSET=1` — numbers
         * that describe one route's bookkeeping, not the video.
         *
         * `downloadedClips` is the honest count: files on disk, handed to evaluation for THIS
         * beat, which is exactly what `offered` means in `adoptClip` ("candidate paths handed to
         * the adopt path"). Nothing is fetched, ranked or judged here — this counts.
         */
        noteBeatCandidatesOffered(
          dedup.beatOutcomeAudit, scene.index, beat.index, downloadedClips.length
        );
        const visionT0 = Date.now();
        for (const { candidate, clipPath } of downloadedClips) {
          const visionResult = await evaluateClipVisionGate(
            clipPath,
            beat.text,
            videoTitle,
            workDir,
            scene.index,
            beat.index,
            dedup.perf.fastStockMode,
            undefined,
            beat.visualDescription,
            dedup.segmentGeoLock,
            undefined,
            isFastShortVideoLength(dedup.videoLength),
            clipContentKey(clipPath)
          );
          /**
           * RONDE 103 — CLIP ranks here, it does not decide.
           *
           * The funnel is the one place CLIP's score genuinely earns its keep: `scored` is what
           * pickBestFunnelCandidate orders, so a better score really does mean a candidate gets
           * looked at first. Recording a reject on top of that was the content decision, and it
           * is the one being removed — a candidate CLIP dislikes now simply sorts lower and the
           * relevance gate below decides whether the winner belongs.
           */
          if (!visionResult.pass && !visionResult.skipped) {
            console.log(
              `[VisionGate] s${scene.index}b${beat.index} CLIP ranks ` +
                `${path.basename(clipPath)} low (score=${visionResult.worstScore10 ?? "?"}) — not a reject`
            );
          }
          scored.push({ candidate, clipPath, visionResult });
        }
        recordPipelineTiming(
          dedup.stepTiming,
          "image_processing",
          `Clip vision gate (${downloadedClips.length} clip(s))`,
          Date.now() - visionT0,
          scene.index
        );

        // FIX 1: prefer a passer this render has not adopted yet. Ranking and VisionGate are
        // untouched — the best REMAINING candidate still wins on its own score. When every
        // passer is used the full set is restored inside pickBestFunnelCandidate(), so reuse
        // is the last resort and a beat is never dropped to fallback because of this.
        let winner = pickBestFunnelCandidate(scored, dedup.usedFunnelCandidateIds, dedup.beatImageRejectedIds);
        /** RONDE 67: the refused winner, kept in case nothing better turns up. */
        let gateReprieveWinner: typeof winner = null;
        /** RONDE 132: what the gate last blamed, null while nothing has been refused. */
        let lastMismatchKind: MismatchKind | null = null;

        // RONDE 58: before adopting, look at the picture.
        //
        // Every other judge in this pipeline decides without seeing the image: the metadata gate
        // reads the provider's title, and the CLIP score is measurably inverted for this
        // material (render 531 scored a white-lives-matter sticker 0.2226 and a genuine Hitler
        // photograph 0.2116 on the same beat). This asks a vision model what is actually in the
        // frame and whether that belongs under this line of narration.
        //
        // It runs on the candidate about to be ADOPTED, not on all of them — one call per beat
        // in the ordinary case. A rejected winner is marked used, the next-best is tried, and
        // after MAX_JUDGEMENTS_PER_BEAT the pipeline takes what it has rather than starving the
        // beat. Every failure mode returns "unknown", which adopts exactly as before.
        if (beatImageRelevanceGateEnabled()) {
          /**
           * RONDE 142 — the judging loop needs a candidate; the research pass below does not.
           *
           * These were one block until now, and video 548 measured what that cost: 13 of its 15
           * beats reached this point with `offered=0` — no candidate at all — so the whole block
           * was skipped, research included. Research is unreachable in exactly the situation it
           * exists for. Splitting the two puts the loop behind `winner` where it belongs and
           * leaves the research pass reachable for a beat that found nothing.
           *
           * The condition is given a name rather than written inline, because RONDE 53 anchors its
           * adoption-audit test on the first bare winner-guard after the picker; a second one here
           * would silently point that test at the wrong block. The comment avoids the literal form
           * for the same reason — RONDE 130 learned that these guards match TEXT, not code.
           */
          const hasCandidateToJudge = winner !== null;
          /**
           * RONDE 168 — which candidates this beat actually looked at.
           *
           * The loop below judges the CURRENT winner and, on a refusal, moves to the next. When it
           * ends because the look ceiling ran out rather than because something passed, the winner
           * it leaves behind has never been judged at all — and video 555 shipped one. See the
           * block after the loop.
           */
          const judgedCandidateIds = new Set<string>();
          if (hasCandidateToJudge) {
          for (let look = 0; look < MAX_JUDGEMENTS_PER_BEAT && winner; look++) {
            judgedCandidateIds.add(winner.candidate.id);
            // RONDE 103: the same central decider every other route uses. The frame sampling,
            // the cleanup and the cache key used to be this loop's own copy of that logic — and
            // it was the copy that keyed on the picture alone, so a clip the funnel approved on
            // beat 1 was never re-examined on beat 7.
            const judgement = await judgeBeatClipRelevance(dedup, scene.index, beat.index, {
              clipPath: winner.clipPath,
              contentKey: clipContentKey(winner.clipPath),
              ctx: beatVisualContext(beat, scene, videoTitle),
              workDir,
              state: dedup.beatImageGate,
              ledger: dedup.beatRelevance,
              route: `funnel:${winner.candidate.source}`,
            });
            /**
             * The verdict is recorded by `judgeBeatClipRelevance` above, along with the spend.
             * It used to be recorded HERE, which is why this was the only one of the gate's four
             * routes whose answers were counted — 61 calls against 16 verdicts on render 562.
             */
            if (judgement.verdict !== "does_not_fit") break;

            recordClipReject(
              dedup.clipRejectAudit, scene.index, beat.index, winner.clipPath,
              "beat_image_gate", winner.candidate.title
            );

            /**
             * RONDE 131 — read what the picture editor just said, and look somewhere else.
             *
             * The gate returns `depicts` and `reason`: prose from a model that has seen the frame
             * and read the narration. Until this round both were logged and discarded, and the
             * loop's second look went to the next candidate in an order the first refusal had not
             * touched — so a beat that had just been told "this is present-day footage under 1945
             * narration" would cheerfully try the next present-day stock clip.
             *
             * Two things happen with it now. It is COUNTED, so the render can finally say whether
             * its refusals were a sourcing problem or a catalogue problem. And when the refusal
             * names something a catalogue actually predicts — a period error, a title card — the
             * remaining candidates are reordered so the ones likely to repeat it sort last.
             *
             * Nothing is removed and no gate is consulted. See ./visualMismatchFeedback for why a
             * reorder is the correct weight for this evidence rather than a rejection.
             */
            const mismatchKind = classifyMismatch(judgement);
            // RONDE 132: the last thing the gate said about this beat, kept so the research pass
            // below can act on it after the loop has run out of candidates.
            lastMismatchKind = mismatchKind;
            /**
             * RONDE 143 — the same dedupe key the shared gate uses.
             *
             * RONDE 142 gave `beatClipPassesVisionGate` a (content, beat) key so a candidate seen
             * by two layers is counted once, but left this registration un-keyed. The funnel and
             * the rescue ladder can be offered the SAME file for the same beat — a Wikimedia clip
             * the funnel refused can come back through the Wikimedia rescue — and the second look
             * reads its verdict from `checkBeatRelevance`'s cache, so it is still a refusal and
             * was still counted a second time. That inflates exactly the numbers RONDE 142 was
             * written to make trustworthy: the refusal total and the per-provider table.
             *
             * The reorder above and `lastMismatchKind` stay unconditional — they are about what
             * the gate SAID, which is true however often it has been asked. Only the counting is
             * deduped.
             */
            recordMismatch(dedup.mismatchTally, {
              kind: mismatchKind,
              source: winner.candidate.source,
              depicts: judgement.depicts,
              reason: judgement.reason,
              dedupeKey: `${clipContentKey(winner.clipPath)}|s${scene.index}b${beat.index}`,
            });
            const beforeOrder = scored;
            /**
             * RONDE 135 §15 — the render's own evidence, on top of the static table.
             *
             * `repeatOffenderSources` reads the tally this render has been filling in since its
             * first refusal. A source refused three times for present-day footage on THIS
             * documentary is not a good bet for the fourth, whatever a table about catalogues in
             * general says. It is a ranking signal only: the reorder is still a permutation, so a
             * beat whose only candidates come from a penalised source still gets them.
             */
            scored = reorderAfterMismatch(
              scored,
              mismatchKind,
              (s) => s.candidate.source,
              repeatOffenderSources(dedup.mismatchTally)
            );
            console.log(
              formatMismatchFeedback({
                sceneIndex: scene.index,
                beatIndex: beat.index,
                source: winner.candidate.source,
                kind: mismatchKind,
                reordered: reorderChangedOrder(beforeOrder, scored),
                remaining: scored.length - dedup.beatImageRejectedIds.size - 1,
                // RONDE 155: printed only when the kind is UNCLEAR — see formatMismatchFeedback.
                depicts: judgement.depicts,
                reason: judgement.reason,
              })
            );
            // RONDE 61: a hard exclusion, not a used-marker. Marking it "used" alone put the
            // clip straight back: with one passer on the beat, unusedPassers empties, the picker
            // restores the full set and hands back the very clip just refused. Render 532 shows
            // exactly that — s2b1, s2b2 and s2b3 each judged twice, does_not_fit both times,
            // and all three in the final manifest, including a white-lives-matter roadside
            // clip under narration about the Battle of Berlin.
            dedup.beatImageRejectedIds.add(winner.candidate.id);
            dedup.usedFunnelCandidateIds.add(winner.candidate.id);
            winner = pickBestFunnelCandidate(scored, dedup.usedFunnelCandidateIds, dedup.beatImageRejectedIds);
          }
          /**
           * RONDE 168 — the beat may not adopt a picture nobody looked at.
           *
           * ── What video 555 shipped ─────────────────────────────────────────────────────────
           *
           *     [BeatRelevance] s2b3 funnel:loc              does_not_fit
           *     [BeatRelevance] s2b3 funnel:internet_archive does_not_fit
           *     [RenderAsset]   provider=nasa scene=2 beat=3
           *                     file=..._nasa_Hidden_Figures_Way_NASA_s_Vision_of_Equality...
           *                     verdict=does_not_fit reprieved=false rendered=true
           *
           * A NASA clip about equality, on screen under narration about Churchill, Roosevelt and
           * Stalin at the Tehran Conference. RONDE 166's guard never saw it, and the reason is two
           * lines of control flow rather than anything about severity.
           *
           * The loop above runs `look < MAX_JUDGEMENTS_PER_BEAT` (=2). Each pass judges the
           * current winner and, on a refusal, picks the next-best. It `break`s the moment one
           * PASSES — so a winner produced by a `break` has been judged. But when the ceiling runs
           * out instead, the winner left in hand is the candidate picked by the LAST refusal, and
           * nothing has ever looked at it. It is not in `beatImageRejectedIds` either, so the
           * reprieve check below does not fire, no severity is consulted, and `funnelClip = clipPath`
           * hands it straight to the montage — the funnel is the one adopt route that does not go
           * through pushClip, so the compose barrier never sees it either.
           *
           * Two refusals therefore bought an UNEXAMINED third candidate a free pass, and the more
           * a beat's candidates were refused the likelier its picture was one nobody had judged.
           * That is the exact inverse of the intent stated four comments above this one: "It runs
           * on the candidate about to be ADOPTED, not on all of them."
           *
           * ── The fix, inside the existing budget ────────────────────────────────────────────
           *
           * The look budget is spent on judging, not on shopping. With two looks a beat may try
           * two candidates properly; it may not try two and then take a third on trust. So an
           * unjudged winner is put back and the beat continues with what it actually knows — the
           * candidates it DID judge, under RONDE 166's severity rules, via the reprieve below.
           *
           * No gate call is added and no ceiling is raised. What changes is which candidate the
           * beat ends on when the ceiling binds: a judged one, or none.
           */
          const judgedOnly = keepOnlyJudgedWinner(
            winner, judgedCandidateIds, scored, dedup.beatImageRejectedIds
          );
          if (judgedOnly.putBack) {
            console.warn(
              formatVisualFitDecision({
                beatLabel: `s${scene.index}b${beat.index}`,
                candidate: path.basename(judgedOnly.putBack.clipPath),
                verdict: judgedOnly.reason,
                severity: "UNKNOWN",
                decision: "REJECTED",
                reason: `look_budget_spent_after_${judgedCandidateIds.size}_judgements`,
              })
            );
            recordAssetOutcome(
              dedup.sourcingCache?.lineage,
              judgedOnly.putBack.clipPath,
              judgedOnly.reason,
              `s${scene.index}b${beat.index}`,
              clipContentKey(judgedOnly.putBack.clipPath)
            );
          }
          winner = judgedOnly.winner;

          // RONDE 61 dropped the winner here so the beat could fall through to another source.
          // RONDE 67 keeps it: render 533 showed what "falling through" costs when the other
          // sources have nothing either — eight beats ended on a grey placeholder, which matches
          // the narration worse than the imperfect picture that was refused. The candidate is
          // held as a reprieve and used only if nothing else is found; funnelClip stays null so
          // every other route is still tried first.
          if (winner && dedup.beatImageRejectedIds.has(winner.candidate.id)) {
            console.log(
              `[BeatImageGate] s${scene.index}b${beat.index} no acceptable candidate ` +
                `after ${MAX_JUDGEMENTS_PER_BEAT} looks — held as reprieve`
            );
            gateReprieveWinner = winner;
            winner = null;
          }
          } // end: candidates existed and were judged

          /**
           * RONDE 132 — the beat has been refused and has nothing left. Ask a better question.
           *
           * This is the point RONDE 131 could not reach. Reordering the pile is the right answer
           * while there is a pile; here there is none, and the beat is about to fall through to a
           * reprieved picture the gate has already said does not belong.
           *
           * The decision is narrow on purpose:
           *
           *  · Never on an unclassified refusal. RONDE 134 does act on a MATERIAL fault, but by
           *    changing what is asked FOR (archive footage) rather than what is asked ABOUT — see
           *    ADD_ARCHIVAL_INTENT in ./mismatchResearch.
           *  · Only once per beat, enforced by `mismatchResearchedBeats` before anything is spent.
           *  · Only when the render can afford it — RONDE 134 §20 passes the remaining scene
           *    budget, and a pass that would not fit is skipped as BUDGET_EXCEEDED rather than
           *    started and cut off.
           *  · RONDE 134: the context is the beat's MERGED with the scene's. A documentary states
           *    its period once and then relies on it, and RONDE 133 measured what reading only the
           *    beat costs — a period correction fired on 2 of 10 realistic beats. The scene's own
           *    words were already admissible evidence to the SearchGate; nothing was building
           *    queries from them.
           *  · Only a query the CONTRACT already minted for this beat. `decideResearch` selects
           *    from `buildPrioritisedQueries`, so the corrected query carries the beat's own proven
           *    tokens — "Hermann Göring Berlin 1945", with the ö intact, never a reconstruction and
           *    never the reject reason glued onto the old string.
           *  · Inside the same provider budget: the cascade's query cap is unchanged, so the
           *    corrected question REPLACES a weaker one rather than being added to it.
           *
           * The clip that comes back has been through `adoptClip`, which runs the beat-image gate
           * like every other route — so a research candidate is judged, never adopted on trust.
           */
          const researchKey = `s${scene.index}b${beat.index}`;
          /**
           * RONDE 142 — the refusal may have happened on another route.
           *
           * `lastMismatchKind` is set inside this loop only. Video 548 showed why that is too
           * narrow: 19 of its 24 refusals came from routes that never touch this loop, and the
           * research pass consequently never saw a fault. The shared gate now records the kind
           * per beat, so a beat refused elsewhere still has something to correct against.
           */
          const beatMismatchKind = lastMismatchKind ?? dedup.lastMismatchByBeat.get(researchKey) ?? null;
          /**
           * RONDE 153 — the budget decides, not the preset.
           *
           * `!fastStockMode` was a second gate on top of one that already exists and is better
           * informed: `decideResearch` takes `remainingBudgetMs` and refuses as BUDGET_EXCEEDED
           * when a pass would not fit. The preset check fired regardless of how much time was
           * actually left, and video 550 measured what that costs on the one-minute preset, where
           * fastStockMode is on by default on Railway:
           *
           *     [MismatchFeedback] 18 refusal(s) — search-preventable=8
           *     research attempts=0
           *     BudgetSummary  estimated=22m  actual=10m 45s  used=49%  total_remaining=11m 15s
           *
           * Eight refusals the feedback chain had already classified as fixable by asking a better
           * question, eleven minutes of unused budget, and not one corrected search — because the
           * preset said "fast". The beats fell through to placeholders and colour cards instead.
           *
           * Research is the recovery path for a refused beat. Switching it off on the preset most
           * likely to be short of footage is backwards; the budget check is what should decide,
           * and it already did.
           */
          if (!winner && beatMismatchKind) {
            const beatLabel = researchKey;
            /**
             * RONDE 134 — the beat's context, widened by the scene's, using the same extractor.
             *
             * `beatSearchProvenance(beat, scene)` is the ambient provenance every provider search
             * on this beat already runs under; calling it a second time with the SCENE's text as
             * the subject yields the scene's own typed tokens through exactly the same code path.
             * No second extractor, and no term that the scene does not literally state.
             */
            const researchCtx = buildResearchContext({
              beat: beatSearchProvenance(beat, scene),
              scene: scene.text?.trim()
                ? beatSearchProvenance({ text: scene.text }, scene)
                : null,
            });
            const decision = decideResearch({
              kind: beatMismatchKind,
              ctx: researchCtx,
              alreadyResearched: dedup.mismatchResearchedBeats.has(researchKey),
              // Every question this beat has already been asked, so a "correction" cannot be one
              // of them wearing a different sort order — RONDE 134 §19.
              alreadyUsed: [
                beat.searchQuery ?? "",
                beat.text,
                ...scored.map((s) => s.candidate.title ?? ""),
              ].filter(Boolean),
              /**
               * RONDE 134 §20 — the render's own tracker, the same one the retry guard at the
               * provider-failure site reads.
               *
               * ── RONDE 171: force-export no longer switches this off outright ────────────────
               *
               * `forceExportMode` used to replace the real number with 0, which meant every
               * research pass after it turned on was refused as BUDGET_EXCEEDED regardless of how
               * much render was actually left. Video 555 measured what that costs:
               *
               *     10:39:47 [Pipeline] Force-export mode (≥9 min) — finishing with archive+stock
               *     10:41:52 [MismatchResearch] beat=s2b0 action=NONE reason=BUDGET_EXCEEDED
               *              [MismatchResearch] attempts=0 produced=0 accepted=0 skipped=2
               *              17 van 30 afgewezen beelden waren fout van soort
               *              [Budget] concat ... remaining=6m 56s
               *
               * Force-export fired nine minutes into a twenty-two minute budget. Every beat after
               * it was refused a forty-five second pass — seventeen of the render's thirty
               * refusals were the kind a better question fixes — and the render finished with
               * nearly seven minutes unspent. Three of nineteen beats ended with an approved
               * picture of their own.
               *
               * This is the same shape RONDE 153 removed one round earlier, for the same reason:
               * a blunt switch sitting on top of a budget check that is better informed. Its words
               * apply verbatim — "Research is the recovery path for a refused beat. Switching it
               * off on the preset most likely to be short of footage is backwards; the budget
               * check is what should decide, and it already did."
               *
               * So the real remaining time is passed and `decideResearch` refuses when a pass will
               * not fit. Force-export is honoured as a MARGIN rather than a veto: a render already
               * past its own pacing must be able to afford the pass twice over before starting it.
               * That keeps the intent — do not gamble late — without making the recovery path dead
               * exactly when a render is short of footage, which is when it is needed.
               */
              remainingBudgetMs: get_activeBudgetTracker()?.remainingMs?.(),
              estimatedCostMs: dedup.forceExportMode
                ? RESEARCH_ESTIMATED_COST_MS * FORCE_EXPORT_RESEARCH_MARGIN
                : undefined,
            });
            console.log(formatResearchDecision(beatLabel, decision));
            console.log(formatResearchContext(beatLabel, researchCtx));
            if (decision.action === "NONE") {
              recordResearchSkip(dedup.researchTally, decision.reason);
            } else {
              // Marked BEFORE the search, so a throw, a timeout or a cancellation cannot leave the
              // beat eligible for a second pass. One extra look means one, however it ends.
              dedup.mismatchResearchedBeats.add(researchKey);
              recordResearchAttempt(dedup.researchTally, decision.strategy);
              console.log(
                formatResearchQuery(beatLabel, beat.searchQuery || beat.text, decision.correctedQuery)
              );
              const fitsBefore = dedup.beatImageGate.judgementsFits;
              const mismatchBefore = dedup.beatImageGate.judgementsMismatch;
              /**
               * RONDE 160 — how many assets this pass actually brought in.
               *
               * Counted from the ledger rather than from the return value: the pass may find
               * footage that a later gate refuses, and "found nothing" and "found twelve and kept
               * none" are different problems needing opposite fixes. Absent when no ledger is
               * attached, and reported as absent rather than as zero.
               */
              const ledgerForResearch = dedup.sourcingCache?.lineage;
              const recordsBefore = ledgerForResearch?.allRecords().length ?? null;
              const researched = await withSceneFetchTimeout(
                () =>
                  fetchHistoricalBeatVideo(
                    beat, scene, workDir, scene.index, beat.holdSec, dedup,
                    buildMediaSearchIntent({
                      beatText: beat.text,
                      // The corrected queries lead inside fetchHistoricalBeatVideo; the intent's
                      // own list stays exactly what every other route on this beat would build,
                      // so nothing about the fallback questions changes.
                      searchQueries: beatMediaSearchQueries(beat, videoTitle),
                      keywords: beat.keywords,
                      primaryPerson: historicalDoc ? "" : personName,
                      persons: scenePersons,
                      videoTitle,
                      powerWord: beat.powerWord,
                      personTopicLock: dedup.personTopicLock && !historicalDoc,
                      spaceTopic: isSpaceRelatedTopic(
                        scene.visualCue, scene.pexelsQuery, beat.text, scene.text, videoTitle ?? ""
                      ),
                      muskTopic,
                    }),
                    beatAdoptOpts,
                    `s${scene.index}b${beat.index}_research`,
                    { leadQueries: decision.correctedQueries, researchPass: true }
                  ),
                beatVisualWallMs(dedup.perf),
                `scene ${scene.index} beat ${beat.index} mismatch research`
              ).catch(() => null);
              const gateFits = dedup.beatImageGate.judgementsFits - fitsBefore;
              const gateRejected = dedup.beatImageGate.judgementsMismatch - mismatchBefore;
              const recordsAfter = ledgerForResearch?.allRecords().length ?? null;
              console.log(
                formatResearchOutcome({
                  beatLabel,
                  kind: beatMismatchKind,
                  strategy: decision.strategy,
                  query: decision.correctedQuery,
                  results:
                    recordsBefore != null && recordsAfter != null
                      ? Math.max(0, recordsAfter - recordsBefore)
                      : -1,
                  eligible: gateFits + gateRejected,
                  adopted: researched ? 1 : 0,
                  gateFits,
                  gateRejected,
                })
              );
              recordResearchOutcome(dedup.researchTally, {
                produced: Boolean(researched) || gateFits + gateRejected > 0,
                accepted: Boolean(researched),
              });
              if (
                researched &&
                (await withAdoptionIntent("research_refetch", () => pushClip(researched!, beat.holdSec)))
              ) {
                // The research candidate is the beat's picture. Nothing below runs for this beat:
                // it has real footage the gate approved, which is the outcome the whole round is for.
                continue;
              }
            }
          }
        }
        // RONDE 9: person-locked renders verify the winner with AWS Rekognition celebrity
        // recognition. Rejects ONLY on strong evidence of a different celebrity (see
        // clipShowsWrongCelebrity) — B-roll and unrecognized footage always pass, any error
        // fails open, and the whole check is a no-op without Rekognition keys.
        if (winner && dedup.personTopicLock && dedup.primaryPerson) {
          const wrongCeleb = await clipShowsWrongCelebrity(
            winner.clipPath,
            dedup.primaryPerson,
            winner.candidate.mediaType,
            winner.candidate.poolCandidate?.durationSec
          );
          if (wrongCeleb) {
            dedup.usedFunnelCandidateIds.add(winner.candidate.id);
            winner = null;
          }
        }
        // Nothing survived, but something was refused: take the refusal back rather than leave
        // the beat to a placeholder. A picture the gate disliked is still a picture.
        if (!winner && gateReprieveWinner) {
          // RONDE 103 phase 15: the override is written down against the clip, so the verdict
          // stays `does_not_fit` and the compose barrier can tell "we decided to use it anyway"
          // apart from "nothing ever objected". Before this, a reprieved clip was indexed by the
          // pipeline as though it had passed.
          //
          // RONDE 166: and the override can be declined. On a hard mismatch the beat keeps `winner`
          // null and falls through to every remaining route — the rescue ladder, the curated
          // archive, the research pass — exactly as a beat that found nothing would. A colour card
          // is what happens if all of those also fail, not what happens instead of trying them.
          if (reprieveBeatClip(dedup.beatRelevance, gateReprieveWinner.clipPath, "nothing else passed")) {
            winner = gateReprieveWinner;
          }
        }
        let funnelClip: string | null = null;
        let winningExternalCandidate: FunnelCandidate | null = null;
        if (winner) {
          const { candidate, clipPath } = winner;
          /**
           * RONDE 132 §2 — registered under EVERY identity it has, not only the funnel's.
           *
           * `usedFunnelCandidateIds.add` was the whole record here, and `usedCuratedAssetIds` had
           * exactly one writer in the file: the older archive scan. So an archive asset adopted
           * through the funnel — the primary path — was never marked as a used ARCHIVE ASSET, and
           * everything that asks that question was blind to it:
           *
           *   · the archive scan re-offered it on a later beat,
           *   · RONDE 131's search memory, whose exclude set IS that Set, could hand it back.
           *
           * `usedContentKeys` still caught it at the adopt point so nothing shipped twice — but
           * only after a download and a vision call, in one of the six shortlist slots the beat
           * had, which is a slot a different picture could have used.
           */
          markAssetUsedInVideo(dedup, {
            funnelCandidateId: candidate.id,
            archiveAssetId: candidate.archivePick?.asset?.id ?? null,
            storageUrl: (candidate.archivePick?.asset as { storageUrl?: string } | undefined)?.storageUrl ?? null,
            provider: candidate.poolCandidate ? candidate.source : null,
            providerAssetId: candidate.poolCandidate?.assetId ?? null,
            contentKey: clipContentKey(clipPath),
          });
          dedup.visualDedupStats.uniqueAssets++;
          funnelClip = clipPath;
          /**
           * The funnel's adoption, in the beat audit's own vocabulary.
           *
           * A winner here has passed the beat image gate, which is the acceptance point
           * `noteBeatEligible` exists for — and it becomes the beat's picture, which is
           * `noteBeatAdopted`. Without these two the audit sees a beat the funnel filled as
           * `adopted=0`, and the coverage roll-up counts it as FALLBACK or NO_VALID_ASSET.
           */
          noteBeatEligible(dedup.beatOutcomeAudit, scene.index, beat.index);
          noteBeatAdopted(
            dedup.beatOutcomeAudit, scene.index, beat.index,
            candidate.source, path.basename(clipPath)
          );
          /**
           * §7 — the ADOPTED lineage event, so `[AssetUsageSummary]` can see this route too.
           *
           * `formatAssetUsageSummary` computes `assigned` from the ADOPTED events on the lineage
           * ledger, and the only place that emitted one was `adoptClip`. That is why the last
           * production render read `pexels assigned=0 rendered=0`, `openverse assigned=0`,
           * `internet_archive assigned=0` — every provider the FUNNEL serves — while wikimedia,
           * which came through adoptClip, read `assigned=2 rendered=1`.
           *
           * Same ledger, same event name, same resolver the picture's own outcomes already use:
           * `resolve` finds the record by path, by derivation chain, or by content key. No second
           * mechanism, and a candidate whose record cannot be resolved records nothing rather than
           * inventing one.
           */
          const adoptedRecord = dedup.sourcingCache?.lineage?.resolve(
            clipPath, clipContentKey(clipPath)
          );
          if (adoptedRecord && dedup.sourcingCache?.lineage) {
            dedup.sourcingCache.lineage.recordEvent(adoptedRecord.lineageId, "ADOPTED", {
              status: "OK",
              currentPath: clipPath,
            });
          }
          // RONDE 53: record the adoption. This is the SECOND route that never did.
          //
          // Ronde 51 closed the scene-pool branch in fetchSceneVisualsInner, but the retrieval
          // funnel adopts through downloadFunnelCandidate — curated assets via
          // prepareCuratedArchiveClip and external ones via downloadAndTrimPoolCandidate — and
          // this block only registered the candidate id, the embedding similarity and the
          // segment similarities. The adoption itself went unrecorded, which is why render 531
          // still printed "beat=? source=unknown" for eleven of seventeen manifest lines, all of
          // them either *_curated_a*.mp4 or *_pool_*.mp4, and why the quality report read
          // "adopt audit beats=8" for a video holding seventeen clips.
          //
          // candidate.source is already the vocabulary summarizeAdoptAudit classifies (archive,
          // wikimedia, pexels, internet_archive, loc, nara, nasa, openverse, europeana), so the
          // beat lands in the right bucket without translating anything.
          recordClipAdopt(
            dedup.clipAdoptAudit, scene.index, beat.index, beat.text, clipPath,
            candidate.source, candidate.title, dedup.segmentGeoLock,
            candidate.archivePick?.asset?.id
          );
          /**
           * RONDE 166 §7 — one line saying why THIS picture is on screen.
           *
           * Printed for a plain approval too, not only for a reprieve: a log that speaks up only
           * when something is wrong cannot tell an approved beat from an unjudged one, and video
           * 554 had both. Null only when the ledger never saw the clip, which the render summary
           * already counts as a barrier bypass.
           */
          const fitLine = formatAdoptedFitDecision(
            dedup.beatRelevance, clipPath, clipContentKey(clipPath)
          );
          if (fitLine) console.log(fitLine);
          if (candidate.source !== "archive") winningExternalCandidate = candidate;
          // RONDE 62: count the moving/still split here too.
          //
          // These counters live in adoptClip, which the funnel does not go through — so render
          // 532 reported "0/4 moving" for a video holding 22 clips. The mix it printed was not a
          // measurement of the render, it was a measurement of the four clips that happened to
          // take the other route.
          if (isStillPhotoClip(clipPath) || isCuratedPreparedStillClip(clipPath)) dedup.stillClipCount++;
          else if (isRealVideoFootageClip(clipPath)) dedup.movingClipCount++;
          // RONDE 62: register the candidate's own title as provider text. Without it every
          // metadata-reading gate — off_topic_protest among them, which asked 32 times in render
          // 532 and read an empty string every time — is judging a clip it knows nothing about.
          if (candidate.title?.trim()) {
            const existingMeta = dedup.clipAnnotationMeta.get(clipPath) ?? {};
            dedup.clipAnnotationMeta.set(clipPath, {
              ...existingMeta,
              providerText: { ...existingMeta.providerText, title: candidate.title },
            });
          }
          // Register embedding similarity so AssetDirector can use it in ranking
          if (candidate.embeddingSimilarity != null) {
            const existing = dedup.clipAnnotationMeta.get(clipPath) ?? {};
            dedup.clipAnnotationMeta.set(clipPath, { ...existing, embeddingSimilarity: candidate.embeddingSimilarity });
          }
          // Compute segment similarities while beat embedding is in scope (archive only)
          if (
            archiveV4ScoringEnabled() &&
            funnelBeatEmb &&
            candidate.source === "archive" &&
            candidate.archivePick?.asset
          ) {
            const asset = candidate.archivePick.asset;
            if (asset.annotationJson?.timeline?.length) {
              const embeddingDir = `${LOCAL_UPLOADS_DIR}/archive-clip-embeddings`;
              const segSims = computeSegmentSimilarities(asset.id, asset.annotationJson, funnelBeatEmb, embeddingDir);
              if (segSims.length > 0) {
                const existing = dedup.clipAnnotationMeta.get(clipPath) ?? {};
                dedup.clipAnnotationMeta.set(clipPath, { ...existing, segmentSimilarities: segSims });
              }
            }
          }
        }

        /**
         * RONDE 165 — the beat is decided; say what became of the candidates that lost it.
         *
         * This is the route render 554's vanished list was mostly made of, and the audit line above
         * is what proved it. Beat s2b3:
         *
         *     downloaded=4 visionJudged=4 visionAccepted=4 adopted=1
         *     [VisualDiscovery] s2b3 winner=loc(score=8.0) runnerUp=archive(score=8.0)
         *
         * Four candidates fetched, four judged, four PASSED, one used. The other three were dropped
         * by `scored` going out of scope — no rejection, because nothing rejected them, and no
         * outcome either, so the ledger showed three assets selected and then simply gone.
         *
         * They get the ending they actually had. `superseded_by_winner` and `not_chosen` are kept
         * apart deliberately: "a better candidate won" is the funnel working, "the beat found no
         * winner at all" is the funnel failing, and one reason covering both would make the next
         * render's audit unreadable in exactly the way this one was.
         */
        for (const candidate of scored) {
          if (winner && candidate.clipPath === winner.clipPath) continue;
          const reason: AssetOutcomeReason = dedup.beatImageRejectedIds.has(candidate.candidate.id)
            ? "vision_rejected"
            : winner
              ? "superseded_by_winner"
              : "not_chosen";
          recordAssetOutcome(
            dedup.sourcingCache?.lineage,
            candidate.clipPath,
            reason,
            `s${scene.index}b${beat.index}`,
            // The curated archive route has no registered path — this is its only handle.
            clipContentKey(candidate.clipPath)
          );
          /**
           * RONDE 131 — a remembered asset that did not survive the gates, counted as such.
           *
           * Only `vision_rejected` counts. Losing to a better candidate is not the memory being
           * wrong, and counting it as a rejection would make the metric read as a failure rate for
           * something that is in fact the funnel doing its job.
           */
          const recalledId = candidate.candidate.archivePick?.asset?.id;
          if (
            reason === "vision_rejected" &&
            recalledId != null &&
            dedup.recalledAssetIds.has(recalledId)
          ) {
            dedup.searchMemoryMetrics.memoryRejectedAfterValidation++;
          }
        }

        // [VisualDiscovery] audit line — counts + per-source scores + winner, one line per beat.
        // FASE 2 / STAP 13: also report runner-up score, whether a stock source won, and whether
        // this beat's winner is queued for archive-ingestion (best-effort, background — see below;
        // "archiving" here means "attempted", not "confirmed written", since ingest runs async).
        /**
         * RONDE 631 — THE PICTURE EDITOR'S REFUSAL REACHES THE ARCHIVE.
         *
         * `visionResult.pass` is the FUNNEL's verdict, a CLIP-similarity score. The beat image
         * gate is a second, later judgement — a model that looks at the frames — and it records
         * its refusals in `dedup.beatImageRejectedIds`. `pickBestFunnelCandidate` reads both and
         * is right to; this line read only the first.
         *
         * Render 599, scene 1 beat 1, the same second in the same log:
         *
         *     …providerAssetId=OqFhvKarYjU stage=REMOVED status=REJECTED reason=vision_rejected:s1b1
         *     …providerAssetId=rPCWO-wZaLo stage=REMOVED status=REJECTED reason=vision_rejected:s1b1
         *     [Ingestion] s1b1 keeping 2 approved runner-up clip(s) the picture editor passed
         *
         * The picture editor did not pass them. It refused both, with reasons — a young German
         * soldier wearing an Iron Cross, and a map of the 1st Belorussian Front, against narration
         * about the orders Hitler issued in the bunker. They were nonetheless queued into the
         * CURATED ARCHIVE, which is source #2, to be offered again on the next render as approved
         * archive material.
         *
         * So the same answer was computed on one side and not handed to the side that decides —
         * this codebase's signature defect, and the reason it matters here is that the archive is
         * the one store whose contents outlive the render that made them.
         *
         * Both readers of `passingScored` want the same exclusion. The archive must not be seeded
         * with a refused picture; and a "runner-up" the gate refused is not a runner-up, so the
         * `[VisualDiscovery]` line stops naming one as though it were the beat's second choice.
         *
         * NOTHING IS LOOSENED. This removes clips from a set; it admits none. No threshold moves,
         * no gate is added, and `winner` is chosen exactly as before by `pickBestFunnelCandidate`,
         * which already applied this same exclusion.
         */
        const passingScored = scored
          .filter(s => s.visionResult.pass)
          .filter(s => !dedup.beatImageRejectedIds.has(s.candidate.id));
        const runnerUp = winner
          ? passingScored
              .filter(s => s !== winner)
              .reduce<ScoredFunnelCandidate | null>(
                (best, s) =>
                  !best || (s.visionResult.worstScore10 ?? 0) > (best.visionResult.worstScore10 ?? 0)
                    ? s
                    : best,
                null
              )
          : null;
        const stockWon = winner
          ? winner.candidate.source === "pexels" || winner.candidate.source === "pixabay"
          : false;
        // RONDE 9 (render 519 + admin screenshot): stock footage is NEVER archive material — a
        // generic Pexels clip that happened to win a Hitler beat was ingested tagged "adolf
        // hitler", then outranked real archival footage on every later Hitler render (the
        // self-poisoning loop). Only authentic sources may enter the curated archive.
        const archiveEligible = !!(
          funnelClip &&
          winningExternalCandidate &&
          externalAssetIngestionEnabled() &&
          /**
           * Same rule, now asked of the one predicate the scene-pool route can ask too. The set is
           * unchanged: `winningExternalCandidate` is only ever set for a non-archive candidate, so
           * the `archive` arm of the predicate is a no-op here and carries the rule for the other
           * caller.
           */
          sourceMayEnterCuratedArchive(winningExternalCandidate.source)
        );
        const willArchive = archiveEligible;
        // FASE 4: sourceDistribution reports which sources actually made the download
        // shortlist (toScore), not the full discovered pool — this is what shows whether
        // buildDownloadShortlist()'s diversity caps are doing their job in practice.
        const sourceDistribution = toScore.reduce<Record<string, number>>((acc, c) => {
          acc[c.source] = (acc[c.source] ?? 0) + 1;
          return acc;
        }, {});
        /**
         * RONDE 164 — one line saying whether this beat lost candidates or was given bad ones.
         *
         * [VisualDiscovery] below reports the same render from the winner's side. This reports it
         * from the funnel's, which is the side that says which constraint bound: a beat that never
         * reached VisionGate needs the funnel widened, one whose candidates VisionGate refused
         * needs better candidates. Nothing here is computed — every value was in hand already.
         */
        recordBeatOutcome(sourcingAudit, {
          candidatesFound: candidatesFoundForBeat,
          downloaded: downloadedCount,
          visionJudged: scored.length,
          visionAccepted: scored.filter((sc) => sc.visionResult.pass).length,
          adopted: Boolean(winner),
        });
        dedup.archiveSourcingAudits.push(sourcingAudit);
        console.log(
          formatArchiveSourcingAudit(`s${scene.index}b${beat.index}`, sourcingAudit)
        );
        console.log(
          `[VisualDiscovery] s${scene.index}b${beat.index} discovered=${discoveredCount} ` +
          `shortlist=${shortlistCount} downloaded=${downloadedCount} scored=${scored.length} ` +
          `sources={${Object.entries(sourceDistribution).map(([s, n]) => `${s}:${n}`).join(",")}} ` +
          `scores={${scored.map(s => `${s.candidate.source}:${(s.visionResult.worstScore10 ?? 0).toFixed(1)}`).join(",")}} ` +
          `winner=${winner ? `${winner.candidate.source}(score=${(winner.visionResult.worstScore10 ?? 0).toFixed(1)})` : "none(fallback)"} ` +
          `runnerUp=${runnerUp ? `${runnerUp.candidate.source}(score=${(runnerUp.visionResult.worstScore10 ?? 0).toFixed(1)})` : "none"} ` +
          `stockWon=${stockWon} archiving=${willArchive}`
        );

        /**
         * SELF-LEARNING — WHAT THE ARCHIVE IS ALLOWED TO KEEP.
         *
         * ── What it kept before, and what that cost ─────────────────────────────────────────
         *
         * One clip per beat: the winner. Everything else the funnel downloaded and the picture
         * editor APPROVED was deleted with the work directory when the render ended.
         *
         * Render 576 is the shape of that. Three hundred and eleven downloads, fourteen clips in
         * the film, and — measured in its own log — not one `[Ingestion]` line, because the beats
         * whose winner came from the curated archive have no external winner to ingest at all.
         * Every approved runner-up from Wikimedia, the Internet Archive and Library of Congress
         * was fetched, judged good, and thrown away. The next render started from nothing and
         * fetched them again.
         *
         * ── What changes, and what deliberately does not ─────────────────────────────────────
         *
         * A clip is kept when the picture editor said it FITS — `visionResult.pass` — and it lost
         * the beat only because another approved clip scored higher. Losing to a better picture is
         * not a verdict on this one; RONDE 131 already says so in as many words about search
         * memory ("Losing to a better candidate is not the memory being wrong").
         *
         * Nothing else moves. A clip Vision refused is still refused and still discarded. Pexels
         * and Pixabay are still barred outright — RONDE 9's self-poisoning loop, where a generic
         * stock clip tagged "adolf hitler" outranked real archive footage on every later render,
         * is exactly the failure this must not reintroduce. `archive` candidates are skipped
         * because they are already in it. And ingestion still runs behind its own semaphore of
         * two, best-effort, never blocking a render.
         */
        const beatQuery = beat.searchQuery?.trim() || beat.text;
        /**
         * The metadata both archive routes send, built once.
         *
         * It used to live inside `queueArchiveIngestion`, which was the only caller. The winner now
         * goes through `storeForProduction` instead — a different function with the same metadata —
         * and two copies of this literal is two chances for the winner and the runners-up to be
         * archived under different provenance. Lifted, not rewritten: every field below is the one
         * that was there, with its reasoning.
         */
        const archiveFactsFor = (
          wec: NonNullable<typeof winningExternalCandidate>
        ): ExternalClipArchiveFacts => ({
          source: wec.source,
          providerAssetId: String(wec.poolCandidate?.id ?? wec.id ?? "").trim() || null,
          title: wec.title,
          mediaType: wec.mediaType,
          license: wec.poolCandidate?.license ?? null,
          licenseUrl: wec.poolCandidate?.licenseUrl ?? null,
          durationSec: wec.poolCandidate?.durationSec ?? null,
          sourceCreator: wec.poolCandidate?.sourceCreator ?? null,
          remoteUrl: wec.poolCandidate?.remoteUrl ?? null,
        });
        const archiveMetadataFor = (
          wec: NonNullable<typeof winningExternalCandidate>
        ): ProductionArchiveMetadata =>
          archiveMetadataForExternalClip(archiveFactsFor(wec), {
            beatQuery,
            personContext: Boolean(dedup.personTopicLock && dedup.primaryPerson),
            topics: beat.keywords ?? [],
          });
        const queueArchiveIngestion = (
          clipPath: string,
          wec: NonNullable<typeof winningExternalCandidate>
        ): void => {
          void (async () => {
            try {
              await ingestExternalClipToArchive(clipPath, archiveMetadataFor(wec));
            } catch {
              // best-effort: never block video production
            }
          })();
        };

        /**
         * THE WINNER IS STORED BEFORE THE TIMELINE IS ALLOWED TO NAME IT.
         *
         * ── The defect this replaces ────────────────────────────────────────────────────────
         *
         * This line used to be `queueArchiveIngestion(funnelClip, winningExternalCandidate)` — the
         * same fire-and-forget call as the runners-up below. `ingestExternalClipToArchive` returns
         * `{ assetId, storageKey }`, and that assetId is `AssetSourceIdentity.archiveAssetId`: the
         * first branch `rehydrateAsset` tries, the one route that cannot fail because a provider's
         * API changed. It was computed at the only site that could produce one for an external
         * provider, thrown away, and not even waited for.
         *
         * So every external clip reached the renderer carrying a provider id and nothing of ours.
         * When the pool had recorded no remote URL either, the identity had no fetchable handle at
         * all, and the render died on `ASSET_NOT_FOUND … has no fetchable URL`.
         *
         * ── Why the winner is awaited and the runners-up are not ────────────────────────────
         *
         * The winner is the clip this beat is going to USE. Its archive id has to exist before the
         * cinematic planner reads this beat's identity, which happens later in the same render —
         * so the store is awaited, and its handle is attached to the lineage record the planner
         * reads from. The runners-up are kept for FUTURE renders' searches; nothing in this render
         * waits on them, and they stay exactly as best-effort as they were.
         *
         * ── What a failure does, and deliberately does not do ───────────────────────────────
         *
         * It does not stop the render and it does not invent a reference. The beat keeps the
         * identity it already had — provider, id, media URL — which is precisely what it had before
         * this round, so a storage outage costs the render its archive handle and nothing else.
         * What it gains is that the failure is named: `ARCHIVE_STORE_FAILED` with its code, at the
         * moment it happens, instead of an `ASSET_NOT_FOUND` twenty minutes later with no way back
         * to the cause.
         */
        if (archiveEligible && funnelClip && winningExternalCandidate) {
          await storeExternalClipForTimeline({
            clipPath: funnelClip,
            facts: archiveFactsFor(winningExternalCandidate),
            metadata: archiveMetadataFor(winningExternalCandidate),
            lineage: dedup.sourcingCache?.lineage,
            workDir,
            sceneIndex: scene.index,
            beatIndex: beat.index,
            route: "funnel",
          });
        }

        /**
         * The approved runners-up, kept for the same reasons and under the same rules.
         *
         * Guarded on their own rather than on `archiveEligible`: that flag requires the WINNER to
         * have been external, so a beat won by the curated archive would otherwise discard every
         * approved Wikimedia or YouTube clip beside it — which is the case render 576 was full of.
         *
         * Bounded without a new budget: `passingScored` cannot exceed the beat's existing shortlist
         * cap, and `ingestExternalClipToArchive` already serialises behind a semaphore of two.
         */
        let approvedKept = 0;
        if (externalAssetIngestionEnabled()) {
          for (const s of passingScored) {
            if (s === winner) continue;
            const src = s.candidate.source;
            /** RONDE 9's rule, unchanged: stock footage is never archive material. */
            if (src === "pexels" || src === "pixabay") continue;
            /** Already in the archive — ingesting it again would be a duplicate of itself. */
            if (src === "archive") continue;
            if (!s.clipPath) continue;
            queueArchiveIngestion(s.clipPath, s.candidate);
            approvedKept += 1;
          }
        }
        if (approvedKept > 0) {
          console.log(
            `[Ingestion] s${scene.index}b${beat.index} keeping ${approvedKept} approved ` +
              `runner-up clip(s) the picture editor passed — they lost the beat, not the judgement`
          );
        }

        if (funnelClip) {
          clip = funnelClip;
        } else {
          clip = await withSceneFetchTimeout(
            () => resolveBeatClip(beat, scene, workDir, scene.index, clipFetchDur, dedup, {
              spaceTopic, personName, videoTitle, adoptOpts: beatAdoptOpts,
              scenePersons, tag: `b${beat.index}`, stockReason: "funnel fallback",
            }),
            beatWallMs,
            `scene ${scene.index} beat ${bi} visuals (funnel fallback)`
          );
        }
      } else if (scenePool && scenePool.candidates.length > 0) {
        // P1: try pool candidate first (no extra API calls), fall back to normal retrieval
        // P2: when thumbnail ranking is enabled, rerank by CLIP before downloading
        /**
         * RONDE 180 — the selection context this call never had.
         *
         * ── What was inert, and why nothing failed ─────────────────────────────────────────
         *
         * This is the ONLY production call to `selectCandidatesFromPool`, and it passed no `ctx`.
         * Two whole features hung off that argument:
         *
         *   · R160 FASE 7's thirteen-signal ranking engine, which only runs `if (poolRankingV2
         *     Enabled() && ctx?.intent)`. Without an intent the pool fell back to the local scorer
         *     that counts shared word-stems and knows nothing about source priority, motion,
         *     aspect, duration fit or what shot the Director asked for.
         *   · R170's duplicate penalty, which needs `ctx.usageLedger`. Without a ledger there is
         *     nothing to be a duplicate OF, so the same shot could come back in three scenes with
         *     no penalty at any of them.
         *
         * Both were built, tested and unreachable. The flag still decides whether V2 ranking runs
         * — `poolRankingV2Enabled` follows the cinematic route — so this hands over the inputs and
         * changes nothing on a deployment that has not turned it on.
         *
         * The intent comes from `intentFrom`, the same builder the cinematic plan uses, with the
         * same extractors. A second intent builder here would let the ranking and the plan describe
         * different beats.
         */
        const rankingIntent = intentFrom(
          {
            index: beat.index,
            text: beat.text,
            searchQuery: beat.searchQuery,
            powerWord: beat.powerWord,
            keywords: beat.keywords,
            holdSec: beat.holdSec,
            visualDescription: beat.visualDescription,
          },
          scene.index,
          beat.index,
          /** No adoption yet — this runs to CHOOSE one. `intentFrom` handles that by design. */
          null,
          {
            people: (t) => extractPersonNamesFromText(t),
            place: (t) => extractVisualPlacePhrase(t),
            action: (t) => extractActionCue(t),
            namedEntities: (t) => beatNamedEntitiesByKind(t),
            secondarySubjects: (t) => extractSecondaryEntities(t, personName || undefined),
          }
        );
        let poolCandidates = selectCandidatesFromPool(
          beat.text,
          beat.powerWord,
          beat.keywords,
          scenePool,
          poolThumbnailRankingEnabled() ? 8 : 3,  // fetch more candidates for P2 to rerank
          {
            intent: rankingIntent,
            targetDurationSec: beat.holdSec,
            /**
             * RONDE 180 — the entities the beat proved, so a candidate that names one is preferred.
             *
             * The same expression `v2Pipeline` uses, not a new one. It is only worth anything since
             * R177 filled `objects`, `brands` and `companies`: before that this list was always
             * just the people, and the entityMatch signal had almost nothing to match on.
             */
            entityTerms: [
              ...rankingIntent.people,
              ...rankingIntent.objects,
              ...rankingIntent.brands,
              ...rankingIntent.companies,
            ],
            usageLedger: dedup.usageLedger,
            at: { sceneIndex: scene.index, beatIndex: beat.index },
            /**
             * WHAT KIND OF PICTURE THIS BEAT NEEDS, so the source table can answer for this beat.
             *
             * Without it `contextualSourcePriority` falls back to `DEFAULT_SOURCE_PRIORITY` — one
             * fixed order for every beat of every topic, in which pexels (80) and pixabay (70) sit
             * above both archives even on a beat dated to 1945. This is the writer for that reader:
             * a need built here, from the beat's own typed terms, and read by the ranking engine.
             *
             * A beat whose extractors typed nothing produces an empty `preferred`, and the engine
             * then gets exactly the table it had before.
             */
            mediaFormNeed: mediaFormsForIntent(
              beatVisualIntent(dedup.beatIntent, scene.index, beat.index)
            ),
          }
        );
        if (poolThumbnailRankingEnabled() && poolCandidates.some(c => c.thumbnailUrl)) {
          poolCandidates = await rankCandidatesByThumbnailClip(
            poolCandidates,
            beat.text,
            beat.visualDescription,
            videoTitle,
            scene.index,
            beat.index
          );
          poolCandidates = poolCandidates.slice(0, 3);
        }
        /**
         * THE DIVERSITY CAP THE SIBLING ROUTE HAS ALWAYS HAD — see `shortlistCapForSource`.
         *
         * This loop downloads until one file survives technically, and until now it did so with no
         * per-source rule, so all of a beat's download attempts could come from one library. The
         * funnel's shortlist has capped exactly this since FASE 4 (stock 1, non-stock 2, archive 3,
         * YouTube by its own setting) and gives unused room back to the non-stock overflow.
         *
         * Render 593 is the measurement: 206 Pexels downloads and 0 Pexels adoptions across twenty
         * beats. One slot per beat is twenty; the pool route is where the other ~186 came from.
         *
         * NO PROVIDER IS SWITCHED OFF, no key is read, no gate moves, and the budget below is
         * unchanged. A beat whose pool holds nothing but one source still asks that source, and a
         * beat this leaves empty falls through to the cascade and the rescue ladder exactly as a
         * beat that found nothing always has.
         */
        {
          const before = poolCandidates.length;
          poolCandidates = capCandidatesPerSource(poolCandidates, before);
          if (poolCandidates.length < before) {
            console.log(
              `[Pool] s${scene.index}b${beat.index} download slots capped by source diversity: ` +
                `${before} → ${poolCandidates.length} ` +
                `(${poolCandidates.map((c) => c.source).join(", ") || "none"})`
            );
          }
        }
        let poolClip: string | null = null;
        let _poolFailReasons: string[] = [];
        for (const candidate of poolCandidates) {
          /**
           * THE LADDER, ASKED AT THE OTHER END OF THE POOL.
           *
           * A pool candidate's provider search happened one scope up, for the whole scene, so by
           * the time a beat picks one there is no query left for `searchGateDecision` to refuse.
           * This is the same question asked where the beat actually spends the tier: the download.
           *
           * Before the integrity audit this was the pipeline's main route to a picture and it
           * asked nothing at all — a Pexels candidate became the beat's clip whether or not the
           * scene had ever reached YouTube, the archive or the open collections. A refusal here
           * skips the candidate; the loop simply tries the next one, which is by construction from
           * a tier the ladder does allow, and an empty shortlist falls through to the cascade that
           * walks the ladder properly.
           */
          const tierVerdict = admitPoolCandidateTier(candidate.source);
          if (!tierVerdict.admitted) {
            const reason =
              `${candidate.source}:${candidate.assetId.slice(0, 20)} refused — ${tierVerdict.reason}` +
              (tierVerdict.skipped.length > 0 ? ` (skips ${tierVerdict.skipped.join(",")})` : "");
            _poolFailReasons.push(reason);
            console.log(`[Retry] s${scene.index}b${beat.index} pool candidate rejected — ${reason}`);
            continue;
          }
          const _cT0 = Date.now();
          poolClip = await downloadAndTrimPoolCandidate(candidate, workDir, scene.index, beat.index, beat.holdSec, dedup.sourcingCache);
          if (poolClip) break;
          const reason = `${candidate.source}:${candidate.assetId.slice(0,20)} failed in ${Date.now()-_cT0}ms`;
          _poolFailReasons.push(reason);
          console.log(`[Retry] s${scene.index}b${beat.index} pool candidate rejected — ${reason}`);
        }
        if (poolClip) {
          clip = poolClip;
          // RONDE 51: the scene-pool path adopted clips without ever recording the adoption.
          // scenePool.ts contains no recordClipAdopt call at all, and this is the only place a
          // pool candidate becomes the beat's clip — so every `*_pool_*` clip was invisible to
          // the adopt audit. Render 530 shipped 19 clips of which 10 were pool clips, and the
          // quality gate judged the render on the 13 beats it could see, reporting
          // "wiki=0 stock=0" while three Wikimedia and six Pexels clips were in the video.
          const adopted = poolCandidates.find(
            // ascii-safe: reproduces the filename written by the line below, character for character.
            (c) => poolClip!.includes(c.assetId.replace(/[^a-z0-9]/gi, "_").slice(0, 30))
          ) ?? poolCandidates[0];
          /**
           * THE ARCHIVE, BEFORE THE ADOPTION IS RECORDED — the invariant this route never had.
           *
           * The funnel has stored its winner and carried the handle since the handle existed. This
           * route did not, and `storeForProduction`'s single call site was behind the funnel's own
           * `winningExternalCandidate`, so a clip that won HERE reached the timeline with a
           * provider id and nothing of ours. YouTube lives in this pool (RONDE 175), and
           * `assetRehydrator` reads `archiveAssetId` first — so without it a later re-render has
           * to reach YouTube again, through an egress that is measurably blocked at intervals.
           *
           * Awaited, and placed BEFORE `recordClipAdopt`, because the brief's requirement is that
           * the handle exists before the clip is an adopted timeline asset — not that it is
           * attempted afterwards and hoped for. It is the same function, the same predicate and
           * the same provenance the funnel uses; nothing here is a second archive path.
           *
           * The file is the one the beat already downloaded and trimmed. Nothing is fetched twice,
           * and `storeForProduction` answers the "already archived?" question itself — by checksum
           * and by (provider, providerAssetId), both requiring `mediaStatus = READY`.
           */
          if (
            adopted &&
            externalAssetIngestionEnabled() &&
            sourceMayEnterCuratedArchive(adopted.source)
          ) {
            const facts: ExternalClipArchiveFacts = {
              source: adopted.source,
              /** The pool's own stable key `${source}:${assetId}`, which is what the funnel stores too. */
              providerAssetId: String(adopted.id ?? adopted.assetId ?? "").trim() || null,
              title: adopted.title,
              mediaType: adopted.mediaType,
              license: adopted.license,
              licenseUrl: adopted.licenseUrl,
              durationSec: adopted.durationSec,
              sourceCreator: adopted.sourceCreator,
              remoteUrl: adopted.remoteUrl,
            };
            await storeExternalClipForTimeline({
              clipPath: poolClip,
              facts,
              metadata: archiveMetadataForExternalClip(facts, {
                beatQuery: beat.searchQuery?.trim() || beat.text,
                personContext: Boolean(dedup.personTopicLock && dedup.primaryPerson),
                topics: beat.keywords ?? [],
              }),
              lineage: dedup.sourcingCache?.lineage,
              workDir,
              sceneIndex: scene.index,
              beatIndex: beat.index,
              route: "pool",
            });
          }
          recordClipAdopt(
            dedup.clipAdoptAudit, scene.index, beat.index, beat.text, poolClip,
            adopted?.source ?? "pool", adopted?.title, dedup.segmentGeoLock
          );
          /**
           * RONDE 180 — the ledger only means something if adoptions are written to it.
           *
           * Recorded at the moment the candidate BECOMES the beat's clip, not when it was ranked:
           * a candidate that was considered and rejected is not a use, and counting it would make
           * the next beat avoid a shot this video never showed.
           *
           * Provider + provider asset id, never the path — the same identity `assetKey` is built
           * from, so two downloads of one source video collapse to one entry.
           */
          if (adopted) {
            recordUse(
              dedup.usageLedger,
              { provider: adopted.source, providerAssetId: adopted.assetId },
              { sceneIndex: scene.index, beatIndex: beat.index }
            );
            /**
             * RONDE 202 — the [Selection] line: WHICH asset won this beat, and why.
             *
             * ── What was missing ───────────────────────────────────────────────────────────
             *
             * `formatSelection` was written in R172 for exactly this and had no caller anywhere
             * but its own test. So a render could say a clip was adopted and never say what it
             * beat or by how much — and "why is this picture on screen" was answerable only by
             * re-running the ranking by hand.
             *
             * The runner-up is the second candidate the SELECTOR returned, which is the one this
             * beat would have used had the winner failed to download. That margin is the honest
             * answer to "why not something better": a 0.002 margin and a 0.30 margin are the
             * difference between a coin toss and a decision.
             *
             * Every value here is scrubbed by `formatSelection` itself — a provider name and an
             * asset id are how you find the asset again, and neither is a secret.
             */
            const runnerUp = poolCandidates.find((c) => c !== adopted);
            console.log(
              formatSelection({
                renderId: dedup.sourcingCache?.lineage?.renderId ?? "-",
                sceneIndex: scene.index,
                beatIndex: beat.index,
                ...(beat.searchQuery ? { query: beat.searchQuery } : {}),
                provider: adopted.source,
                providerAssetId: adopted.assetId,
                ...(adopted.rankingScore != null ? { score: adopted.rankingScore } : {}),
                ...(runnerUp
                  ? {
                      runnerUpProvider: runnerUp.source,
                      ...(runnerUp.rankingScore != null ? { runnerUpScore: runnerUp.rankingScore } : {}),
                    }
                  : {}),
              })
            );
          }
        } else {
          /**
           * RONDE 176 — the cascade is a FALLBACK, and it says so in the agreed vocabulary.
           *
           * The route above is already pool-first: the cascade is only reached when every pool
           * candidate failed to DOWNLOAD, never because the ranking preferred something else. What
           * was missing is a log line that names which of the three things happened, so a
           * production log can distinguish "the pool found nothing" from "the pool found things and
           * none of them could be fetched" — two very different problems that used to read the same.
           */
          console.log(
            formatFallback({
              renderId: dedup.sourcingCache?.lineage?.renderId ?? "-",
              what: `retrieval s${scene.index}b${beat.index}`,
              from: "pool",
              to: "cascade",
              why:
                poolCandidates.length === 0
                  ? "POOL_EMPTY: the pool produced no candidate for this beat"
                  : `CASCADE_FALLBACK: all ${poolCandidates.length} pool candidate(s) failed to download` +
                    (_poolFailReasons.length > 0 ? ` — ${_poolFailReasons.join(" | ")}` : ""),
            })
          );
          if (_poolFailReasons.length > 0) {
            console.log(`[Retry] s${scene.index}b${beat.index} all ${_poolFailReasons.length} pool candidate(s) failed — falling back to per-beat retrieval. Reasons: ${_poolFailReasons.join(" | ")}`);
          }
          // Pool candidates failed to download — fall back to unified retrieval
          clip = await withSceneFetchTimeout(
            () => resolveBeatClip(beat, scene, workDir, scene.index, clipFetchDur, dedup, {
              spaceTopic, personName, videoTitle, adoptOpts: beatAdoptOpts,
              scenePersons, tag: `b${beat.index}`, stockReason: "pool fallback",
            }),
            beatWallMs,
            `scene ${scene.index} beat ${bi} visuals (pool fallback)`
          );
        }
      } else {
        clip = await withSceneFetchTimeout(
          () => resolveBeatClip(beat, scene, workDir, scene.index, clipFetchDur, dedup, {
            spaceTopic, personName, videoTitle, adoptOpts: beatAdoptOpts,
            scenePersons, tag: `b${beat.index}`,
          }),
          beatWallMs,
          `scene ${scene.index} beat ${bi} visuals`
        );
      }
    } catch (err) {
      console.warn(
        `[Pipeline] Scene ${scene.index} beat ${beat.index}: capped at ${Math.round(beatWallMs / 1000)}s:`,
        (err as Error).message
      );
      /** The beat's own search ran out of time: the next sources only, no repeat of it and no AI clip. */
      if (
        !youtubeOnlySourcingEnabled() &&
        (!clip || isPipelineFallbackClip(clip)) &&
        canUseLicensedStockBeat(dedup)
      ) {
        clip = await fetchBeatStockFallback(
          beat, scene, workDir, scene.index, clipFetchDur, dedup, personName, videoTitle, beatAdoptOpts, "beat cap"
        );
      }
      if (
        !youtubeOnlySourcingEnabled() &&
        (!clip || isPipelineFallbackClip(clip)) &&
        canUseGlobalStillPhoto(dedup)
      ) {
        clip = dedup.perf.fastStockMode
          ? await fetchBeatScriptImageForced(
              beat, scene, workDir, scene.index, clipFetchDur, dedup, scenePersons, videoTitle, `b${beat.index}_cap`
            )
          : await fetchBeatScriptImageClip(
              beat,
              scene,
              workDir,
              scene.index,
              clipFetchDur,
              dedup,
              scenePersons,
              videoTitle,
              { ...beatAdoptOpts, scriptImageFallback: true },
              `b${beat.index}_cap`
            );
      }
    } finally {
      clearInterval(beatPulse);
    }

    

    if (clip && !isPipelineFallbackClip(clip)) {
      if (realOnly && isLicensedStockClip(clip) && !canUseLicensedStockBeat(dedup)) {
        clip = null;
      } else {
        clip = await applyVideoBeatTextOverlay(clip, beat, scene, workDir, beat.holdSec, dedup.perf.fastStockMode, dedup.beatRelevance, dedup.sourcingCache?.lineage);
        await withAdoptionIntent("beat_fetch", () => pushClip(clip!));
      }
    }
    if (!clip || isPipelineFallbackClip(clip)) {
      let rescue: string | null = null;
      /** The beat's own search found nothing usable: the next sources once — no repeat, no AI clip. */
      if (
        !youtubeOnlySourcingEnabled() &&
        (!rescue || isPipelineFallbackClip(rescue)) &&
        canUseLicensedStockBeat(dedup)
      ) {
        rescue = await fetchBeatStockFallback(
          beat, scene, workDir, scene.index, clipFetchDur, dedup, personName, videoTitle, beatAdoptOpts, "miss"
        );
      }
      if ((!rescue || isPipelineFallbackClip(rescue)) && canUseGlobalStillPhoto(dedup)) {
        rescue = await fetchBeatScriptImageClip(
          beat,
          scene,
          workDir,
          scene.index,
          clipFetchDur,
          dedup,
          scenePersons,
          videoTitle,
          { ...beatAdoptOpts, scriptImageFallback: true },
          `b${beat.index}_miss`
        );
      }
      if ((!rescue || isPipelineFallbackClip(rescue)) && canUseGlobalStillPhoto(dedup)) {
        rescue = await fetchBeatScriptImageForced(
          beat, scene, workDir, scene.index, clipFetchDur, dedup, scenePersons, videoTitle, `b${beat.index}_miss`
        );
      }
      if (rescue && !isPipelineFallbackClip(rescue)) {
        const withText = await applyVideoBeatTextOverlay(rescue, beat, scene, workDir, beat.holdSec, dedup.perf.fastStockMode, dedup.beatRelevance, dedup.sourcingCache?.lineage);
        await withAdoptionIntent("script_image", () => pushClip(withText));
      } else {
        /** A gap, with the refusals that made it — what `[VisualCoverage]` printed from the rescue ladder. */
        const topRejects =
          beatRejectReasons(dedup.clipRejectAudit, scene.index, beat.index)
            .slice(0, 3)
            .map(([reason, count]) => `${reason}:${count}`)
            .join(",") || "none";
        console.warn(
          `[VisualCoverage] s${scene.index}b${beat.index}: no picture — gap ` +
            `rejected=${beatRejectCount(dedup.clipRejectAudit, scene.index, beat.index)} topRejects=${topRejects}`
        );
      }
    }
  }
  } finally {
    /** The last beat's ladder, and any beat the loop left through a throw. */
    closeBeatLadder?.();
  }

  

  const videoCount = clips.filter((c) => !isStillPhotoClip(c)).length;
  const photoCount = clips.filter((c) => isStillPhotoClip(c)).length;
  const personLabel = scenePersons.length > 0 ? ` [persons: ${scenePersons.join(", ")}]` : "";
  /**
   * The scene's beats have each been asked once. What stood here asked again — a backfill loop of
   * up to N "rescue" fetches, a forced clip / stock / script-image round, and
   * `recoverSceneClipsIfEmpty` — the same sources with the same inputs. A beat with no picture is
   * a gap the timeline holds over; a scene with none is reported and left empty.
   */
  const usable = clips.filter((c) => c && !isPipelineFallbackClip(c));
  if (usable.length === 0) {
    console.warn(`[Pipeline] Scene ${scene.index}: no beat clips — the timeline holds the previous shot`);
  }

  console.log(
    `[Pipeline] Scene ${scene.index}${personLabel}: ${usable.length} beat clip(s) (${videoCount} video, ${photoCount} photo)`
  );
  await assertSceneVisualInventory(scene, usable, beatDurations.slice(0, usable.length), 0, undefined, videoTitle);
  return { clips: usable, beatDurations: beatDurations.slice(0, usable.length) };
}

export async function probeVideoDurationSec(filePath: string): Promise<number> {
  for (const probe of FFPROBE_PATHS()) {
    try {
      // Route through exec() (semaphore-gated + fork-pressure retry with backoff) instead of
      // calling execRaw directly — under heavy concurrent ffmpeg/ffprobe load (e.g. visual
      // sourcing prefetching in the background during TTS), a bare unthrottled, un-retried probe
      // can transiently fail with EAGAIN/"cannot fork" and get silently swallowed by the catch
      // below, making a perfectly good audio file look like it "has no duration". 30s (vs the
      // old 10s) leaves room for exec()'s own retry backoff to actually pay off before this
      // path's attempt is abandoned in favor of the next FFPROBE_PATHS() candidate.
      const { stdout } = await withSceneFetchTimeout(
        () => exec(`"${probe}" -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${filePath}"`),
        30_000,
        `probeVideoDurationSec ${path.basename(filePath)}`
      );
      const d = parseFloat(String(stdout).trim());
      if (!isNaN(d) && d > 0) return d;
    } catch { /* try next */ }
  }
  return 0;
}

/**
 * How long the PICTURE lasts, which is not the same as how long the file lasts.
 *
 * RONDE 158 — the difference between the two is the defect. A scene muxed from a montage shorter
 * than its voice has a container of the full length and a video stream that stops early; a player
 * holds the last frame across the difference, and the final concat turns that hold into real
 * duplicated frames. `format=duration` reports the container and therefore reads such a scene as
 * complete, which is why every check that used it saw nothing wrong.
 *
 * Falls back to frame count over frame rate when the stream carries no duration of its own, and
 * returns 0 when neither can be read — never a guess, because a guessed length here would silently
 * disable the repair that depends on it.
 */
export async function probeVideoStreamDurationSec(filePath: string): Promise<number> {
  for (const probe of FFPROBE_PATHS()) {
    try {
      const { stdout } = await withSceneFetchTimeout(
        () => exec(
          `"${probe}" -v error -select_streams v:0 -show_entries stream=duration,nb_frames,avg_frame_rate ` +
            `-of default=noprint_wrappers=1 "${filePath}"`
        ),
        30_000,
        `probeVideoStreamDurationSec ${path.basename(filePath)}`
      );
      // Read by key: ffprobe emits these in ITS order (avg_frame_rate first), not the requested
      // one, so positional parsing silently returns a frame rate where a duration belongs.
      const fields = new Map<string, string>();
      for (const line of String(stdout).trim().split(/\r?\n/)) {
        const eq = line.indexOf("=");
        if (eq > 0) fields.set(line.slice(0, eq).trim(), line.slice(eq + 1).trim());
      }
      const direct = parseFloat(fields.get("duration") ?? "");
      if (!isNaN(direct) && direct > 0) return direct;
      // MP4 from some encoders reports stream duration as N/A; frames ÷ rate is exact enough.
      const frames = parseInt(fields.get("nb_frames") ?? "", 10);
      const [num, den] = (fields.get("avg_frame_rate") ?? "").split("/").map((v) => parseFloat(v));
      if (!isNaN(frames) && frames > 0 && num && den) {
        const fps = num / den;
        if (fps > 0) return frames / fps;
      }
    } catch { /* try next */ }
  }
  return 0;
}

/** Trim leading/trailing silence so scenes concatenate without dead air. */
async function trimVoiceoverSilence(audioPath: string): Promise<number> {
  if (!fs.existsSync(audioPath)) return 0;
  const tmpPath = audioPath.replace(/\.mp3$/i, "_trim.mp3");
  try {
    await withSceneFetchTimeout(
      () => exec(
        `${FFMPEG_BIN} -y -i "${audioPath}" -af ` +
        `"silenceremove=start_periods=1:start_duration=0.06:start_threshold=-42dB:detection=peak,` +
        `areverse,silenceremove=start_periods=1:start_duration=0.1:start_threshold=-42dB:detection=peak,areverse" ` +
        `-c:a libmp3lame -b:a 192k "${tmpPath}"`
      ),
      45_000,
      "Trim voiceover silence"
    );
    if (fs.existsSync(tmpPath) && fs.statSync(tmpPath).size > 400) {
      fs.unlinkSync(audioPath);
      fs.renameSync(tmpPath, audioPath);
    } else if (fs.existsSync(tmpPath)) {
      try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
    }
  } catch (err) {
    console.warn(`[Pipeline] Voice trim skipped for ${path.basename(audioPath)}:`, (err as Error).message);
    try { if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
  const probed = await probeVideoDurationSec(audioPath);
  return probed > 0 ? probed : 0;
}

// ─── 7. Final Concatenation + Music Mix ───────────────────────────────────────

// ─── Main Pipeline ────────────────────────────────────────────────────────────
export async function runVideoPipeline(
  videoId: number,
  script: string,
  onProgress?: (p: PipelineProgress) => void,
  voiceId?: string,
  customVoiceoverUrl?: string,
  videoLength: string = "8-10",
  enableSubtitles = false,  // Subtitles disabled by default — user can enable via UI
  userPrompt?: string
): Promise<string> {
  // Each render gets its own context so concurrent renders never share singleton state.
  const renderCtx: RenderCtx = {
    watchdog: null,
    renderBudget: null,
    budgetTracker: null,
    barrierPassedUnjudged: 0,
    barrierChecked: 0,
    videoTopic: null,
    videoVisualContext: null,
    voiceoverSilentFallbackNotes: [],
    elevenLabsQuotaExhausted: false,
    sourcingCache: null,
    /** Filled in where the visual dedup state is built — see RONDE 231 there. */
    beatBudget: null,
  };
  // runWithActiveVideoId makes videoId/userId readable from ANY module in this render's call
  // tree (including localClipVision.ts and llm.ts, which can't import from here — see exec()'s
  // cancellation check below and videoGenerationCancel.ts for why). One extra lookup here (not
  // per LLM call) to resolve the owning userId for per-user LLM spend attribution.
  const ownerRow = await getVideoById(videoId);
  const ownerUserId = ownerRow?.userId ?? null;
  /**
   * Open the replay bundle for this render, when one was asked for. Off unless
   * RENDER_REPLAY_RECORD=true, and a failure to open it stands the recorder down rather than
   * failing the render — see renderReplay.ts.
   */
  beginReplayRecording(videoId, process.env.RAILWAY_GIT_COMMIT_SHA?.slice(0, 7) ?? null);
  // RONDE 29: per-gate ask/fire counters for this render. Its own storage rather than a
  // RenderCtx field because gates live in modules that must not import this one (see
  // gateFiringStats.ts). Same per-render isolation, for the same concurrency reason.
  const gateStats = createGateFiringStats();
  /**
   * FINAL VALIDATION — the render's TOPIC, set once, here.
   *
   * `videos.prompt` (or the prompt this call was handed) is what the person typed, and it is the
   * only string admitted: `ownerRow.title` is deliberately NOT part of this expression, because a
   * title is a claim the model made about the video and admitting it as evidence re-opens the hole
   * RONDE 90 closed. See `withRenderTopic` in searchQueryContract.ts.
   *
   * This is the wiring R160 specified and never installed — the reason the first production render
   * blocked "WWII" eighteen times on a video the person had asked for by that word. Outside this
   * scope nothing changes: no topic is set and every gate behaves exactly as before.
   */
  /**
   * RENDER 562 — the source-length memo, opened for the whole render.
   *
   * Render-scoped rather than module-scoped so one video's refusal can never ban an asset for
   * another video whose slots are shorter. See sourceFloorMemo.ts for what it costs not to have
   * one: 222 identical refusals over 34 assets in a single render, one asset refused 26 times.
   */
  const sourceFloorMemo = createSourceFloorMemo();
  /**
   * RENDER 563 — the subject gate's scope, opened for the whole render.
   *
   * Opened HERE, beside the other render scopes, rather than where the beat records it reads are
   * created — that is deep inside `_runVideoPipelineInner`, and a scope entered there would have
   * to wrap the rest of a very long function. The resolver is therefore installed later, once the
   * render has scenes and a beat map; until then it places no beat and the gate declines, which is
   * counted rather than hidden.
   */
  const subjectGateScope: SubjectGateScope = {
    state: createCandidateSubjectGateState(),
    contextFor: () => undefined,
  };
  /**
   * RENDER 564 — the scope that lets a compose barrier ask for the verdict it is missing.
   *
   * Opened here for the same reason as the subject gate's: the records it reads are created deep
   * inside `_runVideoPipelineInner`, and a scope entered there would have to wrap the rest of a
   * very long function. Until the resolvers are installed it can place no beat, which reads as
   * `beat_unknown` and leaves the barrier's own answer untouched.
   */
  const composeJudgeScope: ComposeJudgeScope = {
    workDir: "",
    state: createBeatImageGateState(),
    ledger: createBeatRelevanceLedger(),
    beatForClip: () => undefined,
    contextFor: () => undefined,
    /** Until the render installs the real classifier, nothing is treated as a card. */
    isPlaceholder: () => false,
    budget: maxComposePhaseJudgements(),
    spent: 0,
  };
  /**
   * The render's vision roll-call, in scope for every route that can ask a model to look.
   *
   * Ambient rather than a field on the render context, for the reason every other scope in this
   * chain is ambient: `MAX_CONCURRENT_RENDERS` can be greater than one, and two renders sharing a
   * module-level counter would each report the other's spend. See `visionCensus.ts`.
   */
  const visionCensus = newVisionCensus();
  /**
   * ONE PRODUCTION RENDER PER VIDEO — the guard this function never had.
   *
   * Nothing between the request and twenty-one minutes of work asked whether this video was
   * already being rendered. Video 574 has two runs in its own record, and two rounds of analysis
   * reasoned about the difference between their numbers before anyone noticed they were different
   * runs. See `server/renderLock.ts` for where the atomicity actually lives — the unique key, not
   * this call.
   *
   * The lock is taken here rather than deeper in because this is the outermost thing that knows a
   * production render is starting, and because the release has to survive every ending. The
   * `finally` is the whole point: success, a throw, a cancellation and an export refusal all give
   * the lock back. A render that finishes while its lock stays held would make that video
   * unrenderable until the lease ran out.
   */
  const productionRenderId = newRenderId();
  const lock = await acquireRenderLock(dbRenderLockStore, {
    videoId,
    productionRenderId,
    holderLabel: `pid:${process.pid}`,
  });
  console.log(formatRenderLock(lock));
  if (!lock.acquired) {
    /**
     * The second render does not start, and — deliberately — has not touched anything. Every
     * scope above is opened below this point, so a refused request writes no ledger, no report and
     * no lineage. §9: it may not mutate pipeline state, and the way to guarantee that is to refuse
     * before any of it exists.
     */
    throw pipelineError(
      PIPELINE_ERROR.RENDER_ALREADY_RUNNING,
      `A production render is already running for video ${videoId} ` +
        `(render ${lock.existingRenderId}). This request was refused rather than started ` +
        `alongside it.`
    );
  }

  /**
   * RONDE 652 — a cancel that the pipeline does not act on still gives the lock back.
   *
   * Cancelling is cooperative, and render 607 showed a run that was cancelled and never reached
   * another checkpoint: this `finally` never ran and the lock was held for its whole lease. Once a
   * cancel is requested the render gets a grace period; after it, the run is abandoned — its
   * children killed, its token marked so its own checkpoints keep throwing — and this function
   * rejects, which releases the lock here and the worker slot in the queue.
   */
  /** RONDE 653 — so a worker being stopped knows which locks it holds and can hand them back. */
  registerActiveRender(videoId, productionRenderId);
  const renderRun: RenderRunToken = { abandoned: false };
  const pipelineRun = withVisionCensus(visionCensus, () =>
      withSourceFloorMemo(sourceFloorMemo, () =>
      withSubjectGateScope(subjectGateScope, () =>
        withComposeJudgeScope(composeJudgeScope, () =>
          withRenderTopic(userPrompt ?? ownerRow?.prompt, () =>
            runWithActiveVideoId(videoId, () => renderCtxStorage.run(renderCtx, () =>
              runWithGateFiringStats(gateStats, () => _runVideoPipelineInner(
                videoId, script, onProgress, voiceId, customVoiceoverUrl, videoLength, enableSubtitles, userPrompt,
                sourceFloorMemo, subjectGateScope, composeJudgeScope
              ))
            ), ownerUserId, renderRun)
          )
        )
      )
    )
    );
  const cancelWatch = watchForAbandonedRender({
    videoId,
    isCancelled: () => isVideoGenerationCancelRequested(videoId),
    graceMs: renderCancelGraceMs(),
    onAbandon: (reason) => {
      renderRun.abandoned = true;
      renderCtx.watchdog?.abandon(reason);
      console.error(
        `[RenderCancel] video=${videoId} ABANDONED render=${productionRenderId} — ${reason}`
      );
      /** It keeps running in the background; say so when it finally ends, and never let it throw unobserved. */
      void Promise.resolve(pipelineRun).then(
        () => console.warn(`[RenderCancel] video=${videoId} abandoned render=${productionRenderId} ended late (resolved)`),
        (err) =>
          console.warn(
            `[RenderCancel] video=${videoId} abandoned render=${productionRenderId} ended late: ` +
              `${(err as Error)?.message?.slice(0, 160)}`
          )
      );
    },
  });
  try {
    return await Promise.race([pipelineRun, cancelWatch.abandoned]);
  } catch (err) {
    /**
     * Video 613 — a render that ended in an error ends for its own beats too.
     *
     * The throw ("no picture was found … 10108") stopped the main line only. Its beats kept
     * searching and downloading for another 47 s, into a work directory already removed
     * (`onDisk=false`), spending YouTube and RapidAPI on a render that no longer existed. The
     * run's own token is the signal every checkpoint already reads (`throwIfActiveRenderCancelled`);
     * it is this run's alone, so a later attempt for the same video starts untouched.
     */
    renderRun.abandoned = true;
    throw err;
  } finally {
    cancelWatch.stop();
    unregisterActiveRender(videoId, productionRenderId);
    releaseVideoYoutubePool(videoId);
    /** Every ending, holder-scoped. An overrun render cannot take its successor's lock away. */
    const removed = await releaseRenderLock(dbRenderLockStore, videoId, productionRenderId).catch(
      () => false
    );
    console.log(formatRenderLockRelease(videoId, productionRenderId, removed));
  }
}

async function _runVideoPipelineInner(
  videoId: number,
  script: string,
  onProgress?: (p: PipelineProgress) => void,
  voiceId?: string,
  customVoiceoverUrl?: string,
  videoLength = "8-10",
  enableSubtitles = false,
  userPrompt?: string,
  /** Passed in as well as being ambient, so the render can report on it at the end. */
  sourceFloorMemo?: SourceFloorMemo,
  /** Ambient for the download routes; passed in so this function can install its resolver. */
  subjectGateScope?: SubjectGateScope,
  /** Ambient for the compose barrier; likewise filled in once the render has its records. */
  composeJudgeScope?: ComposeJudgeScope
): Promise<string> {
  videoLength = normalizeVideoLength(videoLength);
  const maxScenes = getScenesForLength(videoLength);
  if (!fs.existsSync(TMP_DIR)) {
    fs.mkdirSync(TMP_DIR, { recursive: true });
  }
  const workDir = path.join(TMP_DIR, `fastvid_${videoId}_${Date.now()}`);
  fs.mkdirSync(workDir, { recursive: true });

  // ── Global render watchdog ────────────────────────────────────────────────
  // Starts with a budget that's never tighter than the pipeline's own central wall-clock
  // policy (sourcingPolicy.ts's maxPipelineWallClockHardMin — the same ceiling the router race
  // and DB stall detector already use for this video length), then gets replaced with the
  // RenderBudget-derived value once actual scene durations are known post-VO-sync. Previously
  // this always started at the flat WATCHDOG_RENDER_MAX_MS (18min) fallback regardless of video
  // length, which is far tighter than the up-to-260min budget long videos are otherwise allowed.
  const { createRenderWatchdog, WATCHDOG_RENDER_MAX_MS } = await import("./renderWatchdog");
  const initialWatchdogBudgetMs = Math.max(WATCHDOG_RENDER_MAX_MS, maxPipelineWallClockHardMin(videoLength) * 60_000);
  const watchdog = createRenderWatchdog(videoId, initialWatchdogBudgetMs);
  // RONDE 25: each render gets its own overlay-check allowance (and a clean memo) so one
  // expensive render cannot spend the next one's budget, and the cache cannot grow unbounded
  // across the lifetime of a long-lived worker process.
  resetOverlayBudget();
  /**
   * RONDE 223 — and its sibling: what THIS render learns about permanently refused downloads is
   * forgotten when the next one starts, so a provider that replaces an oversized file is asked
   * again rather than written off for the lifetime of the worker.
   */
  resetPermanentDownloadRefusals();
  /** The cloud route's egress latch is render-scoped too — see noteCloudEgressBlocked. */
  resetCloudEgressBlocked();
  /** RONDE 261: the sources it points at live in a work directory this render is about to make. */
  resetYoutubeSourceFiles();
  getRenderCtx().watchdog = watchdog;

  // Per-stage budgets — initialised to fallback values, replaced with
  // RenderBudget values once actual scene durations are available post-VO.
  let renderBudgetComposeMs = 90_000;   // per-scene compose
  let renderBudgetConcatMs  = 120_000;  // final concat
  let renderBudgetUploadMs  = 300_000;  // storage upload

  // NOTE: try/finally starts here so workDir is ALWAYS cleaned up, even if
  // the DB call or context-building below throws before Stage 1 begins.
  try {

  assertDiskSpaceAvailable(workDir, videoId);
  /**
   * RENDER 580 — ASK WHETHER THERE IS A JUDGE BEFORE SPENDING AN HOUR FINDING OUT.
   *
   * That render composed three scenes in 3788.7s and was then refused because every vision
   * provider was gone — a condition that was already true when it started. All 228 declines had
   * the same cause and the first one knew it.
   *
   * Beside `assertDiskSpaceAvailable` because it is the same kind of question: a precondition the
   * render cannot create for itself, cheap to ask, and ruinous to discover late.
   *
   * A configuration check would not have caught render 580 — `GEMINI_API_KEY` was set and the key
   * was the wrong thing to look at; the 403 PERMISSION_DENIED exists only in the answer to a real
   * call. So `probeVisionJudge` makes one, through the same `invokeLLM` and the same provider
   * chain the gate itself uses.
   *
   * ── The two cases it deliberately lets through ────────────────────────────────────────────
   *
   *   · The gate switched off. `beatImageRelevanceGateEnabled()` false means the operator turned
   *     the judge off on purpose, and the export gate says the same: "a render where every
   *     provider is down but the gate is switched off passes."
   *   · A reachable judge. Whether this render's footage ends up judged is a question only the
   *     export gate can answer, and it still does. This refuses nothing that the export gate would
   *     have allowed — with no judge at all, every beat's verdict count is zero, so a film with any
   *     real footage is certain to be refused later. The outcome is the same one, an hour earlier.
   */
  if (beatImageRelevanceGateEnabled()) {
    const judge = await probeVisionJudge();
    if (!judge.reachable) {
      console.error(`[VisionPreflight] video ${videoId}: NO JUDGE — ${judge.reason ?? "no reason recorded"}`);
      throw pipelineError(PIPELINE_ERROR.QUALITY_GATE, formatVisionJudgeUnreachable(judge));
    }
    console.log(`[VisionPreflight] video ${videoId}: picture editor reachable via ${judge.provider}`);
  }
  const videoRow = await getVideoById(videoId);
  const pipelineWallStartMs = videoRow?.generationStartedAt
    ? new Date(videoRow.generationStartedAt).getTime()
    : Date.now();
  const effectiveVoiceId = voiceId?.trim() || videoRow?.voiceId?.trim() || undefined;
  if (effectiveVoiceId) {
    console.log(`[Pipeline] Video ${videoId}: using selected ElevenLabs voice ${effectiveVoiceId.slice(0, 12)}…`);
  } else if (!customVoiceoverUrl) {
    console.warn(`[Pipeline] Video ${videoId}: no voiceId on record — using default narrator`);
  }

  const titleMatch = script.match(/^#\s+(.+)/m);
  const videoTitle = titleMatch?.[1]?.trim().slice(0, 80)
    || script.split("\n").find(l => l.trim().length > 5)?.trim().slice(0, 80)
    || "AI Generated Video";
  const topicContext = asVideoTitleString(buildTopicContext(userPrompt ?? videoRow?.prompt, videoTitle));
  const muskLocked = isMuskTeslaTopic(topicContext, script);
  const primaryPerson = resolvePrimaryPersonLock({
    prompt: userPrompt ?? videoRow?.prompt ?? "",
    videoTitle,
    topicContext,
    script,
  });
  const personLocked = Boolean(primaryPerson) || isPersonCelebrityTopic(topicContext);
  getRenderCtx().videoTopic = { videoTitle, primaryPerson };

  console.log(
    `[Pipeline] Video ${videoId}: ${maxScenes} scenes for ${videoLength} min` +
    (muskLocked ? " [Musk/Tesla topic lock]" : "") +
    (personLocked ? ` [person lock: ${primaryPerson}]` : "") +
    ("") +
    (elevenLabsOnlyVoice() ? " [ElevenLabs voice]" : "")
  );

  /**
   * FINAL VALIDATION §14 — which route this render takes, said out loud, before any work.
   *
   * The first real production log had no route line at all: the `[RenderJob] route=…` report lives
   * inside the `cinematicPlanningEnabled()` branch, so a deployment with the engine off is silent
   * about it, and the only way to tell which route ran was to notice that `[Graphics]`, `[Captions]`
   * and `[EDL]` never appeared. This says it directly, with the flag behind each field, so a log
   * can be read forwards instead of by inference.
   *
   * Non-fatal by construction: it is a log line and a dynamic import, and a render must never fail
   * because it could not describe itself.
   */
  try {
    const { formatProductionRoute } = await import("./cinematicProduction");
    console.log(formatProductionRoute(videoId));
    /**
     * A configuration that is SET but shaped wrong — the cloud download service without its
     * token, which answers 401 on every request. Not blocking, so it cannot go in the route
     * line's verdict; silent it would be another provider that reads "on" and fetches nothing.
     */
    for (const warning of youtubeReadinessWarnings()) console.warn(warning);
  } catch (err) {
    console.warn(`[ProductionRoute] video=${videoId} unavailable: ${(err as Error).message.slice(0, 200)}`);
  }

    // ── Stage 1: Parse script into scenes ────────────────────────────────────
    onProgress?.({ stage: STAGE_LABELS.parsing, percent: 3 });
    const pipelineStepTiming = new PipelineStepTiming();
    const t0 = Date.now();
    const scenes = await timePipelineStep(
      pipelineStepTiming,
      "scene_generation",
      "Script parse into scenes",
      () => parseScriptIntoScenes(script, maxScenes, topicContext, pipelineStepTiming)
    );
    for (const scene of scenes) {
      sanitizeSceneStockQueries(scene, topicContext ?? videoTitle);
      if (muskLocked) sanitizeSceneForMuskTopic(scene, scene.index, topicContext ?? videoTitle);
      if (personLocked && primaryPerson) sanitizeSceneForPersonTopic(scene, primaryPerson);
    }
    console.log(`[Pipeline] Stage 1 (parse): ${scenes.length} scenes in ${((Date.now()-t0)/1000).toFixed(1)}s`);

    /**
     * RONDE 658 — ONE YOUTUBE POOL FOR THE WHOLE VIDEO, built while the voice-over is made.
     *
     * The scenes say what the film needs; the pool asks YouTube once (twice at most) for all of it.
     * Registered before any beat runs, so every beat finds it; never awaited here, so TTS is not held.
     */
    if (youtubeVideoPoolEnabled() && youtubeSourcingEnabled() && process.env.YOUTUBE_API_KEY?.trim() && !hasVideoYoutubePool(videoId)) {
      const poolInput = {
        videoId,
        prompt: asVideoTitleString(userPrompt ?? videoRow?.prompt ?? topicContext ?? ""),
        title: asVideoTitleString(videoTitle),
        sceneTexts: scenes.filter((s) => !s.isChapterCard).map((s) => s.text),
      };
      registerVideoYoutubePool(
        videoId,
        productionVideoPoolDeps(poolInput)
          .then((deps) => buildVideoYoutubePool(deps, poolInput))
          .catch((err: Error) => {
            console.warn(`[YouTubeSearchPlan] video=${videoId} pool failed: ${err.message?.slice(0, 160)} — beats go on without YouTube`);
            return emptyVideoYoutubePool(videoId);
          }),
        /** VIDEO 616 — the same build, asked again with the videos refused on screen. */
        (refusedVideoIds) =>
          productionVideoPoolDeps(poolInput).then((deps) => buildVideoYoutubePool(deps, poolInput, { refusedVideoIds }))
      );
    }

    // ── P4: Prefetch scene candidate pools / retrieval funnels during TTS ──────
    // Kick off retrieval for ALL scenes immediately after parse so it runs in
    // parallel with Stage 2 (TTS). Active only when ENABLE_SCENE_CANDIDATE_POOL=true.
    // When ENABLE_RETRIEVAL_FUNNEL=true, builds full hybrid funnels (archive+internet).
    // When only ENABLE_SCENE_CANDIDATE_POOL=true, builds external-only pools.
    let prefetchPools: Map<number, Promise<import("./scenePool").SceneCandidatePool>> | undefined;
    let prefetchFunnels: Map<number, Promise<RetrievalFunnelResult>> | undefined;
    // Cross-video variety exclude set, computed HERE (before visualDedup exists) so the
    // prefetched funnels — built during TTS — already hold back archive assets reused in
    // recent same-topic videos. The same value is copied onto visualDedup.crossVideoExcludeIds
    // below so the inline (non-prefetch) funnel path and the beat-level dedup use it too.
    const crossVideoExcludeIdsForRun = archiveCrossVideoVarietyEnabled(videoLength)
      ? getCrossVideoExcludeAssetIds(topicContext, videoId)
      : new Set<number>();
    if (sceneCandidatePoolEnabled()) {
      if (retrievalFunnelEnabled()) {
        // F3-27 self-learning: proven queries for this video's entity/topic (if any) are
        // fetched once and prepended to every scene's extra queries — priming, not a filter.
        const primedMemoryQueries = await primeQueriesWithSearchMemory(topicContext || videoTitle, undefined);
        prefetchFunnels = new Map();
        for (const scene of scenes) {
          // P1-B (render 517): the scene's stock phrasing carried no period at all ("berlin
          // city skyline" for a 1945 documentary) — anchor it to the year/person/location the
          // script itself states before any provider is queried. No-op for non-historical topics.
          const anchoredQueries = anchorQueriesToHistoricalContext({
            primaryQuery: scene.pexelsQuery || scene.visualCue || scene.text.slice(0, 80),
            extraQueries: [...(primedMemoryQueries ?? []), ...(scene.pexelsQueries?.slice(0, 2) ?? [])],
            sceneText: scene.text,
            videoTitle: topicContext || videoTitle,
            primaryPerson,
          });
          if (anchoredQueries.anchored) {
            console.log(
              `[HistoricalAnchor] scene=${scene.index} primary="${anchoredQueries.primaryQuery}" ` +
              `year=${anchoredQueries.year || "n/a"} extras=${anchoredQueries.extraQueries.length}`
            );
          }
          const funnelPromise = runSceneVisualDiscovery(
            { renderId: String(videoId ?? "-"), sceneIndex: scene.index },
            () => buildRetrievalFunnel({
            sceneIndex: scene.index,
            sceneText: scene.text,
            primaryQuery: anchoredQueries.primaryQuery,
            extraQueries: anchoredQueries.extraQueries,
            /**
             * RONDE 603 — YouTube, which this funnel has never asked. See the fields on
             * `RetrievalFunnelRequest`.
             *
             * No `archiveSearch` here, and that is not an omission: this prefetch runs BEFORE
             * `createVisualDedupState` — the comment below says so for the same reason the
             * deficit and the metrics are absent — and `scenePoolArchiveSearch` needs that state
             * to read the render's used-asset sets. The sibling pool prefetch supplies exactly
             * this pair for exactly this reason. The inline funnel, which runs per scene with the
             * state in hand, supplies both.
             */
            youtubeSearch: scenePoolYoutubeSearch(),
            pexelsApiKey: PEXELS_API_KEY || undefined,
            pixabayApiKey: process.env.PIXABAY_API_KEY || undefined,
            europeanaApiKey: europeanaSourcingEnabled() ? (EUROPEANA_API_KEY || undefined) : undefined,
            naraApiKey: NARA_API_KEY || undefined,
            skipOpenverse: !openverseStillsEnabled(),
            videoTitle: topicContext || undefined,
            // Hold back archive assets reused in recent same-topic videos (computed above).
            crossVideoExcludeIds: crossVideoExcludeIdsForRun,
            // No movingShareDeficit here on purpose: this prefetch runs during TTS, before a
            // single clip has been adopted, so there is no mix to be behind on yet. The inline
            // funnel call — the one that runs per scene, with clips already on the timeline —
            // is where the measured deficit is passed.
            //
            // RONDE 131: the memory IS read here, and this is the call site where it pays best —
            // during TTS, before a single provider request has been made. No exclude set yet for
            // the same reason as the deficit: nothing has been adopted.
            //
            // No metrics object either: this prefetch runs BEFORE createVisualDedupState, so the
            // per-render counters do not exist yet. The per-beat [SearchMemory] line still prints
            // for every scene here — what the summary counts is the inline funnel, which is the
            // path that actually spends a beat's budget.
            memoryEntity: activeMemoryEntity(),
          }).catch(err => {
            console.warn(`[Funnel P4] Scene ${scene.index} prefetch failed:`, (err as Error).message?.slice(0, 80));
            return Promise.reject(err);
          })
          );
          prefetchFunnels.set(scene.index, funnelPromise);
        }
        console.log(`[Funnel P4] Hybrid retrieval prefetch started for ${scenes.length} scene(s) during TTS`);
      } else {
        prefetchPools = new Map();
        for (const scene of scenes) {
          // P1-B: same historical anchoring as the funnel prefetch above.
          const anchoredPoolQueries = anchorQueriesToHistoricalContext({
            primaryQuery: scene.pexelsQuery || scene.visualCue || scene.text.slice(0, 80),
            extraQueries: scene.pexelsQueries?.slice(0, 2),
            sceneText: scene.text,
            videoTitle: topicContext || videoTitle,
            primaryPerson,
          });
          const poolPromise = runSceneVisualDiscovery(
            { renderId: String(videoId ?? "-"), sceneIndex: scene.index },
            () => buildSceneCandidatePool({
            sceneIndex: scene.index,
            sceneText: scene.text,
            primaryQuery: anchoredPoolQueries.primaryQuery,
            extraQueries: anchoredPoolQueries.extraQueries,
            pexelsApiKey: PEXELS_API_KEY || undefined,
            pixabayApiKey: process.env.PIXABAY_API_KEY || undefined,
            /** RONDE 177 — the same source list for the prefetch as for the inline build. */
            youtubeSearch: scenePoolYoutubeSearch(),
          }).catch(err => {
            console.warn(`[Pool P4] Scene ${scene.index} prefetch failed:`, (err as Error).message?.slice(0, 80));
            return Promise.reject(err);
          })
          );
          prefetchPools.set(scene.index, poolPromise);
        }
        console.log(`[Pool P4] Prefetch started for ${scenes.length} scene(s) during TTS`);
      }
    }
    // ─────────────────────────────────────────────────────────────────────────

    // ── Stage 2: Generate ALL voiceovers in parallel batches ──────────────────
    // elevenLabsQuotaExhausted lives on RenderCtx (F3-03) and is initialized to false in the
    // renderCtx literal at the top of this function — no explicit reset needed here anymore.
    // It gets set on the first ElevenLabs failure so the rest of THIS render's segments skip
    // straight to Fish Audio instead of burning retries on a known-down provider, without
    // leaking into any other concurrent render sharing this worker process.
    onProgress?.({ stage: STAGE_LABELS.voiceovers, percent: 8 });
    const t1 = Date.now();
    const audioPaths = scenes.map((_, i) => path.join(workDir, `scene_${i}_audio.mp3`));
    let durations: number[];

    if (customVoiceoverUrl) {
      const customAudioPath = path.join(workDir, "custom_voiceover.mp3");
      const resp = await fetchExternalUrlSafely(customVoiceoverUrl);
      if (!resp.ok) {
        throw pipelineError(PIPELINE_ERROR.CUSTOM_VOICEOVER, `Failed to download custom voiceover: ${resp.status}`);
      }
      if (!resp.body) {
        throw pipelineError(PIPELINE_ERROR.CUSTOM_VOICEOVER, "Custom voiceover download returned no response body");
      }
      // F3-14: streams straight to customAudioPath via pipeline() instead of
      // Buffer.from(await resp.arrayBuffer()), so the download is never fully buffered in
      // memory. AbortSignal.timeout inside fetchExternalUrlSafely now covers this body-read too
      // (see that function's F3-14 comment) — on a timeout/stream error the partial file is
      // removed before the error propagates, matching the existing F3-10/F3-13 cleanup pattern.
      try {
        await pipeline(resp.body, fs.createWriteStream(customAudioPath));
      } catch (err) {
        if (fs.existsSync(customAudioPath)) {
          try { fs.unlinkSync(customAudioPath); } catch { /* ignore */ }
        }
        throw err;
      }
      // F3-07: probeVideoDurationSec is the existing, already-hardened helper for exactly this
      // (semaphore-gated, withSceneFetchTimeout hard-kill, multi-binary retry) — the previous
      // inline execFile() here had no timeout, no semaphore, and its Promise executor never
      // rejected, so a hung ffprobe could block the render forever.
      const totalDuration = await probeVideoDurationSec(customAudioPath) || 60;
      const perScene = Math.max(totalDuration / scenes.length, 5);
      for (let i = 0; i < scenes.length; i++) {
        const start = i * perScene;
        // F3-07: wrapped in withSceneFetchTimeout (45s, same budget splitFullVoiceoverByScenes
        // already uses for the equivalent per-scene ffmpeg audio split) — previously unwrapped,
        // so a hung ffmpeg split here could block the render forever and leak its ffmpegSemaphore
        // slot (exec()'s own semaphore.run() only releases once its promise settles).
        await withSceneFetchTimeout(
          () => exec(`${FFMPEG_BIN} -y -i "${customAudioPath}" -ss ${start} -t ${perScene} -c copy "${audioPaths[i]}"`),
          45_000,
          `Custom voiceover split scene ${i}`
        );
      }
      durations = scenes.map(() => perScene);
    } else {
      durations = await timePipelineStep(
        pipelineStepTiming,
        "voiceover",
        "Bulk voiceover generation",
        () =>
          withSceneFetchTimeout(
            () => generateBulkSceneVoiceovers(scenes, audioPaths, workDir, effectiveVoiceId, (done, total) => {
              onProgress?.({
                stage:
                  done === 0
                    ? STAGE_LABELS.voiceovers
                    : `${STAGE_LABELS.voiceovers} (${done}/${total})`,
                percent: 8 + Math.round((done / total) * 10),
              });
            }, script),
            bulkVoiceoverTimeoutMs(scenes.length, videoLength),
            "Bulk voiceover generation"
          )
      );
    }
    // Tight VO sync: scene length tracks narration; target length padded only on final export
    const shortTargetSec: Record<string, number> = { "1": 58 };
    const targetTotal = shortTargetSec[videoLength];
    const VO_SCENE_TAIL_SEC = 0.35;
    for (let i = 0; i < scenes.length; i++) {
      const probed = await probeVideoDurationSec(audioPaths[i]);
      const audioSec = Math.max(durations[i] || 3, probed || durations[i] || 3);
      durations[i] = audioSec;
      scenes[i].duration = audioSec + VO_SCENE_TAIL_SEC;
    }
    const voTotal = scenes.reduce((sum, s) => sum + s.duration, 0);
    if (targetTotal) {
      console.log(
        `[Pipeline] ${videoLength}-min: VO-synced ${voTotal.toFixed(1)}s (${scenes.length} scenes); ` +
        `final pad to ~${targetTotal}s at export if needed`
      );
    } else {
      console.log(`[Pipeline] VO-synced total ${voTotal.toFixed(1)}s (${scenes.length} scenes)`);
    }
    console.log(`[Pipeline] Stage 2 (voiceovers): ${scenes.length} in ${((Date.now()-t1)/1000).toFixed(1)}s`);

    // ── Master Documentary Director: global visual blueprint ──────────────────
    // Runs after VO so scene durations are known; before retrieval so blueprint
    // can guide clip selection. Fire concurrently with RenderBudget setup.
    const blueprintPromise = masterDocumentaryDirectorEnabled()
      ? createVideoBlueprint(
          String(videoId),
          topicContext ?? videoTitle ?? "documentary",
          parseFloat(videoLength) || 5,
          scenes.map((s) => ({
            index: s.index,
            text: s.text ?? "",
            beats: (s as { beats?: Array<{ index: number; text: string }> }).beats,
          }))
        ).catch(() => null)
      : Promise.resolve(null);

    // ── RenderBudget: derive all timeouts from actual VO durations ───────────
    {
      const { computeRenderBudget, logRenderBudget } = await import("./renderBudget");
      const { BudgetTracker: BT } = await import("./renderBudgetTracker");
      const totalVoSec = scenes.reduce((s, sc) => s + sc.duration, 0);
      const budget = computeRenderBudget(scenes.length, totalVoSec, videoLength);
      logRenderBudget(budget, videoId);
      set_activeRenderBudget(budget);
      set_activeBudgetTracker(new BT(budget, videoId));
      watchdog.updateBudget(budget.totalMs);
      renderBudgetComposeMs = budget.basePerSceneComposeMs;
      renderBudgetConcatMs  = budget.concatMs;
      renderBudgetUploadMs  = budget.uploadMs;
    }

    // ── Stage 3: Per-zin visuals (power word → clip) ─────────────────────────
    onProgress?.({ stage: STAGE_LABELS.visuals, percent: 20 });
    const t2 = Date.now();
    get_activeBudgetTracker()?.stageStart("retrieval", (get_activeRenderBudget()?.perSceneRetrieveMs ?? 35_000) * scenes.length);
    {
      const hasRealOrAi =
        youtubeCcReady() ||
        Boolean(SERPAPI_KEY) ||
        cheapAiImageProvidersReady() ||
        Boolean(PEXELS_API_KEY || PIXABAY_API_KEY);
      if (!hasRealOrAi) {
        console.warn(
          "[Pipeline] No YouTube/SERP/AI/stock keys — beats without a picture hold the previous shot"
        );
      }
    }
    /**
     * RONDE 648 — the render's own copy of the profile carries YouTube-first mode's scene share and
     * parallelism, so every reader of `perf` below sees one set of numbers.
     */
    const perf = applyYoutubeFirstPerf(getPipelinePerfProfile(videoLength));
    const profiler = createPipelineProfiler(String(videoId), videoLength, {
      composeParallelism: composeParallelismForVideo(videoLength, IS_RAILWAY),
      retrieveParallelism: perf.sceneParallelism,
      montageSegmentParallelism: montageSegmentParallelism(IS_RAILWAY),
      ffmpegPreset: process.env.FFMPEG_PRESET ?? "veryfast",
      crf: process.env.FFMPEG_CRF ?? "18",
    });
    profiler.recordStageStart("script", t0);
    profiler.recordStageEnd("script", t1);
    profiler.recordStageStart("tts", t1);
    profiler.recordStageEnd("tts", Date.now());
    profiler.recordStageStart("retrieval", Date.now());
    {
      if (minimizeStockFootageEnabled()) {
        console.log(
          `[Pipeline] Minimize stock: real footage → AI; ≤${perf.maxStockBeatsPerVideo} licensed stock clip(s) per video`
        );
      } else if (!PEXELS_API_KEY && !PIXABAY_API_KEY) {
        console.warn("[Pipeline] No Pexels/Pixabay — relying on YouTube CC and AI only");
      }
      if (SERPAPI_KEY) {
        console.log("[Pipeline] SERPAPI_KEY set — celebrity/person image fallback enabled");
      } else if (/kylie|jenner|celebrity|musk|tesla/i.test(topicContext ?? userPrompt ?? "")) {
        console.warn("[Pipeline] SERPAPI_KEY not set — named-person videos may lack real photos of the subject");
      }
    }
    /**
     * TWO SOURCING MODES, ONE BRANCH, AND THE LOSER SAID NOTHING.
     *
     * `beatPrimaryFetch` opens with `if (curatedArchiveOnlyVisuals())` and RETURNS inside that
     * branch — the archive, then Wikimedia, then Pexels. The `if (youtubeOnlySourcingEnabled())`
     * that follows it is therefore unreachable whenever the curated mode is on, and the curated
     * mode is on by default: `CURATED_ARCHIVE_ONLY !== "false"`.
     *
     * So an operator who sets `YOUTUBE_ONLY_SOURCING=true` to make a film out of YouTube gets a
     * render that behaves exactly as before, with nothing anywhere saying the setting was
     * overruled. The `sourcing=` field below already resolves the conflict the same way the code
     * does — correctly — but it reports the WINNER, and a winner is indistinguishable from a
     * setting that was never made.
     *
     * Nothing here changes which mode wins. It says out loud that a choice was overruled, once
     * per render, so the next flag flip is not paid for with a render.
     */
    
    console.log(
      `[Pipeline] Perf budget: ≤${perf.targetWallClockMin}min wall-clock, ` +
      `≤${perf.maxBeatsPerScene} beats/scene, ${perf.sceneParallelism} parallel scenes, ` +
      `sourcing=${youtubeOnlySourcingEnabled() ? `YouTube-only ≤${youtubeBeatSearchBudgetMs() / 1000}s → Pexels` : youtubeSourcingEnabled() ? "YouTube+archival" : "archival+stills → Pexels (YouTube off)"}, ` +
      `local-vision=${clipVisionGateEnabled() ? "on" : "off"}, ` +
      `fair-use transform=${perf.skipFairUseTransform ? "skip" : "on"}, ` +
      `AI fallback=${"off"}, ` +
      `minimize stock=${perf.minimizeStockFootage ? `yes (≤${perf.maxStockBeatsPerVideo} Pexels/Pixabay)` : "no"}`
    );
    /** No AI clips: a beat no real source can fill is a gap, not a generated picture. */
    const visualDedup = createVisualDedupState(perf, { primaryPerson, personTopicLock: personLocked, videoId });
    /**
     * RONDE 231 — the SAME budget object the beats spend, published where the choke points can
     * reach it. One register, two ways in: `dedup.beatBudget` for the code that already holds the
     * dedup state, the render context for `downloadToFileStreaming` and `runPreparation`, which
     * do not. A second budget object would be a second opinion about the same spend.
     */
    getRenderCtx().beatBudget = visualDedup.beatBudget;
    /**
     * RENDER 563 — the subject gate can now place a beat.
     *
     * The scope was opened before this function was called (see runVideoPipeline); this is where
     * it gains the two things it needs and could not have had earlier: the render's beat record
     * and its scenes. `sceneBeatsBySceneIndex` is the record every beat-resolving route writes
     * through `applyVoiceAlignmentToBeats`, so a beat is placeable no matter which route resolved
     * it.
     *
     * The state is shared rather than copied, so `[SubjectGate]` at the end of the render reports
     * the same counters the download sites incremented.
     */
    if (subjectGateScope) {
      visualDedup.candidateSubjectGate = subjectGateScope.state;
      subjectGateScope.contextFor = (sceneIndex, beatIndex) => {
        const beatText = visualDedup.sceneBeatsBySceneIndex.get(sceneIndex)?.[beatIndex]?.text;
        if (!beatText?.trim()) return undefined;
        const scene = scenes.find((s) => s.index === sceneIndex);
        return {
          beatText,
          ...(scene?.text ? { sceneText: scene.text } : {}),
          ...(asVideoTitleString(videoTitle) ? { videoTitle: asVideoTitleString(videoTitle) } : {}),
          /** The same anchors the funnel used to build inline — one answer for both routes. */
          anchors: [activeMemoryEntity(), ...(scene?.personNames ?? [])].filter(
            (x): x is string => Boolean(x)
          ),
        };
      };
      subjectGateScope.onRefusal = ({ sceneIndex, beatIndex, facts, reason: _reason }) => {
        recordClipReject(
          visualDedup.clipRejectAudit, sceneIndex, beatIndex,
          `${facts.source}:${facts.assetId}`, "subject_gate", facts.title
        );
      };
    }
    /**
     * RENDER 564 — the compose barrier gains the two things it needs to ask a question.
     *
     * `beatForClip` reads the adopt audit backwards: the compose chokepoint knows a scene and a
     * clip index, and the beat is what the narration hangs on. The audit already records a
     * basename per beat, so the mapping exists and is not invented here. Later entries win, which
     * is the assumption `beatVisualStatus` already makes about that array.
     *
     * `contextFor` is the SAME `beatVisualContext` every other judging route builds, over the beat
     * record every route writes through `applyVoiceAlignmentToBeats`. Two different contexts for
     * one beat would let two routes reach different answers about one picture.
     */
    if (composeJudgeScope) {
      composeJudgeScope.workDir = workDir;
      composeJudgeScope.state = visualDedup.beatImageGate;
      composeJudgeScope.ledger = visualDedup.beatRelevance;
      /**
       * THE SAME LADDER THE MANIFEST ALREADY CLIMBS — RONDE 51's, on the third place that needed it.
       *
       * This lookup matched the exact basename and stopped. A clip is renamed after it is adopted:
       * "_still" by the still-to-video step, "_transformed" by the transform step, and a padded
       * clip is republished as `pad_combined_sNbM_<ts>.mp4`. RONDE 51 fixed exactly this for the
       * final manifest and RONDE 133 added `entry.contentKey` to it; the compose barrier kept the
       * bare-basename version, so render 573 reported:
       *
       *     [ComposeBarrier] s2 clip 3: UNJUDGED pad_combined_s2b3_1788851180446.mp4 — beat_unknown;
       *                                 nothing has looked at this picture and nothing can        ×4
       *
       * The origin of every one of those pads HAD been adopted and judged. `linkDerivedPath(...,
       * "PADDED")` records the derivation at the moment the pad is written, so the ledger can walk
       * back to the file adoption knows — one step at a time, bounded, and never in a cycle.
       *
       * A clip that is genuinely unknown still answers undefined. The point is not to find a beat
       * for everything; it is to stop reporting one as missing when the render recorded it.
       */
      composeJudgeScope.beatForClip = (clipPath) => {
        const audit = visualDedup.clipAdoptAudit;
        const at = (basename: string) => {
          for (let i = audit.length - 1; i >= 0; i--) {
            const entry = audit[i]!;
            if (entry.basename === basename) {
              return { sceneIndex: entry.sceneIndex, beatIndex: entry.beatIndex };
            }
          }
          return undefined;
        };
        const direct = at(path.basename(clipPath));
        if (direct) return direct;

        /** The key adoption recorded with the full path in hand, on both sides of the comparison. */
        const key = clipContentKey(clipPath);
        if (key && !key.startsWith("file:")) {
          for (let i = audit.length - 1; i >= 0; i--) {
            const entry = audit[i]!;
            if ((entry.contentKey ?? clipContentKey(entry.basename)) === key) {
              return { sceneIndex: entry.sceneIndex, beatIndex: entry.beatIndex };
            }
          }
        }

        const lineage = visualDedup.sourcingCache?.lineage;
        if (!lineage) return undefined;
        const seen = new Set<string>([clipPath]);
        let origin = lineage.derivationOriginOf(clipPath);
        while (origin && !seen.has(origin)) {
          seen.add(origin);
          const found = at(path.basename(origin));
          if (found) return found;
          origin = lineage.derivationOriginOf(origin);
        }
        return undefined;
      };
      /**
       * How many sentences this scene actually has, from the same record `contextFor` reads.
       *
       * Installed beside it so the barrier can tell a slot past the end of a scene's beats from a
       * beat whose narration is empty — see `beatCountFor`. Reads only; decides nothing.
       */
      composeJudgeScope.beatCountFor = (sceneIndex) =>
        visualDedup.sceneBeatsBySceneIndex.get(sceneIndex)?.length;
      composeJudgeScope.contextFor = (sceneIndex, beatIndex) => {
        const beat = visualDedup.sceneBeatsBySceneIndex.get(sceneIndex)?.[beatIndex];
        if (!beat?.text?.trim()) return undefined;
        const scene = scenes.find((s) => s.index === sceneIndex);
        return beatVisualContext(
          { text: beat.text, index: beatIndex },
          { text: scene?.text, index: sceneIndex },
          asVideoTitleString(videoTitle) || undefined
        );
      };
      /**
       * A card is not a picture, and asking a vision model whether a grey rectangle belongs under
       * a line of narration gets a no — which would then refuse the only thing standing between
       * that beat and an empty slot. `coverageOfAdoptEntry` is the classifier the beat report
       * already uses; it is resolved here because it lives in a module that imports the gate.
       */
      /**
       * RONDE 660 — a picture judged at the push is stamped eligible exactly like one judged
       * earlier, by the same helper. See `noteJudged` on the scope for video 608's four refusals.
       */
      composeJudgeScope.noteJudged = (clipPath, _contentKey, at) => {
        noteEligibleForJudgement(visualDedup, clipPath, "judged_at_push", at.sceneIndex, at.beatIndex);
      };
      composeJudgeScope.isPlaceholder = (basename) => {
        for (let i = visualDedup.clipAdoptAudit.length - 1; i >= 0; i--) {
          const entry = visualDedup.clipAdoptAudit[i]!;
          if (entry.basename !== basename) continue;
          const coverage = coverageOfAdoptEntry({ source: entry.source, basename });
          return coverage !== "own_footage" && coverage !== "subject_only";
        }
        return isGuaranteedClipName(basename);
      };
    }
    visualDedup.stepTiming = pipelineStepTiming;
    visualDedup.videoLength = videoLength;
    visualDedup.pipelineStartedMs = pipelineWallStartMs;
    /**
     * RONDE 173 — publish this render's sourcing cache on its own context.
     *
     * Set once, here, next to the dedup state it belongs to. Every provider fetcher that was never
     * handed a cache through its arguments now finds this one; see the RenderCtx field for the 156
     * uncached searches render 555 measured.
     */
    set_activeSourcingCache(visualDedup.sourcingCache);

    // Await the blueprint (started in parallel above) and attach to dedup state
    const videoBlueprint = await blueprintPromise;
    if (videoBlueprint) {
      visualDedup.videoBlueprint = videoBlueprint;
      visualDedup.visualBudgetTracker = createBudgetTracker(videoBlueprint);
    }

    // Documentary Planning Engine: build full plan (contracts, emotional curve, shot mix)
    // before ANY retrieval — pure derivation from blueprint, no extra LLM calls.
    {
      const { buildDocumentaryPlan, documentaryPlanningEnabled } = await import("./documentaryPlanningEngine");
      if (documentaryPlanningEnabled()) {
        const scenesForPlan = scenes.map((s) => ({
          index: s.index,
          beats: ((s as { beats?: Array<{ index: number; text: string }> }).beats ?? []).map((b) => ({
            index: b.index,
            text: b.text,
          })),
        }));
        visualDedup.documentaryPlan = buildDocumentaryPlan(
          String(videoId),
          videoTitle ?? "documentary",
          scenesForPlan,
          videoBlueprint ?? null
        );
      }
    }

    // Plan graphic clips (fast, no LLM) and pre-generate them concurrently
    if (editorialGraphicsEnabled()) {
      const graphicPlans = planVideoGraphics(scenes, videoTitle ?? "");
      if (graphicPlans.length > 0) {
        console.log(`[EditorialGraphics] Pre-generating ${graphicPlans.length} graphic clip(s)`);
        await Promise.all(
          graphicPlans.map(async (plan: GraphicPlan) => {
            const key = `s${plan.sceneIndex}b${plan.beatIndex}`;
            const clip = await generateGraphicClip(plan, workDir);
            if (clip) {
              visualDedup.graphicClips.set(key, clip.clipPath);
              recordGraphicUsage(visualDedup.graphicsUsageSummary, plan.type);
            }
          })
        );
        console.log(`[EditorialGraphics] Ready: ${visualDedup.graphicClips.size} clip(s)`);
      }
    }

    if (visualSearchPlanEnabled()) {
      visualDedup.videoVisualContext = await buildVideoVisualContext(
        videoTitle ?? "",
        scenes.map((s) => s.text).filter(Boolean).slice(0, 3).join(" ")
      ).catch(() => undefined);
      getRenderCtx().videoVisualContext = visualDedup.videoVisualContext ?? null;
    }
    if (ttsWordAlignmentEnabled()) {
      const storedTts = loadStoredTtsAlignment(workDir);
      if (storedTts) {
        visualDedup.ttsSceneBeats = buildTtsSceneBeatMap(
          scenes,
          storedTts,
          // One beat per sentence; cap only by minimum clip length (never by cadence).
          (dur) => maxBeatCapForVisualCadence(Math.max(1, dur))
        );
        console.log(
          `[Pipeline] TTS beat planner: ${visualDedup.ttsSceneBeats.size}/${scenes.length} scene(s) word-timed`
        );
      }
    }
    visualDedup.visualBeatsTotal = scenes.reduce(
      (sum, s) => sum + maxBeatCapForVisualCadence(s.duration),
      0
    );
    visualDedup.visualBeatsCompleted = 0;
    visualDedup.varietySeed = ((videoId * 2654435761) ^ hashVarietySeed(topicContext)) >>> 0;
    if (archiveCrossVideoVarietyEnabled(videoLength)) {
      // Reuse the set computed before prefetch so the funnels (prefetch + inline) and the
      // beat-level dedup all exclude the same recently-used assets.
      visualDedup.crossVideoExcludeIds = crossVideoExcludeIdsForRun;
      console.log(
        `[Pipeline] Cross-video variety: excluding ${visualDedup.crossVideoExcludeIds.size} asset(s) from recent same-topic videos`
      );
    }
    console.log(`[Pipeline] Archive variety seed: ${visualDedup.varietySeed}`);

    

    // ── Compose diagnostics helpers (shared between P5A and sequential Stage 4) ─

    /** Log detailed diagnostics for a scene that took >60s to compose. */
    const diagnoseSlowCompose = async (
      sceneIdx: number,
      sceneIndex: number,
      sceneDuration: number,
      outputPath: string,
      clipPaths: string[],
      elapsedMs: number,
      wallStartMs: number,
      pipelineT0Ms: number
    ): Promise<void> => {
      try {
        const rel = ((wallStartMs - pipelineT0Ms) / 1000).toFixed(1);
        console.warn(
          `[ComposeDiag] t=${rel}s Scene ${sceneIndex}: SLOW COMPOSE ${(elapsedMs / 1000).toFixed(1)}s — ` +
          `clips=${clipPaths.length}, scene_dur=${sceneDuration.toFixed(1)}s`
        );
        // Clip sizes
        const clipStats = clipPaths.map((p) => {
          try {
            const stat = fs.statSync(p);
            return `${path.basename(p)}(${(stat.size / 1024 / 1024).toFixed(1)}MB)`;
          } catch { return path.basename(p) + "(?)"; }
        });
        console.warn(`[ComposeDiag] Scene ${sceneIndex} inputs: ${clipStats.join(", ")}`);

        // ffprobe output file for encoder/resolution/fps/duration
        try {
          const probe = await withSceneFetchTimeout(
            () => exec(`${FFPROBE_BIN} -v quiet -print_format json -show_streams -show_format "${outputPath}"`),
            10_000, "ffprobe output"
          );
          const info = JSON.parse(probe.stdout);
          const vs = (info.streams as Array<Record<string, unknown>>).find((s) => s.codec_type === "video");
          const as_ = (info.streams as Array<Record<string, unknown>>).find((s) => s.codec_type === "audio");
          console.warn(
            `[ComposeDiag] Scene ${sceneIndex} output: ` +
            `codec=${vs?.codec_name ?? "?"}, ` +
            `resolution=${vs?.width ?? "?"}x${vs?.height ?? "?"}, ` +
            `fps=${vs?.r_frame_rate ?? "?"}, ` +
            `duration=${Number(info.format?.duration ?? 0).toFixed(2)}s, ` +
            `size=${(Number(info.format?.size ?? 0) / 1024 / 1024).toFixed(1)}MB, ` +
            `audio=${as_?.codec_name ?? "none"}`
          );
        } catch { /* non-fatal */ }

        // CPU and memory snapshot from /proc
        try {
          const cpuInfo = fs.readFileSync("/proc/stat", "utf8").split("\n")[0];
          const memInfo = fs.readFileSync("/proc/meminfo", "utf8");
          const memTotal = Number(memInfo.match(/MemTotal:\s+(\d+)/)?.[1] ?? 0);
          const memAvail = Number(memInfo.match(/MemAvailable:\s+(\d+)/)?.[1] ?? 0);
          const memUsedPct = memTotal > 0 ? ((1 - memAvail / memTotal) * 100).toFixed(0) : "?";
          // /proc/stat: cpu user nice system idle iowait irq softirq
          const cpuNums = cpuInfo.replace("cpu", "").trim().split(/\s+/).map(Number);
          const idle = cpuNums[3] + (cpuNums[4] ?? 0);
          const total = cpuNums.reduce((s, n) => s + n, 0);
          const iowaitPct = total > 0 ? ((cpuNums[4] ?? 0) / total * 100).toFixed(0) : "?";
          const cpuUsedPct = total > 0 ? ((1 - idle / total) * 100).toFixed(0) : "?";
          console.warn(`[ComposeDiag] Scene ${sceneIndex} system: CPU=${cpuUsedPct}% IOWait=${iowaitPct}% RAM=${memUsedPct}%`);
        } catch { /* non-fatal — /proc may not be available */ }

        // Check encoder preset from env (a common source of slowness)
        const ffmpegPreset = process.env.FFMPEG_PRESET ?? "veryfast";
        if (ffmpegPreset !== "veryfast" && ffmpegPreset !== "superfast" && ffmpegPreset !== "ultrafast") {
          console.warn(
            `[ComposeDiag] Encoder preset "${ffmpegPreset}" is slow — ` +
            `consider FFMPEG_PRESET=veryfast for 2-5x faster encode with minimal quality loss`
          );
        }
      } catch { /* always non-fatal */ }
    }

    /** Log Gantt-style relative timestamp for a pipeline event. */
    const gantt = (tag: string, t0Ms: number): void => {
      const rel = ((Date.now() - t0Ms) / 1000).toFixed(1);
      process.stdout.write(`[Gantt] t=${rel}s  ${tag}\n`);
    }

    // ── Shared outputs from Stage 3 + Stage 4 (hoisted for P5A pipeline mode) ─
    /**
     * RONDE 661 — ONE RENDER PATH.
     *
     * The timeline render is the only way FastVid makes a video. The compose montage it replaced —
     * scene compose, concat, music mix, heal, audits, upload — has been removed. A deployment
     * with the timeline switched off has no renderer at all, so it is refused here, before any
     * money is spent, rather than after half an hour of sourcing.
     */
    {
      const { cinematicPlanningEnabled, cinematicRenderPathEnabled } = await import("./cinematicProduction");
      if (!(cinematicPlanningEnabled() && cinematicRenderPathEnabled())) {
        throw pipelineError(
          PIPELINE_ERROR.GENERIC,
          "The timeline is FastVid's only render path: CINEMATIC_EDITING_ENGINE and CINEMATIC_RENDER_PATH must both be on"
        );
      }
    }

    let sceneVisualResults: SceneVisualsResult[] = new Array(scenes.length);

    // ── Sequential: Stage 3 (visuals) then Stage 4 (compose), chunked ~60s at a time ──
    // Long videos are processed in small batches through the exact SAME per-scene Stage
    // 3/4 code the 1-minute path already uses, instead of firing every scene in the whole
    // video at LLM/ffmpeg providers simultaneously (bounded only by a concurrency cap) —
    // that burst is what made long-video quality/consistency lag behind 1-minute videos,
    // whose handful of scenes already behaved like a single small chunk. A 1-minute video's
    // 3 scenes always fit in one chunk below, so this is a no-op restructuring for the case
    // that already works well.
    const chunks = groupScenesIntoChunks(scenes, 60);
    console.log(`[Pipeline] Sequential stage: ${scenes.length} scenes in ${chunks.length} chunk(s) of ~60s`);

    // RONDE 5 / FIX 7 — the visual-sourcing degradation ladder (visualSourcingTurbo 3min →
    // isPipelineRushMode 5min → isPipelineEmergencyFinish 7min, all reading
    // dedup.pipelineStartedMs) now measures VISUAL time, from the moment the scene loop
    // below actually starts. It used to measure from videoRow.generationStartedAt, which
    // meant (a) script + TTS + archive-pool warm + CLIP prewarm all counted against the
    // sourcing budgets, and (b) a stall-recovery RETRY inherited the first attempt's clock
    // wholesale — render 517 attempt 2 started with 12s beat budgets 34 seconds in and lost
    // every one of its six VisionGate-passed candidates to them. The hard wall-clock guard is
    // unaffected: assertPipelineWithinBudget stopped throwing on elapsed time in F3-47 and
    // only surfaces real cancellations, which still use pipelineWallStartMs.
    visualDedup.pipelineStartedMs = Date.now();
    console.log(
      `[Pipeline] video=${videoId} sourcing-ladder clock started at visual stage ` +
      `(total elapsed so far: ${Math.round((Date.now() - pipelineWallStartMs) / 1000)}s)`
    );

    /**
     * ONE HARD DEADLINE FOR THE WHOLE VISUAL PHASE — the render's own retrieval budget, as a wall
     * clock. Every chunk's scope is clamped to it, and every scope below inherits the clamp, so at
     * this moment no search, download or fallback may start and in-flight ones are aborted. A beat
     * or scene with no picture by then is a gap; the timeline holds the previous shot over it.
     */
    const visualDeadlineMs = (get_activeRenderBudget()?.perSceneRetrieveMs ?? 35_000) * scenes.length;
    const visualDeadlineAtMs = Date.now() + visualDeadlineMs;
    console.log(
      `[Pipeline] video=${videoId} visual deadline ${Math.round(visualDeadlineMs / 1000)}s — ` +
        `after it no search or download starts and an empty beat is a gap`
    );

    const visualLimit = pLimit(perf.sceneParallelism);
    let completedVisuals = 0;
    let activeSceneIdx = 0;
    let heartbeatTick = 0;
    const visualHeartbeat = setInterval(() => {
      try {
        heartbeatTick++;
        ensurePipelineForceExport(visualDedup);
        assertPipelineWithinBudget(videoId, pipelineWallStartMs, videoLength, visualDedup);
        const beatTotal = Math.max(1, visualDedup.visualBeatsTotal || scenes.length);
        const beatsDone = visualDedup.visualBeatsCompleted ?? completedVisuals;
        onProgress?.({
          stage: `Finding visuals (${beatsDone}/${beatTotal} beats, scene ${Math.min(activeSceneIdx + 1, scenes.length)}/${scenes.length})...`,
          percent: 20 + Math.round((beatsDone / beatTotal) * 25),
        });
      } catch (err) {
        // assertPipelineWithinBudget()'s intentional throw must not escape a raw setInterval
        // callback uncaught — an uncaught throw there would crash the worker process.
        clearInterval(visualHeartbeat);
        console.error(`[Pipeline] video=${videoId} visual heartbeat check failed — cancelling render:`, (err as Error).message);
        requestVideoGenerationCancel(videoId);
      }
    }, 10_000);
    sceneVisualResults = new Array(scenes.length);

    const t3 = Date.now();
    profiler.recordStageEnd("retrieval", t3);

    try {
    for (let chunkIdx = 0; chunkIdx < chunks.length; chunkIdx++) {
      const chunk = chunks[chunkIdx]!;
      const chunkScenes = scenes.slice(chunk.start, chunk.end);
      /** Set when this chunk's scope ends; a scene that returns after that writes nothing. */
      let chunkClosed = false;
      const visualTimeLeftMs = visualDeadlineAtMs - Date.now();
      if (visualTimeLeftMs <= 0) {
        console.warn(
          `[Pipeline] Visual deadline reached — chunk ${chunkIdx + 1}/${chunks.length} is not searched; its scenes are gaps`
        );
      } else
      try {
      await withSceneFetchTimeout(
        () => Promise.all(chunkScenes.map((scene, ci) => visualLimit(async () => {
        const sceneIdx = chunk.start + ci;
        activeSceneIdx = sceneIdx;
        let result: SceneVisualsResult;
        try {
          result = await timePipelineStep(
            pipelineStepTiming,
            "image_search",
            `Scene ${scene.index} visuals (all beats)`,
            () =>
              withSceneFetchTimeout(
                () => fetchSceneVisuals(
                  scene,
                  workDir,
                  topicContext,
                  visualDedup,
                  (beatIdx, beatTotal, phase) => {
              const stage =
                phase === "backfill"
                  ? `Scene ${sceneIdx + 1}/${scenes.length}: backfill ${beatIdx}/${beatTotal}...`
                  : `Finding visuals (${visualDedup.visualBeatsCompleted}/${visualDedup.visualBeatsTotal || beatTotal} beats)...`;
              const progressBase =
                visualDedup.visualBeatsTotal > 0
                  ? visualDedup.visualBeatsCompleted / visualDedup.visualBeatsTotal
                  : (sceneIdx + beatIdx / Math.max(1, beatTotal)) / scenes.length;
              onProgress?.({
                stage,
                percent: 20 + Math.round(progressBase * 25),
              });
            },
                  audioPaths[sceneIdx],
                  prefetchPools,
                  prefetchFunnels
                ),
                sceneSearchBudgetMs({
                  flatMs: perf.sceneVisualTimeoutMs,
                  sceneDurationSec: scene.duration,
                }),
                `Scene ${scene.index} visuals`
              ),
            scene.index
          );
        } catch (sceneErr) {
          /** Reported, and the scene is empty: no second search after a failed first one. */
          console.warn(
            `[Pipeline] Scene ${scene.index} visuals failed — the scene has no picture:`,
            (sceneErr as Error).message
          );
          visualDedup.lock = Promise.resolve();
          result = { clips: [], beatDurations: [] };
        }
        if (chunkClosed) return result;
        sceneVisualResults[sceneIdx] = result;
        completedVisuals++;
        onProgress?.({
          stage: `Generating AI visuals... (${completedVisuals}/${scenes.length} scenes done)`,
          percent: 20 + Math.round((completedVisuals / scenes.length) * 25),
        });
        return result;
      }))),
      // RONDE 81: never below what the scenes in this chunk are each allowed to take —
      // and never past the visual deadline.
      Math.min(
        chunkStageTimeoutMs(
          visualStageTimeoutMs(videoLength, perf),
          chunkScenes.length,
          scenes.length,
          20_000,
          perf.sceneVisualTimeoutMs
        ),
        visualTimeLeftMs
      ),
      `Visual generation stage chunk ${chunkIdx + 1}/${chunks.length}`
    );
    } catch (visualStageErr) {
      chunkClosed = true;
      console.warn(
        `[Pipeline] Visual stage cap hit chunk ${chunkIdx + 1}/${chunks.length} (${completedVisuals}/${scenes.length} scenes done) — self-healing:`,
        (visualStageErr as Error).message
      );
      visualDedup.lock = Promise.resolve();
    }
    chunkClosed = true;
    for (let si = chunk.start; si < chunk.end; si++) {
      sceneVisualResults[si] ??= { clips: [], beatDurations: [] };
    }

    // Refine compose budget based on this chunk's actual clip mix from retrieval — recomputed
    // per chunk (more locally accurate than one whole-video aggregate), feeds into
    // renderBudgetComposeMs used by the compose calls further down for THIS chunk onward.
    const budgetTracker = get_activeBudgetTracker();
    const activeRenderBudget = get_activeRenderBudget();
    if (budgetTracker && activeRenderBudget) {
      const chunkRetrievedClips = sceneVisualResults.slice(chunk.start, chunk.end).flatMap(r => r?.clips ?? []);
      const totalClips = chunkRetrievedClips.length || 1;
      const archiveClips = chunkRetrievedClips.filter(p => curatedClipPathAssetId(p) != null).length;
      const aiClips = chunkRetrievedClips.filter(p => isAIGeneratedClip(p)).length;
      const signals = {
        archiveClipRatio:    archiveClips / totalClips,
        aiClipRatio:         aiClips / totalClips,
        clipCacheHitRatio:   0,
        totalClipsRetrieved: totalClips,
        avgClipsPerScene:    totalClips / chunkScenes.length,
      };
      const { newComposeMs, newConfidence } = budgetTracker.refineFromSignals(signals, activeRenderBudget);
      set_activeRenderBudget({ ...activeRenderBudget, basePerSceneComposeMs: newComposeMs, confidence: newConfidence });
      renderBudgetComposeMs = newComposeMs;
    }

    if (visualDedup.forceExportMode) {
      console.warn("[Pipeline] Force-export — skipping polish, proceeding to compose with current clips");
    }

    /**
     * A scene that came back without a picture stays without one. What stood here were three more
     * layers after the scene's own search — an empty-scene sweep (AI clip, guaranteed cards, a
     * second strict refill), a "still short" refill loop, and a polish pass that could replace a
     * picture already chosen — each with its own clock. The timeline holds the previous shot over
     * a beat with no picture (`holdPictureUnderVoice`), and a film with no picture at all is
     * refused there with a reason.
     */
    for (let si = chunk.start; si < chunk.end; si++) {
      const usable = (sceneVisualResults[si]?.clips ?? []).filter((c) => c && !isPipelineFallbackClip(c));
      if (usable.length > 0) continue;
      console.warn(`[Pipeline] Scene ${scenes[si].index}: no picture found — the timeline holds the previous shot`);
    }

    // ── Editorial Reorder: AI final-editor pass — optimise montage order per scene ──
    if (editorialReorderEnabled()) {
      const reorderT0 = Date.now();
      try {
        await Promise.all(
          chunkScenes.map(async (scene, ci) => {
            const i = chunk.start + ci;
            const vr = sceneVisualResults[i];
            if (!vr || vr.clips.length < 2) return;
            const reordered = await editorialReorderScene(
              scene.index,
              scene.text,
              topicContext ?? "",
              scene.duration,
              vr.clips,
              vr.beatDurations,
              vr.clipBeatIndices,
              vr.beats
            );
            const prevSceneVisual_11 = sceneVisualResults[i];
            sceneVisualResults[i] = {
              ...vr,
              clips: reordered.clips,
              beatDurations: reordered.beatDurations,
              clipBeatIndices: reordered.clipBeatIndices,
            };
            noteSceneClipsResourced(visualDedup, prevSceneVisual_11, sceneVisualResults[i], scenes[i]?.index ?? i, "beat_reorder");
          })
        );
        console.log(`[Editorial] Reorder pass done in ${Date.now() - reorderT0}ms`);
      } catch (err) {
        console.warn("[Editorial] Reorder pass error (ignored):", (err as Error).message?.slice(0, 80));
      }
    }

    // ── Shot Sequence Optimizer: deterministic shot-type variety pass ──
    if (shotSequenceOptimizerEnabled()) {
      for (let i = chunk.start; i < chunk.end; i++) {
        const vr = sceneVisualResults[i];
        if (!vr || vr.clips.length < 2) continue;
        const sso = optimizeShotSequence(scenes[i].index, vr.clips, vr.beatDurations, vr.clipBeatIndices, vr.beats);
        if (sso.changes > 0) {
          const prevSceneVisual_12 = sceneVisualResults[i];
          sceneVisualResults[i] = { ...vr, clips: sso.clips, beatDurations: sso.beatDurations, clipBeatIndices: sso.clipBeatIndices };
          noteSceneClipsResourced(visualDedup, prevSceneVisual_12, sceneVisualResults[i], scenes[i]?.index ?? i, "shot_sequence");
        }
      }
    }

    // ── Visual Rhythm Engine: adjust beat durations to narration energy arc ──
    if (visualRhythmEngineEnabled()) {
      for (let i = chunk.start; i < chunk.end; i++) {
        const vr = sceneVisualResults[i];
        if (!vr || (vr.beatDurations?.length ?? 0) < 2) continue;
        const beatTexts = (vr.beats ?? []).map((b) => b.text);
        if (beatTexts.length === 0) continue;
        const rr = applyVisualRhythm(scenes[i].index, beatTexts, vr.beatDurations);
        const prevSceneVisual_13 = sceneVisualResults[i];
        sceneVisualResults[i] = { ...vr, beatDurations: rr.beatDurations };
        noteSceneClipsResourced(visualDedup, prevSceneVisual_13, sceneVisualResults[i], scenes[i]?.index ?? i, "visual_rhythm");
      }
    }

    if (composeLocalClipsOnly(videoLength)) {
      visualDedup.composeNetworkBlocked = true;
      console.log(
        "[Pipeline] Cache-then-render: compose uses local clips only (set COMPOSE_LOCAL_CLIPS_ONLY=false to allow compose-time fetch)"
      );
    }

    } // end for (chunk of chunks)
    } finally {
      clearInterval(visualHeartbeat);
    }

    /**
     * A scene with no picture is a gap the timeline holds over. A film with no picture in ANY scene
     * has nothing to hold, so it is refused here, with the render's own explanation first.
     */
    const firstEmptySi = sceneVisualResults.findIndex(
      (r) => !(r?.clips ?? []).some((c) => c && !isPipelineFallbackClip(c))
    );
    const noSceneHasPicture = sceneVisualResults.every(
      (r) => !(r?.clips ?? []).some((c) => c && !isPipelineFallbackClip(c))
    );
    if (noSceneHasPicture && firstEmptySi >= 0) {
      const si = firstEmptySi;
      /**
       * RONDE 224/226/227/247 — the render's own explanation, printed at the exit it takes: the
       * vision tally, the funnel, the decline census, the invariants, where the chosen pictures
       * went and the time report. Their other readers are in the report, past this throw.
       */
      const why = formatNoVerdictReasons(visualDedup.beatImageGate);
      const gate = visualDedup.beatImageGate;
      console.error(
        `[Pipeline] Scene ${scenes[si].index}: 0 bruikbare clips — vision attempts=${gate.judgementAttempts} ` +
          `fits=${gate.judgementsFits} mismatch=${gate.judgementsMismatch} failed=${gate.judgementsFailed} ` +
          `skipped=${gate.judgementsSkipped} providerUnavailable=${gate.judgementsProviderUnavailable} askImpossible=${gate.askImpossible}`
      );
      if (why) console.error(why);
      for (const line of formatBeatShortlists(visualDedup.beatShortlist)) console.error(line);
      const census = formatDeclineCensus(visualDedup.beatShortlist);
      if (census) console.error(census);
      for (const line of beatShortlistViolations(visualDedup.beatShortlist)) console.error(line);
      reportLineageOutcomeInvariant(visualDedup.sourcingCache?.lineage, {
        ok: (line) => console.log(line),
        fail: (line) => console.error(line),
      });
      for (const line of pipelineStepTiming.toReportLines()) console.error(line);
      throw pipelineError(
        PIPELINE_ERROR.FFMPEG,
        `Scene ${scenes[si].index}: no picture was found for any of its beats — export geblokkeerd`
      );
    }
    get_activeBudgetTracker()?.stageEnd("retrieval");
    console.log(`[Pipeline] Stage 3 (visuals): ${((Date.now()-t2)/1000).toFixed(1)}s`);

    // ── Global Documentary Director: whole-video editorial analysis — runs once, after all
    // chunks are done, over the fully-accumulated sceneVisualResults (was previously between
    // Stage 3 and Stage 4, now moved here since it's whole-video analysis, not per-chunk). ──
    if (globalDocumentaryDirectorEnabled() && scenes.length >= 2) {
      setImmediate(() => {
        const sceneClips = sceneVisualResults.map((vr) => vr?.clips ?? []);
        const sceneBeats = sceneVisualResults.map((vr) => vr?.beats ?? []);
        /**
         * The same observed-framing resolver `assetDirector` is handed — see `shotTypeOf` there.
         * Without it the director's variety findings were read off the narration, so render 573
         * reported "no wide shots anywhere in the video" about a script, not about a film.
         */
        analyzeVideoStructure(
          topicContext ?? "documentary",
          scenes.map((s) => s.text),
          sceneClips,
          sceneBeats,
          (clipPath) =>
            visualDedup.clipAnnotationMeta.get(clipPath)?.observedShotType ??
            visualDedup.clipAnnotationMeta.get(clipPath)?.annotation?.cinematography?.shotType ??
            null
        ).catch(() => {});
      });
    }

    pipelineStepTiming.summarizeAll();
    logSourcingMetrics(visualDedup.sourcingCache, videoId);

    /**
     * WHAT A SCENE IS MADE OF — one rule, one spelling: the clips its sourcing selected. The
     * editor, the planner and the quality report all read it from here. The report's figures are
     * re-counted against the delivered file once the timeline render has produced it.
     */
    const clipsForScene = (i: number): string[] => sceneVisualResults[i]?.clips ?? [];
    onProgress?.({ stage: STAGE_LABELS.visualReview, percent: 68 });

    /** RONDE 661 — with no compose, the video's clips are each scene's selected clips. */
    const allClipPaths = scenes.map((_, i) => clipsForScene(i)).flat().filter(Boolean);
    /**
     * RONDE 106 — collect the render's own reports so they can be stored with the video.
     *
     * Created here because everything worth keeping is emitted from this point on. The emitters
     * are unchanged; each one now hands its line to the collector on the way to the console.
     */
    const pipelineReport = createPipelineReportCollector(
      videoId,
      visualDedup.sourcingCache.lineage.renderId
    );
    /**
     * THE CURATED CLIPS GET THEIR PROVENANCE BACK, FROM THE ARCHIVE TABLE, BEFORE ANYTHING COUNTS.
     *
     * Render 577 was refused publication on `MOSTLY_UNVERIFIED_CLIPS — 9 of 15 fetched clip(s)
     * have no proven source`. Every one of the nine was a clip out of FastVid's own curated
     * archive, adopted through a route that did not open its lineage record first, so
     * `recordClipAdoption` opened an anonymous one: asset id present, provider absent. The gate
     * was right — the ledger genuinely could not say where the footage came from — and the
     * evidence was sitting in `media_archive_assets` the whole time.
     *
     * Here, because `buildVideoQualityReport` is the first reader that counts providers, and a
     * repair that landed after it would fix the ledger and leave the number that blocks the export
     * untouched. Nothing is relaxed: the lookup either finds the row or it does not, and a record
     * it cannot resolve stays UNVERIFIED.
     */
    try {
      const ledger = visualDedup.sourcingCache.lineage;
      const needing = curatedAssetIdsNeedingProvenance(ledger.allRecords());
      const rows = needing.length > 0 ? await getCuratedArchiveProvenance(needing) : [];
      const repair = repairCuratedProvenance(ledger, rows);
      console.log(formatCuratedProvenanceRepair(repair));
    } catch (err) {
      /** A failed lookup leaves every record exactly as it was — UNVERIFIED, and the gate decides. */
      console.warn(
        `[CuratedProvenance] archive lookup failed — records stay unattributed:`,
        (err as Error).message?.slice(0, 200)
      );
    }
    /** Carried into the quality report's warnings below, so the mix reaches the stored report too. */
    const qualityReportScreenTimeWarnings: string[] = [];
    /**
     * The same findings as VALUES rather than as prose, because the score reads them.
     *
     * A warning is a sentence for a person; `computeMeritQualityScore` needs the codes. Render 578
     * gave 47.6% of a 76-second film to one shot and held another for 17.4 seconds, and scored 43
     * on inputs that could not see either — then the export-availability policy raised that 43 to
     * 85 because every clip came from the curated archive.
     */
    const deliveredScreenTimeFindings: ScreenTimeFinding[] = [];
    /**
     * WHAT THE VIEWER ACTUALLY SPENDS THEIR TIME LOOKING AT — see `deliveredScreenTime`.
     *
     * A 76-second render shipped with one modern stock clip filling 36.3 seconds of it, 47.6% of
     * the film, across three appearances including the opening and closing shots. Every gate
     * passed it, because the one number that describes the mix — `bySource` in the quality report
     * — is `+ 1` per CLIP, so a 36-second clip and a 2-second clip weigh the same.
     *
     * Measured here, beside that report and from the same clip list, in seconds. Durations come
     * from the render's own memoised probe where it has one and a real ffprobe otherwise; the
     * source comes from the ledger, never from a filename.
     */
    try {
      const ledger = visualDedup.sourcingCache.lineage;
      const seenDur = new Map<string, number>();
      const delivered: DeliveredClip[] = [];
      for (const clipPath of allClipPaths) {
        let durationSec = seenDur.get(clipPath) ?? 0;
        if (!durationSec) {
          durationSec =
            memoisedVideoStreamMeta(clipPath)?.durationSec ||
            (await probeVideoDurationSec(clipPath).catch(() => 0));
          seenDur.set(clipPath, durationSec);
        }
        const contentKey = clipContentKey(clipPath) || null;
        delivered.push({
          path: clipPath,
          source: ledger.providerFor(clipPath, contentKey ?? undefined),
          contentKey,
          durationSec,
        });
      }
      const share = computeScreenTimeShare(delivered);
      const findings = screenTimeFindings(share, {}, delivered);
      const line = formatScreenTimeShare(share, findings);
      if (findings.length > 0) console.warn(line);
      else console.log(line);
      for (const f of findings) {
        console.warn(`[ScreenTime] ${f.code} — ${f.detail}`);
        qualityReportScreenTimeWarnings.push(`Screen time: ${f.code} — ${f.detail}`);
        deliveredScreenTimeFindings.push(f);
      }
    } catch (err) {
      /** A measurement that fails measures nothing; it never costs the render its film. */
      console.warn(`[ScreenTime] could not measure the delivered mix:`, (err as Error).message?.slice(0, 200));
    }
    const qualityReport = buildVideoQualityReport(allClipPaths, videoTitle, {
      pipelineSec: Math.round((Date.now() - t0) / 1000),
      stockBeatsUsed: visualDedup.stockBeatsUsed,
      rejectAudit: visualDedup.clipRejectAudit.entries,
      /** The uncapped tally beside the bounded examples — see `rejectTally` in the report. */
      rejectTally: visualDedup.clipRejectAudit,
      adoptAudit: visualDedup.clipAdoptAudit,
      archiveOnly: false,
      fastShort: isFastShortVideoLength(videoLength),
      // RONDE 86/87: the report reads the ledger and nothing else. A clip whose origin cannot be
      // proven comes back null here and is counted as UNVERIFIED — never re-derived from its name.
      resolveSource: (clipPath) => visualDedup.sourcingCache.lineage.providerFor(clipPath),
      /** The same ledger, asked the question `providerFor` cannot express — see generatedClips. */
      isGeneratedClip: (clipPath) => visualDedup.sourcingCache.lineage.isGeneratedFallback(clipPath),
      // RONDE 105: the relevance ledger, so the report can tell a beat whose picture was approved
      // from one whose picture nobody looked at. Without it every beat reads as never_asked.
      relevanceLedger: visualDedup.beatRelevance,
      /** Measured just above, in seconds, on this same clip list — and it costs the score. */
      screenTime: deliveredScreenTimeFindings,
    });
    // RONDE 8 (render 518): a scene whose montage came up short scored 100/100 because the filler
    // is not a fallback clip. Same registration pattern as the silent-voiceover notes below.
    //
    // RONDE 27: reworded, twice over. The list is populated from the pre-compose ESTIMATE, so it
    // flags scenes where the montage was predicted short — render 528 reported "gray pad scene 1"
    // while no tpad filter appears in any of that render's ffmpeg commands, i.e. the estimate was
    // pessimistic and nothing was actually padded. And since RONDE 26 the filler is a held last
    // frame, not grey. Asserting a grey filler had been rendered was wrong on both counts. What the
    // list genuinely means is "this scene did not have enough footage to fill its narration",
    // which is the thing worth reporting either way.
    /**
     * The delivered mix reaches the STORED report, not only the console.
     *
     * Measured a few hundred lines above, before the report exists. Carrying it here rather than
     * leaving it in the log is the difference between a finding an operator can read back off the
     * video and one that scrolls past in a worker log nobody opens — which is how a film that was
     * 47.6% one stock clip reached an audience.
     */
    for (const w of qualityReportScreenTimeWarnings) qualityReport.warnings.push(w);
    if (visualDedup.grayPadScenes.length > 0) {
      const padScenes = [...visualDedup.grayPadScenes].sort((a, b) => a - b);
      qualityReport.warnings.push(formatMontageShortfallWarning(visualDedup.montageShortfalls, padScenes));
      console.warn(
        `[Quality] Video ${videoId}: ${padScenes.length} scene(s) with a short montage (${padScenes.join(", ")}) — visual coverage incomplete`
      );
    }
    // RONDE 29: report the mix the render actually produced. Until now nothing measured this,
    // so "there should be more video than photos" was a claim nobody could check against a
    // finished render — including me, when I sized the moving-footage bonus in RONDE 27.
    {
      /**
       * RONDE 164 — which constraint actually bound this render, across every beat.
       *
       * One beat proves nothing about a download budget. This is the number the next round needs
       * before touching MAX_FUNNEL_CANDIDATES_TO_SCORE: a render whose beats mostly read
       * LOST_BEFORE_VISION with cutByBudget high has a budget problem; one whose beats read
       * REJECTED_BY_VISION has a candidate-quality problem, and raising the budget would only buy
       * more downloads to refuse.
       */
      {
        const sourcingTotal = summarizeArchiveSourcing(visualDedup.archiveSourcingAudits);
        if (sourcingTotal) console.log(sourcingTotal);
      }
      const moving = visualDedup.movingClipCount;
      const still = visualDedup.stillClipCount;
      const total = moving + still;
      console.log(`[Quality] Video ${videoId}: visual mix — ${summarizeMovingShare(moving, still)}`);
      if (total >= MIN_MIX_SAMPLE && movingShareDeficit(moving, total) > 0) {
        qualityReport.warnings.push(
          `visual mix: ${summarizeMovingShare(moving, still)} — below the ${Math.round(
            resolveTargetMovingShare() * 100
          )}% moving-footage target`
        );
      }
    }
    // RONDE 29: which gates actually said no this render, and which never did.
    //
    // A gate that was asked plenty and rejected nothing is exactly the shape of the modern-
    // mismatch bug — 152 calls, healthy logs, flag on, structurally unable to fire. It may also
    // just mean the material was clean, so this is a warning to go look, not a failure.
    {
      // RONDE 67: say how many picture judgements the model could not deliver.
      //
      // Render 533 refused 34 clips on this gate while the log carried 16 `Gemini API error 429`
      // and 5 `groq 400 Bad Request`, and nothing in the report told the two apart. "The gate
      // looked and said no" means the sourcing is wrong; "the gate could not look" means the
      // verdicts are noise and the montage was assembled without a picture editor. Reading one
      // as the other sends the next round of work in the wrong direction.
      {
        const g = visualDedup.beatImageGate;
        const t = judgementTally(g);
        /**
         * RONDE 105 — the counters are printed as a partition, not as numbers to combine.
         *
         * What stood here computed `failed / (used + failed)` and called it "could not fetch N of
         * M". `used` counted ATTEMPTS and `failed` counted the failures among them, so the
         * denominator double-counted every failure: a render where the model answered nothing
         * (attempts 44, failed 44) reported "44 of 88", which reads as half. It was all of them,
         * and the video shipped with a picture editor that had approved not one frame.
         */
        if (t.attempts > 0 || t.skipped > 0) {
          console.log(
            `[Quality] Video ${videoId}: beat image gate — attempts=${t.attempts} ` +
              `answered=${t.answered} (fits=${t.fits} does_not_fit=${t.mismatch}) ` +
              `failed=${t.failed} never_asked=${t.skipped}`
          );
          // RONDE 115: and WHY, in one line — the fact that was previously spread over one log
          // line per clip and therefore invisible.
          {
            const why = formatNoVerdictReasons(g);
            if (why) console.warn(why);
          }
          // RONDE 119: and WHO answered. A chain that fell through to its last provider used to
          // look exactly like one where the configured provider answered everything.
          {
            const who = formatVerdictProviders(g);
            if (who) console.log(who);
          }
          if (t.inconsistent) {
            qualityReport.warnings.push(
              `beeldgate-tellers kloppen niet: ${t.attempts} pogingen ≠ ${t.fits}+${t.mismatch}+${t.failed}`
            );
          }
          if (t.attempts > 0 && t.answered === 0) {
            qualityReport.warnings.push(
              `beeldgate gaf GEEN ENKEL oordeel: ${t.attempts} pogingen, ${t.failed} mislukt — ` +
                `elke clip in deze video is ONGEZIEN aangenomen`
            );
          } else if (t.failed >= Math.max(3, t.attempts * 0.25)) {
            qualityReport.warnings.push(
              `beeldgate kon ${t.failed} van ${t.attempts} pogingen niet beantwoorden — ` +
                `die clips zijn ONGEZIEN aangenomen`
            );
          }
          /**
           * RONDE 103 — a decline is not a pass. `never_asked` counts the asks this gate never
           * attempted: budget spent, per-beat ceiling reached, no readable frame. Kept separate
           * from `unavailable` because the two have different causes and different fixes.
           */
          if (t.skipped >= Math.max(3, t.attempts * 0.25)) {
            qualityReport.warnings.push(
              `beeldgate is ${t.skipped} keer niet eens bevraagd (budget op, of geen ` +
                `leesbaar beeld) — die clips zijn ONGEZIEN aangenomen`
            );
          }
          /**
           * RONDE 131 — and WHAT was wrong with the pictures it refused.
           *
           * `does_not_fit=21` says twenty-one pictures did not belong. It does not say whether a
           * narrower query would have found better ones or whether the archives simply do not
           * hold them, and those are the two projects the next round has to choose between. The
           * split below is the first time this render can answer that.
           */
          {
            const summary = formatMismatchSummary(visualDedup.mismatchTally);
            if (summary) console.log(summary);
            /**
             * RONDE 132 — and what the render DID about it.
             *
             * The mismatch split says how many refusals a better question could have prevented.
             * This says how many the render actually went back and asked, and how many of those
             * came home with a picture the gate then accepted. The two lines together are the
             * before/after this round is measured on.
             */
            const research = formatResearchSummary(visualDedup.researchTally);
            if (research) console.log(research);
            const split = mismatchFaultSplit(visualDedup.mismatchTally);
            if (split.question >= Math.max(3, visualDedup.mismatchTally.total * 0.5)) {
              qualityReport.warnings.push(
                `${split.question} van ${visualDedup.mismatchTally.total} afgewezen beelden waren ` +
                  `fout van soort (verkeerde periode, plaats of onderwerp) — die had een ` +
                  `preciezere zoekvraag kunnen voorkomen`
              );
            }
            /**
             * RONDE 135 — the three lines above, joined to the one fact they were all missing.
             *
             * "21 refusals" is a fact about the render. "Pexels supplied nine candidates and eight
             * were refused as present-day footage" is a fact about a SOURCE, and only the second
             * says where to look next. The tally has been keyed by `${kind}|${source}` since
             * RONDE 131 and nothing had ever printed it.
             */
            const adoptedByProvider = new Map<string, number>();
            for (const entry of visualDedup.clipAdoptAudit) {
              const key = (entry.source ?? "").trim().toLowerCase() || "unknown";
              adoptedByProvider.set(key, (adoptedByProvider.get(key) ?? 0) + 1);
            }
            console.log(
              formatVisualSourcingAudit({
                beats: qualityReport.beatVisuals?.beats ?? 0,
                visionAttempts: t.attempts,
                fits: t.fits,
                doesNotFit: t.mismatch,
                research: {
                  attempts: visualDedup.researchTally.attempts,
                  produced: visualDedup.researchTally.produced,
                  accepted: visualDedup.researchTally.accepted,
                  rejected: visualDedup.researchTally.rejected,
                },
                tally: visualDedup.mismatchTally,
                adoptedByProvider,
              })
            );
            /**
             * A provider that supplied plenty and passed nothing is reported, never removed.
             * RONDE 135 §8: one render is not evidence about a catalogue, it is a prompt to look.
             */
            const unproductive = findUnproductiveProviders(
              summarizeProviderOutcomes({ tally: visualDedup.mismatchTally, adoptedByProvider })
            );
            for (const p of unproductive) {
              qualityReport.warnings.push(
                `bron ${p.provider} leverde ${p.judged} beoordeelde kandidaten en geen enkele ` +
                  `bruikbare${p.topKind ? ` (meestal ${p.topKind})` : ""}`
              );
            }
          }
        }
        console.log(
          `[Quality] Video ${videoId}: ${formatRelevanceSummary(g, visualDedup.beatRelevance)}`
        );
        /**
         * RONDE 203 — the barrier's own coverage, which its comment promised and nothing produced.
         *
         * `barrierCoverage` reports what the ledger holds; the two counters report what the
         * barrier was ASKED. Both, because they answer different questions: how many verdicts this
         * render owns, and how many of the clips that reached compose had one. Printed on a clean
         * render too — "every clip had a verdict" is the claim the export gate rests on, and a
         * line that only appears when something is wrong cannot make it.
         */
        {
          const ctx = getRenderCtx();
          const ledgerCoverage = barrierCoverage(visualDedup.beatRelevance);
          console.log(
            pipelineReport.add(
              "summary",
              `${formatComposeBarrierCoverage(ctx.barrierChecked, ctx.barrierPassedUnjudged)} ` +
                `judgedPaths=${ledgerCoverage.judgedPaths} judgedAssets=${ledgerCoverage.judgedAssets}`
            )
          );
        }
        /**
         * RONDE 103 phase 15 — a shot used over the picture editor's objection is reported as
         * exactly that. The reprieve is a deliberate product choice (a real picture beats a grey
         * card), but a render that had to make it eight times is telling you its sourcing failed,
         * and that has to be visible rather than folded into the pass count.
         */
        let reprieved = 0;
        for (const { decision } of visualDedup.beatRelevance.byClipPath.values()) {
          if (decision.reprieved) reprieved++;
        }
        if (reprieved > 0) {
          qualityReport.warnings.push(
            `${reprieved} clip(s) zijn gebruikt terwijl de beeldgate ze had afgekeurd — er was ` +
              `geen alternatief (verdict=does_not_fit, reprieved=true)`
          );
        }
      }
      // RONDE 70: one funnel line per beat, for EVERY beat.
      //
      // Until now the render explained only its failures — [VisualCoverage] fires inside the
      // placeholder block, so a beat that got a clip said nothing at all. Render 534's central
      // question ("398 candidates, where did they go?") cannot be answered from a log that
      // records only the losses.
      //
      // The report is built in beatOutcomeAudit.renderBeatFunnelReport rather than inlined here,
      // so "one line per beat" is something a test can count instead of read. Everything it uses
      // is a counter this render already kept: no provider is called, nothing is re-ranked and
      // nothing is re-judged.
      {
        const planned: Array<{ sceneIndex: number; beatIndex: number }> = [];
        sceneVisualResults.forEach((svr, si) => {
          const sceneIndex = scenes[si]?.index ?? si;
          for (const b of svr?.beats ?? []) planned.push({ sceneIndex, beatIndex: b.index });
        });
        for (const line of renderBeatFunnelReport(
          visualDedup.beatOutcomeAudit,
          planned,
          visualDedup.clipRejectAudit
        )) {
          console.log(line);
        }
        const byProvider = formatEligibleNotAdoptedByProvider(visualDedup.sourcingCache.metrics);
        if (byProvider) console.log(byProvider);
      }
      const gateStats = getActiveGateFiringStats();
      if (gateStats) {
        console.log(
          pipelineReport.add("gates", `[GateFiring] ${formatGateFiringSummary(gateStats)}`)
        );
        /**
         * RONDE 105/106: the gates RONDE 103 and 104 demoted on purpose are reported as
         * information rather than as an alarm, so the admin can see how often they WOULD have
         * fired without being told to go and fix something that is working as designed.
         */
        for (const row of summarizeDemotedGates(gateStats)) {
          pipelineReport.add(
            "gates",
            `[GateDemoted] ${row.gate} asked=${row.asked} fired=${row.fired} — ` +
              `bewust geen veto meer (RONDE 103/104)`
          );
        }
        const silent = findSilentGates(gateStats);
        if (silent.length > 0) {
          /**
           * RONDE 174 — the warning now carries the measurement instead of an instruction.
           *
           * "verify the check can still fire" told a reader to go and read code, every render,
           * with nothing new to read. `closest 0.021 short of firing` says whether the threshold
           * or the material is the reason, in the same unit the threshold is written in.
           */
          const detail = silent.map(describeSilentGate).join(", ");
          qualityReport.warnings.push(
            `silent gate(s): ${detail} — asked repeatedly, rejected nothing`
          );
          console.warn(pipelineReport.add("gates", `[GateSilent] ${detail}`));
        }
        /**
         * Gates that looked and had no rule that could apply to this subject. Reported as
         * information: `documentary_beat_gate`'s blocklists are about pharmacies, Columbus Ohio
         * and a Dutch/US region lock, so a WWII documentary never touches them. That is not a
         * defect, and reporting it as one every render is how a real alarm gets ignored.
         */
        for (const row of findOutOfScopeGates(gateStats)) {
          console.log(
            pipelineReport.add(
              "gates",
              `[GateOutOfScope] ${row.gate} asked=${row.asked} notArmed=${row.notArmed} — ` +
                `geen regel van toepassing op dit onderwerp`
            )
          );
        }
      }
    }
    // RONDE 28b: with the render finished we know which providers contributed nothing, so the
    // searches that led nowhere can be written down as dead ends. Done here rather than per
    // search because only now is the answer actually known — mid-render a provider that has not
    // produced anything yet may still be about to.
    const missTopic = get_activeVideoTopic();
    if (missTopic) {
      const adoptedByProvider = new Map<string, number>();
      // RONDE 100B: what each provider actually returned, so a source that answered is not
      // written off as a dead end because a later stage ran out of budget.
      const resultsByProvider = new Map<string, number>();
      for (const [provider, m] of visualDedup.sourcingCache.metrics) {
        adoptedByProvider.set(provider.trim().toLowerCase(), m.acceptedCount);
        resultsByProvider.set(provider.trim().toLowerCase(), m.resultCount);
      }
      recordSearchMisses({
        subject: missTopic.primaryPerson || missTopic.videoTitle,
        subjectType: missTopic.primaryPerson ? "person" : "topic",
        searchedKeys: visualDedup.sourcingCache.queries.keys(),
        adoptedByProvider,
        resultsByProvider,
        budgetCancelledProviders: visualDedup.sourcingCache.budgetCancelledProviders,
      });
    }

    const silentVoiceoverNotes = getRenderCtx().voiceoverSilentFallbackNotes;
    if (silentVoiceoverNotes.length > 0) {
      // Registers the silent-fallback occurrence(s) in the persisted quality report — this
      // video must never look like an ordinary "completed" render in the DB/UI when part of
      // its narration is actually silent (see generateVoiceover()'s silent-fallback path).
      for (const note of silentVoiceoverNotes.slice(0, 10)) {
        qualityReport.warnings.push(note);
      }
      qualityReport.hasSilentVoiceover = true;
    }
    logVideoQualityReport(videoId, qualityReport);
    /**
     * RONDE 106 — the pipeline's account of itself is stored with the video.
     *
     * The warnings and the timings were already here; what was missing is everything the render
     * printed about HOW it got there. Written in the same merge so a video can never end up with
     * a quality report and no explanation of it.
     */
    pipelineReport.addAll("warnings", qualityReport.warnings);
    /**
     * RONDE 111 — why a scene came up short of footage, and what was done about it.
     *
     * The single most useful thing to know about a video that looks frozen, and until now it
     * existed only as console output on whichever worker happened to render it.
     */
    pipelineReport.add("summary", describeOnScreenTextPolicy());
    /**
     * RONDE 146 — which ffmpeg this render used, and whether it can draw a character.
     *
     * The fact that silently decided whether ten text engines worked, and that nothing ever
     * reported. A render on a host without a system ffmpeg has no `drawtext`, and until now the
     * only way to find that out was to read a failure message that never reached anybody.
     */
    pipelineReport.add("summary", describeFFmpegCapabilities(FFMPEG_BIN));
    pipelineReport.addAll("warnings", visualDedup.coverageDecisions);
    /**
     * RONDE 112 — the clips that were refused for LENGTH, named separately.
     *
     * They are already in rejectSummary with every other reason, where they are one row among
     * twenty. They are also the direct cause of the shortfalls the lines above describe, so the
     * coverage story is incomplete without them next to it.
     */
    {
      const rejects = qualityReport.rejectSummary ?? {};
      const tooShort =
        (rejects.source_video_too_short ?? 0) +
        (rejects.trimmed_clip_too_short ?? 0) +
        (rejects.ken_burns_clip_too_short ?? 0) +
        (rejects.styled_still_too_short ?? 0);
      if (tooShort > 0) {
        pipelineReport.add(
          "warnings",
          `[Coverage] clips refused for length across this render: ${tooShort} ` +
            `(source=${rejects.source_video_too_short ?? 0} ` +
            `trimmed=${rejects.trimmed_clip_too_short ?? 0} ` +
            `still=${(rejects.ken_burns_clip_too_short ?? 0) + (rejects.styled_still_too_short ?? 0)})`
        );
      }
    }
    // RONDE 237: the report renders itself. This call site used to walk `toReport()`'s three keys
    // as if they were `{ step: ms }` pairs and String()'d an array and two objects into the file.
    pipelineReport.addAll("timing", pipelineStepTiming.toReportLines());
    /**
     * The glance, built where it is stored, so both writes state the same facts about one render.
     *
     * Read at call time rather than captured: the second write happens minutes later, past the
     * cinematic block, and must report the counters as they stand THEN. See `PipelineGlance.renderId`
     * for what a stale glance beside a fresh report cost.
     */
    const glanceNow = (): PipelineGlance => ({
      renderId: visualDedup.sourcingCache.lineage.renderId,
      qualityStatus: qualityReport.qualityStatus,
      score: qualityReport.score,
      beats: qualityReport.beatVisuals?.beats,
      verifiedOwnVisual: qualityReport.beatVisuals?.verifiedOwnVisual,
      uniqueClips: qualityReport.totalClips,
      unverifiedClips: qualityReport.bySource?.[UNVERIFIED_PROVIDER] ?? 0,
      gateAttempts: judgementTally(visualDedup.beatImageGate).attempts,
      gateAnswered: judgementTally(visualDedup.beatImageGate).answered,
      warnings: qualityReport.warnings.length,
    });
    await mergeVideoMetadata(videoId, {
      qualityReport,
      pipelineStepTiming: pipelineStepTiming.toReport(),
      pipelineReport: pipelineReport.build(),
      pipelineGlance: glanceNow(),
    }).catch((err) =>
      console.warn(`[Pipeline] Failed to persist qualityReport for ${videoId}:`, err)
    );

    // Hard final validation gate — a render must never look "completed" when its actual
    // visual coverage is broken (missing beats plugged with the scene-level text/color
    // placeholder rescue path, or too many beats filled by fallback instead of a real
    // sourced clip). The diagnostic qualityReport above is persisted either way; this throws
    // (PIPELINE_ERROR.QUALITY_GATE) so the caller's existing outer catch (server/routers.ts)
    // marks the video "failed" with the concrete reason, exactly like the other
    // post-render pipelineError checks (e.g. "Final video not playable") already do.
    /**
     * EVERY GATE'S ANSWER, LOGGED BEFORE THE FIRST ONE THROWS.
     *
     * Three consecutive production renders were refused by three different gates, each of which
     * had cleared the one before it, and the operator learned that one render at a time. The other
     * answers existed the whole while; nobody asked for them. See `exportGateReadiness` — it
     * decides nothing and every gate below still runs exactly as it did.
     */
    try {
      const { exportGateReadiness, formatExportGateReadiness } = await import("./videoQualityReport");
      for (const line of formatExportGateReadiness(
        videoId,
        exportGateReadiness(qualityReport, visualDedup.sceneRescueColorFallbackCount)
      )) {
        console.log(pipelineReport.add("summary", line));
      }
    } catch (err) {
      /** A readiness REPORT must never be the reason a render fails. */
      console.warn(`[ExportReadiness] could not be computed:`, (err as Error).message);
    }

    assertVisualCoverageExportGate(qualityReport, visualDedup.sceneRescueColorFallbackCount);

    /**
     * RENDER 562 — and a video nobody looked at does not ship either.
     *
     * Next to the coverage gate because it answers the sibling question. That one asks whether the
     * viewer got real footage; this asks whether anyone approved it. Render 562 passed the first
     * and should have failed this one: 45 verdicts, then every vision provider gone, then four
     * beats of real footage adopted with no judgement at all — one of them a present-day protest
     * in a WWII documentary.
     *
     * Built from the beat audit rather than from the gate's prose. See the gate's own comment for
     * why both conditions are required and why CLIP is not an acceptable stand-in.
     */
    /**
     * RENDER 580 — DECIDED HERE, THROWN WHERE THE FILM IS KEPT.
     *
     * This threw on the spot, and the spot is before Stage 5. Render 580 spent 3788.7s composing
     * three scenes, all three finished on disk, and the operator got nothing: no concatenation, no
     * upload, no URL, and a container that is reclaimed afterwards. Sixty-three minutes for a
     * sentence.
     *
     * The refusal was right. Destroying the film is not the same act as refusing to publish it, and
     * RONDE 202 already settled that for every gate downstream of the upload — `recordBlockedExport`
     * writes `failed` AND the file's location together, so "the gate's own sentence reached them;
     * the film did not" cannot happen. This gate simply sat upstream of that rule.
     *
     * So the verdict is taken here, where the beat audit is complete and the evidence is exactly
     * what it always was, announced immediately so the log still shows it at the moment it happens,
     * and carried to the export-gate block below where a refused render is uploaded and recorded.
     * Nothing about what is refused changes.
     */
    const visionCoverageParams = {
      providerUnavailable: visualDedup.beatImageGate.judgementsProviderUnavailable,
      beats: [...visualDedup.beatOutcomeAudit.beats.values()].map((rec) => ({
        sceneIndex: rec.sceneIndex,
        beatIndex: rec.beatIndex,
        verdicts: rec.visionAccepted + rec.visionRejected + rec.visionUnclear,
        hasRealFootage: coverageHasRealFootage(resolveBeatCoverage(rec)),
      })),
      noVerdictSummary: formatNoVerdictReasons(visualDedup.beatImageGate),
    };
    /** The evidence is frozen here; only the moment of throwing moves. */
    const visionCoverageBlock = visionCoverageRefusal(visionCoverageParams);
    if (visionCoverageBlock) {
      console.error(
        pipelineReport.add(
          "summary",
          `[VisionCoverage] EXPORT WILL BE BLOCKED — ${visionCoverageBlock}`
        )
      );
      console.warn(
        `[VisionCoverage] finishing the assembly anyway so the refused film can be looked at — ` +
          `the render still ends as failed`
      );
    }

    console.log(
      pipelineReport.add("summary", `[RenderPath] video=${videoId} route=cinematic_timeline — the only render path`)
    );

    try {
      const ledger = visualDedup.sourcingCache.lineage;

      /**
       * RONDE 88 — the two columns that are provider facts rather than per-asset events.
       *
       * `searches` and `results` belong to a PROVIDER: one search returns 140 rows, and opening a
       * lineage record for each would file thousands of phantom candidates that never produced a
       * clip. The external providers have counted these all along in ProviderSourcingMetrics
       * (searchCount / resultCount), and the curated path reports its own through countSearch —
       * so the external ones are folded in here rather than re-instrumented at a dozen fetch
       * sites. Folded, never overwritten: a provider the ledger already counted keeps its own
       * number, so the two channels cannot double-count each other.
       */
      {
        const already = ledger.summary().byProvider;
        for (const [provider, m] of visualDedup.sourcingCache.metrics) {
          if (already[provider]?.searches) continue;
          for (let i = 0; i < m.searchCount; i++) {
            ledger.countSearch(provider, i === 0 ? m.resultCount : 0);
          }
        }
        /**
         * Same reasoning for the completed downloads, and the two channels are now ADDED rather
         * than chosen between.
         *
         * ── Why it used to choose ───────────────────────────────────────────────────────────
         *
         * A provider that filed real DOWNLOAD_SUCCEEDED events was skipped here entirely, on the
         * reasoning that a route reporting events reports all of its downloads that way and folding
         * the counter on top would double-count. That held while only the curated route filed
         * events.
         *
         * It stops holding the moment the scene-pool route files them, because the pool route and
         * the direct fetchers are DIFFERENT retrieval paths that can both run in one render:
         * wikimedia counts its direct fetches on the counter and its pool fetches as events, and
         * "choose one" would silently drop whichever channel came second.
         *
         * ── Why adding is safe ──────────────────────────────────────────────────────────────
         *
         * The two channels are disjoint by construction: the pool route files events and bumps no
         * counter, the direct fetchers bump the counter and file no events. Pexels was the single
         * exception, reporting one download through both, and it now files the event alone.
         *
         * `downloadCount` means SUCCESSES for every provider, which is what makes the addition
         * honest. It did not always: youtube_cc's ceiling used to read the same field, so a claimed
         * slot bumped it and this fold reported ATTEMPTS in the `downloaded` column. The ceiling has
         * its own `downloadSlotsClaimed` now — see `claimYoutubeDownloadSlot`.
         */
        for (const [provider, m] of visualDedup.sourcingCache.metrics) {
          if (m.downloadCount <= 0) continue;
          ledger.countProviderDownloads(provider, m.downloadCount);
        }
      }
      const summary = ledger.summary();
      /**
       * RONDE 106 — the render's account of itself is kept, not only printed.
       *
       * Every emitter below already composed a report meant to be read; all of it went to stdout
       * and nowhere else, so "why does this video look like this" could only be answered by
       * someone with that render's Railway log still open. `pipelineReport.add` remembers each
       * line as it is printed — same lines, same order, nothing re-instrumented — and the block
       * is stored with the video at the end.
       */
      for (const line of formatSourceSummary(summary, ledger.finalVideoWasVerified)) {
        console.log(pipelineReport.add("sourcing", line));
      }
      for (const line of formatFunnelReport(summary, ledger.finalVideoWasVerified)) {
        console.log(pipelineReport.add("sourcing", line));
      }
      /**
       * §12 — how much of that funnel this render can actually account for, candidate by candidate.
       *
       * `retrieved=30` is a running total from `countSearch`; the ledger opens a record only when a
       * candidate is tagged or downloaded. The line above therefore invites a reading it cannot
       * support — that twenty-nine were considered and turned down — when in truth they were never
       * individually tracked. This says which of the two gaps a number belongs to, and warns only
       * on the one that is a defect: a record the ledger opened and then lost track of.
       */
      for (const line of formatProviderFunnelInvariant(summary, ledger.allRecords(), ledger.allEvents())) {
        if (line.includes("INVARIANT_BROKEN")) console.warn(pipelineReport.add("sourcing", line));
        else console.log(pipelineReport.add("sourcing", line));
      }
      /**
       * RENDER 579 — WHAT THE BACKFILL APPROVAL RULE COST THIS RENDER.
       *
       * Printed unconditionally, zero included. A rule whose line only appears when it fired reads
       * as "this never happens" on every render that does not print it, and the number that matters
       * here is the one next to a quiet film: if this is large while beats end up holding frames,
       * the rule is turning away more than the two unrelated archive clips it was written for, and
       * that has to be visible without re-reading the whole log for `[BeatRelevance]` warnings.
       */
      /**
       * HOW MUCH REAL FOOTAGE THIS FILM CARRIES THAT NOBODY LOOKED AT.
       *
       * Printed unconditionally, zero included — the same reasoning as the line below. An
       * exemption whose line only appears when it fired reads as "this never happens" on every
       * render that stays silent, and this one had been firing for months: video 580 put three
       * curated WW2 clips into a film about Kylie Jenner through it, each with its own warning and
       * no total anywhere.
       */
      console.log(
        pipelineReport.add(
          "sourcing",
          formatSuspendedVisionAdoptions(visualDedup.adoptedWithSuspendedVision)
        )
      );
      /** What the two stock-ladder bounds cost, so the next render can say whether they are right. */
      console.log(pipelineReport.add("sourcing", formatStockLadderBounds(visualDedup)));
      console.log(
        pipelineReport.add(
          "sourcing",
          `[BackfillApproval] refused=${visualDedup.backfillRefusedWithoutApproval} ` +
            `(neverLookedAt=${visualDedup.backfillRefusedNeverLookedAt}) ` +
            `picture(s) the backfill would have used without an approval for the beat they would fill` +
            (visualDedup.backfillRefusedNeverLookedAt > 0
              ? ` — the neverLookedAt half is a spent look budget, not an editorial refusal`
              : "") +
            /**
             * RENDER 592-B: and the other side of the same rule — where the requirement was
             * suspended because no approval could be earned. Printed on the same line as the
             * refusals it belongs beside, never in a report of its own that nobody joins.
             */
            formatBackfillApprovalSuspensions(visualDedup.backfillApprovalSuspended)
        )
      );
      /**
       * EVERY YOUTUBE ASSET, EVENT BY EVENT — the answer to "why was this refused and where did
       * that one go".
       *
       * Render 577 reported `youtube_cc adopted=1 composed=0 finalVideo=0`: one clip cleared every
       * gate and never reached the film, and no line said which clip or where it stopped. The facts
       * were all in the ledger — provider, asset id, scene, beat, query, and per event a stage, a
       * status, a reason and the gate — and nothing read them back out. `formatAssetTrace` has been
       * exported since RONDE 95 with no caller at all.
       *
       * Counted separately, because they are different problems: `refused` is an asset something
       * turned down and said why; `openEnded` is an asset whose life simply stops, which is the
       * disappearance. Blending them is how `adopted=1 composed=0` stayed unexplained for a month.
       *
       * A second READER of the same events the funnel above reads, so the two cannot disagree. It
       * refuses nothing and changes no count.
       */
      for (const line of formatProviderTrace(ledger, "youtube_cc", { label: "YouTubeTrace" })) {
        console.log(pipelineReport.add("sourcing", line));
      }
      /**
       * AND WHAT THE PICTURE EDITOR SAID ABOUT EACH OF THOSE CLIPS, BESIDE WHERE IT ENDED UP.
       *
       * `[YouTubeTrace]` above reads the lineage and can say "adopted, then nothing". It cannot say
       * "APPROVED, then nothing", because `LINEAGE_STAGES` has no stage for a vision verdict — the
       * verdicts live in `beatRelevance` and have never been read against the lifecycle. So the one
       * question this render keeps raising — did a clip the editor said yes to disappear before the
       * film — had no reader at all, and `INCONCLUSIVE` was the honest answer to it.
       *
       * A third READER of registers that both already exist, joined on the content key both sides
       * carry. It files no event, keeps no state and refuses nothing.
       */
      const youtubeLifecycle = traceYoutubeLifecycle(ledger, visualDedup.beatRelevance);
      for (const line of formatYoutubeLifecycle(youtubeLifecycle)) {
        console.log(pipelineReport.add("sourcing", line));
      }
      /**
       * Whether this render had a picture editor at all — once, for the render.
       *
       * `NOT_ASKED` on a row says the gate declined and cannot say why: the reason exists only as
       * prose, and `judgementsProviderUnavailable` is the counter the gate keeps so that no reader
       * has to match on prose. Read here exactly as the export gate reads it.
       */
      for (const line of formatYoutubeVisionAvailability(
        visualDedup.beatImageGate,
        youtubeLifecycle
      )) {
        console.log(pipelineReport.add("sourcing", line));
      }
      /** The same rows as columns, for reading a whole render's YouTube at a glance. */
      for (const line of formatYoutubeLifecycleTable(youtubeLifecycle)) {
        console.log(pipelineReport.add("sourcing", line));
      }
      /** A clean render prints nothing here; an approved clip that vanished is not routine. */
      for (const line of youtubeLifecycleViolations(youtubeLifecycle)) {
        console.warn(pipelineReport.add("sourcing", line));
      }
      // RONDE 94: the same events, per provider, in found/validated/selected/downloaded/assigned/
      // rendered — plus a refusal to print a funnel that widens.
      for (const line of formatAssetUsageSummary(summary, ledger.finalVideoWasVerified)) {
        pipelineReport.add("sourcing", line);
        if (line.startsWith("[AssetUsageInconsistency]")) console.warn(line);
        else console.log(line);
      }
      /**
       * WHERE EACH SOURCE LOSES ITS FOOTAGE — the step the usage summary cannot see.
       *
       * `[AssetUsageSummary]` counts found/validated/selected/downloaded/assigned per provider, and
       * a render with 137 downloads and 7 adoptions raises exactly one question that table cannot
       * answer: where did the other 130 stop. Almost all of them stop at the picture editor, whose
       * verdicts live in a ledger keyed by clip path with no idea which provider anything came
       * from — while the lineage knows the provider and nothing about verdicts.
       *
       * Joined here rather than counted along the way, because counting would mean every judging
       * route also remembering to attribute its verdict, and that is the seam this codebase keeps
       * rediscovering. See `providerFunnel.ts`.
       */
      for (const line of formatProviderFunnel(
        providerVisionFunnel({
          ledger: visualDedup.beatRelevance,
          providerOf: (clipPath) => ledger.resolve(clipPath)?.provider ?? null,
        })
      )) {
        pipelineReport.add("sourcing", line);
        /** A source that supplied candidates and had every one refused is a warning, not a stat. */
        if (line.includes("NOT ONE was accepted") || line.includes("being overruled")) {
          console.warn(line);
        } else {
          console.log(line);
        }
      }
      /**
       * RENDER 562 — what the source-length floor cost, and what this render could have carried.
       *
       * Reported, never acted on. `coverableAtSlowdown` counts refusals whose source was long
       * enough for the pipeline's OWN coverage machinery to fill the slot at full coverage — the
       * one number the "is 2.8s right?" question turns on. Deciding it from here, without a real
       * render to compare against, would turn a measurement into a regression.
       */
      if (sourceFloorMemo) {
        console.log(
          pipelineReport.add(
            "sourcing",
            formatSourceFloorLedger(sourceFloorMemo, MAX_COVERAGE_SLOWDOWN)
          )
        );
      }
      /**
       * RENDER 562 — what the metadata screen refused before anything was fetched.
       *
       * `refused` is downloads that did not happen. 562 downloaded 100 files to use 10, and
       * Pexels alone fetched 73 and contributed nothing, so this is the line that says whether
       * the cheapest check is earning its keep. `noProvider` matters just as much: it says the
       * screen itself was blind, which is the state this gate exists to survive.
       */
      console.log(
        pipelineReport.add(
          "sourcing",
          formatCandidateSubjectSummary(visualDedup.candidateSubjectGate)
        )
      );
      /**
       * RENDER 563 — which routes put a picture on screen that nobody looked at.
       *
       * `never_asked=21` and four `[BeatVisual] … real_footage_never_judged` lines said THAT it
       * happened; nothing said WHERE. These lines name the adopt route, because that is the fact
       * needed to fix it and the one thing 35 call sites cannot be read for by eye.
       *
       * Warned rather than logged: an unjudged picture in a delivered video is not routine, and a
       * clean render prints nothing here at all.
       */
      /**
       * RONDE 95 — the per-beat funnel, which is the line render 568 needed and did not have.
       *
       * `[VisualFunnel] TOTAL retrieved=3995 eligible=4` is a render-wide number and says nothing
       * about which beat starved. This says it per beat, in the order the pipeline walks the
       * stages, and ends every beat with no approval on a NAMED reason rather than on the word
       * "never_asked" — which was a restatement of the question, not an answer to it.
       */
      /**
       * RONDE 96 — what each beat said it was looking for, and the beats that could say nothing.
       *
       * A `[VisualIntentGap]` line is the strongest single predictor of a bad beat: no subject, no
       * entity and no planner contract means every query it built was unanchored and every
       * candidate it ranked was ranked against nothing.
       */
      /**
       * RONDE 97 §3 — what preparation cost, and what the idempotent layer saved.
       *
       * `requested=38 started=1 reused=37` is render 568's duplication as a single line, instead
       * of thirty-eight download entries somebody has to count by hand.
       */
      /** RONDE 97 §10 — what the render spent per beat, and which beats hit a ceiling. */
      for (const line of formatRetrievalBudgets(visualDedup.beatBudget)) {
        console.log(pipelineReport.add("summary", line));
      }
      for (const line of formatPreparationCache(workDir)) {
        console.log(pipelineReport.add("summary", line));
      }
      for (const line of formatIntentSummary(visualDedup.beatIntent)) {
        console.log(pipelineReport.add("summary", line));
      }
      for (const line of formatBeatShortlists(visualDedup.beatShortlist)) {
        console.log(pipelineReport.add("summary", line));
      }
      /** P0-7 — blind, starved or settled. See `formatDeclineCensus`. */
      {
        const census = formatDeclineCensus(visualDedup.beatShortlist);
        if (census) console.log(pipelineReport.add("summary", census));
      }
      /**
       * And the four things that record makes checkable at runtime, none of which could be stated
       * before the stages sat side by side. A clean render prints nothing here.
       */
      for (const line of beatShortlistViolations(visualDedup.beatShortlist)) {
        console.warn(pipelineReport.add("summary", line));
      }
      /**
       * R194 §30/§31 — what each beat put to the picture editor, what it answered, and what the
       * beat did with the answer. `SHORTLIST_FULL (8/8)` says the bound fired; these lines say
       * whether the eight the editor saw were the best eight, and whether its verdicts decided
       * anything.
       */
      for (const line of formatVisionSelection(visualDedup.visionReviewPool)) {
        console.log(pipelineReport.add("summary", line));
      }
      for (const line of visionSelectionViolations(visualDedup.visionReviewPool)) {
        console.warn(pipelineReport.add("summary", line));
      }
      for (const line of formatUnjudgedAdoptions(visualDedup.clipAdoptAudit)) {
        console.warn(pipelineReport.add("summary", line));
      }
      /**
       * RONDE 92 — how many adoptions claim the funnel, and how many the ledger can back.
       *
       * `ELIGIBLE` has been a lineage stage since RONDE 87, written at two sites, read by nothing.
       * This is the read side. The count it prints is the number that decides when the REAL_FUNNEL
       * guard can be switched from measuring to refusing without bricking every render.
       */
      for (const line of formatAdoptionEvidence(visualDedup.clipAdoptAudit)) {
        if (line.includes("INVARIANT_")) {
          console.warn(pipelineReport.add("summary", line));
        } else {
          console.log(pipelineReport.add("summary", line));
        }
      }
      /**
       * RONDE 90 PHASE 2 — WHAT THIS FILM IS MADE OF, by declared category.
       *
       * `[VisualFunnel]` counts by PROVIDER, which is why render 568 could report
       * `wikimedia adopted=2` for two last-resort rescue images and `UNVERIFIED adopted=23` for
       * every route that never reached a provider at all. This counts by what each adoption is
       * ALLOWED TO CLAIM — real funnel footage, a rescue, a subject fallback, held time, a drawn
       * card, a placeholder — and names any route adopting under a label nobody declared, which
       * the old string-shape classifier silently called `primary`.
       */
      {
        const census = censusAdoptionPolicies(
          visualDedup.clipAdoptAudit.map((e) => e.source)
        );
        for (const line of formatAdoptionPolicyCensus(census)) {
          if (line.includes("UNDECLARED_ADOPT_SOURCE")) {
            console.warn(pipelineReport.add("summary", line));
          } else {
            console.log(pipelineReport.add("summary", line));
          }
        }
      }
      /**
       * RONDE 95 (§5) — the manifest, and its counterpart.
       *
       * [RenderAsset] lists what the delivered file actually contains, one line per asset, built
       * from the FINAL_VIDEO events markFinalVideo set out of finalConcatInputs.
       * [AssetNotRendered] lists what the pipeline chose and the file does NOT contain, saying for
       * each whether a recorded replacement explains it or nothing does. The second list is the
       * one worth reading: an asset that was selected, downloaded, and then dropped with no event
       * is a hole in the pipeline, not in the report.
       */
      const allRecords = ledger.allRecords();
      /**
       * RONDE 105 — every rendered asset now carries what the content decider said about it.
       *
       * The ledger records where a clip came from; the relevance ledger records whether it
       * belongs. Both were already written down and neither line printed the other, so a manifest
       * could list fifteen well-attributed clips that nobody had looked at. The lookup goes by
       * beat, which is exact: RONDE 103 stores the beat context alongside every decision.
       */
      /**
       * RENDER 563 — the verdict must be about the clip on the line.
       *
       * This scanned the ledger for the first entry on the same BEAT and returned it, whichever
       * clip it belonged to. Render 563 printed `verdict=does_not_fit` for a file the gate had
       * approved by name in the same log, and the reverse — `fits` on a clip nobody looked at —
       * is the same bug with worse consequences. See relevanceVerdictForRenderedAsset.
       */
      const verdictForRecord = (r: {
        sceneIndex: number;
        beatIndex: number;
        localPath?: string;
        currentFilename?: string;
        contentKey?: string;
      }) => relevanceVerdictForRenderedAsset(visualDedup.beatRelevance, r);
      for (const line of formatRenderManifest(
        allRecords, ledger.finalVideoWasVerified, verdictForRecord
      )) {
        console.log(pipelineReport.add("clips", line));
      }
      /**
       * RONDE 105 (§16) — the block that answers the whole question in one place: how many beats,
       * how many verified, what the gate managed, what is actually in the file and where each
       * clip came from. Built from records that already exist; it counts nothing twice and it
       * says so when the per-provider counts do not add up to the clip count.
       */
      {
        const tally = judgementTally(visualDedup.beatImageGate);
        {
          const why = formatNoVerdictReasons(visualDedup.beatImageGate);
          if (why) pipelineReport.add("summary", why);
        }
        {
          const who = formatVerdictProviders(visualDedup.beatImageGate);
          if (who) pipelineReport.add("summary", who);
        }
        for (const line of formatFinalVisualReport({
          finalVideoVerified: ledger.finalVideoWasVerified,
          records: allRecords,
          beats: qualityReport.beatVisuals?.beats ?? 0,
          verifiedOwnVisual: qualityReport.beatVisuals?.verifiedOwnVisual ?? 0,
          verification: qualityReport.beatVisuals?.byVerification ?? {},
          coverage: qualityReport.beatVisuals?.byCoverage ?? {},
          attempts: tally.attempts,
          answered: tally.answered,
          unavailable: tally.failed,
          neverAsked: tally.skipped,
          qualityStatus: qualityReport.qualityStatus,
          score: qualityReport.score,
        })) {
          pipelineReport.add("summary", line);
          if (line.includes("SOURCE_COUNT_MISMATCH")) console.warn(line);
          else console.log(line);
        }
        // One line per beat that is not finished, so "13 beats without their own picture" can be
        // read as thirteen named beats rather than a number to be trusted.
        for (const line of formatBeatVisualProblems(qualityReport.beatVisualProblems ?? [])) {
          console.warn(pipelineReport.add("beats", line));
        }
        /**
         * RONDE 166 §8/§9 — why each beat's picture is on screen, and why two beats were never
         * judged. The severity comes from the relevance ledger's own words, through the same
         * classifier the reprieve guard consults, so the report and the decision cannot disagree.
         */
        /**
         * RENDER 564 — what the concat actually took, so the invariant can tell a bypass from a
         * barrier that worked. Read from the FINAL_VIDEO EVENTS rather than from the records: one
         * lineage record can be re-pointed across several copies of an asset, so its filename is
         * not evidence of which copy was delivered, while the event carries the path
         * `markFinalVideo` was handed.
         */
        const deliveredBasenames = new Set(
          ledger
            .allEvents()
            .filter((e) => e.stage === "FINAL_VIDEO" && e.currentPath)
            .map((e) => path.basename(e.currentPath!))
        );
        for (const line of formatVisualFitAudit(
          // Every beat, not only the failing ones — verifiedFit and adoptedFit are counted here.
          qualityReport.beatVisualStatuses ?? [],
          (sceneIndex, beatIndex, basename) =>
            beatClipSeverity(visualDedup.beatRelevance, sceneIndex, beatIndex, basename),
          deliveredBasenames
        )) {
          if (line.includes("INVARIANT_BROKEN")) console.error(pipelineReport.add("beats", line));
          else console.log(pipelineReport.add("beats", line));
        }
      }
      for (const line of formatSelectedButNotRendered(
        allRecords, ledger.allEvents(), ledger.finalVideoWasVerified
      )) {
        console.warn(pipelineReport.add("dropped", line));
      }
      /**
       * §9/§10 — the six invariants, and the render summary that counts them.
       *
       * `renderSucceeded` and `deliveryHappened` are read from what this render actually did, not
       * assumed: two of the six are only defects when the render was SUPPOSED to work. A cancelled
       * or failed render legitimately leaves its inputs without an output, and calling that a
       * lineage error would fire the alarm on every timeout — which is how an invariant stops being
       * read.
       */
      {
        const lifecycles = lifecyclesOf(allRecords, ledger.allEvents());
        const errors = formatLifecycleInvariants(lifecycles, {
          renderSucceeded: ledger.finalVideoWasVerified,
          deliveryHappened: ledger.finalVideoWasVerified,
        });
        for (const line of errors) console.error(pipelineReport.add("dropped", line));
        const count = (s: string) => lifecycles.filter((a) => a.terminalStatus === s).length;
        console.log(
          pipelineReport.add(
            "summary",
            `[FORENSIC_RENDER_SUMMARY] render=${videoId} assets=${lifecycles.length} ` +
              `final=${count("FINAL")} renderInput=${count("DELIVERED_INPUT")} ` +
              `droppedAtPush=${count("DROPPED_AT_PUSH")} ` +
              `droppedAtCompose=${count("DROPPED_AT_COMPOSE")} ` +
              `droppedAtCinematic=${count("DROPPED_AT_CINEMATIC")} ` +
              `droppedAtDownload=${count("DROPPED_AT_DOWNLOAD")} ` +
              `replaced=${count("REPLACED")} neverSelected=${count("NEVER_SELECTED")} ` +
              `downloadedNeverJudged=${count("DOWNLOADED_NEVER_JUDGED")} ` +
              `unexplained=${count("UNEXPLAINED")} lineageErrors=${errors.length} ` +
              `finalOutputVerified=UNKNOWN`
          )
        );
      }
      /**
       * §17's invariant, checked by the render on itself.
       *
       * "An ADOPTED real asset + the same beat + a guaranteed filler + no ending on the asset" is
       * the state VID-0567's beat 0 was in, and nothing in the render said so. The beats a filler
       * ended up on are read from the delivered manifest rather than from any counter, so this
       * asks about the film that exists.
       *
       * Reported at `error` level because it is an invariant, not an observation: reaching it means
       * a real asset was adopted for a beat and a generic clip took that beat with no explanation
       * anywhere. A render that is fine prints nothing.
       */
      {
        const filledBeats = new Set<string>();
        for (const entry of visualDedup.clipAdoptAudit) {
          if (!isPipelineFallbackClip(entry.basename)) continue;
          filledBeats.add(`${entry.sceneIndex}:${entry.beatIndex}`);
        }
        for (const line of formatFillerOverAdoptedAsset(
          allRecords, ledger.allEvents(), filledBeats
        )) {
          console.error(pipelineReport.add("dropped", line));
        }
      }
      // RONDE 89 (§15): what the provider gate did — built, validated, rejected, sent, blocked,
      // and how many calls arrived without a context and were counted as bypass attempts.
      for (const line of formatSearchGateReport()) console.log(pipelineReport.add("search", line));
      /**
       * RONDE 140 — the two rights-check lists, for the two sources that carry no proof.
       *
       * `formatYoutubeUsageReport` has existed since RONDE 124 and was never called once. It was
       * written to be the starting point of a manual rights check, and a report nobody prints is
       * not a starting point for anything — which matters a great deal more now that the operator
       * may switch the blanket YouTube authorisation on (its flag lives in youtubeLicenseStatus.ts,
       * where RONDE 147 put it, and is deliberately not named here) and needs to be able to see
       * what that decision actually admitted.
       *
       * Both lists are built from the ledger rather than from a new collector: `finalVideoAt` is
       * already the record of what reached the delivered file, and a second count of the same
       * thing is exactly how two numbers start disagreeing.
       *
       * What the YouTube entries deliberately do NOT claim: a licence. The ledger records where a
       * clip came from, not which licence pass found it, and YouTube's own
       * `videoLicense=creativeCommon` filter is YouTube's assertion rather than a verification
       * FastVid performed. So every live-YouTube clip is reported UNVERIFIED with a null licence,
       * which is precisely what is known about it. (The archive `youtube-*` route is the one with
       * real metadata, and it has said so on its own line since RONDE 124.)
       */
      {
        const rendered = allRecords.filter((r) => r.finalVideoAt != null);
        const verdictOf = (r: { sceneIndex: number; beatIndex: number }) =>
          verdictForRecord(r)?.verdict ?? "never_asked";
        const youtubeEntries: YoutubeUsageEntry[] = rendered
          .filter((r) => r.provider === "youtube_cc" && r.providerAssetId)
          .map((r) => ({
            sceneIndex: r.sceneIndex,
            beatIndex: r.beatIndex,
            youtubeVideoId: r.providerAssetId!,
            title: r.assetTitle,
            licenseStatus: "UNVERIFIED" as const,
            licenseUrl: null,
            rights: null,
            previewStatus: "not_recorded",
            visionVerdict: verdictOf(r),
          }));
        for (const line of formatYoutubeUsageReport(youtubeEntries).split("\n")) {
          console.log(pipelineReport.add("sourcing", line));
        }
        const openWebEntries: OpenWebUsageEntry[] = rendered
          .filter((r) => r.provider === "serpapi")
          .map((r) => ({
            sceneIndex: r.sceneIndex,
            beatIndex: r.beatIndex,
            host: openWebHost(r.sourceUrl),
            sourceUrl: r.sourceUrl ?? null,
            title: r.assetTitle,
            visionVerdict: verdictOf(r),
          }));
        for (const line of formatOpenWebUsageReport(openWebEntries).split("\n")) {
          console.log(pipelineReport.add("sourcing", line));
        }
        console.log(
          pipelineReport.add(
            "sourcing",
            formatOpenWebPolicyReport(visualDedup.openWebPolicyStats)
          )
        );
      }
      const reconciliation = ledger.reconcile();
      for (const line of formatAuditReport(reconciliation)) console.log(pipelineReport.add("sourcing", line));
      /**
       * RONDE 131 — what the persistent cross-video memory saved this render.
       *
       * The one number that answers "is FastVid getting faster per video": beats that found their
       * subject already proven, against beats that had to start from the providers.
       */
      console.log(
        pipelineReport.add("sourcing", formatSearchMemorySummary(visualDedup.searchMemoryMetrics))
      );
      /**
       * RONDE 132 §2 — how many distinct pictures this video actually used.
       *
       * `uniqueAssets` against `duplicateAttempts` is the number that answers "is the same footage
       * coming back", and `matchedOn` says which identity caught it — an archive-asset match and a
       * content-key match are two different stories about where the repeat came from.
       */
      console.log(
        pipelineReport.add(
          "sourcing",
          formatVisualDedupSummary(getActiveVideoId() ?? null, visualDedup.visualDedupStats)
        )
      );
      /**
       * RONDE 165 — the denominator under the vanished warnings printed just above.
       *
       * formatAuditReport names each unaccounted asset; this counts all of them against the assets
       * that were delivered or explained, so `unresolved=` is a number the next render can be
       * measured against rather than a list to be eyeballed.
       */
      for (const line of formatAssetLifecycleAudit(ledger)) {
        if (line.includes("unresolved=0")) console.log(pipelineReport.add("sourcing", line));
        else console.warn(pipelineReport.add("sourcing", line));
      }
      /**
       * RONDE 167 §8 — the hard invariant, stated as a pass or a failure rather than a count.
       *
       * The audit above says how many assets are unaccounted for; nothing said whether that is
       * acceptable. It never is. Every asset this render CHOSE owes it an ending, and a render
       * that cannot produce one for a clip cannot answer where its pictures came from.
       *
       * Logged, never thrown: the whole audit block sits inside a try precisely because reporting
       * must not be able to destroy a finished video. The line is an error so it cannot be read as
       * routine, and each offender is named so the route can be found.
       */
      reportLineageOutcomeInvariant(ledger, {
        ok: (line) => console.log(pipelineReport.add("sourcing", line)),
        fail: (line) => console.error(pipelineReport.add("sourcing", line)),
      });
      console.log(formatGlobalBudget());
      console.log(
        pipelineReport.add(
          "sourcing",
          `[SourceLineage] video=${videoId} render=${ledger.renderId} ` +
            `records=${ledger.size} events=${ledger.allEvents().length} ` +
            `verified=${summary.verifiedRecords} unverified=${summary.unverifiedRecords}`
        )
      );
    } catch (err) {
      // The audit reports on the render; it must never be able to fail one.
      console.warn("[VisualAudit] audit reporting failed (non-fatal):", (err as Error).message?.slice(0, 160));
    }

    // ── Stage 6: Export gates (the delivered file is produced by the timeline render below) ──
    onProgress?.({ stage: STAGE_LABELS.uploading, percent: 93 });
    const t5 = Date.now();
    profiler.recordStageStart("upload", t5);
    get_activeBudgetTracker()?.stageStart("upload", get_activeRenderBudget()?.uploadMs ?? 300_000);
    // Final videos can be hundreds of MB to low-GB — storagePutFromFile streams directly from
    // disk (multipart upload for S3/R2) instead of reading the whole file into a single Buffer
    // first, which previously peaked at roughly 2x the file size in RAM for this one step.
    /**
     * RONDE 222 — IS THE FILM LOUD ENOUGH TO HEAR?
     *
     * Render 574 shipped at -41.2 LUFS against a -14 LUFS streaming target: twenty-seven decibels
     * under, effectively inaudible at normal volume. Nothing measured it, because until this round
     * nothing in the tree knew what LUFS was.
     *
     * Placed here, after `ensureFinalVideoExportReady` — which may REASSEMBLE the file — and before
     * the size is taken and the envelope is measured, so the correction cannot be discarded by a
     * later rebuild and every number stage 6 reports describes the file that is uploaded.
     *
     * Reports and never gates: a film that could not be levelled is still delivered, with the
     * reason on the line. The pass replaces the file only when the corrected audio measures closer
     * to target than the original.
     */

    /**
     * RONDE 223 — say what the refusal memo saved, or say nothing at all.
     *
     * Printed only when something was actually refused, so a healthy render gains no noise, and a
     * render that hit render 575's fault can be read for how much work it did not repeat.
     */
    {
      const refusalLine = formatPermanentDownloadRefusals();
      if (refusalLine) console.log(pipelineReport.add("summary", refusalLine));
      /**
       * RONDE 261: beside it, and for the same reason. The refusal memo has reported what it saved
       * since RONDE 223; its counterpart for successful downloads had no memo at all, so a render
       * could fetch one video six times and say nothing about it.
       */
      const reuseLine = formatYoutubeSourceReuse();
      if (reuseLine) console.log(pipelineReport.add("summary", reuseLine));
    }

    /**
     * R195 — DOES THE PICTURE COVER THE NARRATION?
     *
     * The check that answers it has existed, been tested and been wired into the render-job route
     * for several rounds. This route — the one that delivers whenever the cinematic render is not
     * used — never took the measurement, which is why video 574 shipped 68.04s of picture under
     * 69.88s of audio and no line anywhere said so.
     *
     * Two ffprobe reads and one silencedetect pass, so it is cheap enough to run unconditionally.
     * It reports and does not gate, exactly as the spot check beside it does. When the cinematic
     * render delivers instead, the block at the cutover replaces this with the render job's own
     * verdict on the file the viewer actually received.
     */
    /**
     * RONDE 133 — measure the finished file, on every render.
     *
     * RONDE 130 built `videoStillnessAudit` to answer the one question the whole no-frozen-frame
     * chain exists for: how long is the viewer looking at exactly the same thing. It proved the
     * tail-pad fix on a real MP4 and it was never called from the pipeline — so `auditVideoStillness`
     * appeared in the codebase and in its own tests, and in not one production render.
     *
     * That is the RONDE 26 shape this project keeps rediscovering, and all three of the lenses
     * RONDE 29 named miss it in the same way: the module is exercised (by tests), it logs (in
     * tests), and no flag switches it off. What it never did was run on a real export.
     *
     * Wired here because this is the first point where the finished MP4 exists. It decides
     * nothing: it measures, it warns, and it is wrapped so a slow or broken audit can never cost a
     * render that is otherwise complete.
     */

    /**
     * A BLOCKED EXPORT MAY NOT PUBLISH THE FILM. IT MAY NOT LOSE IT EITHER.
     *
     * The upload immediately above has already put the MP4 somewhere the owner's own download
     * route can reach — `/api/download/video/:id` asks for ownership and a URL, never a status.
     * But the only write that records that URL sits on the success path a thousand lines below,
     * past this gate. So render 577 uploaded 71 MB, the gate refused it over
     * MOSTLY_UNVERIFIED_CLIPS, the row went to `failed` with no URL at all, and the person who
     * asked for the film could not look at the thing that had been judged. The gate's own
     * sentence reached them; the film did not.
     *
     * The refusal is recorded, not softened. `recordBlockedExport` writes `failed` and the
     * location of the refused file in one statement, and the same error travels on to the outer
     * catch in routers.ts exactly as before. Nothing downstream reads this as approval: the
     * video is not `completed`, no quality check is skipped, and the ledger is untouched. This
     * is only the difference between "may not go out" and "does not exist".
     */
    try {
      /**
       * RENDER 580's refusal, thrown here rather than before Stage 5, so the `catch` below records
       * it against the film instead of leaving the operator with a sentence and no video. First,
       * because it is the gravest of the refusals: unjudged footage on screen is what RONDE 562's
       * gate exists to stop, and it should be the reason reported when more than one applies.
       */
      assertVisionCoverageExportGate(visionCoverageParams);
      enforceQualityExportGate(videoId, qualityReport);
    } catch (gateError) {
      throw gateError;
    }
    qualityReport.generatedAt = new Date().toISOString();

    get_activeBudgetTracker()?.stageEnd("upload");
    profiler.recordStageEnd("upload", Date.now());
    console.log(`[Pipeline] Stage 6 (export gates): ${((Date.now()-t5)/1000).toFixed(1)}s`);

    qualityReport.pipelineSec = Math.round((Date.now() - t0) / 1000);

    let editorScenes: EditorScene[] = [];
    try {
      /**
       * RONDE 146 — the manifest carries the ADOPTION RECORD, not just the provider's name.
       *
       * Both resolvers read the same ledger entry. `providerFor` has answered "which provider"
       * since RONDE 87; the second one answers "which file at that provider", which is the half
       * that was being discarded — and the half a re-render needs. Nothing here reads a filename:
       * `resolve()` finds the record the downloader opened with the provider's own data in hand.
       */
      editorScenes = await buildEditorScenesFromPipeline(
        scenes,
        /** The one rule, not a fourth spelling of it — see `clipsForScene`. */
        scenes.map((_, i) => clipsForScene(i)),
        (clipPath) => visualDedup.sourcingCache.lineage.providerFor(clipPath),
        (clipPath) => {
          const record = visualDedup.sourcingCache.lineage.resolve(clipPath);
          if (!record) return null;
          return {
            provider: record.provider,
            providerAssetId: record.providerAssetId,
            sourceUrl: record.sourceUrl,
            originalUrl: record.originalUrl,
            assetTitle: record.assetTitle,
            archiveAssetId: record.archiveAssetId,
          };
        },
        /**
         * Trim, only where the render measured it.
         *
         * `memoisedVideoStreamMeta` returns a probe this render already took, or undefined. An
         * undefined answer produces NO trim fields rather than 0/duration — §9's "NIET gokken".
         * The in/out points inside the source are not recorded anywhere today, so they are absent
         * rather than fabricated; the on-screen duration is, and it is written.
         */
        (clipPath) => {
          const meta = memoisedVideoStreamMeta(clipPath);
          if (!meta || !(meta.durationSec > 0)) return null;
          return { durationSec: Number(meta.durationSec.toFixed(3)) };
        }
      );
      /**
       * THE VISION ROLL-CALL, for the whole render, in one place.
       *
       * Printed here rather than inside any one caller, because the point of it is that no single
       * caller could ever produce it. Five routes reach a vision model; two kept their own ledgers
       * and three kept none, so every render-level count of vision spend was a count of one
       * subsystem presented as a total.
       */
      for (const line of formatVisionCensus(getVisionCensus())) {
        console.log(pipelineReport.add("sourcing", line));
      }
      await updateVideoScenes(videoId, editorScenes);
      for (const line of formatManifestIdentityReport(editorScenes)) {
        console.log(pipelineReport.add("sourcing", line));
      }
      const coverage = manifestRehydrationSummary(editorScenes);
      console.log(
        pipelineReport.add(
          "sourcing",
          `[AssetIdentity] TOTAL clips=${coverage.total} rehydratable=${coverage.rehydratable} ` +
            `unrecoverable=${coverage.total - coverage.rehydratable} schema=v${coverage.schemaVersion}`
        )
      );
    } catch (err) {
      console.warn(`[Pipeline] Editor manifest persist failed for ${videoId}:`, (err as Error).message);
    }

    /**
     * RONDE 146 §5/§6 — the narration outlives the work directory.
     *
     * This runs BEFORE the `finally` that deletes workDir, and only on a render that reached
     * completion. Until now the only thing a render ever made permanent was final.mp4, so
     * `full_voiceover.mp3` and `tts_word_alignment.json` were destroyed along with the directory —
     * and `videos.voiceoverUrl` has existed as a column without a writer for that entire time.
     *
     * A failure here does not fail the render: the video is finished and uploaded, and refusing to
     * deliver it because its audio could not be archived would be the wrong trade. But it is never
     * silent — VOICEOVER_PERSISTENCE_FAILED says so in a line built to be grepped.
     */
    /**
     * RONDE 151 — hoisted out of the try below so the cinematic plan can read them.
     *
     * The narration URL and the measured word boundaries are two of the five inputs that plan
     * needs, and re-deriving them there would mean a second read of the same alignment file.
     */
    let persisted: Awaited<ReturnType<typeof persistVoiceover>> | null = null;
    let storedAlignment: ReturnType<typeof loadStoredTtsAlignment> = null;
    /** RONDE 647 — the narration the timeline carries; see `narrationForTimeline`. */
    let narration: ReturnType<typeof narrationForTimeline> = null;
    let narrationMeta: ReturnType<typeof loadNarrationMeta> = null;
    let wordTiming: NarrationWordTiming = { words: [], source: "none", note: "narration not persisted" };
    try {
      persisted = await persistVoiceover({
        videoId,
        workDir,
        upload: (key, filePath, contentType) => storagePutFromFile(key, filePath, contentType),
      });
      storedAlignment = loadStoredTtsAlignment(workDir);
      narrationMeta = loadNarrationMeta(workDir);
      const measuredVoiceSec =
        persisted.ok && !(storedAlignment?.totalDurationSec && storedAlignment.totalDurationSec > 0)
          ? (await probeMediaFacts(persisted.sourcePath).catch(() => null))?.durationSec ?? null
          : null;
      narration = narrationForTimeline({
        persisted,
        alignmentDurationSec: storedAlignment?.totalDurationSec,
        measuredDurationSec: measuredVoiceSec,
      });
      /**
       * RONDE 653 — word timing for the plan, whichever voice spoke. ElevenLabs' own timestamps
       * when it spoke; otherwise the finished narration transcribed, otherwise an estimate from
       * the script. Held here only: the alignment file the scene split reads is left alone, so an
       * estimate can never move a cut.
       */
      wordTiming = await narrationWordTiming({
        measured: storedAlignment?.words,
        audioPath: persisted.ok ? persisted.sourcePath : null,
        text: narrationMeta?.text ?? script,
        durationSec: narration?.durationSec ?? null,
        transcribe: (audioPath, expectedWords, durationSec) =>
          whisperWordTimings({
            audioPath,
            expectedWords,
            durationSec,
            apiKey: whisperApiKey(),
            apiUrl: whisperApiUrl(),
          }),
      });
      const wordLine =
        `[Voice] video=${videoId} word timing source=${wordTiming.source} words=${wordTiming.words.length} ` +
        `voice=${narrationMeta ? summarizeProviders(narrationMeta.providers) : "unknown"} — ${wordTiming.note}`;
      if (wordTiming.source === "elevenlabs") console.log(wordLine);
      else console.warn(pipelineReport.add("summary", wordLine));
      console.log(
        narration
          ? `[Voice] video=${videoId} narration on the timeline duration=${narration.durationSec.toFixed(2)}s ` +
              `source=${narration.durationSource} words=${wordTiming.words.length}`
          : `[Voice] video=${videoId} NO NARRATION ON THE TIMELINE — persisted=${persisted.ok} ` +
              `alignment=${storedAlignment?.totalDurationSec ?? "none"} measured=${measuredVoiceSec ?? "none"}`
      );
      if (persisted.ok) {
        await updateVideoStatus(videoId, "completed", { voiceoverUrl: persisted.url });
        console.log(
          pipelineReport.add(
            "summary",
            formatVoicePersistSuccess(videoId, persisted, storedAlignment?.words.length ?? 0)
          )
        );
      } else {
        console.error(pipelineReport.add("summary", formatVoicePersistFailure(videoId, persisted)));
      }
      await mergeVideoMetadata(videoId, {
        manifestSchemaVersion: MANIFEST_SCHEMA_VERSION,
        narration: buildNarrationPersistence({
          voiceoverUrl: persisted.ok ? persisted.url : null,
          durationSec: narration?.durationSec ?? null,
          // Only what the render actually knows. The TTS ladder picks its own tier at call time
          // and does not report which one answered, so this stays null rather than guessing
          // "elevenlabs" for a clip that may have come from the Google or Fish fallback.
          provider: narrationProviderLabel(narrationMeta?.providers ?? []),
          voiceId: voiceId ?? null,
          words: wordTiming.words,
        }),
      });
    } catch (err) {
      console.error(
        `VOICEOVER_PERSISTENCE_FAILED video=${videoId} reason=unexpected_error ` +
          `detail="${(err as Error)?.message?.slice(0, 300) ?? "unknown"}"`
      );
    }

    /**
     * RONDE 151 §2/§19 — the cinematic route, called from the production pipeline at last.
     *
     * ── Why HERE and not earlier ────────────────────────────────────────────────────────────
     *
     * This is the first point in the render where all five inputs exist at once: the scenes, each
     * scene's TTS-aligned beats, the clips that were actually adopted, the lineage records that
     * prove where those clips came from, and the persisted narration with its measured word
     * boundaries. Planning any earlier would mean planning around clips that had not been chosen.
     *
     * ── Why it does not replace the render (yet) ────────────────────────────────────────────
     *
     * The video has already been produced and uploaded by the time this runs. What this adds is
     * the PLAN: one ProjectTimeline, validated and stored, which the editor opens and the render
     * job re-renders from. That makes the new-video and existing-video paths use the same editing
     * model, which is §23's test.
     *
     * §19's cutover — the timeline producing the delivered MP4 instead of composeSceneVideo — is
     * behind `CINEMATIC_RENDER_PATH`, and the line below says which route ran on every render, so
     * the migration is countable rather than assumed.
     *
     * A failure in any of this never costs a finished video. The render is complete; refusing to
     * deliver it because a caption planner hit an edge case would be the wrong trade every time.
     */
    /**
     * The cinematic render's output, when it produced one — the file the viewer receives.
     *
     * Declared out here because the write that persists the video's URL is below this whole block.
     * Null means the render did not deliver and is refused; the reason is logged where it is
     * decided rather than inferred from this being null.
     */
    let cinematicDeliveredUrl: string | null = null;
    /**
     * RONDE 643 — the timeline the delivered cinematic file was rendered from, kept so the last
     * gate can say how many seconds of it are YouTube. `basis` says which of the two delivery paths
     * set it: the one that ran the render knows what was rendered; the one that waited knows what
     * was asked for. Null when the render did not deliver.
     */
    let deliveredTimeline: {
      clips: TimelineVideoClip[];
      basis: "rendered_timeline" | "planned_timeline";
    } | null = null;
    /**
     * The cinematic refusal, hoisted so the final gate can read it.
     *
     * `cinematicRefusal` itself lives inside the block that produces it, and the gate that has to
     * tell a FALLBACK delivery from a CONFIGURED one runs below that block. Same value, carried to
     * where the decision is made — the omission of exactly this carry is what this programme keeps
     * finding.
     */
    let cinematicRefusalForGate: string | null = null;
    /**
     * R195 — the two states between "the route is on" and "the viewer got its output".
     *
     * Recorded where they happen rather than inferred at the end from `cinematicDeliveredUrl`,
     * because the whole point of the feature matrix is that a plan that was never rendered and a
     * render that never delivered are different failures with different fixes.
     */
    const cinematicProgress = {
      enabled: false,
      planned: false,
      rendered: false,
      /**
       * R197 §10/§12 — WHAT THE DOCUMENT THE RENDERER READS ACTUALLY CARRIES.
       *
       * Read off the stored timeline rather than off the plan that asked for it, for the reason
       * `formatSfxPlan` already gives in cinematicProduction.ts: "The plan is what was asked for;
       * the timeline is what will play. Reporting from the plan would let a render claim a sound
       * that was dropped in translation."
       *
       * These are the feature matrix's only evidence that a caption, a graphic or a bed is in the
       * delivered file, and they count for nothing unless the cinematic render is what delivered.
       */
      captionsOnTimeline: 0,
      graphicsOnTimeline: 0,
      ambientClipsOnTimeline: 0,
      sfxClipsOnTimeline: 0,
      musicClipsOnTimeline: 0,
    };
    try {
      const {
        planAndStoreCinematicTimeline,
        cinematicPlanningEnabled,
        cinematicRenderPathEnabled,
        enqueueCinematicRender,
        inProcessCinematicRenderBudgetMs,
      } = await import("./cinematicProduction");
      const { pairClipsToBeats } = await import("./cinematicPipelineInputs");
      if (cinematicPlanningEnabled()) {
        const lineage = visualDedup.sourcingCache.lineage;
        /**
         * THE FILES THIS RENDER ALREADY HOLDS, keyed the way the plan will ask for them.
         *
         * Filled while the planner's inputs are built, because that is the one place where a beat's
         * position and the file the render used for it are both in hand. It is handed to the render
         * job below so the job does not re-fetch assets that are already on this disk — the failure
         * that killed render 564. See `localFilesForTimelineClips`.
         */
        const localFileByBeat = new Map<string, string>();
        /**
         * §10's counter — how many beats reached the planner holding a card this pipeline drew.
         *
         * Counted rather than inferred from the plan's `dropped` total, which mixes this in with
         * beats that had no clip at all and beats the planner refused for its own reasons. The
         * three are different failures: no media was found, media was found and was nothing, and
         * media was found and the plan could not use it.
         */
        let placeholdersRefusedFromTimeline = 0;
        /**
         * §3 — THE WHOLE ADOPTED SET REACHES THE PLANNER.
         *
         * `plannerClipsForScene` carries the reasoning, including why RONDE 636 removed the
         * usability probe that used to stand here: it read the filesystem one stage too late,
         * refused thirteen of thirteen adopted clips on render 602, and was a second copy of
         * checks the planner already performs at the only moment they are current.
         *
         * Nothing is awaited any more, so this is assembled inside the map with everything else.
         */
        const outcome = await planAndStoreCinematicTimeline({
          videoId,
          /** RONDE 649 — the video's own subtitle setting; off unless the user switched it on. */
          includeSubtitles: enableSubtitles,
          /** The render's own id, so an adapter refusal names the run that produced it. */
          renderId: lineage.renderId,
          scenes: scenes.map((scene, i) => {
            /**
             * RENDER 562 — from the render's own record, not from the clip list.
             *
             * `sceneVisualResults[i].beats` is optional, and the routes that rebuild a scene's clip
             * list drop it. On 562 all three scenes ended on such a route, so this read produced
             * three empty arrays and the planner reported `beats=0 dropped=3` — no beat failed a
             * check, there were none to check. `sceneBeatsBySceneIndex` is written where the render
             * establishes a scene's beats and nothing rebuilds it. The clip list stays the
             * fallback, so a scene that somehow reached the record without reaching this map is no
             * worse off than before.
             */
            const beats =
              visualDedup.sceneBeatsBySceneIndex.get(scene.index) ??
              sceneVisualResults[i]?.beats ??
              [];
            /**
             * `pairClipsToBeats` rather than `clipPaths[beatIndex]` — see its own comment. The
             * positional read was a guess that only ever ran over an empty beat list.
             */
            /** RONDE 661 — the scene's selected clips are the only clip list there is. */
            const plannerSource = { clipPaths: sceneVisualResults[i]?.clips ?? [] };
            console.log(`[CinematicPlannerSource] scene=${scene.index} clips=${plannerSource.clipPaths.length}`);
            const sceneAdoptions = visualDedup.clipAdoptAudit.filter(
              (e) => e.sceneIndex === scene.index
            );
            const clipForBeat = pairClipsToBeats({
              clipPaths: plannerSource.clipPaths,
              adoptions: sceneAdoptions,
              beats,
              basenameOf: (clipPath) => path.basename(clipPath),
            });
            /**
             * §5 — WHY A BEAT HAS NO PICTURE, SAID WHERE IT CAN BE PROVEN.
             *
             * `planCinematicScene` drops an empty beat with `NO_ADOPTED_CLIP`, which was the label
             * that lied: a clip HAD been adopted, the planner was handed a list that did not carry
             * it. That sentence is true from inside that function — it received nothing — and the
             * render needs the reason that function cannot know. It is known here, one line from
             * the list itself:
             *
             *     CANONICAL_CLIP_AVAILABLE  the beat's adopted clip is in the planner's list
             *     NO_CANONICAL_CLIP         nothing was ever adopted for this beat
             *
             * RONDE 636 removed a third, `CANONICAL_CLIP_EXCLUDED`, together with the mistimed
             * probe that was the only thing producing it. Nothing is filtered out of the planner's
             * list here any more, so a beat either has its adopted clip or never had one, and a
             * beat the PLANNER then refuses says so in its own words (`NOT_REHYDRATABLE`,
             * `SCENE_TIME_EXHAUSTED`, `NO_DURATION`) at the moment it decides.
             */
            beats.forEach((beat, position) => {
              const beatKey = beat.index ?? position;
              const clipPath = clipForBeat[position];
              console.log(
                `[CinematicPlannerBeat] scene=${scene.index} beat=${beatKey} ` +
                  `reason=${clipPath ? "CANONICAL_CLIP_AVAILABLE" : "NO_CANONICAL_CLIP"}` +
                  (clipPath ? ` file=${path.basename(clipPath)}` : "")
              );
            });
            clipForBeat.forEach((clipPath, beatIndex) => {
              if (clipPath) localFileByBeat.set(`${scene.index}:${beatIndex}`, clipPath);
            });
            return {
              scene,
              beats,
              clips: beats.map((_, beatIndex) => {
                const clipPath = clipForBeat[beatIndex];
                if (!clipPath) return null;
                /**
                 * With the content key, like every other resolve in this file — `resolve` reaches
                 * its third rung only when one is supplied. Twenty-six lines above, the divergence
                 * report already calls `lineage.resolve(p, clipContentKey(p))`; this call, which
                 * decides whether a beat survives into the cinematic plan at all, did not.
                 */
                const record = lineage.resolve(clipPath, clipContentKey(clipPath));
                /**
                 * §10 — A CARD THIS PIPELINE DREW DOES NOT ENTER THE TIMELINE.
                 *
                 * ── What it was doing here ──────────────────────────────────────────────────
                 *
                 * Nothing filtered placeholders out of the planner's input. A beat that ended on
                 * the guaranteed ladder's `text_overlay` or `color_fallback` rung arrived here as
                 * an ordinary clip path, was paired to its beat, and became a TimelineVideoClip
                 * like any other. `cinematicProduction` and `cinematicPipelineInputs` contain no
                 * mention of fallback, filler, placeholder or guaranteed — there was no gate to
                 * pass, because there was no gate.
                 *
                 * The two gates further down did not close it either. `renderJobWorker`'s delivery
                 * gate asks `isPipelineFallbackClip`, which matches `_fallback.mp4` and NOT the
                 * `_guaranteed.mp4` name this ladder actually writes; the FinalRenderInputs line
                 * counts fallbackAssets with the same predicate, over a title rather than a path.
                 * So a drawn card reached the renderer counted as a real asset.
                 *
                 * ── What happens instead ────────────────────────────────────────────────────
                 *
                 * The beat is handed `null`, which is the planner's existing word for "this beat
                 * has no clip" — the same value an unfilled beat has always produced, travelling
                 * the same path, dropped by the same code with `CINEMATIC_DROPPED` on the ledger.
                 * No new failure mode is introduced; a beat that could not be filled with real
                 * media is simply no longer filled with a picture of nothing.
                 *
                 * ── The consequence, stated rather than discovered ──────────────────────────
                 *
                 * A render whose beats are mostly cards now plans a shorter timeline, and if every
                 * beat is a card it plans none — the render then fails with its reason logged,
                 * exactly as it does for any plan that fails. That is the honest outcome of "geen
                 * beeld gevonden" and it is visible in the counter below rather than hidden inside
                 * a film.
                 *
                 * The verdict is taken from the ledger route, which is where `rescue_placeholder`
                 * lands via `adoptRouteForSource`, with the narrow filename as a last resort. The
                 * TIER is the strongest authority and is deliberately NOT available here — it goes
                 * out of scope at the ladder — which is why the route is written down at all.
                 */
                const placeholderVerdict = beatClipIsPlaceholder({
                  clipPath,
                  /**
                   * Matched on the BASENAME, which is the only path-like field an adopt entry
                   * carries, and on the beat — `pushClip` appends, so one beat can hold a real
                   * clip and a card, and the entry that speaks for this clip is the one naming
                   * this file. A beat with no entry falls through to the ledger route.
                   */
                  adoptSource: visualDedup.clipAdoptAudit.find(
                    (e) =>
                      e.sceneIndex === scene.index &&
                      e.basename === path.basename(clipPath)
                  )?.source,
                  lineageRoute: record?.route,
                });
                if (placeholderVerdict.placeholder) {
                  placeholdersRefusedFromTimeline += 1;
                  console.warn(
                    `[PlaceholderRefused] video=${videoId} scene=${scene.index} beat=${beatIndex} ` +
                      `authority=${placeholderVerdict.authority} ` +
                      `evidence=${placeholderVerdict.evidence} ` +
                      `file=${path.basename(clipPath)} — a card this pipeline drew is not media; ` +
                      "the beat enters the plan unresolved"
                  );
                  visualDedup.sourcingCache?.lineage?.recordEventForPath(
                    clipPath,
                    "CINEMATIC_DROPPED",
                    { status: "REJECTED", reason: "PLACEHOLDER_NOT_IN_TIMELINE" }
                  );
                  localFileByBeat.delete(`${scene.index}:${beatIndex}`);
                  return null;
                }
                const meta = memoisedVideoStreamMeta(clipPath);
                return {
                  facts: {
                    localPath: clipPath,
                    ...(meta?.width ? { widthPx: meta.width } : {}),
                    ...(meta?.height ? { heightPx: meta.height } : {}),
                    ...(meta && meta.durationSec > 0
                      ? { durationSec: Number(meta.durationSec.toFixed(3)) }
                      : {}),
                  },
                  adoption: record
                    ? {
                        provider: record.provider,
                        providerAssetId: record.providerAssetId,
                        archiveAssetId: record.archiveAssetId,
                        sourceUrl: record.sourceUrl,
                        originalUrl: record.originalUrl,
                        assetTitle: record.assetTitle,
                        query: record.query,
                        candidateId: record.candidateId,
                        /** §7 — the cut this render made into the provider's original, if any. */
                        sourceInSec: record.sourceInSec,
                        sourceOutSec: record.sourceOutSec,
                      }
                    : null,
                };
              }),
            };
          }),
          /**
           * RONDE 121 — THE PLANNER'S TWO ENDINGS, WRITTEN DOWN AT LAST.
           *
           * `CINEMATIC_SELECTED` and `CINEMATIC_DROPPED` have been declared stages of a clip's
           * life for rounds, and RONDE 120's census found that production wrote NEITHER — so
           * `lifecyclesOf` reported both as false for every asset of every render, while render
           * 572 dropped six beats at that exact step and said so only on the console. A clip the
           * planner dropped therefore reached the audit with no cinematic ending at all, which is
           * one source of the `unexplained` assets nobody could name.
           *
           * This is the caller the ledger's own note said existed. The planner announces what it
           * decided; the writing happens here, where the ledger is in scope — the planner stays
           * decoupled from lineage, as three rounds of its notes ask.
           *
           * A path the ledger never saw resolves to nothing and writes nothing, which is the
           * honest outcome: a beat planned around a file with no record cannot gain one here.
           */
          onBeatOutcome: (o) => {
            if (!o.clipPath) return;
            visualDedup.sourcingCache?.lineage?.recordEventForPath(o.clipPath, o.stage, {
              status: "OK",
              reason: o.reason,
            });
          },
          /** The pipeline's OWN extractors, injected — never a second copy (§28). */
          extractors: {
            people: (text) => extractPersonNamesFromText(text),
            place: (text) => extractVisualPlacePhrase(text),
            action: (text) => extractActionCue(text),
            /**
             * RONDE 177 — the named entities and secondary subjects the RETRIEVAL path resolved
             * for this beat. Injected from here so the plan describes the same beat the search
             * described; a parallel extractor would let the caption name something else.
             */
            namedEntities: (text) => beatNamedEntitiesByKind(text),
            secondarySubjects: (text) => extractSecondaryEntities(text, undefined),
          },
          voice: narration ? { url: narration.url, durationSec: narration.durationSec } : null,
          words: wordTiming.words,
          persist: (p) => saveVideoTimeline(p),
          /**
           * RONDE 647 — a YouTube shot is held to five seconds and taken from one continuous shot
           * of the original. Its length and cuts come from its archive row, measured once.
           */
          youtubeSourceFacts: async (identity) => {
            const { youtubeSourceFactsFor, productionShotCutDeps } = await import("./youtubeShotCuts");
            return youtubeSourceFactsFor(identity, productionShotCutDeps(workDir));
          },
          /**
           * The emotional curve this render already built, handed to the score.
           *
           * `buildDocumentaryPlan` runs at the top of the render and produces the curve from the
           * whole script. Passing it here is what lets the music cue sheet follow the story — an
           * intro over the opening, a build where intensity rises, deliberate silence under the
           * quietest passage — instead of laying one bed across everything.
           */
          emotionalCurve: visualDedup.documentaryPlan?.emotionalCurve,
          storedVersion: (await getStoredTimeline(videoId))?.timelineVersion ?? 0,
        });
        for (const line of outcome.log) console.log(pipelineReport.add("summary", line));
        /**
         * §23's two numbers, on every render, including the renders where both are zero.
         *
         * Printed unconditionally so "no placeholder reached the timeline" is a stated measurement
         * rather than the absence of a warning — the same reason `[ProviderSkipped]` names a
         * provider that was never asked.
         */
        {
          /**
           * `placeholdersOnTimeline` is COUNTED off the stored document, never asserted to be zero.
           *
           * The refusal above runs over the planner's INPUT; this runs over its OUTPUT. If they
           * ever disagree, a clip reached the timeline by a path this gate does not stand in, and
           * that is precisely the thing worth knowing — an invariant that reports itself satisfied
           * without looking is the failure mode this whole programme keeps finding.
           */
          const onTimeline = outcome.ok ? videoTrack(outcome.timeline) : [];
          const stillPlaceholder = onTimeline.filter((c) => {
            const local =
              c.sceneIndex != null && c.beatIndex != null
                ? localFileByBeat.get(`${c.sceneIndex}:${c.beatIndex}`)
                : undefined;
            return beatClipIsPlaceholder({
              clipPath: local ?? c.source.title ?? c.id,
              lineageRoute: local
                ? lineage.resolve(local, clipContentKey(local))?.route
                : undefined,
            }).placeholder;
          }).length;
          console.log(
            pipelineReport.add(
              "summary",
              `[PlaceholderGate] video=${videoId} ` +
                `refusedFromTimeline=${placeholdersRefusedFromTimeline} ` +
                `clipsOnTimeline=${onTimeline.length} ` +
                `placeholdersOnTimeline=${stillPlaceholder}`
            )
          );
          if (stillPlaceholder > 0) {
            console.error(
              pipelineReport.add(
                "summary",
                `[PlaceholderGate] video=${videoId} INVARIANT_BREACHED — ${stillPlaceholder} ` +
                  "clip(s) the refusal did not stand in front of reached the timeline"
              )
            );
          }
        }
        if (!outcome.ok) {
          console.warn(
            pipelineReport.add(
              "summary",
              `[CinematicPipeline] video=${videoId} plan NOT stored code=${outcome.code} reason=${outcome.reason}`
            )
          );
        }
        /**
         * RONDE 122 §2 — THE LINEAGE IS WRITTEN DOWN BEFORE ANYTHING RENDERS IT.
         *
         * The ledger has always been an in-memory object created per render, so the moment this
         * process ended, every asset's history ended with it — which is why `DELIVERED` had no
         * writer for rounds: the code that uploads the file and learns its URL runs in a render
         * job that may start minutes later, in a different process, holding only a timeline.
         *
         * A timeline knows identities and no histories. So the histories are persisted HERE, at
         * the last moment both the ledger and the stored timeline's version are in scope, keyed by
         * canonical asset identity so the render job can join its own output against them. It is
         * stored beside the qualityReport and the render report in `videos.metadata`, which is
         * where this pipeline's per-render evidence already lives.
         *
         * Written whether or not the cinematic route is taken, and before the claim: a job the
         * poll loop takes must find the same lineage the in-process render would have found.
         */
        if (outcome.ok) {
          /** R195 — a timeline exists. Whether anything renders from it is the next state. */
          cinematicProgress.planned = true;
          /**
           * R197 — and WHAT it holds, counted off the document itself.
           *
           * This is the only evidence the feature matrix accepts for captions, graphics, ambience,
           * sfx and music: the tracks on the timeline the renderer will read. Counting the plan
           * instead would let a render claim a caption that was dropped in translation, which is
           * exactly the false positive this round found in R196's first version.
           */
          try {
            const t = outcome.timeline;
            cinematicProgress.captionsOnTimeline = captionTrack(t).length;
            cinematicProgress.graphicsOnTimeline = graphicsTrack(t).length;
            cinematicProgress.ambientClipsOnTimeline = audioTrackOf(t, "AMBIENT").length;
            cinematicProgress.sfxClipsOnTimeline = audioTrackOf(t, "SFX").length;
            cinematicProgress.musicClipsOnTimeline = audioTrackOf(t, "MUSIC").length;
          } catch {
            /** A count that cannot be taken stays zero — absent, never assumed present. */
          }
          try {
            const ledger = visualDedup.sourcingCache?.lineage;
            if (ledger) {
              const snapshot = snapshotLineage(ledger, {
                videoId,
                timelineVersion: outcome.timelineVersion,
              });
              await persistVisualLineage(videoId, snapshot);
              console.log(
                pipelineReport.add(
                  "sourcing",
                  `[VisualLineage] video=${videoId} persisted assets=${snapshot.assets.length} ` +
                    `unidentifiedRecords=${snapshot.unidentifiedRecords} ` +
                    `truncated=${snapshot.truncated ?? 0} timelineVersion=${snapshot.timelineVersion}`
                )
              );
            }
          } catch (err) {
            console.warn(
              `[VisualLineage] video=${videoId} could not persist the lineage — the render is ` +
                `unaffected and its delivery cannot be attributed: ${(err as Error).message.slice(0, 200)}`
            );
          }
        }
        /**
         * R159 §24 — when the flag is on and the plan is good, the timeline RENDERS the video.
         *
         * A render job is queued from the stored timeline and the same worker that renders a
         * hand-edited video takes it from there: rehydrate, validate, ffmpeg, Remotion overlay,
         * composite, ffprobe, upload. §26's "one timeline, one renderer" is kept by not building a
         * second path — this only puts a row in the queue.
         *
         * The compose output produced earlier in this render is still uploaded and still the
         * video's current output. The cinematic render supersedes it when it finishes, through the
         * existing `renderAttempt` fencing, so a failure of the new route costs nothing.
         */
        let cutover: Awaited<ReturnType<typeof enqueueCinematicRender>> | null = null;
        /** Why the delivered file is NOT the cinematic render, when it is not. Never left empty. */
        let cinematicRefusal: string | null = null;
        /** R195 — read once, here, because the flag lives behind this block's dynamic import. */
        cinematicProgress.enabled = cinematicRenderPathEnabled();
        /**
         * Video 612 — the timeline as it will be rendered, after its holds and YouTube pieces. When
         * one piece of footage fills it, nothing is rendered: the render job's delivery gate would
         * refuse the same film five minutes later, on the same measurement.
         */
        const footageRefusal = outcome.ok
          ? finalTimelineFootageRefusal(
              videoTrack(outcome.timeline),
              undefined,
              await youtubeVideoIdsForArchiveAssets(videoTrack(outcome.timeline), getMediaArchiveAssetById)
            )
          : null;
        if (footageRefusal) {
          cinematicRefusal = `ONE_FOOTAGE_FILLS_FILM — ${footageRefusal}`;
          console.error(pipelineReport.add("summary", `[DeliveryGate] video=${videoId} not rendered: ${cinematicRefusal}`));
        }
        if (outcome.ok && cinematicProgress.enabled && !footageRefusal) {
          try {
            const { claimRenderAttempt, createRenderJob, claimQueuedRenderJob, getRenderJobById } =
              await import("./db");
            cutover = await enqueueCinematicRender({
              videoId,
              timelineVersion: outcome.timelineVersion,
              claimAttempt: (id) => claimRenderAttempt(id),
              createJob: (p) => createRenderJob(p),
            });
            for (const line of cutover.log) console.log(pipelineReport.add("summary", line));
            if (!cutover.ok) {
              cinematicRefusal = cutover.reason;
              console.warn(
                pipelineReport.add(
                  "summary",
                  `[RenderJob] video=${videoId} cinematic render NOT queued: ${cutover.reason}`
                )
              );
            } else {
              /**
               * §19's cutover, FINISHED: the timeline renders the file the viewer receives.
               *
               * ── Why this is run here and not left to the poll loop ──────────────────────────
               *
               * The queue was only ever half the cutover. A queued job renders minutes later and
               * publishes to `editedVideoUrl`, a column ONLY the timeline editor reads — the
               * dashboard shows and downloads `videoUrl`. So on render 564 the cinematic route was
               * chosen, the plan was stored, the job was queued 27 ms before COMPLETE, and the file
               * the viewer downloaded was still the compose montage. Graphics, ambience, SFX,
               * captions and planned transitions all live on the route that did not deliver.
               *
               * Rendering it HERE, before the video is marked complete, is what makes the plan the
               * product. It is the SAME `runRenderJob` the editor's re-render uses, on the same
               * queue row, with the same attempt fencing — §26's "one timeline, one renderer" holds
               * because no second renderer is introduced. What changes is only WHEN it runs and
               * which column its output lands in.
               *
               * ── The claim is what keeps the poll loop out ───────────────────────────────────
               *
               * `claimQueuedRenderJob` is a conditional UPDATE from `queued` to `running`: exactly
               * one caller can win it. Losing it means the worker already took this job, and then
               * this render does NOT render it a second time — it waits for the worker's outcome,
               * which is the honest outcome rather than two ffmpeg runs racing for one row.
               */
              const claimed = await claimQueuedRenderJob(cutover.renderJobId);
              if (!claimed) {
                /**
                 * §16 — LOSING THE CLAIM IS NOT THE SAME AS THE RENDER FAILING.
                 *
                 * What stood here was the second half of that sentence: this render "did not
                 * produce the cinematic file", written down as `cinematicRefusal`, which the
                 * delivery gate reads as AUTHORITATIVE_RENDER_FAILED.
                 *
                 * Render 600 measured what that costs. Sixty-one milliseconds after queueing job
                 * 19 the video was written off as failed; eight seconds later the worker started
                 * it, and two and a half minutes after that the film passed the gate reading the
                 * real file and was published. The MP4 existed the whole time.
                 *
                 * Not rendering it twice is right and is unchanged — `awaitRenderJobOutcome` only
                 * READS the row, never claims it, so the mutual exclusion
                 * `claimQueuedRenderJob` establishes is untouched. What changes is that this
                 * render now asks the question it was answering: not "did I render it" but "was
                 * it rendered".
                 */
                const { awaitRenderJobOutcome, formatRenderJobWait } = await import(
                  "./awaitRenderJobOutcome"
                );
                const waitBudgetMs = inProcessCinematicRenderBudgetMs();
                const waited = await awaitRenderJobOutcome({
                  jobId: cutover.renderJobId,
                  budgetMs: waitBudgetMs,
                  readJob: (id) => getRenderJobById(id),
                  /** The watchdog is fed exactly as the claimed path feeds it while ffmpeg runs. */
                  onWaiting: ({ waitedMs, status }) =>
                    get_activeWatchdog()?.ping(
                      `waiting on render job=${cutover?.ok ? cutover.renderJobId : "?"} ` +
                        `${status} ${Math.round(waitedMs / 1000)}s`
                    ),
                });
                console.log(
                  pipelineReport.add(
                    "summary",
                    `[RenderJob] video=${videoId} ${formatRenderJobWait(cutover.renderJobId, waited)}`
                  )
                );
                if (waited.kind === "DELIVERED") {
                  cinematicDeliveredUrl = waited.outputUrl;
                  deliveredTimeline = { clips: videoTrack(outcome.timeline), basis: "planned_timeline" };
                  /** The renderer ran — in the worker's process, but it ran, and it delivered. */
                  cinematicProgress.rendered = true;
                  /**
                   * RONDE 639 — AND FINAL_VIDEO STOPS DESCRIBING THE MONTAGE NOBODY RECEIVED.
                   *
                   * The claimed path below marks FINAL_VIDEO with `replaceFinalVideo` against what
                   * the render job reported it rendered. This path had no such marking, and the
                   * LAST delivery gate reads exactly that marking (`deliveryClipFactsFromLedger`
                   * keeps `finalVideoAt != null`). Before RONDE 661 it read the compose montage's.
                   *
                   * Render 603 is what that cost. The film was rendered, published and passed the
                   * gate that read the real file:
                   *
                   *     [PlaceholderGate] video=603 refusedFromTimeline=1 clipsOnTimeline=9
                   *                       placeholdersOnTimeline=0
                   *     [DeliveryGate] DELIVERY_GATE_PASS video=603 clips=9 checks=assets+file
                   *     [RenderJob] job=20 status=completed published=true clips=9 duration=65.54s
                   *
                   * and four seconds later the pipeline refused it:
                   *
                   *     [DeliveryGate] DELIVERY_GATE_FAIL video=603 clips=13 checks=assets failures=1
                   *       PLACEHOLDER_IN_DELIVERY — clip=…#149 is a placeholder or colour fallback
                   *
                   * Thirteen clips judged for a film made of nine, and the one it failed on is a
                   * card the placeholder gate had already refused from the timeline. The video was
                   * blocked over a picture that is not in it.
                   *
                   * ── What this can and cannot claim ─────────────────────────────────────────
                   *
                   * The claimed path knows what the renderer RENDERED (`renderedClipIds`). Another
                   * process rendered this one, so the strongest list available here is the stored
                   * timeline the job carried — what was ASKED for. A clip the worker could not
                   * rehydrate would still be marked, so this is not as strong as the claimed
                   * path's list and the log says which it is rather than implying the other.
                   *
                   * It is the same marking applied at the same point for the same reason.
                   */
                  try {
                    const ledger = visualDedup.sourcingCache.lineage;
                    const { localFilesForTimelineClips } = await import("./cinematicPipelineInputs");
                    const { videoTrack } = await import("./projectTimeline");
                    const timelineClips = videoTrack(outcome.timeline);
                    const localByClipId = localFilesForTimelineClips({
                      clips: timelineClips,
                      localPathFor: (sceneIndex, beatIndex) =>
                        localFileByBeat.get(`${sceneIndex}:${beatIndex}`) ?? null,
                    });
                    const deliveredPaths: string[] = [];
                    let unattributable = 0;
                    for (const clip of timelineClips) {
                      const local = localByClipId.get(clip.id);
                      if (local) deliveredPaths.push(local);
                      else unattributable++;
                    }
                    const proven = ledger.replaceFinalVideo(deliveredPaths);
                    console.log(
                      pipelineReport.add(
                        "sourcing",
                        `[VisualAudit] video=${videoId} FINAL_VIDEO re-proved against the timeline ` +
                          `the worker rendered: ${timelineClips.length} shot(s) planned, ` +
                          `${proven} clip(s) proven` +
                          (unattributable > 0
                            ? `, ${unattributable} rehydrated by the render job and not attributable`
                            : "") +
                          " — planned rather than confirmed rendered, because another process rendered it"
                      )
                    );
                  } catch (err) {
                    console.warn(
                      `[VisualAudit] video=${videoId} could not re-prove FINAL_VIDEO against the ` +
                        `worker's timeline: ${(err as Error).message.slice(0, 200)}`
                    );
                  }
                  /**
                   * RONDE 661 — the claimed path fills the spot check and the AV envelope from the
                   * render job's own return value. Another process rendered this file, so this
                   * process has neither, and the report says so rather than leaving a gap unnamed.
                   */
                  qualityReport.warnings.push(
                    `the delivered file was rendered by another render job worker, so this report ` +
                      `has no black-frame or AV-envelope figures for it and its clip figures count ` +
                      `the selected clips, not the delivered file`
                  );
                } else {
                  cinematicRefusal = formatRenderJobWait(cutover.renderJobId, waited);
                }
              } else {
                onProgress?.({ stage: "Rendering the edit", percent: 97 });
                const { runRenderJob } = await import("./renderJobWorker");
                const { localFilesForTimelineClips } = await import("./cinematicPipelineInputs");
                const { videoTrack } = await import("./projectTimeline");
                const existingByClipId = localFilesForTimelineClips({
                  clips: videoTrack(outcome.timeline),
                  localPathFor: (sceneIndex, beatIndex) =>
                    localFileByBeat.get(`${sceneIndex}:${beatIndex}`) ?? null,
                });
                /**
                 * A beat whose file this render downloaded and no longer has is NAMED.
                 *
                 * `localFilesForTimelineClips` now verifies the bytes, so `alreadyLocal` is a count
                 * of files rather than of paths — and the clips it left out would otherwise vanish
                 * from the record entirely, which is how render 589 came to report that all three
                 * of its clips were in hand while one was about to send the renderer to Commons.
                 * A clip on this list will be re-fetched, and the fetch is now expected.
                 */
                const sweptClips = videoTrack(outcome.timeline)
                  .filter(
                    (c) =>
                      c.sceneIndex != null &&
                      c.beatIndex != null &&
                      localFileByBeat.get(`${c.sceneIndex}:${c.beatIndex}`) &&
                      !existingByClipId.has(c.id)
                  )
                  .map((c) => `${c.id}(s${c.sceneIndex}b${c.beatIndex})`);
                console.log(
                  pipelineReport.add(
                    "summary",
                    `[RenderJob] video=${videoId} job=${cutover.renderJobId} rendering in-process ` +
                      `clips=${videoTrack(outcome.timeline).length} ` +
                      `alreadyLocal=${existingByClipId.size}`
                  )
                );
                if (sweptClips.length > 0) {
                  console.warn(
                    pipelineReport.add(
                      "summary",
                      `[RenderJob] video=${videoId} job=${cutover.renderJobId} ` +
                        `LOCAL_FILE_GONE clips=${sweptClips.length} ${sweptClips.join(" ")} — ` +
                        "this render downloaded these and no longer holds them; each one must be " +
                        "fetched from its provider again"
                    )
                  );
                }
                /**
                 * §7 — THE RENDER'S INPUT, ASSET BY ASSET, BEFORE A FRAME IS DRAWN.
                 *
                 * `[RenderAsset]` describes the DELIVERED file, built afterwards from the lineage
                 * ledger. That is the right report for "what does this video contain" and the wrong
                 * one for "what was this renderer handed" — a render that fails, is cancelled or
                 * drops a clip produces no such lines at all, and the two questions then have the
                 * same empty answer.
                 *
                 * These lines are emitted from the timeline itself, so the last checkpoint before
                 * ffmpeg is on the record whatever happens next. `TimelineVideoClip.source` is an
                 * `AssetSourceIdentity`, so the identity is the one the planner proved rather than
                 * anything re-derived here.
                 *
                 * `origin` distinguishes what the film is made of. A guaranteed filler is a real
                 * file and a real render input, and calling it a real ASSET would inflate every
                 * count that matters — this is the same distinction `[FORENSIC_BEAT_SUMMARY]`
                 * needs and the one VID-0567 turned on.
                 */
                {
                  const inputs = videoTrack(outcome.timeline);
                  const originOf = (c: (typeof inputs)[number]): string =>
                    isPipelineFallbackClip(c.source.title ?? c.id)
                      ? "GUARANTEED_FILLER"
                      : c.source.provider && c.source.provider !== "UNVERIFIED"
                        ? "REAL_ASSET"
                        : "UNVERIFIED_SOURCE";
                  const real = inputs.filter((c) => originOf(c) === "REAL_ASSET").length;
                  const filler = inputs.filter((c) => originOf(c) === "GUARANTEED_FILLER").length;
                  console.log(
                    `[FinalRenderInputs] render=${videoId} job=${cutover.renderJobId} ` +
                      `clips=${inputs.length} realAssets=${real} fallbackAssets=${filler} ` +
                      `unverified=${inputs.length - real - filler} ` +
                      `alreadyLocal=${existingByClipId.size} ` +
                      `pictureDuration=${(outcome.timeline.durationSec ?? 0).toFixed(2)}`
                  );
                  for (const c of inputs) {
                    const sourceId =
                      c.source.providerAssetId ??
                      (c.source.archiveAssetId != null ? String(c.source.archiveAssetId) : "none");
                    console.log(
                      `[FinalRenderAsset] render=${videoId} job=${cutover.renderJobId} ` +
                        `asset=${c.source.provider}:${sourceId} provider=${c.source.provider} ` +
                        `sourceId=${sourceId} clip=${c.id} ` +
                        `start=${c.timelineStart.toFixed(2)} ` +
                        `duration=${(c.timelineEnd - c.timelineStart).toFixed(2)} ` +
                        `origin=${originOf(c)} local=${existingByClipId.has(c.id)}`
                    );
                    /**
                     * §9 — AND ON THE LEDGER, NOT ONLY IN THE LOG.
                     *
                     * The line above is greppable; an invariant needs a data structure. A clip the
                     * planner kept and the renderer was never handed is invariant C, and it can
                     * only be computed if both facts are events on the same record.
                     *
                     * Resolved by the local file the render will actually read, so the event lands
                     * on the asset rather than on a timeline id the ledger has never heard of. A
                     * clip whose file this render does not hold records nothing — the ledger does
                     * not invent a record to satisfy a report.
                     */
                    const localForClip = existingByClipId.get(c.id);
                    if (localForClip) {
                      visualDedup.sourcingCache?.lineage?.recordEventForPath(
                        localForClip, "RENDER_INPUT", { status: "OK" }
                      );
                    }
                  }
                }
                /**
                 * THE WATCHDOG DOES NOT SEE THIS RENDER'S FFMPEG, SO IT IS TOLD ABOUT IT.
                 *
                 * `timelineRenderer` spawns through its own `execFileAsync`, which never calls
                 * `trackChild`. The watchdog's total-budget check measures IDLE time since the last
                 * signal, so without this the whole cinematic render looks like a hang — and a
                 * watchdog kill here would fire `throwIfVideoGenerationCancelled` mid-render.
                 *
                 * The heartbeat is bounded rather than unconditional. An unconditional ping would
                 * switch the watchdog off for as long as this took, which is exactly the protection
                 * it exists to provide. Past the deadline the pings stop and the watchdog is free to
                 * act again; a render that still finishes is delivered and says it overran.
                 *
                 * The render is not killed at the deadline — its ffmpeg children are not ours to
                 * SIGKILL from here. It continues, and if it eventually finishes it publishes to
                 * `editedVideoUrl` like any other job, so the work is not thrown away; it simply is
                 * not what this render waited for.
                 */
                const renderDeadlineMs = inProcessCinematicRenderBudgetMs();
                const renderStartedAt = Date.now();
                const heartbeat = setInterval(() => {
                  if (Date.now() - renderStartedAt > renderDeadlineMs) return;
                  get_activeWatchdog()?.ping(
                    `cinematic render job=${cutover?.ok ? cutover.renderJobId : "?"} ` +
                      `${Math.round((Date.now() - renderStartedAt) / 1000)}s`
                  );
                }, 30_000);
                let jobOutcome: Awaited<ReturnType<typeof runRenderJob>>;
                try {
                  jobOutcome = await runRenderJob({
                    jobId: cutover.renderJobId,
                    existingByClipId,
                  });
                } finally {
                  clearInterval(heartbeat);
                  /** R195 — the renderer ran. Whether its output is delivered comes next. */
                  cinematicProgress.rendered = true;
                }
                if (Date.now() - renderStartedAt > renderDeadlineMs && jobOutcome.ok) {
                  console.warn(
                    pipelineReport.add(
                      "summary",
                      `[RenderJob] video=${videoId} job=${cutover.renderJobId} finished after its ` +
                        `in-process budget (${Math.round((Date.now() - renderStartedAt) / 1000)}s > ` +
                        `${Math.round(renderDeadlineMs / 1000)}s) — delivered anyway, it is a real file`
                    )
                  );
                }
                if (jobOutcome.ok) {
                  cinematicDeliveredUrl = jobOutcome.outputUrl;
                  /**
                   * RONDE 644 — only the clips the renderer REPORTS it rendered. The job can drop a
                   * clip it cannot use (`disableClipsForRender`) on its own copy of the timeline; the
                   * plan here would still list it, and "rendered" would then be a claim about a plan.
                   */
                  const renderedIds = new Set(jobOutcome.renderedClipIds);
                  deliveredTimeline = {
                    clips: videoTrack(outcome.timeline).filter((c) => renderedIds.has(c.id)),
                    basis: "rendered_timeline",
                  };
                  console.log(
                    pipelineReport.add(
                      "summary",
                      `[RenderJob] video=${videoId} job=${cutover.renderJobId} ` +
                        `DELIVERED_BY=cinematic_timeline duration=` +
                        `${jobOutcome.durationSec?.toFixed(2) ?? "unmeasured"}s`
                    )
                  );
                  /**
                   * THE REPORT NOW DESCRIBES WHAT WAS DELIVERED.
                   *
                   * `qualityReport.postRenderSpotCheck` is the render job's own check on the
                   * delivered file — black frames, freezes and silences. A report about a different
                   * video is worse than no report, because it reads as reassurance.
                   *
                   * The final `mergeVideoMetadata` runs after this block, so this reaches the
                   * stored record.
                   */
                  if (jobOutcome.spotCheck) {
                    const spot = jobOutcome.spotCheck;
                    qualityReport.postRenderSpotCheck = {
                      ok: spot.ok,
                      blackFrameCount: spot.blackFrameCount,
                      framesChecked: spot.framesChecked,
                      worstMeanLuma: spot.worstMeanLuma,
                      warnings: spot.warnings,
                    };
                    for (const w of spot.warnings) {
                      qualityReport.warnings.push(`Delivered file: ${w}`);
                    }
                  }
                  /**
                   * R195 — AND THE AV ENVELOPE OF THE FILE THE VIEWER RECEIVED.
                   *
                   * The render job already measured this and returned it with a doc comment saying
                   * "Returned rather than only logged so the caller can put it in the quality
                   * report". This is that caller, and it read `outputUrl`, `durationSec`,
                   * `spotCheck`, `renderedClipIds`, `code` and `message` — never `avSync`. So the
                   * one check that names narration running past the picture was computed on the
                   * delivered file and then dropped on the floor.
                   *
                   * Same treatment as the spot check above, for the same reason: this CAN follow
                   * the delivery, so it does.
                   */
                  if (jobOutcome.avSync) {
                    const av = jobOutcome.avSync;
                    qualityReport.avSync = {
                      measuredOn: "delivered_render",
                      ok: av.ok,
                      videoSec: av.envelope.videoSec,
                      audioSec: av.envelope.audioSec,
                      findings: avSyncFindingCodes(av),
                    };
                    for (const f of av.findings) {
                      qualityReport.warnings.push(`Delivered file AV envelope: ${f.reason}`);
                    }
                  }
                  /**
                   * AND SO DOES THE SOURCE AUDIT — FINAL_VIDEO IS PROVEN FROM THE DELIVERED FILE.
                   *
                   * ── The claim that was about the wrong video ──────────────────────────────
                   *
                   * `markFinalVideo` runs at stage 6, from `finalConcatInputs` — the input list of
                   * the concat that produced the COMPOSE montage. Its own comment says it is
                   * emitted there "because this is the first moment FINAL_VIDEO is knowable", and
                   * that stopped being true at the cutover: the delivered file is produced here,
                   * eight hundred lines later, by a different renderer, from its own clip list.
                   *
                   * So `[AssetUsageSummary]`'s `rendered` column, `[VisualFunnel]`'s `finalVideo`
                   * and every `unused` figure derived from them described a file nobody receives.
                   * A clip the cinematic renderer could NOT recover — named in its `skipped` list,
                   * absent from the delivered picture — was reported as being in the video, which
                   * is the same defect as the spot check above, one column further along.
                   *
                   * ── Why the numbers are re-printed rather than quietly corrected ──────────
                   *
                   * The first table has already been logged. Replacing the proof and saying
                   * nothing would leave two contradictory tables in one render log with no
                   * indication which is which. The corrected lines are printed again, labelled,
                   * and they are the ones the stored report ends with.
                   *
                   * ── What cannot be proven, and is not claimed ─────────────────────────────
                   *
                   * A rendered clip is attributable only when this render holds the local file the
                   * timeline named — `existingByClipId`. Clips the job rehydrated for itself live
                   * at paths the lineage never saw, and they are counted as unattributable rather
                   * than guessed at, exactly as `[AssetUsageSummary]` treats UNVERIFIED.
                   */
                  try {
                    const ledger = visualDedup.sourcingCache.lineage;
                    const deliveredPaths: string[] = [];
                    let unattributable = 0;
                    for (const clipId of jobOutcome.renderedClipIds) {
                      const local = existingByClipId.get(clipId);
                      if (local) deliveredPaths.push(local);
                      else unattributable++;
                    }
                    const proven = ledger.replaceFinalVideo(deliveredPaths);
                    console.log(
                      pipelineReport.add(
                        "sourcing",
                        `[VisualAudit] delivered file carried ${jobOutcome.renderedClipIds.length} ` +
                          `shot(s); ${proven} clip(s) proven in it` +
                          (unattributable > 0
                            ? `, ${unattributable} rehydrated by the render job and not attributable`
                            : "")
                      )
                    );
                    const redone = ledger.summary();
                    for (const line of formatAssetUsageSummary(redone, ledger.finalVideoWasVerified)) {
                      pipelineReport.add("sourcing", `${line} (delivered)`);
                      if (line.startsWith("[AssetUsageInconsistency]")) console.warn(`${line} (delivered)`);
                      else console.log(`${line} (delivered)`);
                    }
                    /**
                     * AND THE CLIP FIGURES, AGAINST THE SAME LIST.
                     *
                     * `deliveredPaths` was built four lines up, spent on `replaceFinalVideo`, and
                     * dropped. Meanwhile `bySource`, `byMixKind`, `totalClips` and the score they
                     * feed had been computed at stage 6 from the COMPOSE montage — a file this
                     * viewer did not receive. Render 574's report answered "where did my footage
                     * come from" about nineteen clips while the delivered file carried twelve.
                     *
                     * The same list now answers both questions. See
                     * `recountQualityReportForDeliveredClips` for what it does and does not redo.
                     */
                    const recount = recountQualityReportForDeliveredClips(
                      qualityReport,
                      deliveredPaths,
                      {
                        resolveSource: (clipPath) => ledger.providerFor(clipPath),
                        /** The same two resolvers stage 6 used — one rule, asked about a second list. */
                        isGeneratedClip: (clipPath) => ledger.isGeneratedFallback(clipPath),
                        adoptAudit: visualDedup.clipAdoptAudit,
                        archiveOnly: false,
                        fastShort: isFastShortVideoLength(videoLength),
                      }
                    );
                    console.log(
                      pipelineReport.add(
                        "sourcing",
                        `[Quality] figures re-counted against the delivered file: ` +
                          `clips ${recount.clipsBefore}→${recount.clipsAfter}, ` +
                          `score ${recount.scoreBefore}→${recount.scoreAfter}`
                      )
                    );
                  } catch (err) {
                    console.warn(
                      `[VisualAudit] video=${videoId} could not re-prove FINAL_VIDEO against the ` +
                        `delivered file: ${(err as Error).message.slice(0, 200)}`
                    );
                  }
                } else {
                  cinematicRefusal = `${jobOutcome.code} — ${jobOutcome.message}`;
                }
              }
            }
          } catch (err) {
            cinematicRefusal = `the cinematic render threw: ${(err as Error).message.slice(0, 200)}`;
          }
        }

        /**
         * RONDE 661 — one route, stated with its outcome. A render that did not deliver says why
         * here, and is refused below the block; there is no second render to hand over instead.
         */
        cinematicRefusalForGate = outcome.ok
          ? cinematicRefusal
          : `the cinematic plan was not usable: ${outcome.reason}`;
        if (cinematicDeliveredUrl) {
          console.log(pipelineReport.add("summary", `[RenderJob] video=${videoId} route=cinematic_timeline`));
        } else {
          console.error(
            pipelineReport.add(
              "summary",
              `[RenderJob] video=${videoId} route=cinematic_timeline NOT_DELIVERED ` +
                `reason=${cinematicRefusalForGate ?? "unknown"}`
            )
          );
        }
      }
    } catch (err) {
      /** RONDE 661 — the timeline is the only render, so its failure is the render's failure. */
      cinematicRefusalForGate ??= `the cinematic render threw: ${(err as Error).message.slice(0, 300)}`;
      console.error(`[CinematicPipeline] video=${videoId} ${cinematicRefusalForGate}`);
    }

    // Budget summary + history persistence (non-fatal — never block URL persistence)
    let budgetOutcome: import("./renderBudgetTracker").BudgetOutcome | undefined;
    try {
      const activeBudgetTracker = get_activeBudgetTracker();
      if (activeBudgetTracker) {
        activeBudgetTracker.logSummary();
        const { recordBudgetOutcome } = await import("./renderBudgetTracker");
        budgetOutcome = activeBudgetTracker.outcome();
        recordBudgetOutcome(budgetOutcome);
      }
    } catch (err) {
      console.warn(`[Pipeline] BudgetTracker summary failed for ${videoId}:`, (err as Error).message);
    }

    /**
     * R195 — WHAT THIS RENDER PROMISED, WHAT IT DID, AND WHAT REACHED THE VIEWER.
     *
     * ── An invariant that could not fire ────────────────────────────────────────────────────
     *
     * `renderContract.ts` has carried the enabled → planned → executed → delivered → verified
     * monotonicity check, the UNEXPLAINED_GAP rule and `musicFeatureStatus` for several rounds,
     * and nothing in production ever built a matrix for it to check. So DELIVERED_WITHOUT_EXECUTION
     * could not be reported by any render, and the one statement the music blocker deserves —
     * "this build has no catalogue, and a sine bed is not music" — never reached a report.
     *
     * ── Why here ────────────────────────────────────────────────────────────────────────────
     *
     * This is the last point where every state is settled: the cinematic cutover has decided, the
     * delivered file has been measured, the quality report is final. Built earlier it would have to
     * guess at `delivered`, which is the half the matrix exists for.
     *
     * Every fact below is read from something this render actually recorded. `verified` is false
     * for all but `deliveredQC`, and that is the honest answer rather than a gap: nothing here
     * reads the finished MP4 back and confirms a caption is on it.
     */
    try {
      const funnel = [...visualDedup.beatShortlist.beats.values()];
      const allBeats = [...visualDedup.sceneBeatsBySceneIndex.values()].flat();
      const pools = [...visualDedup.visionReviewPool.beats.values()];
      const soundPlans = [...visualDedup.sceneSoundPlans.values()];
      const ledgerForMatrix = visualDedup.sourcingCache?.lineage;
      const assetsInFinalVideo = ledgerForMatrix
        ? lifecyclesOf(ledgerForMatrix.allRecords(), ledgerForMatrix.allEvents()).filter(
            (a) => a.finalVideo
          ).length
        : 0;
      const matrix = buildRenderFeatureMatrix({
        beatsWithIntent: allBeats.filter((b) => (b.visualDescription ?? "").trim().length > 0).length,
        beatsTotal: allBeats.length,
        retrieved: funnel.reduce((n, f) => n + f.retrieved, 0),
        eligible: funnel.reduce((n, f) => n + f.eligible, 0),
        shortlisted: funnel.reduce((n, f) => n + f.shortlisted, 0),
        visionEnabled: beatImageRelevanceGateEnabled(),
        visionReviewPool: pools.reduce((n, p) => n + p.declared.length, 0),
        visionAsked: funnel.reduce((n, f) => n + f.visionAsked, 0),
        visionApproved: funnel.reduce((n, f) => n + f.approved, 0),
        motionBandsPlanned: visualDedup.motionBandBeats.size,
        motionScored: visualDedup.motionScoredBeats.size,
        cinematicEnabled: cinematicProgress.enabled,
        cinematicPlanned: cinematicProgress.planned,
        cinematicRendered: cinematicProgress.rendered,
        captionsEnabled: enableSubtitles,
        captionsPlanned: enableSubtitles ? allBeats.length : 0,
        graphicsEnabled: visualDedup.graphicClips.size > 0,
        graphicsPlanned: visualDedup.graphicClips.size,
        /**
         * RONDE 661 — read off the delivered timeline: every join into a clip that is not a hard
         * cut. The compose montage's own tally went with the compose route.
         */
        transitionsApplied: (deliveredTimeline?.clips ?? []).filter(
          (c, i) => i > 0 && c.transitionIn !== "hard_cut"
        ).length,
        /** No catalogue is registered in this build — `musicFeatureStatus` states the consequence. */
        musicCatalogueAvailable: false,
        /**
         * The ranking-side sound classification, which is what this render actually planned per
         * scene. R197: it is a PLAN and it is labelled as one — the delivery evidence below comes
         * from the timeline, never from this.
         */
        ambiencePlanned: soundPlans.filter((p) => p.ambience.length > 0).length,
        ambienceUnavailable: 0,
        sfxPlanned: soundPlans.reduce((n, p) => n + p.objectSounds.length, 0),
        duckingApplied: soundPlans.some((p) => p.ambience.length > 0),
        delivery: {
          fileExists: cinematicDeliveredUrl != null,
          /** FILE FACTS — the streams ffprobe actually found in the delivered container. */
          hasVideoStream: (qualityReport.avSync?.videoSec ?? null) != null,
          hasAudioStream: (qualityReport.avSync?.audioSec ?? null) != null,
          /** ROUTE IDENTITY — this is set only where the cinematic render's URL was adopted. */
          fromCinematicRender: cinematicDeliveredUrl != null,
          assetsInFinalVideo,
          captionsOnTimeline: cinematicProgress.captionsOnTimeline,
          graphicsOnTimeline: cinematicProgress.graphicsOnTimeline,
          ambientClipsOnTimeline: cinematicProgress.ambientClipsOnTimeline,
          sfxClipsOnTimeline: cinematicProgress.sfxClipsOnTimeline,
          musicClipsOnTimeline: cinematicProgress.musicClipsOnTimeline,
          graphicsBurnedInByCompose: visualDedup.graphicsUsageSummary.total,
          avSyncMeasured: qualityReport.avSync != null,
          spotChecked: qualityReport.postRenderSpotCheck != null,
        },
      });
      for (const line of formatFeatureMatrix(matrix)) {
        if (line.includes("WITHOUT") || line.includes("PLANNED_WHILE_DISABLED")) {
          console.warn(pipelineReport.add("summary", line));
        } else {
          console.log(pipelineReport.add("summary", line));
        }
      }
    } catch (err) {
      /** A report that cannot be built must never cost a render that is otherwise complete. */
      console.warn(`[FeatureMatrix] video=${videoId} not built: ${(err as Error).message}`);
    }

    /**
     * THE LAST GATE, AND THE ONLY POINT BOTH PRODUCTION ROUTES PASS THROUGH.
     *
     * ── Why here and not at the upload ──────────────────────────────────────────────────────
     *
     * Two routes can publish a video, and the gate wired into `renderJobWorker` covers one of
     * them. The compose route never builds a `ProjectTimeline`, so it has no clip sources to
     * check and never met that gate at all — the invariant held on one of the two ways a film
     * reaches a viewer, which is the exact shape of defect this programme keeps removing.
     *
     * The upload above is deliberately NOT the place to stop it. It also serves a second purpose
     * documented beside it: an export the quality gate refuses is still uploaded so the owner can
     * look at the file that was judged, and blocking there would remove a behaviour built on
     * purpose. `updateVideoStatus(…, "completed")` below is where a file becomes THE video, and
     * that is what this refuses.
     *
     * ── And why it sits ABOVE the report's final store ──────────────────────────────────────
     *
     * The first draft put it after `mergeVideoMetadata`, and `ronde106PipelineReport` caught it:
     * `pipelineReport.build()` stamps the report and everything added afterwards is lost. This
     * gate's own lines — the ones that say WHY a delivery was refused — would have gone to the
     * console and not to the record anybody reads later. That is the defect this whole programme
     * is about, committed by the check written to prevent it.
     *
     * ── What it reads ───────────────────────────────────────────────────────────────────────
     *
     * The lineage ledger, filtered to the records `markFinalVideo` proved out of the input list of
     * the concat that produced the validated output. That is a stronger list than a timeline: what
     * the file is made of rather than what it was planned to be made of. Nothing is probed again —
     * the delivered file's own measurements come from the quality report this render already built.
     */
    /**
     * RONDE 643 — HOW MANY SECONDS OF THIS FILM ARE YOUTUBE, ASKED OF THE FILM.
     *
     * Render 603 found 49 YouTube videos, downloaded none, and delivered a film every gate passed.
     * Nothing said that the one thing this product is for had not happened. This line always
     * prints, measured on the timeline the delivered file was rendered from, and counts YouTube
     * footage that arrived through the archive (the background prefetch) as well as directly.
     * It blocks only when a deployment sets REQUIRE_YOUTUBE_MIN_SECONDS.
     */
    let youtubeFootageVerdict: ReturnType<typeof judgeYoutubeRequirement> = { ok: true };
    try {
      let footage = unmeasuredFootage();
      if (cinematicDeliveredUrl && deliveredTimeline) {
        const origins = new Map<number, ArchiveOrigin>();
        const assetIds = Array.from(
          new Set(deliveredTimeline.clips.flatMap((c) => (c.source?.archiveAssetId != null ? [c.source.archiveAssetId] : [])))
        );
        for (const id of assetIds) {
          const row = await getMediaArchiveAssetById(id).catch(() => undefined);
          if (row) origins.set(id, { sourcePlatform: row.sourcePlatform ?? null, sourceUrl: row.sourceUrl ?? null });
        }
        footage = youtubeFootageInTimeline(deliveredTimeline.clips, origins, deliveredTimeline.basis);
      }
      const lineage = visualDedup.sourcingCache?.lineage;
      const totals = lineage ? youtubeLifecycleTotals(traceYoutubeLifecycle(lineage, visualDedup.beatRelevance)) : null;
      const line = formatYoutubeFootage(videoId, footage, totals
        ? { found: totals.youtubeFound, downloaded: totals.youtubeDownloaded, adopted: totals.youtubeAdopted }
        : undefined);
      if (footage.youtubeSec > 0) console.log(pipelineReport.add("summary", line));
      else console.warn(pipelineReport.add("summary", line));
      youtubeFootageVerdict = judgeYoutubeRequirement(footage, requiredYoutubeSeconds());
      /**
       * RONDE 658 — what the video's one or two searches finally became, on the same row as the
       * searches themselves: downloads tried, downloads that arrived, YouTube clips in the delivered
       * film, and how many clips the other sources (archive, open, stock, AI) had to supply.
       */
      if (youtubeVideoPoolEnabled()) {
        const outcome = {
          downloads: providerMetrics(visualDedup.sourcingCache, "youtube_cc").downloadSlotsClaimed,
          downloadsOk: totals?.youtubeDownloaded ?? 0,
          timelineClips: footage.clips.length,
          fallbackUsed: Math.max(0, (deliveredTimeline?.clips.length ?? 0) - footage.clips.length),
        };
        console.log(
          pipelineReport.add(
            "summary",
            `[YouTubeSearchOutcome] video=${videoId} downloads=${outcome.downloads} downloadsOk=${outcome.downloadsOk} ` +
              `timelineClips=${outcome.timelineClips} fallbackClips=${outcome.fallbackUsed}`
          )
        );
        void dbYoutubeSearchBudgetStore.record(videoId, outcome).catch(() => {});
      }
    } catch (err) {
      console.warn(`[YouTubeInFilm] video=${videoId} not measured: ${(err as Error).message}`);
      youtubeFootageVerdict = judgeYoutubeRequirement(unmeasuredFootage(), requiredYoutubeSeconds());
    }

    /** RONDE 661 — with one render path, a timeline render that did not deliver is the end. */
    const deliveredUrl = cinematicDeliveredUrl;
    if (!deliveredUrl) {
      throw pipelineError(
        PIPELINE_ERROR.FFMPEG,
        `The timeline render did not deliver video ${videoId}: ` +
          `${cinematicRefusalForGate ?? "no reason was recorded"} — there is no second render to fall back to`
      );
    }

    /**
     * The delivery gate already ran, once, in the render job, against the timeline that was
     * rendered and the file that came out. A second verdict here, rebuilt from the ledger, is how
     * render 603 was refused four seconds after its film had passed and been published.
     */
    {
      if (!youtubeFootageVerdict.ok) {
        console.error(
          pipelineReport.add(
            "summary",
            `[DeliveryGate] ${youtubeFootageVerdict.code} video=${videoId} — ${youtubeFootageVerdict.detail}`
          )
        );
        throw pipelineError(
          PIPELINE_ERROR.FFMPEG,
          `Delivery blocked for video ${videoId}: ${youtubeFootageVerdict.code} — ${youtubeFootageVerdict.detail}`
        );
      }
    }

    await mergeVideoMetadata(videoId, {
      qualityReport,
      pipelineStepTiming: pipelineStepTiming.toReport(),
      ...(budgetOutcome ? { renderBudget: budgetOutcome } : {}),
      /**
       * THE REPORT, BUILT AFTER THE LINES IT REPORTS ON.
       *
       * The earlier `mergeVideoMetadata` also stores `pipelineReport.build()`, and it runs before
       * the sourcing summary, the beat ledger, the search-gate report, the asset audit, the
       * voice-persist lines, the cinematic route and the SFX plan have been collected. Thirty-four
       * of the forty-one `.add()` calls in this function happen AFTER it, so the stored report held
       * seven lines and none of the seven measurement families a reader opens it for.
       *
       * The export gave it away: a sixteen-minute render whose report claimed a 159 ms window,
       * because `build()` stamps `finishedAt` when it is called.
       *
       * The early store is KEPT, deliberately. The quality gate a few lines below it throws on a
       * bad render, and that partial report is the only record such a render leaves. This is the
       * complete one, written on the path where there is more to say.
       */
      pipelineReport: pipelineReport.build(),
      /**
       * AND THE GLANCE BESIDE IT, FROM THE SAME RENDER AT THE SAME MOMENT.
       *
       * The glance used to be written ONLY at the early merge, while `pipelineReport` was written
       * at both. So the two halves of one stored record could come from different renders, and
       * video 574's did: a report from `rmtsu22cb-1` beside `gateAttempts=0` from a 147 ms render
       * that never judged a picture, while `rmtsu22cb-1`'s own log said `attempts=54 answered=54`.
       * Nothing in the export could say so, because neither half named its render.
       *
       * Written here as well — not instead — for the same reason the early one is kept: a render
       * that dies before this point still leaves the early numbers rather than none.
       */
      pipelineGlance: glanceNow(),
    }).catch((err) =>
      console.warn(`[Pipeline] Failed to persist qualityReport on complete for ${videoId}:`, err)
    );

    // The upload above has no cancellation checkpoint of its own (it's an HTTP/SDK call, not
    // routed through exec()'s throwIfActiveRenderCancelled()) — without this check, a render
    // cancelled while the upload was already in flight would still reach here and overwrite
    // whatever "failed"/cancelled status the cancellation handler already wrote. This is the
    // last point before that write; throwing here lets the existing outer catch (which already
    // knows how to turn a cancellation into the correct terminal status) handle it instead.
    throwIfVideoGenerationCancelled(videoId);

    // Persist URL immediately so a crash during finalization cannot lose the finished video
    await updateVideoStatus(videoId, "completed", {
      videoUrl: deliveredUrl,
      progressStep: STAGE_LABELS.complete,
      progressPercent: 100,
    }).catch((err) => console.warn(`[Pipeline] Failed to persist videoUrl for ${videoId}:`, err));

    await writeDeliveredLineage({
      videoId,
      ledger: visualDedup.sourcingCache?.lineage ?? null,
      report: pipelineReport,
    });

    onProgress?.({ stage: STAGE_LABELS.complete, percent: 100 });
    const totalMs = Date.now() - t0;
    console.log(
      `[Pipeline] Video ${videoId} COMPLETE in ${(totalMs / 60000).toFixed(1)} min ` +
        `via cinematic_timeline: ${deliveredUrl}`
    );
    profiler.printReport(totalMs, pipelineStepTiming.toReport());
    /**
     * RONDE 157 — the variety memory is written whenever variety is on.
     *
     * The read side excludes assets used by recent same-topic videos, and it is gated on
     * archiveCrossVideoVarietyEnabled alone. The WRITE side carried a second condition,
     * curatedArchiveOnlyVisuals(), and that flag is off in production (CURATED_ARCHIVE_ONLY is
     * set to "false" so the external cascade stays reachable). So nothing was ever recorded, the
     * exclude set was empty on every render, and the ranking — which is deterministic — handed
     * back the same top-scoring assets every time.
     *
     * Measured across the two most recent production renders on the same topic:
     *
     *     video 551   21 archive assets
     *     video 552   47 archive assets
     *     shared      12 — 57% of video 551's footage came back in video 552
     *
     * and neither log contains a single [ArchiveVariety] line, which is what a write that never
     * happens looks like.
     *
     * The two flags are about different things. CURATED_ARCHIVE_ONLY says which SOURCES a render
     * may draw from; the variety memory says which assets the LAST renders already used. Assets
     * are recorded from usedCuratedAssetIds either way — video 552's own filenames are
     * `curated_a56104` and so on — so the condition suppressed a fact the render had regardless.
     */
    if (archiveCrossVideoVarietyEnabled(videoLength)) {
      recordArchiveVideoUsage(videoId, visualDedup.usedCuratedAssetIds, topicContext);
    }

    // Print editorial graphics usage report
    if (editorialGraphicsEnabled() && visualDedup.graphicsUsageSummary.total > 0) {
      printGraphicsUsageReport(visualDedup.graphicsUsageSummary);
    }

    // Print visual budget summary from Master Documentary Director
    if (visualDedup.visualBudgetTracker) {
      printBudgetSummary(visualDedup.visualBudgetTracker);
    }

    // Fire-and-forget: update editorial scores based on adopt/reject events this render
    setImmediate(() => {
      const assetIdsByBasename = new Map(
        visualDedup.clipAdoptAudit
          .filter((e) => e.assetId != null)
          .map((e) => [e.basename.toLowerCase(), e.assetId!])
      );
      applyEditorialScoreFeedback(visualDedup.clipAdoptAudit, assetIdsByBasename).catch(() => {});
    });

    // Fire-and-forget: post-render editorial quality review
    if (editorialReviewEnabled()) {
      setImmediate(() => {
        runEditorialReview({
          videoId: String(videoId),
          videoTitle: topicContext,
          scenes: scenes.map((s) => ({ index: s.index, text: s.text ?? "" })),
          adoptAudit: visualDedup.clipAdoptAudit,
          rejectAudit: visualDedup.clipRejectAudit.entries,
          qualityReport,
          sceneClips: sceneVisualResults.map((svr) => svr?.clips ?? []),
          sceneBeatDurations: sceneVisualResults.map((svr) => svr?.beatDurations ?? []),
          sceneBeats: sceneVisualResults.map((svr) => svr?.beats?.map((b) => ({ index: b.index, text: b.text })) ?? []),
        }).then((review) => {
          printRenderQualityReport(review);
          saveEditorialReview(review).catch(() => {});
        }).catch(() => {});
      });
    }

    /**
     * The DELIVERED file, not the compose intermediate.
     *
     * Callers treat this return value as "the video that was made" — it is written to the row and
     * handed to the notification. Returning `url` here would hand every caller the montage while
     * the database held the cinematic render, and the two would disagree about the same video.
     */
    return deliveredUrl;
  } finally {
    watchdog.stop();
    getRenderCtx().watchdog = null;
    set_activeRenderBudget(null);
    set_activeBudgetTracker(null);
    // Per-video only — other videos may still be rendering concurrently in this same worker
    // process (MAX_CONCURRENT_JOBS), so a blanket cache .clear() here would wipe their
    // still-in-progress cached storyboards/search plans too.
    clearStoryboardCacheForVideo(videoId);
    clearVisualSearchPlanCacheForVideo(videoId);
    /**
     * Every beat's ladder and every scene's discovery, released with the render that built them.
     *
     * Per-video for the same reason as the two caches above: a worker process outlives a render and
     * may be running another one right now. Keyed on the render id, so this drops exactly this
     * render's scenes and no one else's.
     */
    forgetRenderSourcing(String(videoId ?? "-"));
    try {
      /**
       * RONDE 97 §3 — the preparation cache is keyed on this directory, so it goes with it.
       *
       * A worker process outlives a render. Leaving the entries behind would grow a map for every
       * render the process ever ran, and — worse — leave paths pointing into a directory that no
       * longer exists, which `runPreparation`'s existence check would then have to catch one entry
       * at a time. Released here, where the directory's own lifetime ends.
       */
      resetPreparationScope(workDir);
      fs.rmSync(workDir, { recursive: true, force: true });
    } catch { /* ignore */ }
  }
}
